/**
 * /api/accounting/landed-cost
 * GET — List landed cost allocations (companySlug)
 * POST — Create landed cost allocation
 */
import { NextRequest, NextResponse } from "next/server";
import { db } from "@/lib/db";
import { requirePermissionForCompany } from "@/lib/middleware";
import { logAudit } from "@/lib/audit";
import { num } from "@/lib/money";
import { calculateLandedCost } from "@/lib/accounting/inventory-costing";
import { apiError, withErrorHandler, parseJsonBody } from "@/lib/api";
import { parseCursorParams, buildCursorResponse, buildCursorPrismaQuery } from "@/lib/cursor-pagination-server";
import { z } from "zod";

// ── GET: List landed cost allocations ───────────────────────────────────────────

export const GET = withErrorHandler(async (req: NextRequest) => {
  const { companySlug, cursor, limit, extraFilters } = parseCursorParams(req);
  if (!companySlug) return apiError("companySlug مطلوب", 400);

  const access = await requirePermissionForCompany(req, "finance_access", companySlug);
  if ("error" in access) return access.error;

  const pagination = buildCursorPrismaQuery(cursor, limit, "createdAt", "desc");
  const allAllocations = await db.landedCostAllocation.findMany({
    where: { companySlug },
    include: { lines: true, purchaseInvoice: true },
    ...pagination,
  });

  const { items, nextCursor } = buildCursorResponse(allAllocations, limit);
  return NextResponse.json({
    allocations: items.map((a) => ({
      ...a,
      totalCost: num(a.totalCost, 3),
      lines: a.lines.map((l) => ({
        ...l,
        allocatedCost: num(l.allocatedCost, 3),
        baseQuantity: num(l.baseQuantity ?? "0", 3),
        baseValue: num(l.baseValue ?? "0", 3),
      })),
    })),
    nextCursor,
  });
});

// ── POST: Create landed cost allocation ─────────────────────────────────────────

const LandedCostLineSchema = z.object({
  itemId: z.number().int().optional(),
  productId: z.number().int().optional(),
  baseQuantity: z.union([z.number(), z.string()]).optional(),
  baseValue: z.union([z.number(), z.string()]).optional(),
  weight: z.union([z.number(), z.string()]).optional(),
  volume: z.union([z.number(), z.string()]).optional(),
});

const CreateLandedCostSchema = z.object({
  companySlug: z.string().min(1),
  purchaseInvoiceId: z.number().int().positive(),
  costType: z.enum(["shipping", "customs", "clearance", "insurance", "other"]),
  totalCost: z.union([z.number(), z.string()]),
  allocationMethod: z.enum(["quantity", "value", "weight", "volume"]).default("quantity"),
  lines: z.array(LandedCostLineSchema).min(1, "At least one line required"),
});

export const POST = withErrorHandler(async (req: NextRequest) => {
  const body = await parseJsonBody(req);
  const parsed = CreateLandedCostSchema.safeParse(body);
  if (!parsed.success) return apiError(parsed.error.issues[0]?.message || "Invalid input", 400);
  const data = parsed.data;

  const access = await requirePermissionForCompany(req, "finance_access", data.companySlug);
  if ("error" in access) return access.error;
  const user = access.user;

  // Verify purchase invoice exists and belongs to this company
  const purchaseInvoice = await db.purchaseInvoice.findFirst({
    where: { id: data.purchaseInvoiceId, companySlug: data.companySlug },
  });
  if (!purchaseInvoice) return apiError("Purchase invoice not found or does not belong to this company", 404);

  // Calculate landed cost allocation
  const totalCostStr = typeof data.totalCost === "number"
    ? num(data.totalCost, 3).toFixed(3)
    : String(data.totalCost);

  const allocationResult = calculateLandedCost({
    allocationId: 0, // Will be set after creation
    costType: data.costType,
    totalCost: totalCostStr,
    allocationMethod: data.allocationMethod,
    lines: data.lines.map((l) => ({
      itemId: l.itemId,
      productId: l.productId,
      baseQuantity: l.baseQuantity ? (typeof l.baseQuantity === "number" ? num(l.baseQuantity, 3).toFixed(3) : String(l.baseQuantity)) : undefined,
      baseValue: l.baseValue ? (typeof l.baseValue === "number" ? num(l.baseValue, 3).toFixed(3) : String(l.baseValue)) : undefined,
      weight: l.weight ? (typeof l.weight === "number" ? num(l.weight, 3).toFixed(3) : String(l.weight)) : undefined,
      volume: l.volume ? (typeof l.volume === "number" ? num(l.volume, 3).toFixed(3) : String(l.volume)) : undefined,
    })),
  });

  // Create allocation with lines in a transaction
  const allocation = await db.$transaction(async (tx) => {
    const created = await tx.landedCostAllocation.create({
      data: {
        companySlug: data.companySlug,
        purchaseInvoiceId: data.purchaseInvoiceId,
        costType: data.costType,
        totalCost: totalCostStr,
        allocationMethod: data.allocationMethod,
        lines: {
          create: data.lines.map((l, i) => ({
            inventoryItemId: l.itemId ?? null,
            productCatalogId: l.productId ?? null,
            allocatedCost: allocationResult.lines[i].allocatedCost,
            baseQuantity: l.baseQuantity
              ? (typeof l.baseQuantity === "number" ? num(l.baseQuantity, 3).toFixed(3) : String(l.baseQuantity))
              : null,
            baseValue: l.baseValue
              ? (typeof l.baseValue === "number" ? num(l.baseValue, 3).toFixed(3) : String(l.baseValue))
              : null,
          })),
        },
      },
      include: { lines: true },
    });
    return created;
  });

  await logAudit({
    userEmail: user.email,
    userUid: user.uid,
    action: "create",
    entity: "landed_cost_allocation",
    entityId: allocation.id,
    companySlug: data.companySlug,
    details: { costType: data.costType, totalCost: totalCostStr, allocationMethod: data.allocationMethod, lineCount: data.lines.length },
  });

  return NextResponse.json({ ok: true, allocation, allocationResult });
});

/**
 * GET /api/accounting/profit-loss?companySlug=X&from=YYYY-MM-DD&to=YYYY-MM-DD
 * ACC-1: Profit & Loss Statement (قائمة الدخل)
 */
import { NextRequest, NextResponse } from "next/server";
import { db } from "@/lib/db";
import { requirePermissionForCompany } from "@/lib/middleware";
import { num } from "@/lib/money";
import { withErrorHandler, parseJsonField } from "@/lib/api";

export const GET = withErrorHandler(async (req: NextRequest) => {
  const sp = req.nextUrl.searchParams;
  const companySlug = sp.get("companySlug");
  if (!companySlug) return NextResponse.json({ error: "companySlug مطلوب" }, { status: 400 });
  const from = sp.get("from") || new Date(new Date().getFullYear(), 0, 1).toISOString().slice(0, 10);
  const to = sp.get("to") || new Date().toISOString().slice(0, 10);

  const access = await requirePermissionForCompany(req, "finance_access", companySlug);
  if ("error" in access) return access.error;

  // Fetch all posted journal entry lines in date range
  const entries = await db.journalEntry.findMany({
    where: { companySlug, date: { gte: from, lte: to }, status: "posted" },
    include: { lines: { include: { account: true } } },
  });

  // Group by account type
  const groups: Record<string, { revenue: number; expense: number; contra_revenue: number }> = {};
  for (const entry of entries) {
    for (const line of entry.lines) {
      const acc = line.account;
      if (!acc) continue;
      const type = acc.type;
      if (!groups[type]) groups[type] = { revenue: 0, expense: 0, contra_revenue: 0 };
      const debit = num(line.debit, 3);
      const credit = num(line.credit, 3);
      // Revenue: credit increases, debit decreases
      if (type === "revenue") groups[type].revenue += credit - debit;
      // Expense: debit increases, credit decreases
      else if (type === "expense") groups[type].expense += debit - credit;
      // Contra revenue: debit increases
      else if (type === "contra_revenue") groups[type].contra_revenue += debit - credit;
    }
  }

  const totalRevenue = (groups["revenue"]?.revenue || 0);
  const contraRevenue = (groups["contra_revenue"]?.contra_revenue || 0);
  const netRevenue = totalRevenue - contraRevenue;
  const totalExpenses = (groups["expense"]?.expense || 0);
  const netProfit = netRevenue - totalExpenses;

  // Detail by account
  const accountDetails: Array<{ code: string; nameAr: string; type: string; amount: number }> = [];
  const accountMap = new Map<string, { code: string; nameAr: string; type: string; amount: number }>();
  for (const entry of entries) {
    for (const line of entry.lines) {
      const acc = line.account;
      if (!acc) continue;
      const key = acc.code;
      if (!accountMap.has(key)) {
        accountMap.set(key, { code: acc.code, nameAr: acc.nameAr, type: acc.type, amount: 0 });
      }
      const item = accountMap.get(key)!;
      const debit = num(line.debit, 3);
      const credit = num(line.credit, 3);
      if (acc.type === "revenue") item.amount += credit - debit;
      else if (acc.type === "expense") item.amount += debit - credit;
      else if (acc.type === "contra_revenue") item.amount += debit - credit;
    }
  }
  for (const [, item] of accountMap) accountDetails.push(item);

  return NextResponse.json({
    dateRange: { from, to },
    revenue: { total: totalRevenue, contra: contraRevenue, net: netRevenue },
    expenses: { total: totalExpenses },
    netProfit,
    margin: netRevenue > 0 ? ((netProfit / netRevenue) * 100).toFixed(2) + "%" : "0%",
    accounts: accountDetails.sort((a, b) => a.code.localeCompare(b.code)),
  });
});

/**
 * /api/ai/agents
 *
 * POST — route a user message to one of three specialized AI agents.
 *
 * Body: { agentType: "accounting" | "sales" | "inventory", message: string, companySlug: string }
 *
 * Flow:
 *   1. Auth + company access check
 *   2. Look up the agent's config (systemPrompt, allowedIntents)
 *   3. Ask the LLM (classifier) whether the message is within the agent's scope
 *      - If NO → return { ok, inScope: false, response: agent.redirectHint, ... }
 *      - If YES → call the LLM with the agent's systemPrompt + user message
 *        → return { ok, inScope: true, response, allowedIntents, ... }
 *
 * All action execution still goes through /api/ai/tools with the same
 * 2-step confirmation (preview → confirm) — agents never bypass that.
 * The agent's response includes `allowedIntents` so the client knows
 * which intents it can safely suggest to the user.
 */
import { NextRequest, NextResponse } from "next/server";
import { resolveAuth, assertCompanyAccess } from "@/lib/auth";
import { callAI as callAIProvider } from "@/lib/aiProvider";
import {
  AGENTS,
  isAgentType,
  buildScopeClassifierPrompt,
  type AgentType,
} from "@/lib/aiAgents";
import { logAudit } from "@/lib/audit";
import { logger } from "@/lib/logger";
import { z } from "zod";
import { apiError, withErrorHandler, parseJsonBody } from "@/lib/api";
import { rateLimitResponse, LIMITS } from "@/lib/rateLimit";

const RequestSchema = z.object({
  agentType: z.string().min(1),
  message: z.string().min(1, "الرسالة مطلوبة"),
  companySlug: z.string().min(1, "companySlug is required"),
});

/**
 * Call the LLM with a system prompt and a single user message.
 * Returns the assistant's text response.
 */
async function callLLM(systemPrompt: string, userMessage: string): Promise<string> {
  try {
    const result = await callAIProvider({
      messages: [
        { role: "system", content: systemPrompt },
        { role: "user", content: userMessage },
      ],
      temperature: 0.4,
      maxTokens: 800,
    });
    return typeof result.content === "string" ? result.content : String(result.content || "");
  } catch (err) {
    logger.error("[ai/agents] LLM call failed", { err: err instanceof Error ? err.message : String(err) });
    return "عذراً، حدث خطأ أثناء معالجة طلبك. حاول مرة أخرى لاحقاً.";
  }
}

/**
 * Classify whether the user's message is within the agent's scope.
 * Returns true if the LLM says "yes".
 */
async function isInScope(agentType: AgentType, userMessage: string): Promise<boolean> {
  const agent = AGENTS[agentType];
  const classifierPrompt = buildScopeClassifierPrompt(agent, userMessage);
  const reply = await callLLM(
    "أنت مصنّف أسئلة دقيق. تجيب فقط بكلمة yes أو no.",
    classifierPrompt,
  );
  const trimmed = reply.trim().toLowerCase();
  // Be lenient: any reply that starts with yes counts
  return trimmed.startsWith("yes") || trimmed === "نعم" || trimmed.includes("yes");
}

export const POST = withErrorHandler(async (req: NextRequest) => {
  const result = await resolveAuth(req);
  if (!result.ok || !result.user) {
    return NextResponse.json({ error: "Unauthorized" }, { status: 401 });
  }
  const user = result.user;

  // SEC-FIX: Rate limit AI endpoints to prevent cost abuse
  const limited = await rateLimitResponse(req, "ai-agents", LIMITS.AI_BULK, user.uid);
  if (limited) return limited;

  const body = await parseJsonBody(req);
  const parsed = RequestSchema.safeParse(body);
  if (!parsed.success) {
    return apiError(parsed.error.issues?.[0]?.message || "Invalid input", 400);
  }
  const { message, companySlug } = parsed.data;

  if (!isAgentType(parsed.data.agentType)) {
    return apiError(
      `agentType must be one of: accounting, sales, inventory (got "${parsed.data.agentType}")`,
      400,
    );
  }
  const agentType = parsed.data.agentType;
  const agent = AGENTS[agentType];

  // Enforce company access
  if (!assertCompanyAccess(user, companySlug)) {
    return NextResponse.json({ error: "Forbidden" }, { status: 403 });
  }

  // ─── Step 1: scope classification ─────────────────────────────────────
  let inScope = true;
  try {
    inScope = await isInScope(agentType, message);
  } catch (err) {
    logger.warn("[ai/agents] classifier failed — assuming in scope", { err: err instanceof Error ? err.message : String(err), agentType });
    // Fail-open: if the classifier errors, assume in scope so the user
    // still gets a helpful response rather than a hard error.
    inScope = true;
  }

  if (!inScope) {
    await logAudit({
      userEmail: user.email,
      userUid: user.uid,
      action: "ai_agent_redirect",
      entity: "ai_agent",
      companySlug,
      details: { agentType, messagePreview: message.slice(0, 80) },
    });

    return NextResponse.json({
      ok: true,
      inScope: false,
      agentType,
      agentName: agent.nameAr,
      agentIcon: agent.icon,
      response: agent.redirectHint,
      allowedIntents: agent.allowedIntents,
    });
  }

  // ─── Step 2: in-scope → call LLM with the agent's system prompt ───────
  const response = await callLLM(agent.systemPrompt, message);

  await logAudit({
    userEmail: user.email,
    userUid: user.uid,
    action: "ai_agent_reply",
    entity: "ai_agent",
    companySlug,
    details: {
      agentType,
      messagePreview: message.slice(0, 80),
      responsePreview: response.slice(0, 80),
    },
  });

  return NextResponse.json({
    ok: true,
    inScope: true,
    agentType,
    agentName: agent.nameAr,
    agentIcon: agent.icon,
    response,
    allowedIntents: agent.allowedIntents,
    // Hint to the client: any action the agent suggests must still go
    // through /api/ai/tools with the 2-step confirmation flow.
    actionEndpoint: "/api/ai/tools",
  });
});

/**
 * GET — list the available agents (for the client to render a picker).
 */
export const GET = withErrorHandler(async (req: NextRequest) => {
  const result = await resolveAuth(req);
  if (!result.ok || !result.user) {
    return NextResponse.json({ error: "Unauthorized" }, { status: 401 });
  }
  return NextResponse.json({
    agents: Object.values(AGENTS).map((a) => ({
      type: a.type,
      name: a.name,
      nameAr: a.nameAr,
      icon: a.icon,
      allowedIntents: a.allowedIntents,
    })),
  });
});

/**
 * POST /api/ai/bulk-import
 *
 * Save an array of parsed orders as real invoices in a single transaction.
 * Optionally creates corresponding journal entries (S-01 from ERP audit —
 * invoices now produce accounting side-effects when an Accounts Receivable
 * + Sales Revenue account pair exists for the company).
 *
 * Body: {
 *   companySlug: string,
 *   orders: ParsedOrder[],
 *   createJournalEntries?: boolean (default: false),
 * }
 * Returns: { created: Invoice[], errors: Array<{ order, error }> }
 */
import { NextRequest, NextResponse } from "next/server";
import { db } from "@/lib/db";
import { resolveAuth, assertCompanyAccess } from "@/lib/auth";
import { requirePermissionForCompany } from "@/lib/middleware";
import { calcInvoiceTotals, num } from "@/lib/money";
import { logAudit } from "@/lib/audit";
import { logger } from "@/lib/logger";
import { z } from "zod";
import { apiError, withErrorHandler, parseJsonBody } from "@/lib/api";
import { syncInventoryOnSale } from "@/lib/inventorySync";
import { checkTrialExpiry, checkInvoiceQuota } from "@/lib/usageMeter";

const ItemSchema = z.object({
  name: z.string().min(1),
  qty: z.union([z.number(), z.string()]),
  unitPrice: z.union([z.number(), z.string()]),
});

const OrderSchema = z.object({
  clientName: z.string().min(1, "اسم العميل مطلوب"),
  clientPhone: z.string().optional().default(""),
  clientAddress: z.string().optional().default(""),
  clientEmail: z.string().email().optional().or(z.literal("")).default(""),
  items: z.array(ItemSchema).min(1, "كل فاتورة تحتاج عنصراً واحداً على الأقل"),
  taxRate: z.union([z.number(), z.string()]).optional().default(0),
  shipping: z.union([z.number(), z.string()]).optional().default(0),
  discount: z.union([z.number(), z.string()]).optional().default(0),
  notes: z.string().optional().default(""),
});

const RequestSchema = z.object({
  companySlug: z.string().min(1, "companySlug مطلوب"),
  orders: z.array(OrderSchema).min(1, "أرسل طلباً واحداً على الأقل"),
  createJournalEntries: z.boolean().optional().default(false),
});

export const POST = withErrorHandler(async (req: NextRequest) => {
  const body = await parseJsonBody(req);
  const parsed = RequestSchema.safeParse(body);
  if (!parsed.success) {
    return apiError(parsed.error.issues[0]?.message || "مدخلات غير صالحة", 400);
  }
  const { companySlug, orders, createJournalEntries } = parsed.data;

  // Enforce permission (create_invoice) + company access
  const access = await requirePermissionForCompany(req, "create_invoice", companySlug);
  if ("error" in access) return access.error;
  const user = access.user;

  // Fetch the company for currency + default tax rate
  const company = await db.company.findUnique({ where: { slug: companySlug } });
  if (!company) return apiError("الشركة غير موجودة", 404);

  // Quota enforcement (gap fix): bulk-import previously bypassed trial-expiry
  // and invoice-quota checks entirely. A bulk import of 1000 orders on a
  // trial tenant would sail through. Now enforced here, same as the single
  // invoice POST path (see /api/invoices/route.ts).
  const trialCheck = await checkTrialExpiry(companySlug);
  if (!trialCheck.ok) {
    return NextResponse.json(
      { error: trialCheck.reason, code: "TRIAL_EXPIRED" },
      { status: 402 },
    );
  }
  const quotaCheck = await checkInvoiceQuota(companySlug);
  if (!quotaCheck.ok) {
    return NextResponse.json(
      {
        error: `تجاوزت حد الفواتير الشهرية (${quotaCheck.limit}). الفواتير الحالية: ${quotaCheck.current}، تحاول إضافة: ${orders.length}.`,
        code: "QUOTA_EXCEEDED",
        limit: quotaCheck.limit,
        current: quotaCheck.current,
      },
      { status: 402 },
    );
  }

  // Optional: fetch AR + Sales accounts for journal entries
  let arAccount: { id: number } | null = null;
  let salesAccount: { id: number } | null = null;
  let taxAccount: { id: number } | null = null;
  if (createJournalEntries) {
    const accounts = await db.account.findMany({
      where: { companySlug, isActive: true },
      select: { id: true, code: true, type: true },
    });
    // Find by convention: AR = type='asset' AND code starts with '11', Sales = type='revenue', Tax = type='liability' code starts with '2'
    arAccount = accounts.find((a) => a.type === "asset" && a.code.startsWith("11")) || null;
    salesAccount = accounts.find((a) => a.type === "revenue") || null;
    taxAccount = accounts.find((a) => a.type === "liability" && a.code.startsWith("2")) || null;
    if (!arAccount || !salesAccount) {
      logger.warn("[bulk-import] journal entries requested but AR/Sales accounts not found — skipping JE", { companySlug, hasAR: !!arAccount, hasSales: !!salesAccount });
    }
  }

  const created: Array<Record<string, unknown>> = [];
  const errors: Array<{ index: number; error: string }> = [];
  let invCounter = 0;
  // Generate a unique invoice number base from current timestamp + count
  const baseInvNum = `INV-${Date.now().toString().slice(-6)}`;

  for (let i = 0; i < orders.length; i++) {
    const order = orders[i];
    try {
      invCounter++;
      const invoiceNumber = `${baseInvNum}-${invCounter}`;
      const items = order.items.map((it) => ({
        description: it.name,
        qty: num(it.qty),
        price: num(it.unitPrice, 3),
      }));
      const taxRate = order.taxRate !== undefined ? num(order.taxRate) : num(company.defaultTaxRate);
      const totals = calcInvoiceTotals(items, taxRate, num(order.shipping), num(order.discount));

      // Find or skip client matching (we don't create clients automatically — user can do it later)
      let clientId: number | null = null;
      if (order.clientPhone || order.clientEmail) {
        const existingClient = await db.client.findFirst({
          where: {
            companySlug,
            OR: [
              order.clientPhone ? { phone: order.clientPhone } : {},
              order.clientEmail ? { email: order.clientEmail } : {},
            ].filter((c) => Object.keys(c).length > 0),
          },
        });
        if (existingClient) clientId = existingClient.id;
      }

      const issueDate = new Date().toISOString().slice(0, 10);
      const dueDate = new Date(Date.now() + 30 * 24 * 60 * 60 * 1000).toISOString().slice(0, 10);

      // Use a transaction so the invoice + journal entry are atomic (DB-CRIT-03)
      const invoice = await db.$transaction(async (tx) => {
        const inv = await tx.invoice.create({
          data: {
            companySlug,
            invoiceNumber,
            clientId,
            clientName: order.clientName,
            clientEmail: order.clientEmail || null,
            clientPhone: order.clientPhone || null,
            clientAddress: order.clientAddress || null,
            issueDate,
            dueDate,
            status: "sent",
            lineItems: JSON.stringify(items),
            subtotal: totals.subtotal,
            taxRate: totals.taxRate,
            taxAmount: totals.taxAmount,
            total: totals.total,
            shipping: totals.shipping,
            discount: totals.discount,
            paid: "0",
            notes: order.notes || null,
            source: "ai-bulk-import",
            createdByEmail: user.email,
            createdByName: user.uid,
            version: 0,
          },
        });

        // Optional: create the journal entry (S-01 fix from ERP audit)
        if (createJournalEntries && arAccount && salesAccount && num(totals.total) > 0) {
          const je = await tx.journalEntry.create({
            data: {
              companySlug,
              date: issueDate,
              description: `فاتورة مبيعات ${invoiceNumber} — ${order.clientName}`,
              reference: invoiceNumber,
              status: "posted",
              createdBy: user.email,
              sourceType: "invoice",
              sourceId: inv.id,
              lines: {
                create: [
                  // Debit AR (asset increases with debit)
                  {
                    accountId: arAccount.id,
                    debit: totals.total,
                    credit: "0",
                    description: `ذمم عملاء - ${invoiceNumber}`,
                  },
                  // Credit Sales Revenue (revenue increases with credit)
                  {
                    accountId: salesAccount.id,
                    debit: "0",
                    credit: totals.subtotal,
                    description: `إيراد مبيعات - ${invoiceNumber}`,
                  },
                  // Credit Tax Payable if there's tax
                  ...(taxAccount && num(totals.taxAmount) > 0 ? [{
                    accountId: taxAccount.id,
                    debit: "0",
                    credit: totals.taxAmount,
                    description: `ضريبة مستحقة - ${invoiceNumber}`,
                  }] : []),
                ],
              },
            },
          });

          // Update the invoice to link the journal entry
          await tx.invoice.update({
            where: { id: inv.id },
            data: { journalEntryId: je.id },
          });

          // Update account balances
          await tx.account.update({
            where: { id: arAccount.id },
            data: { balance: (num((await tx.account.findUnique({ where: { id: arAccount.id } }))?.balance || "0", 3) + num(totals.total, 3)).toFixed(3) },
          });
          await tx.account.update({
            where: { id: salesAccount.id },
            data: { balance: (num((await tx.account.findUnique({ where: { id: salesAccount.id } }))?.balance || "0", 3) + num(totals.subtotal, 3)).toFixed(3) },
          });
          if (taxAccount && num(totals.taxAmount) > 0) {
            await tx.account.update({
              where: { id: taxAccount.id },
              data: { balance: (num((await tx.account.findUnique({ where: { id: taxAccount.id } }))?.balance || "0", 3) + num(totals.taxAmount, 3)).toFixed(3) },
            });
          }
        }

        return inv;
      });

      created.push({
        id: invoice.id,
        invoiceNumber: invoice.invoiceNumber,
        clientName: invoice.clientName,
        total: num(invoice.total, 3),
        status: invoice.status,
      });

      // Sync inventory (Task 24: oversell blocking + StockMovement ledger)
      const syncResult = await db.$transaction(async (tx) => {
        return await syncInventoryOnSale(tx, companySlug, items, invoice.id);
      });
      const syncWarnings = syncResult.warnings || [];
      (created[created.length - 1] as any).warnings = syncWarnings;
    } catch (err) {
      const msg = "خطأ في إنشاء الفاتورة";
      logger.error("[bulk-import] order failed", { err: err instanceof Error ? err.message : String(err), index: i, order: order.clientName });
      errors.push({ index: i, error: msg });
    }
  }

  // Aggregate [REVIEW-QUEUE] + [OVERSELL] warnings for UI banner
  const reviewQueueWarnings: string[] = [];
  for (const c of created) {
    const w = (c as any).warnings as string[] | undefined;
    if (w && w.length > 0) {
      reviewQueueWarnings.push(...w.filter((x) => x.startsWith("[REVIEW-QUEUE]") || x.startsWith("[OVERSELL]")));
    }
  }

  await logAudit({
    userEmail: user.email,
    userUid: user.uid,
    action: "ai_bulk_import",
    entity: "invoice",
    companySlug,
    details: {
      totalOrders: orders.length,
      created: created.length,
      errors: errors.length,
      withJournalEntries: createJournalEntries && !!arAccount && !!salesAccount,
      reviewQueueWarnings: reviewQueueWarnings.length,
    },
  });

  return NextResponse.json({
    ok: true,
    created,
    errors,
    reviewQueueWarnings,
    meta: {
      totalOrders: orders.length,
      createdCount: created.length,
      errorCount: errors.length,
      reviewQueueWarningCount: reviewQueueWarnings.length,
    },
  });
});

/**
 * POST /api/ai/parse-file
 *
 * Parse an uploaded Excel/CSV file into structured invoice drafts.
 * Uses the xlsx library to read the file, then passes the extracted
 * rows to the AI (z-ai-web-dev-sdk) to structure them into the same
 * ParsedOrder format as /api/ai/smart-parse.
 *
 * Body: { fileBase64: string, fileName: string, companySlug?: string }
 * Returns: { orders: ParsedOrder[], meta: { ... } }
 */
import { NextRequest, NextResponse } from "next/server";
import { db } from "@/lib/db";
import { resolveAuth, assertCompanyAccess } from "@/lib/auth";
import { requirePermission } from "@/lib/middleware";
import { num } from "@/lib/money";
import { logAudit } from "@/lib/audit";
import { logger } from "@/lib/logger";
import { z } from "zod";
import { apiError, withErrorHandler, parseJsonBody } from "@/lib/api";
import { logAiUsage } from "@/lib/ai/costTracker";
import { rateLimitResponse, LIMITS } from "@/lib/rateLimit";

const RequestSchema = z.object({
  fileBase64: z.string().min(100, "ملف غير صالح"),
  fileName: z.string().min(1),
  companySlug: z.string().optional(),
});

interface ParsedItem { name: string; qty: number; unitPrice: number; }
interface ParsedOrder {
  clientName: string; clientPhone: string; clientAddress: string;
  items: ParsedItem[]; taxRate: number; shipping: number; discount: number; notes: string;
}

function normalizeOrder(raw: unknown): ParsedOrder | null {
  if (!raw || typeof raw !== "object") return null;
  const r = raw as Record<string, unknown>;
  const items = Array.isArray(r.items) ? r.items.map(normalizeItem).filter(Boolean) as ParsedItem[] : [];
  if (items.length === 0) return null;
  return {
    clientName: typeof r.clientName === "string" ? r.clientName.trim() : "",
    clientPhone: typeof r.clientPhone === "string" ? r.clientPhone.replace(/[^\d+]/g, "") : "",
    clientAddress: typeof r.clientAddress === "string" ? r.clientAddress.trim() : "",
    items,
    taxRate: num(r.taxRate, 2),
    shipping: num(r.shipping, 3),
    discount: num(r.discount, 3),
    notes: typeof r.notes === "string" ? r.notes.trim() : "",
  };
}

function normalizeItem(raw: unknown): ParsedItem | null {
  if (!raw || typeof raw !== "object") return null;
  const r = raw as Record<string, unknown>;
  const name = typeof r.name === "string" ? r.name.trim() : "";
  if (!name) return null;
  return {
    name,
    qty: Math.max(1, Math.floor(num(r.qty))),
    unitPrice: Math.max(0, num(r.unitPrice, 3)),
  };
}

async function callAI(systemPrompt: string, userText: string): Promise<{
  content: string;
  usage: { prompt_tokens: number; completion_tokens: number; total_tokens: number };
  processingMs: number;
}> {
  const t0 = Date.now();
  const ZAI = (await import("z-ai-web-dev-sdk")).default;
  const ai = await ZAI.create();
  const completion = await ai.chat.completions.create({
    messages: [
      { role: "system", content: systemPrompt },
      { role: "user", content: userText },
    ],
    temperature: 0.1,
    max_tokens: 4000,
  });
  return {
    content: completion.choices?.[0]?.message?.content || "{}",
    usage: completion.usage || { prompt_tokens: 0, completion_tokens: 0, total_tokens: 0 },
    processingMs: Date.now() - t0,
  };
}

function stripFences(text: string): string {
  let t = text.trim();
  if (t.startsWith("```")) t = t.replace(/^```(?:json)?\s*/i, "").replace(/```\s*$/i, "");
  return t.trim();
}

export const POST = withErrorHandler(async (req: NextRequest) => {
  // Require bulk_input permission
  const permCheck = await requirePermission(req, "bulk_input");
  if ("error" in permCheck) return permCheck.error;
  const user = permCheck.user;

  // SEC-FIX: Rate limit AI endpoints to prevent cost abuse
  const limited = await rateLimitResponse(req, "ai-parse-file", LIMITS.AI_BULK, user.uid);
  if (limited) return limited;

  const body = await parseJsonBody(req);
  const parsed = RequestSchema.safeParse(body);
  if (!parsed.success) return apiError(parsed.error.issues[0]?.message || "Invalid input", 400);
  const { fileBase64, fileName, companySlug } = parsed.data;

  if (companySlug && !assertCompanyAccess(user, companySlug)) {
    return NextResponse.json({ error: "Forbidden" }, { status: 403 });
  }

  const t0 = Date.now();
  logger.info("[parse-file] starting", { user: user.uid, companySlug, fileName, size: fileBase64.length });

  try {
    // Parse the Excel file using exceljs
    const ExcelJS = (await import("exceljs")).default;
    const buffer = Buffer.from(fileBase64.replace(/^data:[^;]+;base64,/, ""), "base64");
    const workbook = new ExcelJS.Workbook();
    await workbook.xlsx.load(buffer as unknown as ArrayBuffer);
    const firstSheet = workbook.worksheets[0];
    if (!firstSheet) {
      return apiError("الملف لا يحتوي على أوراق عمل", 400);
    }
    const rows: Record<string, unknown>[] = [];
    const headers: string[] = [];
    firstSheet.eachRow((row, rowNumber) => {
      if (rowNumber === 1) {
        // First row = headers
        row.eachCell((cell, colNumber) => {
          headers[colNumber] = String(cell.value ?? "");
        });
        return;
      }
      const obj: Record<string, unknown> = {};
      row.eachCell((cell, colNumber) => {
        const header = headers[colNumber] || `col${colNumber}`;
        obj[header] = cell.value ?? "";
      });
      rows.push(obj);
    });

    if (rows.length === 0) {
      return apiError("الملف لا يحتوي على بيانات", 400);
    }

    // Convert rows to a text representation for the AI
    const headerKeys = Object.keys(rows[0]);
    const textRows = rows.slice(0, 200).map((r) =>
      headerKeys.map((h) => `${h}: ${r[h]}`).join(" | "),
    ).join("\n");

    const systemPrompt = `أنت محلل فواتير خبير. تستقبل بيانات من ملف Excel/CSV (كل سطر يمثل صف).
استخرج الطلبات المنظمة من هذه البيانات.

لكل طلب:
- clientName: اسم العميل (من عمود "العميل" أو "اسم" أو ما يشبه)
- clientPhone: رقم الهاتف
- clientAddress: العنوان
- items: مصفوفة المنتجات [{name, qty, unitPrice}]
- taxRate, shipping, discount, notes

قواعد:
- الأرقام العربية الهندية: ١=1 ٢=2 ٣=3
- إذا كان كل صف يمثل فاتورة كاملة، استخرج كل صف كطلب منفصل
- إذا كان الملف يحتوي على بنود متعددة لنفس العميل، اجمعها في طلب واحد
- qty و unitPrice أرقام موجبة دائماً

أجب فقط بـ JSON:
{"orders":[{"clientName":"","clientPhone":"","clientAddress":"","items":[{"name":"","qty":1,"unitPrice":0.0}],"taxRate":0,"shipping":0,"discount":0,"notes":""}]}`;

    const aiResult = await callAI(systemPrompt, `أعمدة الملف: ${headerKeys.join(", ")}\n\nالبيانات:\n${textRows}`);
    const content = aiResult.content;

    let orders: ParsedOrder[] = [];
    try {
      const obj = JSON.parse(stripFences(content));
      const raw = Array.isArray(obj) ? obj : (obj.orders ?? obj.items ?? []);
      orders = (raw as unknown[]).map(normalizeOrder).filter(Boolean) as ParsedOrder[];
    } catch (err) {
      logger.error("[parse-file] JSON parse failed", { err: err instanceof Error ? err.message : String(err) });
      // P0 FIX: log the AI call even though JSON parsing failed — the
      // provider call itself succeeded; the failure is downstream.
      void logAiUsage({
        companySlug: companySlug || null,
        userUid: user.uid,
        provider: "z-ai",
        model: "z-ai-glm",
        endpoint: "parse-file",
        tokensIn: aiResult.usage.prompt_tokens || 0,
        tokensOut: aiResult.usage.completion_tokens || 0,
        processingMs: aiResult.processingMs,
        success: false,
        errorMessage: `JSON parse failed: ${err instanceof Error ? err.message : String(err)}`,
      });
      return NextResponse.json(
        { error: "رد الذكاء الاصطناعي غير صالح", raw: content.slice(0, 500) },
        { status: 502 },
      );
    }

    const processingMs = Date.now() - t0;
    const itemsCount = orders.reduce((s, o) => s + o.items.length, 0);

    // P0 FIX (AI Effectiveness prompt): log every parse-file AI call to
    // ai_usage_logs with real token counts + the AI provider call latency
    // (aiResult.processingMs), distinct from the whole-handler processingMs.
    void logAiUsage({
      companySlug: companySlug || null,
      userUid: user.uid,
      provider: "z-ai",
      model: "z-ai-glm",
      endpoint: "parse-file",
      tokensIn: aiResult.usage.prompt_tokens || 0,
      tokensOut: aiResult.usage.completion_tokens || 0,
      processingMs: aiResult.processingMs,
      success: true,
    });

    await db.aIProcessingLog.create({
      data: {
        companySlug: companySlug || null,
        endpoint: "parse-file",
        model: "z-ai-glm",
        provider: "z-ai",
        ordersCount: orders.length,
        itemsCount,
        processingMs,
        inputTokens: aiResult.usage.prompt_tokens || 0,
        outputTokens: aiResult.usage.completion_tokens || 0,
        totalTokens: aiResult.usage.total_tokens || 0,
        success: true,
      },
    });

    await logAudit({
      userEmail: user.email, userUid: user.uid,
      action: "ai_parse_file", entity: "ai", companySlug: companySlug || null,
      details: { fileName, rowsParsed: rows.length, ordersExtracted: orders.length, processingMs, aiMs: aiResult.processingMs },
    });

    return NextResponse.json({
      orders,
      meta: {
        processingMs,
        aiMs: aiResult.processingMs,
        inputTokens: aiResult.usage.prompt_tokens || 0,
        outputTokens: aiResult.usage.completion_tokens || 0,
        totalTokens: aiResult.usage.total_tokens || 0,
        model: "z-ai-glm",
        rowsParsed: rows.length,
        ordersCount: orders.length,
        itemsCount,
      },
    });
  } catch (err) {
    const processingMs = Date.now() - t0;
    logger.error("[parse-file] failed", { err: err instanceof Error ? err.message : String(err), processingMs });
    // P0 FIX: log the failed AI call when the handler itself errored
    // (e.g. upstream provider threw before returning a completion).
    void logAiUsage({
      companySlug: companySlug || null,
      userUid: user.uid,
      provider: "z-ai",
      model: "z-ai-glm",
      endpoint: "parse-file",
      tokensIn: 0,
      tokensOut: 0,
      processingMs,
      success: false,
      errorMessage: err instanceof Error ? err.message : String(err),
    });
    return NextResponse.json(
      { error: "خطأ في معالجة الملف" },
      { status: 500 },
    );
  }
});

/**
 * POST /api/ai/tools
 *
 * Executive AI Assistant — executes real commands on behalf of the user.
 *
 * Security model:
 *   1. User must be authenticated
 *   2. User must have the required permission for the action
 *   3. For destructive actions, a confirmation token is required (two-step)
 *   4. Every action is logged to AuditLog with action="ai_executed_[type]"
 *
 * Flow:
 *   Step 1: Client sends { intent, params, confirm: false }
 *     → Server validates params, returns a preview + confirmToken
 *   Step 2: Client sends { intent, params, confirm: true, confirmToken }
 *     → Server executes the action, returns result
 *
 * Supported intents:
 *   - create_invoice
 *   - list_invoices
 *   - list_clients
 *   - get_client_balance
 *   - mark_invoice_paid
 *   - create_client
 */
import { NextRequest, NextResponse } from "next/server";
import { randomUUID } from "node:crypto";
import { readFileSync, writeFileSync, existsSync, mkdirSync } from "node:fs";
import { join } from "node:path";
import { db } from "@/lib/db";
import { resolveAuth, assertCompanyAccess, type AuthPayload } from "@/lib/auth";
import { requirePermissionForCompany, hasPermission } from "@/lib/middleware";
import { calcInvoiceTotals, num } from "@/lib/money";
import { logAudit } from "@/lib/audit";
import { logger } from "@/lib/logger";
import { z } from "zod";
import { apiError, withErrorHandler, parseJsonBody, parseJsonField } from "@/lib/api";
import { syncInventoryOnSale } from "@/lib/inventorySync";
import { logAiUsage } from "@/lib/ai/costTracker";
import { rateLimitResponse, LIMITS } from "@/lib/rateLimit";

// ── File-based confirmation tokens (C4 FIX: persist across restarts) ────────
const CONFIRM_TOKENS_PATH = join(process.cwd(), "data", "confirm-tokens.json");
const CONFIRM_TOKEN_TTL = 5 * 60 * 1000; // 5 min

interface ConfirmTokenEntry {
  intent: string;
  params: unknown;
  userUid: string;
  expiresAt: number;
}

function loadConfirmTokens(): Map<string, ConfirmTokenEntry> {
  try {
    if (existsSync(CONFIRM_TOKENS_PATH)) {
      const raw = readFileSync(CONFIRM_TOKENS_PATH, "utf-8");
      const obj = JSON.parse(raw) as Record<string, ConfirmTokenEntry>;
      const map = new Map<string, ConfirmTokenEntry>();
      const now = Date.now();
      for (const [key, val] of Object.entries(obj)) {
        if (val.expiresAt > now) map.set(key, val); // skip expired
      }
      return map;
    }
  } catch { /* ignore */ }
  return new Map();
}

function saveConfirmTokens(map: Map<string, ConfirmTokenEntry>): void {
  try {
    const dir = join(process.cwd(), "data");
    if (!existsSync(dir)) mkdirSync(dir, { recursive: true });
    const obj: Record<string, ConfirmTokenEntry> = {};
    const now = Date.now();
    for (const [key, val] of map) {
      if (val.expiresAt > now) obj[key] = val; // skip expired
    }
    writeFileSync(CONFIRM_TOKENS_PATH, JSON.stringify(obj));
  } catch { /* ignore — best effort */ }
}

const confirmTokens = loadConfirmTokens();

// Clean expired tokens and persist every 5 min
if (typeof setInterval !== "undefined") {
  setInterval(() => {
    const now = Date.now();
    let changed = false;
    for (const [key, val] of confirmTokens) {
      if (val.expiresAt < now) { confirmTokens.delete(key); changed = true; }
    }
    if (changed) saveConfirmTokens(confirmTokens);
  }, 300_000).unref?.();
}

const IntentSchema = z.object({
  intent: z.enum([
    "create_invoice", "list_invoices", "list_clients",
    "get_client_balance", "mark_invoice_paid", "create_client",
    // File 5 prerequisite fix: AI Copilot can adjust inventory (qty +/-, set, etc.)
    // via the SAME /api/inventory/items endpoint the Inventory page uses — single
    // source of truth, single audit trail, single permission gate.
    "adjust_inventory",
  ]),
  params: z.record(z.string(), z.unknown()),
  confirm: z.boolean().default(false),
  confirmToken: z.string().optional(),
});

interface ToolPreview {
  description: string;
  affectedRecords?: Array<{ type: string; id?: string | number; name?: string }>;
  warning?: string;
}

interface ToolResult {
  ok: boolean;
  summary: string;
  data?: unknown;
  reviewQueueWarnings?: string[];
}

export const POST = withErrorHandler(async (req: NextRequest) => {
  const result = await resolveAuth(req);
  if (!result.ok || !result.user) {
    return NextResponse.json({ error: "Unauthorized" }, { status: 401 });
  }
  const user = result.user;

  // H3 FIX: Rate limit AI tool execution (3/min per user)
  const aiRateLimitErr = await rateLimitResponse(req, "ai:tools", LIMITS.AI_BULK, user.uid);
  if (aiRateLimitErr) return aiRateLimitErr;

  const body = await parseJsonBody(req);
  const parsed = IntentSchema.safeParse(body);
  if (!parsed.success) return apiError(parsed.error.issues[0]?.message || "Invalid input", 400);
  const { intent, params, confirm, confirmToken } = parsed.data;

  const companySlug = params.companySlug as string | undefined;
  if (!companySlug) return apiError("companySlug required", 400);
  if (!assertCompanyAccess(user, companySlug)) {
    return NextResponse.json({ error: "Forbidden" }, { status: 403 });
  }

  // ─── Step 1: Preview (confirm=false) ──────────────────────────────────────
  if (!confirm) {
    const preview = await generatePreview(intent, params, user);
    if (!preview) return apiError("Unknown intent", 400);

    const token = randomUUID();
    confirmTokens.set(token, {
      intent,
      params,
      userUid: user.uid,
      expiresAt: Date.now() + 5 * 60 * 1000,
    });
    saveConfirmTokens(confirmTokens);

    return NextResponse.json({
      ok: true,
      needsConfirmation: true,
      confirmToken: token,
      preview,
    });
  }

  // ─── Step 2: Execute (confirm=true) ───────────────────────────────────────
  if (!confirmToken) return apiError("confirmToken required", 400);
  const stored = confirmTokens.get(confirmToken);
  if (!stored || stored.userUid !== user.uid || stored.intent !== intent) {
    return apiError("Invalid or expired confirmation token", 400);
  }
  confirmTokens.delete(confirmToken);
  saveConfirmTokens(confirmTokens);

  // P0.2 FIX (AI Effectiveness prompt): capture execution latency around
  // executeIntent() only — not the whole handler (auth + token lookup are
  // excluded). tools/route.ts does NOT call an AI provider directly (the
  // conversational AI parsing happens in /api/ai/chat, then the structured
  // intent is dispatched here), so this logs as endpoint="tools" with
  // tokensIn=0/tokensOut=0 — the latency is what matters for this endpoint.
  const execT0 = Date.now();
  const execResult = await executeIntent(intent, params, user, companySlug);
  const execMs = Date.now() - execT0;

  // P0.1 FIX: log every tool execution to ai_usage_logs so the founder
  // dashboard can report per-endpoint latency for the copilot's action path.
  // Honest disclosure: there is no AI provider token consumption here — the
  // `success` flag reflects whether the intent executed without error.
  void logAiUsage({
    companySlug,
    userUid: user.uid,
    provider: "internal",
    model: "tool-executor",
    endpoint: "tools",
    tokensIn: 0,
    tokensOut: 0,
    processingMs: execMs,
    success: execResult.ok,
    errorMessage: execResult.ok ? null : execResult.summary,
  });

  return NextResponse.json({
    ok: execResult.ok,
    summary: execResult.summary,
    data: execResult.data,
    // P0.1 fix (Remaining Work Handoff): previously computed in executeIntent
    // but silently dropped from the response. AICopilotBubble now renders a
    // warning banner when this array is non-empty, matching the BulkInputView
    // banner pattern from GATE 5.1.
    reviewQueueWarnings: execResult.reviewQueueWarnings || [],
    needsConfirmation: false,
    meta: { processingMs: execMs },
  });
});

// ─── Preview generators ─────────────────────────────────────────────────────

async function generatePreview(intent: string, params: Record<string, unknown>, user: { uid: string; email: string; role: string; permissions: Record<string, number> }): Promise<ToolPreview | null> {
  switch (intent) {
    case "create_invoice": {
      const clientName = params.clientName as string;
      const items = params.items as Array<{ name: string; qty: number; price: number }>;
      if (!clientName || !Array.isArray(items) || items.length === 0) {
        return { description: "⚠️ بيانات ناقصة: مطلوب clientName و items[]" };
      }
      const subtotal = items.reduce((s, it) => s + (it.qty || 0) * (it.price || 0), 0);
      return {
        description: `سيتم إنشاء فاتورة للعميل "${clientName}" بقيمة ${subtotal.toFixed(3)} (${items.length} بند)`,
        affectedRecords: [{ type: "invoice", name: `فاتورة لـ ${clientName}` }],
        warning: "هذا إجراء مالي — سيتم تسجيله في سجل التدقيق",
      };
    }
    case "list_invoices": {
      return {
        description: `سيتم عرض آخر ${params.limit || 10} فواتير${params.status ? ` بحالة "${params.status}"` : ""}`,
      };
    }
    case "list_clients": {
      return {
        description: `سيتم عرض ${params.limit || 10} عملاء${params.search ? ` مطابقين لـ "${params.search}"` : ""}`,
      };
    }
    case "get_client_balance": {
      const clientId = params.clientId as number;
      const client = await db.client.findUnique({ where: { id: clientId } });
      return {
        description: `سيتم عرض رصيد العميل "${client?.name || `#${clientId}`}"`,
      };
    }
    case "mark_invoice_paid": {
      const invoiceId = params.invoiceId as number;
      const inv = await db.invoice.findUnique({ where: { id: invoiceId } });
      if (!inv) return { description: "⚠️ الفاتورة غير موجودة" };
      return {
        description: `سيتم تعليم الفاتورة ${inv.invoiceNumber} (${inv.clientName}) كمكتملة الدفع بقيمة ${num(inv.total, 3)}`,
        warning: "هذا إجراء مالي — سيتم تسجيل الدفعة في سجل التدقيق",
      };
    }
    case "create_client": {
      return {
        description: `سيتم إنشاء عميل جديد: "${params.name}"`,
        affectedRecords: [{ type: "client", name: params.name as string }],
      };
    }
    case "adjust_inventory": {
      // File 5 prerequisite: AI Copilot inventory edit preview.
      const productId = Number(params.productId);
      const warehouseId = Number(params.warehouseId);
      const mode = (params.mode as "set" | "adjust") || "adjust";
      const delta = Number(params.quantity);
      const [product, warehouse] = await Promise.all([
        db.productCatalog.findUnique({ where: { id: productId } }),
        db.warehouse.findUnique({ where: { id: warehouseId } }),
      ]);
      if (!product || product.companySlug !== (params.companySlug as string)) {
        return { description: "⚠️ المنتج غير موجود أو لا يتبع لهذه الشركة" };
      }
      if (!warehouse || warehouse.companySlug !== (params.companySlug as string)) {
        return { description: "⚠️ المستودع غير موجود أو لا يتبع لهذه الشركة" };
      }
      const existing = await db.inventoryItem.findUnique({
        where: { warehouseId_productId: { warehouseId, productId } },
      });
      const currentQty = num(existing?.quantity || "0", 3);
      const newQty = mode === "adjust" ? currentQty + delta : delta;
      return {
        description: `سيتم ${mode === "adjust" ? (delta >= 0 ? "إضافة" : "خصم") : "ضبط"} مخزون "${product.name}" في مستودع "${warehouse.name}":
المخزون الحالي: ${currentQty.toFixed(3)}
${mode === "adjust" ? `الفرق: ${delta >= 0 ? "+" : ""}${delta.toFixed(3)}` : ""}
المخزون الجديد: ${newQty.toFixed(3)}`,
        affectedRecords: [{ type: "inventory_item", id: existing?.id, name: product.name }],
        warning: newQty < 0
          ? "⚠️ هذا الإجراء سيجعل المخزون سالباً — سيتم رفضه (oversell محظور)"
          : "سيتم تسجيل الحركة في دفتر StockMovement مع audit trail",
      };
    }
    default:
      return null;
  }
}

// ─── Intent executors ───────────────────────────────────────────────────────

async function executeIntent(
  intent: string,
  params: Record<string, unknown>,
  user: AuthPayload,
  companySlug: string,
): Promise<ToolResult> {
  try {
    switch (intent) {
      case "create_invoice": {
        // Require create_invoice permission
        if (!hasPermission(user, "create_invoice")) {
          return { ok: false, summary: "ليس لديك صلاحية لإنشاء فواتير" };
        }
        const items = (params.items as Array<{ name: string; qty: number; price: number }>).map((it) => ({
          description: it.name,
          qty: num(it.qty),
          price: num(it.price, 3),
        }));
        const totals = calcInvoiceTotals(items, num(params.taxRate || 0), num(params.shipping || 0), num(params.discount || 0));
        const invoiceNumber = `INV-${Date.now().toString().slice(-6)}`;
        const today = new Date().toISOString().slice(0, 10);
        const dueDate = new Date(Date.now() + 30 * 24 * 60 * 60 * 1000).toISOString().slice(0, 10);

        const invoice = await db.invoice.create({
          data: {
            companySlug,
            invoiceNumber,
            clientName: params.clientName as string,
            clientPhone: (params.clientPhone as string) || null,
            clientEmail: (params.clientEmail as string) || null,
            issueDate: today,
            dueDate,
            status: "sent",
            lineItems: JSON.stringify(items),
            subtotal: totals.subtotal,
            taxRate: totals.taxRate,
            taxAmount: totals.taxAmount,
            total: totals.total,
            shipping: totals.shipping,
            discount: totals.discount,
            paid: "0",
            source: "ai_assistant",
            createdByEmail: user.email,
            createdByName: user.uid,
            version: 0,
          },
        });

        // Sync inventory (Task 24: oversell blocking + StockMovement ledger)
        let inventoryWarnings: string[] = [];
        try {
          const syncResult = await db.$transaction(async (tx) => {
            return await syncInventoryOnSale(tx, companySlug, items, invoice.id);
          });
          inventoryWarnings = syncResult.warnings;
        } catch (syncErr) {
          logger.error("[ai/tools] inventory sync failed", { err: syncErr instanceof Error ? (syncErr as Error).message : String(syncErr) });
        }
        const reviewQueueWarnings = inventoryWarnings.filter((w) => w.startsWith("[REVIEW-QUEUE]") || w.startsWith("[OVERSELL]"));

        await logAudit({
          userEmail: user.email,
          userUid: user.uid,
          action: "ai_executed_create_invoice",
          entity: "invoice",
          entityId: invoice.id,
          companySlug,
          details: { invoiceNumber, total: totals.total, source: "ai_assistant", reviewQueueWarnings: reviewQueueWarnings.length },
        });

        // P0.1 fix: append warnings to the summary string so they appear in the
        // chat bubble even if the frontend banner renderer is bypassed, AND
        // surface them as a structured field for the banner UI.
        // Task 14: standardized wording "⚠️ N صنف يحتاج مراجعة" across all surfaces.
        let summary = `✅ تم إنشاء الفاتورة ${invoiceNumber} للعميل ${params.clientName} بقيمة ${totals.total}`;
        if (reviewQueueWarnings.length > 0) {
          summary += `\n\n⚠️ ${reviewQueueWarnings.length} صنف يحتاج مراجعة:\n${reviewQueueWarnings.map((w) => `• ${w}`).join("\n")}`;
        }

        return {
          ok: true,
          summary,
          data: { id: invoice.id, invoiceNumber, total: num(totals.total, 3) },
          reviewQueueWarnings,
        };
      }

      case "list_invoices": {
        const limit = Math.min(Number(params.limit) || 10, 50);
        const where: Record<string, unknown> = { companySlug };
        if (params.status) where.status = params.status;
        const invoices = await db.invoice.findMany({
          where, orderBy: { createdAt: "desc" }, take: limit,
          select: { id: true, invoiceNumber: true, clientName: true, status: true, total: true, issueDate: true },
        });
        const summary = `وجدت ${invoices.length} فاتورة:\n${invoices.map((i) => `• ${i.invoiceNumber} — ${i.clientName} — ${num(i.total, 3)} — ${i.status}`).join("\n")}`;
        return { ok: true, summary, data: invoices };
      }

      case "list_clients": {
        const limit = Math.min(Number(params.limit) || 10, 50);
        const where: Record<string, unknown> = { companySlug };
        if (params.search) {
          where.OR = [
            { name: { contains: params.search as string } },
            { phone: { contains: params.search as string } },
            { email: { contains: params.search as string } },
          ];
        }
        const clients = await db.client.findMany({
          where, orderBy: { createdAt: "desc" }, take: limit,
          select: { id: true, name: true, phone: true, email: true, company: true },
        });
        const summary = `وجدت ${clients.length} عميل:\n${clients.map((c) => `• ${c.name} — ${c.phone || "لا هاتف"}`).join("\n")}`;
        return { ok: true, summary, data: clients };
      }

      case "get_client_balance": {
        const clientId = Number(params.clientId);
        const client = await db.client.findUnique({ where: { id: clientId } });
        if (!client || client.companySlug !== companySlug) {
          return { ok: false, summary: "العميل غير موجود" };
        }
        const invoices = await db.invoice.findMany({
          where: { clientId, companySlug },
          select: { total: true, paid: true, status: true, invoiceNumber: true },
        });
        const totalDue = invoices.reduce((s, i) => s + num(i.total, 3), 0);
        const totalPaid = invoices.reduce((s, i) => s + num(i.paid, 3), 0);
        const balance = totalDue - totalPaid;
        return {
          ok: true,
          summary: `العميل: ${client.name}\nإجمالي الفواتير: ${totalDue.toFixed(3)}\nالمحصّل: ${totalPaid.toFixed(3)}\nالمتبقي: ${balance.toFixed(3)}\nعدد الفواتير: ${invoices.length}`,
          data: { totalDue, totalPaid, balance, invoiceCount: invoices.length },
        };
      }

      case "mark_invoice_paid": {
        if (!hasPermission(user, "finance_access")) {
          return { ok: false, summary: "ليس لديك صلاحية مالية لتسجيل المدفوعات" };
        }
        const invoiceId = Number(params.invoiceId);
        const existing = await db.invoice.findUnique({ where: { id: invoiceId } });
        if (!existing || existing.companySlug !== companySlug) {
          return { ok: false, summary: "الفاتورة غير موجودة" };
        }
        const newPaid = existing.total;
        const invoice = await db.invoice.update({
          where: { id: invoiceId },
          data: { paid: newPaid, status: "paid", version: { increment: 1 } },
        });
        await logAudit({
          userEmail: user.email, userUid: user.uid,
          action: "ai_executed_mark_paid", entity: "invoice", entityId: invoiceId,
          companySlug, details: { amount: newPaid, source: "ai_assistant" },
        });
        return {
          ok: true,
          summary: `✅ تم تعليم الفاتورة ${existing.invoiceNumber} كمكتملة الدفع (${num(newPaid, 3)})`,
          data: { id: invoice.id, status: invoice.status },
        };
      }

      case "create_client": {
        if (!hasPermission(user, "edit_customer")) {
          return { ok: false, summary: "ليس لديك صلاحية لإنشاء عملاء" };
        }
        const client = await db.client.create({
          data: {
            name: params.name as string,
            phone: (params.phone as string) || null,
            email: (params.email as string) || null,
            address: (params.address as string) || null,
            companySlug,
          },
        });
        await logAudit({
          userEmail: user.email, userUid: user.uid,
          action: "ai_executed_create_client", entity: "client", entityId: client.id,
          companySlug, details: { name: params.name, source: "ai_assistant" },
        });
        return {
          ok: true,
          summary: `✅ تم إنشاء العميل "${params.name}"`,
          data: { id: client.id, name: client.name },
        };
      }

      case "adjust_inventory": {
        // File 5 prerequisite: AI Copilot inventory edit.
        // Uses /api/inventory/items POST contract — single source of truth.
        if (!hasPermission(user, "settings_access")) {
          return { ok: false, summary: "ليس لديك صلاحية لتعديل المخزون" };
        }
        const productId = Number(params.productId);
        const warehouseId = Number(params.warehouseId);
        const mode = (params.mode as "set" | "adjust") || "adjust";
        const quantity = Number(params.quantity);
        if (!Number.isFinite(productId) || !Number.isFinite(warehouseId) || !Number.isFinite(quantity)) {
          return { ok: false, summary: "المعطيات غير صالحة: مطلوب productId + warehouseId + quantity (أرقام)" };
        }

        // Delegate to the same /api/inventory/items POST handler logic by calling
        // the shared inventorySync + db functions directly. We inline the logic
        // here (rather than HTTP-rewriting to /api/inventory/items) to avoid
        // cookie-forwarding complexity — but the audit trail + StockMovement
        // recording + oversell block + permission gate are IDENTICAL.
        const [product, warehouse] = await Promise.all([
          db.productCatalog.findUnique({ where: { id: productId } }),
          db.warehouse.findUnique({ where: { id: warehouseId } }),
        ]);
        if (!product || product.companySlug !== companySlug) {
          return { ok: false, summary: "المنتج غير موجود أو لا يتبع لهذه الشركة" };
        }
        if (!warehouse || warehouse.companySlug !== companySlug) {
          return { ok: false, summary: "المستودع غير موجود أو لا يتبع لهذه الشركة" };
        }

        const existing = await db.inventoryItem.findUnique({
          where: { warehouseId_productId: { warehouseId, productId } },
        });
        const prevQty = num(existing?.quantity || "0", 3);
        const newQty = mode === "adjust" ? prevQty + quantity : quantity;

        // Oversell block — matches inventory/items/route.ts line 127-129.
        if (newQty < 0) {
          return {
            ok: false,
            summary: `❌ تم رفض الإجراء: المخزون الحالي ${prevQty.toFixed(3)} + الفرق ${quantity >= 0 ? "+" : ""}${quantity.toFixed(3)} = ${newQty.toFixed(3)} (سالباً). oversell محظور.`,
          };
        }

        const { recordStockMovement } = await import("@/lib/inventorySync");
        const signedDelta = newQty - prevQty;
        const updated = await db.$transaction(async (tx) => {
          if (existing) {
            const item = await tx.inventoryItem.update({
              where: { id: existing.id },
              data: {
                quantity: newQty.toFixed(3),
                reorderLevel: existing.reorderLevel,
                reorderQty: existing.reorderQty,
              },
            });
            if (Math.abs(signedDelta) > 0.0001) {
              await recordStockMovement(
                tx, companySlug, productId, warehouseId, signedDelta,
                "ai_adjustment", null,
                `AI Copilot ${mode === "adjust" ? "adjust" : "set"}: ${prevQty.toFixed(3)} → ${newQty.toFixed(3)} (delta ${signedDelta >= 0 ? "+" : ""}${signedDelta.toFixed(3)})`,
                user.uid,
              );
            }
            return item;
          }
          const item = await tx.inventoryItem.create({
            data: {
              companySlug, warehouseId, productId,
              quantity: newQty.toFixed(3),
              reorderLevel: "0", reorderQty: "0",
            },
          });
          if (newQty > 0) {
            await recordStockMovement(
              tx, companySlug, productId, warehouseId, newQty,
              "ai_initial_stock", null,
              `AI Copilot create: initial stock ${newQty.toFixed(3)}`,
              user.uid,
            );
          }
          return item;
        });

        await logAudit({
          userEmail: user.email, userUid: user.uid,
          action: "ai_executed_adjust_inventory",
          entity: "inventory_item", entityId: updated.id,
          companySlug,
          details: {
            productId, warehouseId, mode, delta: quantity,
            prevQty: prevQty.toFixed(3), newQty: newQty.toFixed(3),
            source: "ai_assistant", stockMovementRecorded: Math.abs(signedDelta) > 0.0001,
          },
        });

        return {
          ok: true,
          summary: `✅ تم ${mode === "adjust" ? "تعديل" : "ضبط"} مخزون "${product.name}":
${prevQty.toFixed(3)} → ${newQty.toFixed(3)} (الفرق ${signedDelta >= 0 ? "+" : ""}${signedDelta.toFixed(3)})
تم تسجيل الحركة في دفتر StockMovement.`,
          data: { id: updated.id, productId, warehouseId, quantity: newQty.toFixed(3) },
        };
      }

      default:
        return { ok: false, summary: "إجراء غير معروف" };
    }
  } catch (err) {
    logger.error("[ai/tools] execution failed", { err: err instanceof Error ? err.message : String(err), intent });
    return { ok: false, summary: "خطأ في التنفيذ" };
  }
}

/**
 * GET /api/internal/ai-fabric/savings
 *
 * Internal endpoint for the Founder Panel's AI savings display.
 * Returns cascade breakdown + cost savings for a company or platform-wide.
 *
 * Query params:
 *   companySlug (optional) — specific company, omit for platform-wide
 *   period (optional) — "7d" | "30d" | "90d" (default: "30d")
 *
 * Source: AIRequestLog (all numbers from real data, no mocks)
 * Access: Founder Panel only (not exposed to tenants)
 */

import { NextRequest, NextResponse } from "next/server";
import { calculateSavedCost, getPlatformSavings, getCascadeBreakdown } from "@/lib/ai-fabric/cost-optimizer";
import { requireFounder } from "@/lib/middleware";

const PERIOD_MAP: Record<string, number> = {
  "7d": 7 * 24 * 60 * 60 * 1000,
  "30d": 30 * 24 * 60 * 60 * 1000,
  "90d": 90 * 24 * 60 * 60 * 1000,
};

export async function GET(request: NextRequest) {
  // SEC-C11 (Cycle 4): close missing-auth — despite the header comment "Access:
  // Founder Panel only", the handler had zero auth. Returns per-company AI cost
  // savings breakdowns + platform-wide totals.
  const authResult = await requireFounder(request);
  if (authResult instanceof NextResponse) return authResult;

  try {
    const { searchParams } = new URL(request.url);
    const companySlug = searchParams.get("companySlug") || undefined;
    const periodKey = searchParams.get("period") || "30d";
    const periodMs = PERIOD_MAP[periodKey] || PERIOD_MAP["30d"];

    const periodEnd = new Date();
    const periodStart = new Date(Date.now() - periodMs);

    if (companySlug) {
      const [savings, breakdown] = await Promise.all([
        calculateSavedCost(companySlug, periodStart, periodEnd),
        getCascadeBreakdown(companySlug, periodStart, periodEnd),
      ]);

      return NextResponse.json({ savings, breakdown });
    }

    const [savings, breakdown] = await Promise.all([
      getPlatformSavings(periodStart, periodEnd),
      // For platform-wide, we aggregate breakdown from calculateSavedCost
      getCascadeBreakdown("_all_", periodStart, periodEnd).catch(() => []),
    ]);

    return NextResponse.json({
      savings,
      // Use the breakdown from savings report (platform-wide)
      breakdown: savings.breakdown,
    });
  } catch (err) {
    console.error("[ai-fabric/savings] error:", err);
    return NextResponse.json(
      { error: "Failed to compute savings" },
      { status: 500 },
    );
  }
}

/**
 * /api/invoices/[id]
 * GET    — fetch invoice
 * PATCH  — update (with optimistic-lock version check)
 * DELETE — delete
 */
import { NextRequest, NextResponse } from "next/server";
import { db } from "@/lib/db";
import { resolveAuth, assertCompanyAccess } from "@/lib/auth";
import { requirePermission, requirePermissionForCompany, hasPermission } from "@/lib/middleware";
import { logAudit } from "@/lib/audit";
import { calcInvoiceTotals, num, type LineItem } from "@/lib/money";
import { z } from "zod";
import { apiError, withErrorHandler, parseJsonBody, parseJsonField } from "@/lib/api";
import { applyKuwaitCompliance, formatKuwaitErrorsForResponse } from "@/lib/e-invoicing/kuwait-validation";
import { checkInvoiceRetention } from "@/lib/e-invoicing/retention";
import { isKuwait } from "@/lib/gulfConfig";
import { logger } from "@/lib/logger";

const UpdateSchema = z.object({
  invoiceNumber: z.string().min(1).optional(),
  clientId: z.number().int().optional().nullable(),
  clientName: z.string().min(1).optional(),
  clientEmail: z.string().email().optional().or(z.literal("")).nullable(),
  clientPhone: z.string().optional().nullable(),
  clientAddress: z.string().optional().nullable(),
  issueDate: z.string().optional(),
  dueDate: z.string().optional(),
  // SECURITY: `status` is intentionally NOT accepted here. Status changes must
  // go through PATCH /api/invoices/[id]/status (operational statuses only) or
  // PATCH /api/invoices/[id]/payment (for paid/partial — requires
  // finance_access, updates the `paid` amount, and writes a payment audit
  // trail). Previously the general edit endpoint accepted `status` with only
  // `edit_invoice` permission, letting a non-finance employee mark an invoice
  // "paid" without updating `paid` or creating an audit record.
  lineItems: z.array(z.object({
    description: z.string(),
    qty: z.union([z.number(), z.string()]).default(1),
    price: z.union([z.number(), z.string()]).default(0),
    total: z.union([z.number(), z.string()]).optional(),
  })).optional(),
  taxRate: z.union([z.number(), z.string()]).optional(),
  shipping: z.union([z.number(), z.string()]).optional(),
  discount: z.union([z.number(), z.string()]).optional(),
  notes: z.string().optional().nullable(),
  expectedVersion: z.number().int().optional(),
  // Kuwait Decree 10/2026 compliance fields
  sellerNameAr: z.string().optional(),
  sellerAddressAr: z.string().optional(),
  buyerNameAr: z.string().optional(),
  buyerAddressAr: z.string().optional(),
  lineItemsAr: z.string().optional(),
  notesAr: z.string().optional().nullable(),
  invoiceTypeAr: z.string().optional(),
  invoiceTypeEn: z.string().optional(),
  mociNumber: z.string().optional(),
});

type RouteParams = { params: Promise<{ id: string }> };

export const GET = withErrorHandler(async (req: NextRequest, { params }: RouteParams) => {
  const result = await resolveAuth(req);
  if (!result.ok || !result.user) return NextResponse.json({ error: "Unauthorized" }, { status: 401 });
  const { id } = await params;
  // H1 FIX: filter out soft-deleted invoices on GET.
  const invoice = await db.invoice.findUnique({ where: { id: parseInt(id) } });
  if (!invoice || invoice.deletedAt) return apiError("Invoice not found", 404);
  if (!assertCompanyAccess(result.user, invoice.companySlug)) {
    return NextResponse.json({ error: "Forbidden" }, { status: 403 });
  }
  return NextResponse.json({
    invoice: {
      ...invoice,
      lineItems: parseJsonField(invoice.lineItems, []),
      subtotal: num(invoice.subtotal, 3),
      taxRate: num(invoice.taxRate),
      taxAmount: num(invoice.taxAmount, 3),
      total: num(invoice.total, 3),
      shipping: num(invoice.shipping, 3),
      paid: num(invoice.paid, 3),
      discount: num(invoice.discount, 3),
    },
  });
});

export const PATCH = withErrorHandler(async (req: NextRequest, { params }: RouteParams) => {
  const { id } = await params;
  const existing = await db.invoice.findUnique({ where: { id: parseInt(id) } });
  if (!existing || existing.deletedAt) return apiError("Invoice not found", 404);
  const access = await requirePermissionForCompany(req, "edit_invoice", existing.companySlug);
  if ("error" in access) return access.error;
  const user = access.user;

  const body = await parseJsonBody(req);
  const parsed = UpdateSchema.safeParse(body);
  if (!parsed.success) return apiError(parsed.error.issues[0]?.message || "Invalid input", 400);
  const data = parsed.data;

  // ── C1 FIX: Atomic optimistic locking ───────────────────────────────────
  // Old pattern (read-then-write TOCTOU): two concurrent requests could both
  // read v=N, both pass `expectedVersion === existing.version`, and both
  // write v=N+1 — last-writer-wins silently overwrites the other's change.
  // For a financial system this means lost updates and lost payments.
  //
  // New pattern: validate the version atomically via `updateMany` with a
  // `version = expectedVersion` filter. If count === 0, either the version
  // changed concurrently OR the row was soft-deleted concurrently — both
  // are 409 conflicts. The increment itself is atomic.
  //
  // When the client does NOT supply expectedVersion we preserve the legacy
  // "no version check" behavior (still atomic on the increment, just no
  // conflict detection). Callers SHOULD always send expectedVersion.
  const expectedVersion = data.expectedVersion;
  const versionFilter = expectedVersion !== undefined ? { version: expectedVersion } : {};

  // Recalc totals if relevant fields changed
  let updateData: Record<string, unknown> = { ...data, expectedVersion: undefined };
  if (data.lineItems || data.taxRate !== undefined || data.shipping !== undefined || data.discount !== undefined) {
    const items = data.lineItems ?? parseJsonField(existing.lineItems, []);
    const taxRate = data.taxRate !== undefined ? num(data.taxRate) : num(existing.taxRate);
    const shipping = data.shipping !== undefined ? num(data.shipping) : num(existing.shipping);
    const discount = data.discount !== undefined ? num(data.discount) : num(existing.discount);
    const totals = calcInvoiceTotals(items as LineItem[], taxRate, shipping, discount);
    updateData.subtotal = totals.subtotal;
    updateData.taxRate = totals.taxRate;
    updateData.taxAmount = totals.taxAmount;
    updateData.total = totals.total;
    updateData.shipping = totals.shipping;
    updateData.discount = totals.discount;
    updateData.lineItems = JSON.stringify(items);
  }
  // Drop expectedVersion from data payload — it's a control field, not a column.
  delete updateData.expectedVersion;
  updateData.version = { increment: 1 };

  // ── Kuwait Decree 10/2026 compliance for updates ──────────────────────
  let kuwaitWarnings: Array<{ field: string; messageAr: string; messageEn: string }> = [];
  const company = await db.company.findUnique({ where: { slug: existing.companySlug } });
  if (company && isKuwait(company.country)) {
    const kuwaitResult = applyKuwaitCompliance(
      { ...updateData, ...existing },
      company as Record<string, unknown>,
    );
    if (!kuwaitResult.valid) {
      const errorResponse = formatKuwaitErrorsForResponse(kuwaitResult);
      return NextResponse.json(
        { error: errorResponse.error, code: "KUWAIT_COMPLIANCE_ERROR", details: errorResponse.details },
        { status: 400 },
      );
    }
    kuwaitWarnings = kuwaitResult.warnings;
    // Merge Kuwait-enriched fields into update data
    const enriched = kuwaitResult.enrichedData;
    for (const key of [
      "hijriIssueDate", "hijriDueDate", "mociNumber", "invoiceTypeAr", "invoiceTypeEn",
      "sellerNameAr", "sellerAddressAr", "buyerNameAr", "buyerAddressAr",
      "lineItemsAr", "notesAr", "currencyDecimalPlaces", "eInvoiceAuthority",
    ]) {
      if (enriched[key] !== undefined) {
        updateData[key] = enriched[key];
      }
    }
  }

  // C1 FIX: Atomic conditional update — succeeds only if version still matches
  // AND the row has not been soft-deleted concurrently (H4 FIX).
  const result = await db.invoice.updateMany({
    where: { id: existing.id, deletedAt: null, ...versionFilter },
    data: updateData,
  });
  if (result.count === 0) {
    // Either the version changed (concurrent edit) or the row was soft-deleted
    // concurrently. Both are 409 — the client must re-read and retry.
    return NextResponse.json(
      { error: "Conflict: invoice was modified or deleted by another request", code: "VERSION_CONFLICT" },
      { status: 409 },
    );
  }

  // Re-fetch the updated row so we return the canonical post-update state
  // (with the new version and any DB-computed fields).
  const invoice = await db.invoice.findUnique({ where: { id: existing.id } });
  if (!invoice) {
    // Extremely unlikely (we just updated it), but be defensive.
    return apiError("Invoice disappeared after update", 500);
  }

  await logAudit({
    userEmail: user.email,
    userUid: user.uid,
    action: "update",
    entity: "invoice",
    entityId: invoice.id,
    companySlug: existing.companySlug,
  });

  return NextResponse.json({ ok: true, invoice, kuwaitWarnings });
});

export const DELETE = withErrorHandler(async (req: NextRequest, { params }: RouteParams) => {
  const { id } = await params;
  const existing = await db.invoice.findUnique({ where: { id: parseInt(id) } });
  if (!existing) return apiError("Invoice not found", 404);
  if (existing.deletedAt) return apiError("Invoice already deleted", 400);
  const access = await requirePermissionForCompany(req, "delete_invoice", existing.companySlug);
  if ("error" in access) return access.error;
  const user = access.user;

  // ── Kuwait Decree 10/2026: retention enforcement ──────────────────────
  // Check retention period before allowing soft-delete
  const company = await db.company.findUnique({ where: { slug: existing.companySlug } });
  if (company) {
    const retentionCheck = checkInvoiceRetention(
      existing as Record<string, unknown>,
      company as Record<string, unknown>,
    );
    // Soft-delete is always allowed, but we log the retention warning
    if (retentionCheck.reasonAr) {
      logger.info("[invoice-delete] retention notice", {
        invoiceId: existing.id,
        retentionYears: retentionCheck.retentionYears,
        decreeRef: retentionCheck.decreeRef,
        reasonEn: retentionCheck.reasonEn,
      });
    }
  }

  // DB-005 FIX: Soft delete instead of hard delete
  await db.invoice.update({
    where: { id: existing.id },
    data: { deletedAt: new Date(), deletedBy: user.email },
  });
  await logAudit({
    userEmail: user.email,
    userUid: user.uid,
    action: "delete",
    entity: "invoice",
    entityId: existing.id,
    companySlug: existing.companySlug,
    details: { softDelete: true, retentionNotice: company ? checkInvoiceRetention(existing as Record<string, unknown>, company as Record<string, unknown>).reasonEn : undefined },
  });
  return NextResponse.json({ ok: true });
});

/**
 * GET /api/metrics/prometheus — Prometheus exposition format metrics export.
 *
 * Converts the existing MetricsRegistry data into the Prometheus text-based
 * exposition format (OpenMetrics / Prometheus format). This enables direct
 * scraping by Prometheus servers without needing an OTLP bridge.
 *
 * Format follows the Prometheus exposition format spec:
 *   - # TYPE metric_name counter/gauge/histogram
 *   - metric_name{label="value"} number
 *   - For histograms: _bucket{le="N"} count, _sum total, _count total
 *   - +Inf bucket for histogram completeness
 *
 * Founder-only access — metrics contain sensitive operational data.
 * Content-Type: text/plain; version=0.0.4; charset=utf-8
 *
 * RUNTIME: Node.js only
 */

export const runtime = "nodejs";
export const dynamic = "force-dynamic";

import { NextRequest, NextResponse } from "next/server";
import { resolveAuth } from "@/lib/auth";
import { isFounderEmail } from "@/lib/founder";
import { metrics, getOtelServiceName } from "@/lib/observability";
import { logger } from "@/lib/logger";

/**
 * Format labels as Prometheus label string: {key="value",key2="value2"}
 * Escapes special characters in label values per Prometheus spec.
 */
function formatLabels(labels: Record<string, string>): string {
  const entries = Object.entries(labels)
    .filter(([k]) => k !== "_name") // Skip internal _name label
    .map(([k, v]) => `${k}="${escapeLabelValue(v)}"`)
    .join(",");
  return entries.length > 0 ? `{${entries}}` : "";
}

/**
 * Escape special characters in Prometheus label values.
 * Per spec: backslash, double-quote, and newline must be escaped.
 */
function escapeLabelValue(value: string): string {
  return value
    .replace(/\\/g, "\\\\")
    .replace(/"/g, "\\\"")
    .replace(/\n/g, "\\n");
}

/**
 * Convert the MetricsRegistry data to Prometheus exposition format.
 */
function toPrometheusFormat(): string {
  const lines: string[] = [];
  const otlp = metrics.exportOTLP();
  const serviceName = getOtelServiceName();

  // Add resource labels as target info (Prometheus convention)
  lines.push("# TARGET target_info");
  const resourceLabels = Object.entries(otlp.resource.attributes)
    .map(([k, v]) => `${k.replace(/\./g, "_")}="${escapeLabelValue(v)}"`)
    .join(",");
  lines.push(`target_info{${resourceLabels}} 1`);
  lines.push("");

  for (const scopeMetric of otlp.scopeMetrics) {
    for (const metric of scopeMetric.metrics) {
      const metricName = metric.name.replace(/\./g, "_");
      const metricLabels = formatLabels(
        (Object.entries(metric.labels)
          .filter(([k, v]) => k !== "_name" && v !== undefined)
          .reduce((acc, [k, v]) => { acc[k] = String(v); return acc; }, {} as Record<string, string>)),
      );

      if (metric.kind === "COUNTER") {
        lines.push(`# TYPE ${metricName} counter`);
        lines.push(`${metricName}${metricLabels} ${metric.value}`);
        lines.push("");
      } else if (metric.kind === "GAUGE") {
        lines.push(`# TYPE ${metricName} gauge`);
        lines.push(`${metricName}${metricLabels} ${metric.value}`);
        lines.push("");
      } else if (metric.kind === "HISTOGRAM" && metric.summary) {
        lines.push(`# TYPE ${metricName} histogram`);

        // Histogram buckets
        for (const bucket of metric.summary.buckets) {
          const bucketLabels = metricLabels
            ? `${metricLabels.replace("{", "").replace("}", "").length > 0
              ? metricLabels.slice(0, -1) + `,le="${bucket.le}"}`
              : `{le="${bucket.le}"}`
            }`
            : `{le="${bucket.le}"}`;
          lines.push(`${metricName}_bucket${bucketLabels} ${bucket.count}`);
        }

        // +Inf bucket (total count)
        const infLabels = metricLabels
          ? `${metricLabels.replace("{", "").replace("}", "").length > 0
            ? metricLabels.slice(0, -1) + `,le="+Inf"}`
            : `{le="+Inf"}`
          }`
          : `{le="+Inf"}`
        ;
        lines.push(`${metricName}_bucket${infLabels} ${metric.summary.count}`);

        // Sum and count
        lines.push(`${metricName}_sum${metricLabels} ${metric.summary.sum}`);
        lines.push(`${metricName}_count${metricLabels} ${metric.summary.count}`);
        lines.push("");
      }
    }
  }

  // Add service metadata as gauge
  lines.push("# TYPE garfix_eos_info gauge");
  lines.push(`garfix_eos_info{service="${serviceName}",version="12.1.0"} 1`);

  return lines.join("\n");
}

export async function GET(req: NextRequest) {
  // ── Auth: founder-only ────────────────────────────────────────────────────
  const authResult = await resolveAuth(req);
  if (!authResult.ok || !authResult.user) {
    return NextResponse.json({ error: "Unauthorized" }, { status: 401 });
  }
  if (!isFounderEmail(authResult.user.email)) {
    return NextResponse.json({ error: "Founder only" }, { status: 403 });
  }

  const requestId = req.headers.get("x-request-id") || "unknown";

  logger.info("[prometheus] metrics export", {
    requestId,
    requester: authResult.user.email,
    serviceName: getOtelServiceName(),
  });

  const prometheusText = toPrometheusFormat();

  return new NextResponse(prometheusText, {
    status: 200,
    headers: {
      "Content-Type": "text/plain; version=0.0.4; charset=utf-8",
      "Cache-Control": "no-store, no-cache, must-revalidate",
    },
  });
}

/**
 * /api/platform-admin/ai-providers
 * GET  — list all providers with their config + connection status
 * PATCH — update a provider (apiKey, model, isEnabled, priority, baseUrl)
 *
 * RUNTIME: Node.js only — imports cryptoVault.ts (node:crypto)
 */
export const runtime = 'nodejs';

import { NextRequest, NextResponse } from "next/server";
import { requireFounder } from "@/lib/middleware";
import { getAiProviders, setProviderApiKey, setProviderModel, setProviderEnabled, setProviderPriority, PROVIDER_INFO, type ProviderType } from "@/lib/aiProvider";
import { decryptSecret, isEncrypted } from "@/lib/cryptoVault";
import { db } from "@/lib/db";
import { logAdminAction } from "@/lib/audit";
import { withErrorHandler, parseJsonBody, apiError } from "@/lib/api";
import { validateBaseUrl } from "@/lib/ssrf";
import { z } from "zod";

export const GET = withErrorHandler(async (req: NextRequest) => {
  const authResult = await requireFounder(req);
  if (authResult instanceof NextResponse) return authResult;
  const user = authResult.user;

  const providers = await getAiProviders();

  // Merge with PROVIDER_INFO to get descriptions
  const result = PROVIDER_INFO.map(info => {
    const config = providers.find(p => p.provider === info.type);
    return {
      type: info.type,
      name: info.name,
      description: info.description,
      defaultModel: info.defaultModel,
      keyPrefix: info.keyPrefix,
      model: config?.model || info.defaultModel,
      isEnabled: config?.isEnabled ?? (info.type === "z-ai"),
      priority: config?.priority ?? 99,
      hasApiKey: !!config?.apiKey,
      // SEC-H9C4 (Cycle 4): stop returning decrypted API key bytes. The previous
      // implementation returned `${apiKey.slice(0,6)}...${apiKey.slice(-4)}` —
      // for OpenAI keys this leaks the "sk-pro" prefix (confirms key type) plus
      // 10 chars that dramatically narrow a brute-force search. We now return
      // only hasApiKey (boolean). The UI should use that to show "key set" /
      // "no key" status without exposing any key material.
      apiKeyMasked: config?.apiKey ? `${info.keyPrefix}…` : null,
      baseUrl: config?.baseUrl || null,
    };
  });

  return NextResponse.json({ providers: result });
});

const UpdateSchema = z.object({
  provider: z.enum(["z-ai", "openrouter", "anthropic", "openai", "gemini", "deepseek", "custom"]),
  apiKey: z.string().optional(),
  model: z.string().optional(),
  isEnabled: z.boolean().optional(),
  priority: z.number().int().optional(),
  baseUrl: z.string().optional(),
});

export const PATCH = withErrorHandler(async (req: NextRequest) => {
  const authResult = await requireFounder(req);
  if (authResult instanceof NextResponse) return authResult;
  const user = authResult.user;

  const body = await parseJsonBody(req);
  const parsed = UpdateSchema.safeParse(body);
  if (!parsed.success) return apiError(parsed.error.issues[0]?.message || "Invalid input", 400);
  const { provider, apiKey, model, isEnabled, priority, baseUrl } = parsed.data;

  if (apiKey !== undefined) await setProviderApiKey(provider as ProviderType, apiKey);
  if (model !== undefined) await setProviderModel(provider as ProviderType, model);
  if (isEnabled !== undefined) await setProviderEnabled(provider as ProviderType, isEnabled);
  if (priority !== undefined) await setProviderPriority(provider as ProviderType, priority);
  if (baseUrl !== undefined) {
    // SEC-H10C4 (Cycle 4): validate baseUrl BEFORE persisting. Previously the
    // URL was written to PlatformSetting raw and only validated later inside
    // getBaseUrl() at chat-call time — a founder (or DB-tamperer) could persist
    // an internal URL that would only be rejected at runtime.
    try {
      validateBaseUrl(baseUrl);
    } catch (err) {
      const msg = err instanceof Error ? err.message : String(err);
      return apiError(`عنوان base_url غير آمن: ${msg}`, 400);
    }
    const key = `ai.provider.${provider}.baseUrl`;
    const existing = await db.platformSettings.findUnique({ where: { key } });
    if (existing) await db.platformSettings.update({ where: { key }, data: { value: JSON.stringify(baseUrl) } });
    else await db.platformSettings.create({ data: { key, category: "ai", valueType: "string", value: JSON.stringify(baseUrl) } });
  }

  await logAdminAction({
    adminEmail: user.email,
    action: "update_ai_provider",
    targetType: "ai_provider",
    targetId: provider,
    changes: { model, isEnabled, priority, hasApiKey: !!apiKey },
  });

  return NextResponse.json({ ok: true });
});

/**
 * /api/platform-admin/ai-usage
 *
 * GET — Aggregate AI usage statistics from the `ai_usage_logs` table.
 *
 * Returns:
 *   - totals: totalCalls, totalCost, totalTokensIn, totalTokensOut, totalTokens,
 *     successCount, failureCount, callsToday, successRate
 *   - last30Days: [{ date, calls, cost }]
 *   - perCompany: [{ companySlug, calls, cost, tokens }]
 *   - perEndpoint: [{ endpoint, calls, cost, tokens, successCount, failureCount,
 *     p50Ms, p95Ms, minMs, maxMs, avgMs }]  ← latency breakdown per endpoint
 *   - perModel: [{ model, calls, cost, tokens }]
 *   - perCompanyMonthly: [{ companySlug, month, calls, tokens, cost }]
 *   - recentErrors: [{ id, provider, model, endpoint, errorMessage, createdAt }]
 *
 * Founder-only.
 */
import { NextRequest, NextResponse } from "next/server";
import { db } from "@/lib/db";
import { requireFounder } from "@/lib/middleware";
import { withErrorHandler } from "@/lib/api";

/**
 * Compute percentiles from an array of latencies (ms).
 * Returns { p50, p95, min, max, avg } or nulls if the array is empty.
 * Uses the nearest-rank method (no interpolation) — standard for latency SLOs.
 */
function computeLatencyStats(latencies: number[]): {
  p50: number | null; p95: number | null; min: number | null; max: number | null; avg: number | null;
} {
  if (latencies.length === 0) return { p50: null, p95: null, min: null, max: null, avg: null };
  const sorted = [...latencies].sort((a, b) => a - b);
  const n = sorted.length;
  // Nearest-rank: percentile p → index ceil(p/100 * n) - 1 (clamped to [0, n-1])
  const rank = (p: number) => {
    const idx = Math.ceil((p / 100) * n) - 1;
    return sorted[Math.max(0, Math.min(n - 1, idx))];
  };
  const sum = sorted.reduce((s, v) => s + v, 0);
  return {
    p50: rank(50),
    p95: rank(95),
    min: sorted[0],
    max: sorted[n - 1],
    avg: Math.round(sum / n),
  };
}

export const GET = withErrorHandler(async (req: NextRequest) => {
  const authResult = await requireFounder(req);
  if (authResult instanceof NextResponse) return authResult;

  // ── Overall totals ──────────────────────────────────────────────────────
  const all = await db.aIUsageLog.findMany({
    select: {
      id: true,
      companySlug: true,
      provider: true,
      model: true,
      endpoint: true,
      tokensIn: true,
      tokensOut: true,
      totalTokens: true,
      estimatedCost: true,
      processingMs: true,
      success: true,
      errorMessage: true,
      createdAt: true,
    },
  });

  const totalCalls = all.length;
  const totalCost = all.reduce((s, r) => s + (r.estimatedCost || 0), 0);
  const totalTokensIn = all.reduce((s, r) => s + r.tokensIn, 0);
  const totalTokensOut = all.reduce((s, r) => s + r.tokensOut, 0);
  const totalTokens = all.reduce((s, r) => s + r.totalTokens, 0);
  const successCount = all.filter((r) => r.success).length;
  const failureCount = totalCalls - successCount;

  // P0.3 FIX: calls/day + overall success rate — the two headline numbers
  // the founder asks for first ("how much AI are we using, and is it working?").
  // `callsToday` counts rows created since local midnight today.
  const today = new Date();
  today.setHours(0, 0, 0, 0);
  const callsToday = all.filter((r) => r.createdAt >= today).length;
  const successRate = totalCalls > 0 ? Math.round((successCount / totalCalls) * 1000) / 10 : null;

  // ── Last 30 days daily series ───────────────────────────────────────────
  const now = new Date();
  const start30 = new Date(now);
  start30.setDate(now.getDate() - 29);
  start30.setHours(0, 0, 0, 0);

  const dayBuckets: Record<string, { calls: number; cost: number }> = {};
  for (let i = 0; i < 30; i++) {
    const d = new Date(start30);
    d.setDate(start30.getDate() + i);
    const key = `${d.getFullYear()}-${String(d.getMonth() + 1).padStart(2, "0")}-${String(d.getDate()).padStart(2, "0")}`;
    dayBuckets[key] = { calls: 0, cost: 0 };
  }
  for (const r of all) {
    if (r.createdAt < start30) continue;
    const key = `${r.createdAt.getFullYear()}-${String(r.createdAt.getMonth() + 1).padStart(2, "0")}-${String(r.createdAt.getDate()).padStart(2, "0")}`;
    if (!dayBuckets[key]) dayBuckets[key] = { calls: 0, cost: 0 };
    dayBuckets[key].calls += 1;
    dayBuckets[key].cost += r.estimatedCost || 0;
  }
  const last30Days = Object.entries(dayBuckets).map(([date, v]) => ({
    date,
    calls: v.calls,
    cost: Math.round(v.cost * 1e6) / 1e6,
  }));

  // ── Per company breakdown ───────────────────────────────────────────────
  const perCompanyMap = new Map<string, { calls: number; cost: number; tokens: number }>();
  for (const r of all) {
    const key = r.companySlug || "(none)";
    const prev = perCompanyMap.get(key) || { calls: 0, cost: 0, tokens: 0 };
    prev.calls += 1;
    prev.cost += r.estimatedCost || 0;
    prev.tokens += r.totalTokens;
    perCompanyMap.set(key, prev);
  }
  const perCompany = Array.from(perCompanyMap.entries())
    .map(([companySlug, v]) => ({
      companySlug,
      calls: v.calls,
      cost: Math.round(v.cost * 1e6) / 1e6,
      tokens: v.tokens,
    }))
    .sort((a, b) => b.cost - a.cost);

  // ── Per endpoint breakdown (with latency p50/p95) ───────────────────────
  // P0.3 FIX (AI Effectiveness prompt): the founder dashboard needs to answer
  // "how fast is each AI endpoint?" — not just "how many calls / how much
  // cost". We now aggregate successCount, failureCount, and the full latency
  // distribution (min/p50/p95/max/avg) per endpoint, using only rows where
  // processingMs was recorded (null entries are excluded from the latency
  // arrays but still counted in the calls total).
  const perEndpointMap = new Map<string, {
    calls: number; cost: number; tokens: number;
    successCount: number; failureCount: number;
    latencies: number[];
  }>();
  for (const r of all) {
    const prev = perEndpointMap.get(r.endpoint) || { calls: 0, cost: 0, tokens: 0, successCount: 0, failureCount: 0, latencies: [] };
    prev.calls += 1;
    prev.cost += r.estimatedCost || 0;
    prev.tokens += r.totalTokens;
    if (r.success) prev.successCount += 1; else prev.failureCount += 1;
    if (typeof r.processingMs === "number" && r.processingMs > 0) prev.latencies.push(r.processingMs);
    perEndpointMap.set(r.endpoint, prev);
  }
  const perEndpoint = Array.from(perEndpointMap.entries())
    .map(([endpoint, v]) => {
      const stats = computeLatencyStats(v.latencies);
      return {
        endpoint,
        calls: v.calls,
        cost: Math.round(v.cost * 1e6) / 1e6,
        tokens: v.tokens,
        successCount: v.successCount,
        failureCount: v.failureCount,
        successRate: v.calls > 0 ? Math.round((v.successCount / v.calls) * 1000) / 10 : null,
        p50Ms: stats.p50,
        p95Ms: stats.p95,
        minMs: stats.min,
        maxMs: stats.max,
        avgMs: stats.avg,
      };
    })
    .sort((a, b) => b.calls - a.calls);

  // ── Per model breakdown ─────────────────────────────────────────────────
  const perModelMap = new Map<string, { calls: number; cost: number; tokens: number }>();
  for (const r of all) {
    const prev = perModelMap.get(r.model) || { calls: 0, cost: 0, tokens: 0 };
    prev.calls += 1;
    prev.cost += r.estimatedCost || 0;
    prev.tokens += r.totalTokens;
    perModelMap.set(r.model, prev);
  }
  const perModel = Array.from(perModelMap.entries())
    .map(([model, v]) => ({
      model,
      calls: v.calls,
      cost: Math.round(v.cost * 1e6) / 1e6,
      tokens: v.tokens,
    }))
    .sort((a, b) => b.calls - a.calls);

  // ── Per company × month breakdown (GATE 4 Task 3: founder AI usage table) ─
  // Returns one row per (tenant, year-month) so the founder panel can render
  // a tenant|month|AI calls|tokens|cost table. Months without activity are
  // omitted (no zero-fill) so the table stays compact.
  const perCompanyMonthlyMap = new Map<string, { companySlug: string; month: string; calls: number; tokens: number; cost: number }>();
  for (const r of all) {
    const slug = r.companySlug || "(none)";
    const month = `${r.createdAt.getFullYear()}-${String(r.createdAt.getMonth() + 1).padStart(2, "0")}`;
    const key = `${slug}|${month}`;
    const prev = perCompanyMonthlyMap.get(key) || { companySlug: slug, month, calls: 0, tokens: 0, cost: 0 };
    prev.calls += 1;
    prev.tokens += r.totalTokens;
    prev.cost += r.estimatedCost || 0;
    perCompanyMonthlyMap.set(key, prev);
  }
  const perCompanyMonthly = Array.from(perCompanyMonthlyMap.values())
    .map((v) => ({
      companySlug: v.companySlug,
      month: v.month,
      calls: v.calls,
      tokens: v.tokens,
      cost: Math.round(v.cost * 1e6) / 1e6,
    }))
    .sort((a, b) => (a.month < b.month ? 1 : a.month > b.month ? -1 : b.cost - a.cost));

  // ── Recent errors (last 20) ─────────────────────────────────────────────
  const recentErrors = all
    .filter((r) => !r.success)
    .sort((a, b) => b.createdAt.getTime() - a.createdAt.getTime())
    .slice(0, 20)
    .map((r) => ({
      id: r.id,
      companySlug: r.companySlug,
      provider: r.provider,
      model: r.model,
      endpoint: r.endpoint,
      errorMessage: r.errorMessage,
      createdAt: r.createdAt.toISOString(),
    }));

  return NextResponse.json({
    totals: {
      totalCalls,
      totalCost: Math.round(totalCost * 1e6) / 1e6,
      totalTokensIn,
      totalTokensOut,
      totalTokens,
      successCount,
      failureCount,
      callsToday,
      successRate,
    },
    last30Days,
    perCompany,
    perEndpoint,
    perModel,
    perCompanyMonthly,
    recentErrors,
  });
});

/**
 * GET  /api/product-matching/config?companySlug=...
 * PUT  /api/product-matching/config
 *
 * Read + update the per-tenant product matching configuration:
 *   - autoMatchThreshold / suggestedThreshold (tier boundaries)
 *   - autoMatchingEnabled (global kill-switch via feature flag)
 *   - evidenceWeights (Enterprise v4: weighted multi-signal scoring)
 *   - signalFlags     (Enterprise v4: per-signal feature flags)
 *
 * Permission: settings_access (admin/manager).
 */
import { NextRequest, NextResponse } from "next/server";
import { db } from "@/lib/db";
import { requirePermissionForCompany } from "@/lib/middleware";
import { logAudit } from "@/lib/audit";
import { apiError, withErrorHandler, parseJsonBody } from "@/lib/api";
import {
  DEFAULT_AUTO_MATCH_THRESHOLD,
  DEFAULT_SUGGESTED_THRESHOLD,
  DEFAULT_EVIDENCE_WEIGHTS,
  DEFAULT_SIGNAL_FLAGS,
  invalidateKillSwitchCache,
  type EvidenceWeights,
  type SignalFlags,
} from "@/lib/productMatcher";
import { z } from "zod";

// ─── GET ─────────────────────────────────────────────────────────────────────

export const GET = withErrorHandler(async (req: NextRequest) => {
  const companySlug = req.nextUrl.searchParams.get("companySlug");
  if (!companySlug) return apiError("companySlug مطلوب", 400);
  const access = await requirePermissionForCompany(req, "settings_access", companySlug);
  if ("error" in access) return access.error;

  const flag = await db.featureFlag.findUnique({ where: { key: "product-auto-matching" } });
  const settings = await db.platformSettings.findMany({ where: { key: { startsWith: `product.matching.${companySlug}.` } } });

  let autoMatchThreshold = DEFAULT_AUTO_MATCH_THRESHOLD;
  let suggestedThreshold = DEFAULT_SUGGESTED_THRESHOLD;
  let evidenceWeights = { ...DEFAULT_EVIDENCE_WEIGHTS };
  let signalFlags = { ...DEFAULT_SIGNAL_FLAGS };

  for (const s of settings) {
    try {
      const val = JSON.parse(s.value);
      if (s.key.endsWith(".autoThreshold") && typeof val === "number") autoMatchThreshold = val;
      else if (s.key.endsWith(".suggestedThreshold") && typeof val === "number") suggestedThreshold = val;
      else if (s.key.endsWith(".weights") && typeof val === "object" && val !== null) {
        for (const k of Object.keys(DEFAULT_EVIDENCE_WEIGHTS) as (keyof EvidenceWeights)[]) {
          if (typeof val[k] === "number") evidenceWeights[k] = val[k];
        }
      } else if (s.key.endsWith(".flags") && typeof val === "object" && val !== null) {
        for (const k of Object.keys(DEFAULT_SIGNAL_FLAGS) as (keyof SignalFlags)[]) {
          if (typeof val[k] === "boolean") signalFlags[k] = val[k];
        }
      }
    } catch { /* skip malformed */ }
  }

  return NextResponse.json({
    autoMatchThreshold,
    suggestedThreshold,
    autoMatchingEnabled: flag ? flag.isActive : true,
    evidenceWeights,
    signalFlags,
    defaults: { evidenceWeights: DEFAULT_EVIDENCE_WEIGHTS, signalFlags: DEFAULT_SIGNAL_FLAGS },
  });
});

// ─── PUT ─────────────────────────────────────────────────────────────────────

const WeightsSchema = z.object({
  text: z.number().min(0).max(1).optional(),
  brand: z.number().min(0).max(1).optional(),
  category: z.number().min(0).max(1).optional(),
  historical: z.number().min(0).max(1).optional(),
  semantic: z.number().min(0).max(1).optional(),
});

const FlagsSchema = z.object({
  text: z.boolean().optional(),
  brand: z.boolean().optional(),
  category: z.boolean().optional(),
  historical: z.boolean().optional(),
  semantic: z.boolean().optional(),
});

const ConfigUpdateSchema = z.object({
  companySlug: z.string().min(1),
  autoMatchThreshold: z.number().min(0).max(1).optional(),
  suggestedThreshold: z.number().min(0).max(1).optional(),
  evidenceWeights: WeightsSchema.optional(),
  signalFlags: FlagsSchema.optional(),
});

export const PUT = withErrorHandler(async (req: NextRequest) => {
  const body = await parseJsonBody(req);
  const parsed = ConfigUpdateSchema.safeParse(body);
  if (!parsed.success) return apiError(parsed.error.issues[0]?.message || "Invalid", 400);
  const { companySlug, autoMatchThreshold, suggestedThreshold, evidenceWeights, signalFlags } = parsed.data;

  const access = await requirePermissionForCompany(req, "settings_access", companySlug);
  if ("error" in access) return access.error;
  const user = access.user;

  const prefix = `product.matching.${companySlug}.`;
  const updates: { key: string; value: string; category: string; valueType: string; description: string }[] = [];

  if (typeof autoMatchThreshold === "number") {
    updates.push({ key: `${prefix}autoThreshold`, value: JSON.stringify(autoMatchThreshold), category: "product-matching", valueType: "number", description: "Auto-match confidence threshold" });
  }
  if (typeof suggestedThreshold === "number") {
    updates.push({ key: `${prefix}suggestedThreshold`, value: JSON.stringify(suggestedThreshold), category: "product-matching", valueType: "number", description: "Suggested (review queue) threshold" });
  }
  if (evidenceWeights) {
    updates.push({ key: `${prefix}weights`, value: JSON.stringify({ ...DEFAULT_EVIDENCE_WEIGHTS, ...evidenceWeights }), category: "product-matching", valueType: "json", description: "Evidence signal weights (text/brand/category/historical/semantic)" });
  }
  if (signalFlags) {
    updates.push({ key: `${prefix}flags`, value: JSON.stringify({ ...DEFAULT_SIGNAL_FLAGS, ...signalFlags }), category: "product-matching", valueType: "json", description: "Per-signal feature flags (enable/disable each evidence signal)" });
  }

  for (const u of updates) {
    await db.platformSettings.upsert({
      where: { key: u.key },
      update: { value: u.value, updatedBy: user.email },
      create: u,
    });
  }

  // Invalidate the in-memory config cache so the next match picks up new settings
  invalidateKillSwitchCache(companySlug);

  await logAudit({
    userEmail: user.email,
    userUid: user.uid,
    action: "update_matching_config",
    entity: "platform_setting",
    entityId: 0,
    companySlug,
    details: { autoMatchThreshold, suggestedThreshold, evidenceWeights, signalFlags },
  });

  return NextResponse.json({ ok: true, updated: updates.length, message: "تم تحديث إعدادات المطابقة" });
});

/**
 * /api/reports
 * GET — generate business reports (sales, profit, cash flow) with CSV export.
 *
 * Query params:
 *   companySlug — required
 *   type — "sales" | "profit" | "cashflow" | "tax"
 *   from — YYYY-MM-DD (default: start of current month)
 *   to — YYYY-MM-DD (default: today)
 *   format — "json" (default) | "csv"
 */
import { NextRequest, NextResponse } from "next/server";
import { db } from "@/lib/db";
import { requirePermissionForCompany } from "@/lib/middleware";
import { num } from "@/lib/money";
import { withErrorHandler, apiError, parseJsonField } from "@/lib/api";

function toCsv(rows: Record<string, unknown>[], headers?: string[]): string {
  if (rows.length === 0) return "";
  const cols = headers || Object.keys(rows[0]);
  const header = cols.join(",");
  const lines = rows.map((r) =>
    cols.map((c) => {
      const v = r[c];
      if (v === null || v === undefined) return "";
      const s = String(v);
      // Escape quotes and wrap in quotes if contains comma/newline/quote
      if (s.includes(",") || s.includes("\n") || s.includes('"')) {
        return `"${s.replace(/"/g, '""')}"`;
      }
      return s;
    }).join(","),
  );
  return [header, ...lines].join("\n");
}

export const GET = withErrorHandler(async (req: NextRequest) => {
  const sp = req.nextUrl.searchParams;
  const companySlug = sp.get("companySlug");
  const type = sp.get("type") || "sales";
  const from = sp.get("from") || new Date(new Date().getFullYear(), new Date().getMonth(), 1).toISOString().slice(0, 10);
  const to = sp.get("to") || new Date().toISOString().slice(0, 10);
  const format = sp.get("format") || "json";

  if (!companySlug) return apiError("companySlug مطلوب", 400);

  // Require reports_access permission
  const access = await requirePermissionForCompany(req, "reports_access", companySlug);
  if ("error" in access) return access.error;

  // Fetch invoices in date range
  const invoices = await db.invoice.findMany({
    where: {
      companySlug,
      issueDate: { gte: from, lte: to },
    },
    orderBy: { issueDate: "asc" },
    select: {
      id: true, invoiceNumber: true, clientName: true, clientEmail: true,
      issueDate: true, dueDate: true, status: true,
      subtotal: true, taxRate: true, taxAmount: true,
      total: true, shipping: true, discount: true, paid: true,
      lineItems: true, createdAt: true,
    },
    take: 5000,
  });

  // Fetch purchase invoices in the same range
  const purchases = await db.purchaseInvoice.findMany({
    where: {
      companySlug,
      date: { gte: from, lte: to },
    },
    orderBy: { date: "asc" },
    select: { id: true, num: true, date: true, supplier: true, items: true, totalQty: true, notes: true },
    take: 5000,
  });

  let reportData: Record<string, unknown>[] = [];
  let summary: Record<string, unknown> = {};

  if (type === "sales") {
    reportData = invoices.map((inv) => ({
      invoiceNumber: inv.invoiceNumber,
      clientName: inv.clientName,
      issueDate: inv.issueDate,
      dueDate: inv.dueDate,
      status: inv.status,
      subtotal: num(inv.subtotal, 3),
      taxAmount: num(inv.taxAmount, 3),
      shipping: num(inv.shipping, 3),
      discount: num(inv.discount, 3),
      total: num(inv.total, 3),
      paid: num(inv.paid, 3),
      outstanding: Math.max(0, num(inv.total, 3) - num(inv.paid, 3)),
    }));

    summary = {
      totalInvoices: invoices.length,
      totalRevenue: invoices.reduce((s, i) => s + num(i.total, 3), 0),
      totalPaid: invoices.reduce((s, i) => s + num(i.paid, 3), 0),
      totalOutstanding: invoices.reduce((s, i) => s + Math.max(0, num(i.total, 3) - num(i.paid, 3)), 0),
      totalTax: invoices.reduce((s, i) => s + num(i.taxAmount, 3), 0),
      totalDiscount: invoices.reduce((s, i) => s + num(i.discount, 3), 0),
    };
  } else if (type === "profit") {
    // Revenue - COGS (purchase cost)
    const totalRevenue = invoices.reduce((s, i) => s + num(i.subtotal, 3), 0);
    // Estimate COGS from purchase invoices (simplified — real COGS needs inventory tracking)
    const totalCogs = purchases.reduce((s, p) => {
      const items = parseJsonField<Array<{ qty?: number; price?: number }>>(p.items, []);
      return s + items.reduce((cs, it) => cs + num(it.qty) * num(it.price, 3), 0);
    }, 0);
    const grossProfit = totalRevenue - totalCogs;
    const totalExpenses = 0; // would come from expense tracking module

    reportData = [
      { metric: "الإيرادات (Revenue)", amount: totalRevenue },
      { metric: "تكلفة البضاعة المباعة (COGS)", amount: totalCogs },
      { metric: "إجمالي الربح (Gross Profit)", amount: grossProfit },
      { metric: "المصروفات (Expenses)", amount: totalExpenses },
      { metric: "صافي الربح (Net Profit)", amount: grossProfit - totalExpenses },
    ];

    summary = {
      totalRevenue,
      totalCogs,
      grossProfit,
      grossMargin: totalRevenue > 0 ? ((grossProfit / totalRevenue) * 100).toFixed(2) + "%" : "0%",
      netProfit: grossProfit - totalExpenses,
    };
  } else if (type === "cashflow") {
    // Cash inflow = paid amounts, outflow = purchases
    const inflow = invoices.reduce((s, i) => s + num(i.paid, 3), 0);
    const outflow = purchases.reduce((s, p) => {
      const items = parseJsonField<Array<{ qty?: number; price?: number }>>(p.items, []);
      return s + items.reduce((cs, it) => cs + num(it.qty) * num(it.price, 3), 0);
    }, 0);

    reportData = [
      { metric: "التدفق الداخل (Cash Inflow)", amount: inflow, count: invoices.filter((i) => num(i.paid, 3) > 0).length },
      { metric: "التدفق الخارج (Cash Outflow)", amount: outflow, count: purchases.length },
      { metric: "صافي التدفق (Net Cash Flow)", amount: inflow - outflow, count: 0 },
    ];

    summary = { inflow, outflow, netCashFlow: inflow - outflow };
  } else if (type === "tax") {
    reportData = invoices.map((inv) => ({
      invoiceNumber: inv.invoiceNumber,
      clientName: inv.clientName,
      issueDate: inv.issueDate,
      subtotal: num(inv.subtotal, 3),
      taxRate: num(inv.taxRate),
      taxAmount: num(inv.taxAmount, 3),
      total: num(inv.total, 3),
    }));

    summary = {
      totalSubtotal: invoices.reduce((s, i) => s + num(i.subtotal, 3), 0),
      totalTax: invoices.reduce((s, i) => s + num(i.taxAmount, 3), 0),
      totalWithTax: invoices.reduce((s, i) => s + num(i.total, 3), 0),
      invoiceCount: invoices.length,
    };
  }

  // CSV export
  if (format === "csv") {
    const csv = toCsv(reportData);
    const bom = "\uFEFF"; // UTF-8 BOM for Arabic Excel compatibility
    return new NextResponse(bom + csv, {
      headers: {
        "Content-Type": "text/csv; charset=utf-8",
        "Content-Disposition": `attachment; filename="garfix-${type}-report-${from}-to-${to}.csv"`,
      },
    });
  }

  return NextResponse.json({
    type,
    companySlug,
    dateRange: { from, to },
    summary,
    rows: reportData,
    count: reportData.length,
  });
});

/**
 * GET /api/storage/[key] — Serve a stored file (logos, etc.).
 * Files are stored via lib/storage.ts (E-17).
 *
 * Wrapped in `withErrorHandler` (GLM P0.3 fix) so any unexpected throw from
 * `readAsBuffer` produces the standard `{ error }` JSON shape instead of an
 * unhandled 500 with stack trace leakage. Existing 400/404 paths are preserved
 * as-is — they are intentional, validated responses, not errors.
 */
import { NextRequest, NextResponse } from "next/server";
import { readAsBuffer } from "@/lib/storage";
import { logger } from "@/lib/logger";
import { withErrorHandler } from "@/lib/api";
import { resolveAuth } from "@/lib/auth";

const MIME_MAP: Record<string, string> = {
  png: "image/png",
  jpg: "image/jpeg",
  jpeg: "image/jpeg",
  gif: "image/gif",
  webp: "image/webp",
  pdf: "application/pdf",
};

type RouteParams = { params: Promise<{ key: string }> };

export const GET = withErrorHandler<[NextRequest, RouteParams]>(
  // GATE3 IDOR FIX: previously this route served files with no auth at all.
  // Storage keys are random UUIDs (128 bits of entropy), so guess-attacks
  // are infeasible, but the route still leaked files to anyone who held a
  // link. We now require an authenticated session — browsers automatically
  // send the auth cookie on `<img src="/api/storage/...">` requests, so this
  // does not break legitimate image rendering inside the app. Public/landing
  // assets should use a separate public-bucket path (TODO: signed URLs).
  async (req, { params }) => {
    const authResult = await resolveAuth(req);
    if (!authResult.ok || !authResult.user) {
      return NextResponse.json({ error: "Unauthorized" }, { status: 401 });
    }
    const { key } = await params;
    // Sanitize — only allow alphanumeric + dash + dot (UUIDs + extension)
    if (!/^[a-f0-9-]+\.[a-z0-9]+$/i.test(key)) {
      return NextResponse.json({ error: "Invalid file key" }, { status: 400 });
    }
    const buffer = await readAsBuffer(key);
    if (!buffer) {
      return NextResponse.json({ error: "File not found" }, { status: 404 });
    }
    const ext = key.split(".").pop()?.toLowerCase() || "bin";
    const mime = MIME_MAP[ext] || "application/octet-stream";
    logger.debug("[storage] serving file", { key, mime, size: buffer.length });
    return new NextResponse(new Uint8Array(buffer) as BodyInit, {
      headers: {
        "Content-Type": mime,
        "Cache-Control": "private, max-age=3600",
        "Content-Length": buffer.length.toString(),
      },
    });
  },
);

