function MetricCard({
  title,
  value,
  unit,
  subtitle,
  trend,
  status,
}: {
  title: string;
  value: string | number;
  unit?: string;
  subtitle?: string;
  trend?: "up" | "down" | "stable";
  status?: "healthy" | "warning" | "critical";
}) {
  const statusColors = {
