        </div>
        {(subtitle || trend) && (
          <div className="mt-1 flex items-center gap-2 text-xs text-gray-500">
            {trend === "up" && <span>↑</span>}
            {trend === "down" && <span>↓</span>}
            {trend === "stable" && <span>→</span>}
            {subtitle && <span>{subtitle}</span>}
