"use client";

import { useState, useEffect } from "react";
import { Activity, CheckCircle, AlertTriangle, XCircle, Clock, RefreshCw } from "lucide-react";
import { FooterPageLayout } from "@/components/garfix/FooterPageLayout";

interface ServiceStatus {
  name: string;
  status: "operational" | "degraded" | "outage" | "maintenance";
  uptime: string;
  latency: string;
  description: string;
}

const SERVICES: ServiceStatus[] = [
  { name: "لوحة التحكم", status: "operational", uptime: "99.98%", latency: "45ms", description: "الواجهة الرئيسية للمستخدم وإدارة الأعمال" },
  { name: "واجهة برمجة التطبيقات (API)", status: "operational", uptime: "99.99%", latency: "32ms", description: "جميع نقاط نهاية API للمنصة" },
  { name: "نظام الفواتير", status: "operational", uptime: "99.97%", latency: "58ms", description: "إنشاء وإرسال ومعالجة الفواتير" },
  { name: "مساعد الذكاء الاصطناعي", status: "operational", uptime: "99.95%", latency: "120ms", description: "المساعد الذكي ومعالجة الأوامر" },
  { name: "قاعدة البيانات", status: "operational", uptime: "99.99%", latency: "12ms", description: "قواعد بيانات PostgreSQL وPrisma" },
  { name: "نظام المصادقة", status: "operational", uptime: "99.99%", latency: "28ms", description: "تسجيل الدخول وإدارة الجلسات والرموز" },
  { name: "النسخ الاحتياطي", status: "operational", uptime: "100%", latency: "-", description: "النسخ الاحتياطية اليومية التلقائية" },
  { name: "نظام الإشعارات", status: "operational", uptime: "99.90%", latency: "85ms", description: "الإشعارات عبر البريد الإلكتروني والواتساب" },
];

const STATUS_CONFIG = {
  operational: { label: "يعمل بشكل طبيعي", color: "text-green-400", bg: "bg-green-400/10", icon: <CheckCircle size={16} /> },
  degraded: { label: "أداء متدني", color: "text-yellow-400", bg: "bg-yellow-400/10", icon: <AlertTriangle size={16} /> },
  outage: { label: "انقطاع", color: "text-red-400", bg: "bg-red-400/10", icon: <XCircle size={16} /> },
  maintenance: { label: "صيانة مجدولة", color: "text-blue-400", bg: "bg-blue-400/10", icon: <Clock size={16} /> },
};

const INCIDENT_HISTORY = [
  {
    date: "15 يوليو 2025",
    title: "تأخير طفيف في نظام الإشعارات",
    status: "تم الحل",
    duration: "23 دقيقة",
    desc: "تأخر في إرسال بعض إشعارات البريد الإلكتروني بسبب ضغط مؤقت على خوادم الإشعارات. تم حل المشكلة بتوسيع سعة المعالجة.",
  },
  {
    date: "2 يوليو 2025",
    title: "صيانة مجدولة لقاعدة البيانات",
    status: "مكتمل",
    duration: "15 دقيقة",
    desc: "ترقية خوادم قاعدة البيانات إلى إصدار أحدث لتحسين الأداء. تم تنفيذ الصيانة خارج ساعات الذروة دون تأثير ملحوظ.",
  },
  {
    date: "18 يونيو 2025",
    title: "انقطاع مؤقت في مساعد الذكاء الاصطناعي",
    status: "تم الحل",
    duration: "45 دقيقة",
    desc: "توقف مؤقت في خدمة المساعد الذكي بسبب مشكلة في مزود الذكاء الاصطناعي. تم التبديل إلى مزود احتياطي واستعادة الخدمة.",
  },
];

export default function StatusPage() {
  const [lastChecked, setLastChecked] = useState<string>("");
  const [overallStatus, setOverallStatus] = useState<"operational" | "degraded" | "outage">("operational");

  useEffect(() => {
    const now = new Date();
    setLastChecked(now.toLocaleString("ar-KW", { timeZone: "Asia/Kuwait" }));
    // Determine overall status from services
    const hasOutage = SERVICES.some((s) => s.status === "outage");
    const hasDegraded = SERVICES.some((s) => s.status === "degraded");
    if (hasOutage) setOverallStatus("outage");
    else if (hasDegraded) setOverallStatus("degraded");
    else setOverallStatus("operational");
  }, []);

  const overallConfig = STATUS_CONFIG[overallStatus];

  return (
    <FooterPageLayout
      title="حالة الخدمة"
      subtitle="الوضع الحالي لجميع خدمات GARFIX وسجل الأعطال"
      icon={<Activity size={28} />}
    >
      <div className="space-y-10 text-white/80 text-[15px] leading-[1.9]">
        {/* الحالة الإجمالية */}
        <div className={`${overallConfig.bg} border border-white/[0.06] rounded-xl p-6 text-center`}>
          <div className={`inline-flex items-center gap-2 ${overallConfig.color} text-lg font-extrabold mb-2`}>
            {overallConfig.icon}
            جميع الأنظمة تعمل بشكل طبيعي
          </div>
          <p className="text-white/50 text-sm">
            آخر فحص: {lastChecked} (توقيت الكويت)
          </p>
          <button
            onClick={() => {
              const now = new Date();
              setLastChecked(now.toLocaleString("ar-KW", { timeZone: "Asia/Kuwait" }));
            }}
            className="mt-3 inline-flex items-center gap-1.5 text-white/40 hover:text-white/60 text-xs cursor-pointer bg-transparent border-none transition-colors"
          >
            <RefreshCw size={12} />
            تحديث
          </button>
        </div>

        {/* ملخص الأداء */}
        <div className="grid grid-cols-2 md:grid-cols-4 gap-3">
          {[
            { label: "وقت التشغيل", value: "99.97%", sub: "آخر 30 يوماً" },
            { label: "متوسط الاستجابة", value: "54ms", sub: "عالمياً" },
            { label: "حوادث الشهر", value: "1", sub: "يوليو 2025" },
            { label: "وقت الاسترداد", value: "< 30 د", sub: "متوسط" },
          ].map((stat) => (
            <div key={stat.label} className="p-4 rounded-xl bg-white/[0.03] border border-white/[0.06] text-center">
              <div className="text-2xl font-black text-[#fbbf24]">{stat.value}</div>
              <div className="text-xs text-white/70 font-bold mt-0.5">{stat.label}</div>
              <div className="text-[10px] text-white/40">{stat.sub}</div>
            </div>
          ))}
        </div>

        {/* حالة كل خدمة */}
        <section>
          <h2 className="text-xl font-extrabold text-white mb-5">حالة الخدمات</h2>
          <div className="space-y-2">
            {SERVICES.map((service) => {
              const config = STATUS_CONFIG[service.status];
              return (
                <div
                  key={service.name}
                  className="flex items-center gap-4 p-4 rounded-xl bg-white/[0.02] border border-white/[0.05] hover:bg-white/[0.04] transition-all"
                >
                  <div className={`${config.color} shrink-0`}>{config.icon}</div>
                  <div className="flex-1 min-w-0">
                    <div className="flex items-center gap-2 mb-0.5">
                      <span className="font-bold text-white text-sm">{service.name}</span>
                      <span className={`text-[11px] px-2 py-0.5 rounded-full ${config.bg} ${config.color} font-bold`}>
                        {config.label}
                      </span>
                    </div>
                    <div className="text-white/50 text-[12px]">{service.description}</div>
                  </div>
                  <div className="text-left shrink-0 hidden sm:block">
                    <div className="text-white/70 text-xs font-bold">{service.uptime}</div>
                    <div className="text-white/40 text-[10px]">{service.latency}</div>
                  </div>
                </div>
              );
            })}
          </div>
        </section>

        {/* سجل الأعطال */}
        <section>
          <h2 className="text-xl font-extrabold text-white mb-5">سجل الأعطال</h2>
          <div className="space-y-4">
            {INCIDENT_HISTORY.map((incident) => (
              <div
                key={incident.title}
                className="bg-white/[0.03] border border-white/[0.06] rounded-xl p-5"
              >
                <div className="flex flex-wrap items-center gap-2 mb-2">
                  <span className="text-white/40 text-xs">{incident.date}</span>
                  <span className="text-[10px] px-2 py-0.5 rounded-full bg-green-400/10 text-green-400 font-bold">
                    {incident.status}
                  </span>
                  <span className="text-white/40 text-[11px]">المدة: {incident.duration}</span>
                </div>
                <div className="font-bold text-white text-sm mb-1.5">{incident.title}</div>
                <p className="text-white/60 text-[13px] leading-relaxed">{incident.desc}</p>
              </div>
            ))}
          </div>
        </section>

        {/* الاشتراك في التحديثات */}
        <div className="bg-[rgba(124,58,237,0.08)] border border-[rgba(124,58,237,0.2)] rounded-xl p-6 text-center">
          <h3 className="font-bold text-white text-sm mb-2">اشترك في تحديثات حالة الخدمة</h3>
          <p className="text-white/50 text-[13px] mb-4">
            احصل على إشعارات فورية عند حدوث أي تغيير في حالة الخدمات
          </p>
          <div className="flex gap-2 max-w-[400px] mx-auto">
            <input
              type="email"
              placeholder="بريدك الإلكتروني"
              className="flex-1 px-4 py-2.5 rounded-lg bg-white/[0.05] border border-white/[0.1] text-white text-sm outline-none focus:border-[#7c3aed] transition-colors"
              dir="ltr"
            />
            <button className="px-5 py-2.5 rounded-lg bg-[linear-gradient(135deg,#7c3aed,#a78bfa)] text-white font-bold text-sm cursor-pointer border-none transition-all hover:shadow-[0_4px_12px_rgba(124,58,237,0.3)] whitespace-nowrap">
              اشترك
            </button>
          </div>
        </div>
      </div>
    </FooterPageLayout>
  );
}

"use client";

import { useEffect, useMemo, useRef, useState, useCallback } from "react";
import {
  Search, FileText, Users, LayoutDashboard, Package, ShoppingCart,
  UserCog, Calculator, BarChart3, Settings, Building2, Shield, History,
  Plus, Sparkles, User, CornerDownLeft, ArrowUp, ArrowDown, X, Boxes,
} from "lucide-react";
import { useBrand } from "@/context/BrandContext";
import { authedFetch } from "@/context/AuthContext";

export interface CommandPaletteProps {
  open: boolean;
  onClose: () => void;
}

// ─── Navigation items ──────────────────────────────────────────────────────

interface NavItem {
  hash: string;
  label: string;
  labelEn: string;
  keywords: string[];
  icon: React.ComponentType<{ size?: number; className?: string; style?: React.CSSProperties }>;
}

const NAV_ITEMS: NavItem[] = [
  { hash: "dash", label: "لوحة التحكم", labelEn: "Dashboard", keywords: ["dash", "لوحة", "تحكم", "رئيسية"], icon: LayoutDashboard },
  { hash: "invoices", label: "الفواتير", labelEn: "Invoices", keywords: ["invoices", "فوا", "فاتورة", "فواتير"], icon: FileText },
  { hash: "clients", label: "العملاء", labelEn: "Clients", keywords: ["clients", "عملاء", "عميل", "عمليل"], icon: Users },
  { hash: "catalog", label: "المنتجات", labelEn: "Catalog", keywords: ["catalog", "products", "منتجات", "منتج"], icon: Package },
  { hash: "inventory", label: "المخزون", labelEn: "Inventory", keywords: ["inventory", "مخزون", "مستودع", "مستودعات", "stock", "warehouse"], icon: Boxes },
  { hash: "purchases", label: "المشتريات", labelEn: "Purchases", keywords: ["purchases", "مشتريات", "شراء"], icon: ShoppingCart },
  { hash: "hr", label: "الموارد البشرية", labelEn: "HR", keywords: ["hr", "موارد", "بشرية", "موظفين", "رواتب"], icon: UserCog },
  { hash: "accounting", label: "المحاسبة", labelEn: "Accounting", keywords: ["accounting", "محاسبة", "قيود", "حسابات"], icon: Calculator },
  { hash: "reports", label: "التقارير", labelEn: "Reports", keywords: ["reports", "تقارير", "تقرير"], icon: BarChart3 },
  { hash: "bulk-input", label: "إدخال مجمع بالـ AI", labelEn: "Bulk Input", keywords: ["bulk", "إدخال", "مجمع", "ذكاء"], icon: Sparkles },
  { hash: "team", label: "فريقي", labelEn: "Team", keywords: ["team", "فريق", "فريقي"], icon: Users },
  { hash: "settings", label: "الإعدادات", labelEn: "Settings", keywords: ["settings", "إعدادات", "اعدادات"], icon: Settings },
  { hash: "account", label: "حسابي", labelEn: "Account", keywords: ["account", "حسابي", "حساب"], icon: User },
  { hash: "saas", label: "إدارة المنصة", labelEn: "SaaS", keywords: ["saas", "منصة", "إدارة"], icon: Building2 },
  { hash: "platform-admin", label: "إدارة المؤسس", labelEn: "Platform Admin", keywords: ["platform", "admin", "مؤسس", "إدارة"], icon: Shield },
  { hash: "audit", label: "سجل التدقيق", labelEn: "Audit", keywords: ["audit", "تدقيق", "سجل"], icon: History },
];

// ─── Quick actions ──────────────────────────────────────────────────────────

interface QuickAction {
  id: string;
  label: string;
  keywords: string[];
  hash: string;
  eventDetail: { type: string };
  icon: React.ComponentType<{ size?: number; className?: string; style?: React.CSSProperties }>;
}

const QUICK_ACTIONS: QuickAction[] = [
  {
    id: "new-invoice",
    label: "فاتورة جديدة",
    keywords: ["فاتورة", "جديدة", "new", "invoice", "create", "إنشاء"],
    hash: "invoices",
    eventDetail: { type: "new-invoice" },
    icon: Plus,
  },
  {
    id: "new-client",
    label: "عميل جديد",
    keywords: ["عميل", "جديد", "new", "client", "create", "إنشاء"],
    hash: "clients",
    eventDetail: { type: "new-client" },
    icon: Plus,
  },
  {
    id: "bulk-input",
    label: "إدخال مجمع بالـ AI",
    keywords: ["إدخال", "مجمع", "ذكاء", "bulk", "ai"],
    hash: "bulk-input",
    eventDetail: { type: "open-bulk" },
    icon: Sparkles,
  },
];

// ─── Result types ───────────────────────────────────────────────────────────

type ResultSection = "navigation" | "actions" | "invoices" | "clients";

interface BaseResult {
  id: string;
  section: ResultSection;
  label: string;
  sublabel?: string;
  icon: React.ComponentType<{ size?: number; className?: string; style?: React.CSSProperties }>;
  onSelect: () => void;
}

interface InvoiceHit { id: number; invoiceNumber: string; clientName: string; total?: string | number; status?: string; }
interface ClientHit { id: number; name: string; phone?: string | null; }

// ─── Component ──────────────────────────────────────────────────────────────

export function CommandPalette({ open, onClose }: CommandPaletteProps) {
  const { activeCompany } = useBrand();
  const [query, setQuery] = useState("");
  const [selectedIndex, setSelectedIndex] = useState(0);
  const [loading, setLoading] = useState(false);
  const [invoiceHits, setInvoiceHits] = useState<InvoiceHit[]>([]);
  const [clientHits, setClientHits] = useState<ClientHit[]>([]);
  const inputRef = useRef<HTMLInputElement>(null);
  const listRef = useRef<HTMLDivElement>(null);

  // Reset internal state when the palette opens (render-time adjustment, no cascading render).
  const [prevOpen, setPrevOpen] = useState(open);
  if (open !== prevOpen) {
    setPrevOpen(open);
    if (open) {
      setQuery("");
      setSelectedIndex(0);
      setInvoiceHits([]);
      setClientHits([]);
    }
  }

  // Focus input on next tick when palette opens (side effect kept in useEffect)
  useEffect(() => {
    if (open) {
      setTimeout(() => inputRef.current?.focus(), 30);
    }
  }, [open]);

  // ─── Debounced search against API (only for >=2 chars) ───────────────────
  // Sync state adjustments when search conditions change (render-time, no cascading render).
  const searchQuery = query.trim();
  const searchActive = open && searchQuery.length >= 2 && !!activeCompany?.slug;
  const searchKey = `${open ? 1 : 0}|${searchQuery}|${activeCompany?.slug || ""}`;
  const [prevSearchKey, setPrevSearchKey] = useState(searchKey);
  if (searchKey !== prevSearchKey) {
    setPrevSearchKey(searchKey);
    if (!searchActive) {
      setInvoiceHits([]);
      setClientHits([]);
      setLoading(false);
    } else {
      setLoading(true);
    }
  }

  useEffect(() => {
    if (!searchActive || !activeCompany?.slug) return;
    const slug = activeCompany.slug;
    const q = searchQuery;
    const controller = new AbortController();
    const t = setTimeout(async () => {
      try {
        const [invRes, cliRes] = await Promise.all([
          authedFetch(`/api/invoices?companySlug=${encodeURIComponent(slug)}&search=${encodeURIComponent(q)}&limit=5`, { signal: controller.signal }),
          authedFetch(`/api/clients?companySlug=${encodeURIComponent(slug)}&search=${encodeURIComponent(q)}`, { signal: controller.signal }),
        ]);
        if (controller.signal.aborted) return;
        const inv = invRes.ok ? await invRes.json() : { invoices: [] };
        const cli = cliRes.ok ? await cliRes.json() : { clients: [] };
        setInvoiceHits((inv.invoices || []).slice(0, 5));
        setClientHits((cli.clients || []).slice(0, 5));
      } catch (err) {
        if ((err as Error).name !== 'AbortError') {
          setInvoiceHits([]);
          setClientHits([]);
        }
      } finally {
        if (!controller.signal.aborted) setLoading(false);
      }
    }, 220);
    return () => { controller.abort(); clearTimeout(t); };
  }, [searchActive, searchQuery, activeCompany]);

  const navigate = useCallback((hash: string, eventDetail?: { type: string }) => {
    window.location.hash = hash;
    if (eventDetail) {
      // Dispatch after the hash change so the target view has mounted
      setTimeout(() => {
        window.dispatchEvent(new CustomEvent("garfix:quick-action", { detail: eventDetail }));
      }, 80);
    }
    onClose();
  }, [onClose]);

  // ─── Build the flat results list ─────────────────────────────────────────
  const results: BaseResult[] = useMemo(() => {
    const q = query.trim().toLowerCase();
    const out: BaseResult[] = [];

    // Navigation matches (empty query → show all)
    const navMatches = q.length === 0
      ? NAV_ITEMS
      : NAV_ITEMS.filter((n) =>
          n.label.toLowerCase().includes(q) ||
          n.labelEn.toLowerCase().includes(q) ||
          n.keywords.some((k) => k.toLowerCase().includes(q) || q.includes(k.toLowerCase())),
        );
    for (const n of navMatches) {
      out.push({
        id: `nav-${n.hash}`,
        section: "navigation",
        label: n.label,
        sublabel: n.labelEn,
        icon: n.icon,
        onSelect: () => navigate(n.hash),
      });
    }

    // Quick actions
    const actionMatches = q.length === 0
      ? QUICK_ACTIONS
      : QUICK_ACTIONS.filter((a) =>
          a.label.toLowerCase().includes(q) ||
          a.keywords.some((k) => k.toLowerCase().includes(q) || q.includes(k.toLowerCase())),
        );
    for (const a of actionMatches) {
      out.push({
        id: `act-${a.id}`,
        section: "actions",
        label: a.label,
        sublabel: "إجراء سريع",
        icon: a.icon,
        onSelect: () => navigate(a.hash, a.eventDetail),
      });
    }

    // Search hits (only when query has 2+ chars)
    if (q.length >= 2) {
      for (const inv of invoiceHits) {
        out.push({
          id: `inv-${inv.id}`,
          section: "invoices",
          label: inv.invoiceNumber,
          sublabel: inv.clientName,
          icon: FileText,
          onSelect: () => navigate("invoices"),
        });
      }
      for (const c of clientHits) {
        out.push({
          id: `cli-${c.id}`,
          section: "clients",
          label: c.name,
          sublabel: c.phone || "عميل",
          icon: Users,
          onSelect: () => navigate("clients"),
        });
      }
    }

    return out;
  }, [query, invoiceHits, clientHits, navigate]);

  // Clamp selection when results shrink (render-time adjustment, no cascading render).
  const [prevResultsLen, setPrevResultsLen] = useState(results.length);
  if (results.length !== prevResultsLen) {
    setPrevResultsLen(results.length);
    if (selectedIndex >= results.length) setSelectedIndex(0);
  }

  // Scroll selected item into view
  useEffect(() => {
    if (!open) return;
    const el = listRef.current?.querySelector(`[data-idx="${selectedIndex}"]`) as HTMLElement | null;
    el?.scrollIntoView({ block: "nearest" });
  }, [selectedIndex, open]);

  // ─── Keyboard navigation ─────────────────────────────────────────────────
  const onKeyDown = (e: React.KeyboardEvent<HTMLInputElement>) => {
    if (e.key === "ArrowDown") {
      e.preventDefault();
      setSelectedIndex((i) => Math.min(i + 1, Math.max(results.length - 1, 0)));
    } else if (e.key === "ArrowUp") {
      e.preventDefault();
      setSelectedIndex((i) => Math.max(i - 1, 0));
    } else if (e.key === "Enter") {
      e.preventDefault();
      const r = results[selectedIndex];
      if (r) r.onSelect();
    } else if (e.key === "Escape") {
      e.preventDefault();
      onClose();
    }
  };

  if (!open) return null;

  // Group results by section for rendering
  const sectionLabels: Record<ResultSection, string> = {
    navigation: "التنقل",
    actions: "إجراءات سريعة",
    invoices: "الفواتير",
    clients: "العملاء",
  };
  const sectionOrder: ResultSection[] = ["navigation", "actions", "invoices", "clients"];

  let flatIdx = -1;
  const isEmpty = results.length === 0;

  return (
    <div
      dir="rtl"
      onClick={onClose}
      className="fixed inset-0 z-[9999] bg-[rgba(8,8,16,0.55)] backdrop-blur-[6px] flex items-start justify-center pt-[8vh] px-4 pb-4"
    >
      <div
        onClick={(e) => e.stopPropagation()}
        className="w-[min(640px,100%)] max-h-[70vh] flex flex-col rounded-2xl overflow-hidden border border-white/[0.08] bg-[linear-gradient(180deg,#1a1a2e_0%,#16162a_60%,#12121f_100%)] shadow-[0_24px_80px_rgba(0,0,0,0.55),0_0_0_1px_rgba(124,58,237,0.18)] text-[#f5f5fa] font-[inherit]"
      >
        {/* Search input */}
        <div
          className="flex items-center gap-[10px] py-[14px] px-4 border-b border-white/[0.06] bg-[rgba(124,58,237,0.06)]"
        >
          <Search size={18} className="text-[#a78bfa] shrink-0" />
          <input
            ref={inputRef}
            type="text"
            value={query}
            onChange={(e) => { setQuery(e.target.value); setSelectedIndex(0); }}
            onKeyDown={onKeyDown}
            placeholder="ابحث عن صفحة، إجراء، فاتورة أو عميل… (مثال: فوا)"
            className="flex-1 bg-transparent border-none outline-none text-[#f5f5fa] text-[15px] font-[inherit] [direction:rtl]"
          />
          <button
            onClick={onClose}
            title="إغلاق (Esc)"
            className="bg-white/[0.06] border-none text-[#9ca3af] cursor-pointer rounded-md p-1 flex items-center"
          >
            <X size={14} />
          </button>
        </div>

        {/* Results */}
        <div
          ref={listRef}
          className="overflow-y-auto flex-1 p-[6px] garfix-scroll"
        >
          {loading && (
            <div className="p-5 text-center text-[13px] text-[#9ca3af]">
              جارٍ البحث…
            </div>
          )}

          {!loading && isEmpty && (
            <div className="py-8 px-5 text-center text-[#9ca3af]">
              <Search size={28} className="opacity-40 mb-2" />
              <div className="text-[13px]">
                {query.trim().length === 0
                  ? "ابدأ بالكتابة للبحث أو اختر من القائمة"
                  : "لا توجد نتائج مطابقة"}
              </div>
            </div>
          )}

          {!loading && !isEmpty && sectionOrder.map((section) => {
            const sectionResults = results.filter((r) => r.section === section);
            if (sectionResults.length === 0) return null;
            return (
              <div key={section} className="mb-1">
                <div
                  className="pt-2 px-3 pb-1 text-[10px] font-extrabold text-[#7c3aed] uppercase tracking-[0.6px]"
                >
                  {sectionLabels[section]}
                </div>
                {sectionResults.map((r) => {
                  flatIdx += 1;
                  const idx = flatIdx;
                  const isSelected = idx === selectedIndex;
                  const Icon = r.icon;
                  return (
                    <button
                      key={r.id}
                      data-idx={idx}
                      onClick={() => r.onSelect()}
                      onMouseEnter={() => setSelectedIndex(idx)}
                      className={`w-full flex items-center gap-[10px] py-[9px] px-3 rounded-[10px] ${isSelected ? "bg-[rgba(124,58,237,0.18)]" : "bg-transparent"} border-none font-[inherit] text-[13px] cursor-pointer text-right transition-[background_120ms_ease] ${isSelected ? "text-[#f5f5fa]" : "text-[#cbd5e1]"}`}
                    >
                      <Icon size={15} className={`shrink-0 ${isSelected ? "text-[#a78bfa]" : "text-[#6b7280]"}`} />
                      <div className="flex-1 min-w-0">
                        <div className={`font-semibold truncate ${r.section === "invoices" ? "[direction:ltr] text-left font-mono" : "text-right font-[inherit]"}`}>
                          {r.label}
                        </div>
                        {r.sublabel && (
                          <div className="text-[11px] text-[#9ca3af] truncate">
                            {r.sublabel}
                          </div>
                        )}
                      </div>
                      {isSelected && (
                        <CornerDownLeft size={13} className="text-[#a78bfa] shrink-0" />
                      )}
                    </button>
                  );
                })}
              </div>
            );
          })}
        </div>

        {/* Footer hint */}
        <div
          className="py-2 px-[14px] border-t border-white/[0.06] bg-[rgba(0,0,0,0.2)] flex items-center justify-between text-[10px] text-[#6b7280] gap-2 flex-wrap"
        >
          <div className="flex items-center gap-3">
            <span className="inline-flex items-center gap-1">
              <Kbd><ArrowUp size={9} /><ArrowDown size={9} /></Kbd>
              تنقل
            </span>
            <span className="inline-flex items-center gap-1">
              <Kbd>Enter</Kbd>
              اختيار
            </span>
            <span className="inline-flex items-center gap-1">
              <Kbd>Esc</Kbd>
              إغلاق
            </span>
          </div>
          <span className="text-[#7c3aed] font-bold">GarfiX ⌘K</span>
        </div>
      </div>
    </div>
  );
}

function Kbd({ children }: { children: React.ReactNode }) {
  return (
    <kbd
      className="bg-white/[0.08] border border-white/[0.12] rounded py-[1px] px-[5px] text-[10px] font-mono text-[#cbd5e1] inline-flex items-center gap-[2px] min-w-[16px] justify-center"
    >
      {children}
    </kbd>
  );
}

export default CommandPalette;

/**
 * DataTable — Reusable table component with search, pagination, and responsive layout.
 */
"use client";

import { useState, useEffect, useCallback, useRef } from "react";
import { authedFetch } from "@/context/AuthContext";
import { Search, ChevronLeft, Inbox } from "lucide-react";
import { cn } from "@/lib/utils";

export interface Column<T = Record<string, unknown>> {
  key: string;
  label: string;
  render?: (row: T) => React.ReactNode;
  sortable?: boolean;
  width?: string;
  mobileHidden?: boolean;
}

interface DataTableProps {
  columns: Column[];
  fetchUrl: string;
  fetchParams?: Record<string, string | number | boolean | undefined>;
  rowKey: string;
  onRowClick?: (row: Record<string, unknown>) => void;
  searchPlaceholder?: string;
  searchFields?: string[];
  pageSize?: number;
  emptyMessage?: string;
  actions?: React.ReactNode;
}

export function DataTable({
  columns, fetchUrl, fetchParams = {}, rowKey, onRowClick,
  searchPlaceholder = "بحث...",
  searchFields = [],
  pageSize = 20,
  emptyMessage = "لا توجد بيانات",
  actions,
}: DataTableProps) {
  const [rows, setRows] = useState<Record<string, unknown>[]>([]);
  const [loading, setLoading] = useState(true);
  const [search, setSearch] = useState("");
  const [hasMore, setHasMore] = useState(false);
  const [totalCount, setTotalCount] = useState<number | null>(null);
  const debounceRef = useRef<ReturnType<typeof setTimeout> | null>(null);

  // Extract fetchParams serialization to a stable primitive so it can be used in dependency arrays.
  const fetchParamsKey = JSON.stringify(fetchParams);

  const fetchData = useCallback(async (signal?: AbortSignal) => {
    setLoading(true);
    try {
      const params = new URLSearchParams();
      Object.entries(fetchParams).forEach(([k, v]) => {
        if (v !== undefined && v !== null) params.set(k, String(v));
      });
      if (search && searchFields.length > 0) params.set("search", search);
      params.set("limit", String(pageSize));

      const res = await authedFetch(`${fetchUrl}?${params.toString()}`, signal ? { signal } : undefined);
      if (res.ok) {
        const data = await res.json();
        const newRows = data.rows || data.invoices || data.clients || data.products || data.employees || data.logs || data.tenants || data.users || data.tickets || data.announcements || data.entries || data.accounts || data.notifications || data.backups || data.companies || data.salaries || data.attendance || data.commissions || data.leaves || data.performance || [];
        const newTotal = data.total ?? data.totalCount ?? null;
        setRows(newRows);
        setHasMore(newRows.length === pageSize);
        setTotalCount(newTotal);
      }
    } catch (err) {
      if ((err as Error).name !== 'AbortError') console.error("[DataTable] fetch failed:", err);
    } finally {
      setLoading(false);
    }
  }, [fetchUrl, fetchParamsKey, search, searchFields, pageSize]);

  useEffect(() => {
    const controller = new AbortController();
    // setState runs inside async .then() callback in fetchData (after await authedFetch) — not synchronous in effect body; no cascading render.
    // eslint-disable-next-line react-hooks/set-state-in-effect
    fetchData(controller.signal);
    return () => controller.abort();
  }, [fetchUrl, fetchParamsKey, fetchData]);

  useEffect(() => {
    const controller = new AbortController();
    if (debounceRef.current) clearTimeout(debounceRef.current);
    debounceRef.current = setTimeout(() => fetchData(controller.signal), 400);
    return () => { controller.abort(); if (debounceRef.current) clearTimeout(debounceRef.current); };
  }, [search, fetchData]);

  const inputClass = "w-full py-2 pr-9 pl-3 rounded-lg bg-[var(--background)] border border-[var(--border)] text-[var(--foreground)] font-inherit text-[13px] outline-none";
  const thClass = "text-end px-3 py-2.5 text-[11px] text-[var(--muted-foreground)] font-bold";
  const tdClass = "px-3 py-2.5 text-[13px]";

  return (
    <div className="overflow-x-auto">
      {(searchFields.length > 0 || actions) && (
        <div className="flex gap-2 md:gap-[10px] mb-3 md:mb-[12px] flex-wrap">
          {searchFields.length > 0 && (
            <div className="relative flex-1 min-w-[180px] md:min-w-[200px]">
              <Search size={14} className="absolute end-3 top-1/2 -translate-y-1/2 text-muted-foreground pointer-events-none" />
              <input value={search} onChange={(e) => setSearch(e.target.value)} placeholder={searchPlaceholder} className={inputClass} />
            </div>
          )}
          {actions}
        </div>
      )}

      {loading && rows.length === 0 ? (
        <div className="p-8 md:p-12 text-center text-muted-foreground">جارٍ التحميل...</div>
      ) : rows.length === 0 ? (
        <div className="p-8 md:p-12 text-center text-muted-foreground">
          <Inbox size={32} className="opacity-30 mb-2" />
          <div>{emptyMessage}</div>
        </div>
      ) : (
        <>
          <div className="overflow-x-auto garfix-scroll">
            <table className="w-full border-collapse min-w-[480px] md:min-w-0">
              <thead>
                <tr className="bg-[var(--muted)]">
                  {columns.map((col) => (
                    <th scope="col" key={col.key} className={cn(thClass, col.width && `[width:${col.width}]`)}>{col.label}</th>
                  ))}
                </tr>
              </thead>
              <tbody>
                {rows.map((row, idx) => (
                  <tr
                    key={String(row[rowKey] ?? idx)}
                    onClick={() => onRowClick?.(row)}
                    className={cn("border-b border-[var(--border)]", onRowClick ? "cursor-pointer" : "cursor-default")}
                  >
                    {columns.map((col) => (
                      <td key={col.key} className={tdClass}>
                        {col.render ? col.render(row) : String(row[col.key] ?? "—")}
                      </td>
                    ))}
                  </tr>
                ))}
              </tbody>
            </table>
          </div>

          <div className="flex justify-between items-center mt-3 md:mt-[12px] text-xs md:text-[12px] text-muted-foreground">
            <span>{rows.length} {totalCount ? `من ${totalCount}` : ""} سجل</span>
            {hasMore && (
              <button
                onClick={() => fetchData()}
                disabled={loading}
                className="inline-flex items-center gap-1 py-1.5 px-3.5 rounded-lg bg-[var(--muted)] text-[var(--foreground)] border border-[var(--border)] font-inherit text-xs font-bold cursor-pointer disabled:opacity-60 disabled:cursor-not-allowed"
              >
                {loading ? "..." : "تحميل المزيد"} {!loading && <ChevronLeft size={12} />}
              </button>
            )}
          </div>
        </>
      )}
    </div>
  );
}

export default DataTable;

"use client"

import * as React from "react"
import useEmblaCarousel, {
  type UseEmblaCarouselType,
} from "embla-carousel-react"
import { ArrowLeft, ArrowRight } from "lucide-react"

import { cn } from "@/lib/utils"
import { Button } from "@/components/ui/button"

type CarouselApi = UseEmblaCarouselType[1]
type UseCarouselParameters = Parameters<typeof useEmblaCarousel>
type CarouselOptions = UseCarouselParameters[0]
type CarouselPlugin = UseCarouselParameters[1]

type CarouselProps = {
  opts?: CarouselOptions
  plugins?: CarouselPlugin
  orientation?: "horizontal" | "vertical"
  setApi?: (api: CarouselApi) => void
}

type CarouselContextProps = {
  carouselRef: ReturnType<typeof useEmblaCarousel>[0]
  api: ReturnType<typeof useEmblaCarousel>[1]
  scrollPrev: () => void
  scrollNext: () => void
  canScrollPrev: boolean
  canScrollNext: boolean
} & CarouselProps

const CarouselContext = React.createContext<CarouselContextProps | null>(null)

function useCarousel() {
  const context = React.useContext(CarouselContext)

  if (!context) {
    throw new Error("useCarousel must be used within a <Carousel />")
  }

  return context
}

function Carousel({
  orientation = "horizontal",
  opts,
  setApi,
  plugins,
  className,
  children,
  ...props
}: React.ComponentProps<"div"> & CarouselProps) {
  const [carouselRef, api] = useEmblaCarousel(
    {
      ...opts,
      axis: orientation === "horizontal" ? "x" : "y",
    },
    plugins
  )
  const [canScrollPrev, setCanScrollPrev] = React.useState(false)
  const [canScrollNext, setCanScrollNext] = React.useState(false)

  const onSelect = React.useCallback((api: CarouselApi) => {
    if (!api) return
    setCanScrollPrev(api.canScrollPrev())
    setCanScrollNext(api.canScrollNext())
  }, [])

  const scrollPrev = React.useCallback(() => {
    api?.scrollPrev()
  }, [api])

  const scrollNext = React.useCallback(() => {
    api?.scrollNext()
  }, [api])

  const handleKeyDown = React.useCallback(
    (event: React.KeyboardEvent<HTMLDivElement>) => {
      if (event.key === "ArrowLeft") {
        event.preventDefault()
        scrollPrev()
      } else if (event.key === "ArrowRight") {
        event.preventDefault()
        scrollNext()
      }
    },
    [scrollPrev, scrollNext]
  )

  React.useEffect(() => {
    if (!api || !setApi) return
    setApi(api)
  }, [api, setApi])

  React.useEffect(() => {
    if (!api) return
    onSelect(api)
    api.on("reInit", onSelect)
    api.on("select", onSelect)

    return () => {
      api?.off("select", onSelect)
    }
  }, [api, onSelect])

  return (
    <CarouselContext.Provider
      value={{
        carouselRef,
        api: api,
        opts,
        orientation:
          orientation || (opts?.axis === "y" ? "vertical" : "horizontal"),
        scrollPrev,
        scrollNext,
        canScrollPrev,
        canScrollNext,
      }}
    >
      <div
        onKeyDownCapture={handleKeyDown}
        className={cn("relative", className)}
        role="region"
        aria-roledescription="carousel"
        data-slot="carousel"
        {...props}
      >
        {children}
      </div>
    </CarouselContext.Provider>
  )
}

function CarouselContent({ className, ...props }: React.ComponentProps<"div">) {
  const { carouselRef, orientation } = useCarousel()

  return (
    <div
      ref={carouselRef}
      className="overflow-hidden"
      data-slot="carousel-content"
    >
      <div
        className={cn(
          "flex",
          orientation === "horizontal" ? "-ml-4" : "-mt-4 flex-col",
          className
        )}
        {...props}
      />
    </div>
  )
}

function CarouselItem({ className, ...props }: React.ComponentProps<"div">) {
  const { orientation } = useCarousel()

  return (
    <div
      role="group"
      aria-roledescription="slide"
      data-slot="carousel-item"
      className={cn(
        "min-w-0 shrink-0 grow-0 basis-full",
        orientation === "horizontal" ? "pl-4" : "pt-4",
        className
      )}
      {...props}
    />
  )
}

function CarouselPrevious({
  className,
  variant = "outline",
  size = "icon",
  ...props
}: React.ComponentProps<typeof Button>) {
  const { orientation, scrollPrev, canScrollPrev } = useCarousel()

  return (
    <Button
      data-slot="carousel-previous"
      variant={variant}
      size={size}
      className={cn(
        "absolute size-8 rounded-full",
        orientation === "horizontal"
          ? "top-1/2 -left-12 -translate-y-1/2"
          : "-top-12 left-1/2 -translate-x-1/2 rotate-90",
        className
      )}
      disabled={!canScrollPrev}
      onClick={scrollPrev}
      {...props}
    >
      <ArrowLeft />
      <span className="sr-only">Previous slide</span>
    </Button>
  )
}

function CarouselNext({
  className,
  variant = "outline",
  size = "icon",
  ...props
}: React.ComponentProps<typeof Button>) {
  const { orientation, scrollNext, canScrollNext } = useCarousel()

  return (
    <Button
      data-slot="carousel-next"
      variant={variant}
      size={size}
      className={cn(
        "absolute size-8 rounded-full",
        orientation === "horizontal"
          ? "top-1/2 -right-12 -translate-y-1/2"
          : "-bottom-12 left-1/2 -translate-x-1/2 rotate-90",
        className
      )}
      disabled={!canScrollNext}
      onClick={scrollNext}
      {...props}
    >
      <ArrowRight />
      <span className="sr-only">Next slide</span>
    </Button>
  )
}

export {
  type CarouselApi,
  Carousel,
  CarouselContent,
  CarouselItem,
  CarouselPrevious,
  CarouselNext,
}

"use client"

import * as React from "react"
import * as RechartsPrimitive from "recharts"

import { cn } from "@/lib/utils"

// Format: { THEME_NAME: CSS_SELECTOR }
const THEMES = { light: "", dark: ".dark" } as const

export type ChartConfig = {
  [k in string]: {
    label?: React.ReactNode
    icon?: React.ComponentType
  } & (
    | { color?: string; theme?: never }
    | { color?: never; theme: Record<keyof typeof THEMES, string> }
  )
}

type ChartContextProps = {
  config: ChartConfig
}

const ChartContext = React.createContext<ChartContextProps | null>(null)

function useChart() {
  const context = React.useContext(ChartContext)

  if (!context) {
    throw new Error("useChart must be used within a <ChartContainer />")
  }

  return context
}

function ChartContainer({
  id,
  className,
  children,
  config,
  ...props
}: React.ComponentProps<"div"> & {
  config: ChartConfig
  children: React.ComponentProps<
    typeof RechartsPrimitive.ResponsiveContainer
  >["children"]
}) {
  const uniqueId = React.useId()
  const chartId = `chart-${id || uniqueId.replace(/:/g, "")}`

  return (
    <ChartContext.Provider value={{ config }}>
      <div
        data-slot="chart"
        data-chart={chartId}
        className={cn(
          "[&_.recharts-cartesian-axis-tick_text]:fill-muted-foreground [&_.recharts-cartesian-grid_line[stroke='#ccc']]:stroke-border/50 [&_.recharts-curve.recharts-tooltip-cursor]:stroke-border [&_.recharts-polar-grid_[stroke='#ccc']]:stroke-border [&_.recharts-radial-bar-background-sector]:fill-muted [&_.recharts-rectangle.recharts-tooltip-cursor]:fill-muted [&_.recharts-reference-line_[stroke='#ccc']]:stroke-border flex aspect-video justify-center text-xs [&_.recharts-dot[stroke='#fff']]:stroke-transparent [&_.recharts-layer]:outline-hidden [&_.recharts-sector]:outline-hidden [&_.recharts-sector[stroke='#fff']]:stroke-transparent [&_.recharts-surface]:outline-hidden",
          className
        )}
        {...props}
      >
        <ChartStyle id={chartId} config={config} />
        <RechartsPrimitive.ResponsiveContainer>
          {children}
        </RechartsPrimitive.ResponsiveContainer>
      </div>
    </ChartContext.Provider>
  )
}

const ChartStyle = ({ id, config }: { id: string; config: ChartConfig }) => {
  const colorConfig = Object.entries(config).filter(
    ([, config]) => config.theme || config.color
  )

  if (!colorConfig.length) {
    return null
  }

  return (
    <style
      dangerouslySetInnerHTML={{
        __html: Object.entries(THEMES)
          .map(
            ([theme, prefix]) => `
${prefix} [data-chart=${id}] {
${colorConfig
  .map(([key, itemConfig]) => {
    const color =
      itemConfig.theme?.[theme as keyof typeof itemConfig.theme] ||
      itemConfig.color
    return color ? `  --color-${key}: ${color};` : null
  })
  .join("\n")}
}
`
          )
          .join("\n"),
      }}
    />
  )
}

const ChartTooltip = RechartsPrimitive.Tooltip

function ChartTooltipContent({
  active,
  payload,
  className,
  indicator = "dot",
  hideLabel = false,
  hideIndicator = false,
  label,
  labelFormatter,
  labelClassName,
  formatter,
  color,
  nameKey,
  labelKey,
}: React.ComponentProps<typeof RechartsPrimitive.Tooltip> &
  React.ComponentProps<"div"> & {
    hideLabel?: boolean
    hideIndicator?: boolean
    indicator?: "line" | "dot" | "dashed"
    nameKey?: string
    labelKey?: string
  }) {
  const { config } = useChart()

  const tooltipLabel = React.useMemo(() => {
    if (hideLabel || !payload?.length) {
      return null
    }

    const [item] = payload
    const key = `${labelKey || item?.dataKey || item?.name || "value"}`
    const itemConfig = getPayloadConfigFromPayload(config, item, key)
    const value =
      !labelKey && typeof label === "string"
        ? config[label as keyof typeof config]?.label || label
        : itemConfig?.label

    if (labelFormatter) {
      return (
        <div className={cn("font-medium", labelClassName)}>
          {labelFormatter(value, payload)}
        </div>
      )
    }

    if (!value) {
      return null
    }

    return <div className={cn("font-medium", labelClassName)}>{value}</div>
  }, [
    label,
    labelFormatter,
    payload,
    hideLabel,
    labelClassName,
    config,
    labelKey,
  ])

  if (!active || !payload?.length) {
    return null
  }

  const nestLabel = payload.length === 1 && indicator !== "dot"

  return (
    <div
      className={cn(
        "border-border/50 bg-background grid min-w-[8rem] items-start gap-1.5 rounded-lg border px-2.5 py-1.5 text-xs shadow-xl",
        className
      )}
    >
      {!nestLabel ? tooltipLabel : null}
      <div className="grid gap-1.5">
        {payload.map((item, index) => {
          const key = `${nameKey || item.name || item.dataKey || "value"}`
          const itemConfig = getPayloadConfigFromPayload(config, item, key)
          const indicatorColor = color || item.payload.fill || item.color

          return (
            <div
              key={item.dataKey}
              className={cn(
                "[&>svg]:text-muted-foreground flex w-full flex-wrap items-stretch gap-2 [&>svg]:h-2.5 [&>svg]:w-2.5",
                indicator === "dot" && "items-center"
              )}
            >
              {formatter && item?.value !== undefined && item.name ? (
                formatter(item.value, item.name, item, index, item.payload)
              ) : (
                <>
                  {itemConfig?.icon ? (
                    <itemConfig.icon />
                  ) : (
                    !hideIndicator && (
                      <div
                        className={cn(
                          "shrink-0 rounded-[2px] border-(--color-border) bg-(--color-bg)",
                          {
                            "h-2.5 w-2.5": indicator === "dot",
                            "w-1": indicator === "line",
                            "w-0 border-[1.5px] border-dashed bg-transparent":
                              indicator === "dashed",
                            "my-0.5": nestLabel && indicator === "dashed",
                          }
                        )}
                        style={
                          {
                            "--color-bg": indicatorColor,
                            "--color-border": indicatorColor,
                          } as React.CSSProperties
                        } /* TAILWINDBREAK: dynamic CSS custom properties for chart indicator colors */
                      />
                    )
                  )}
                  <div
                    className={cn(
                      "flex flex-1 justify-between leading-none",
                      nestLabel ? "items-end" : "items-center"
                    )}
                  >
                    <div className="grid gap-1.5">
                      {nestLabel ? tooltipLabel : null}
                      <span className="text-muted-foreground">
                        {itemConfig?.label || item.name}
                      </span>
                    </div>
                    {item.value && (
                      <span className="text-foreground font-mono font-medium tabular-nums">
                        {item.value.toLocaleString()}
                      </span>
                    )}
                  </div>
                </>
              )}
            </div>
          )
        })}
      </div>
    </div>
  )
}

const ChartLegend = RechartsPrimitive.Legend

function ChartLegendContent({
  className,
  hideIcon = false,
  payload,
  verticalAlign = "bottom",
  nameKey,
}: React.ComponentProps<"div"> &
  Pick<RechartsPrimitive.LegendProps, "payload" | "verticalAlign"> & {
    hideIcon?: boolean
    nameKey?: string
  }) {
  const { config } = useChart()

  if (!payload?.length) {
    return null
  }

  return (
    <div
      className={cn(
        "flex items-center justify-center gap-4",
        verticalAlign === "top" ? "pb-3" : "pt-3",
        className
      )}
    >
      {payload.map((item) => {
        const key = `${nameKey || item.dataKey || "value"}`
        const itemConfig = getPayloadConfigFromPayload(config, item, key)

        return (
          <div
            key={item.value}
            className={cn(
              "[&>svg]:text-muted-foreground flex items-center gap-1.5 [&>svg]:h-3 [&>svg]:w-3"
            )}
          >
            {itemConfig?.icon && !hideIcon ? (
              <itemConfig.icon />
            ) : (
              <div
                className="h-2 w-2 shrink-0 rounded-[2px]"
                style={{
                  backgroundColor: item.color,
                }} /* TAILWINDBREAK: dynamic chart item color from recharts payload */
              />
            )}
            {itemConfig?.label}
          </div>
        )
      })}
    </div>
  )
}

// Helper to extract item config from a payload.
function getPayloadConfigFromPayload(
  config: ChartConfig,
  payload: unknown,
  key: string
) {
  if (typeof payload !== "object" || payload === null) {
    return undefined
  }

  const payloadPayload =
    "payload" in payload &&
    typeof payload.payload === "object" &&
    payload.payload !== null
      ? payload.payload
      : undefined

  let configLabelKey: string = key

  if (
    key in payload &&
    typeof payload[key as keyof typeof payload] === "string"
  ) {
    configLabelKey = payload[key as keyof typeof payload] as string
  } else if (
    payloadPayload &&
    key in payloadPayload &&
    typeof payloadPayload[key as keyof typeof payloadPayload] === "string"
  ) {
    configLabelKey = payloadPayload[
      key as keyof typeof payloadPayload
    ] as string
  }

  return configLabelKey in config
    ? config[configLabelKey]
    : config[key as keyof typeof config]
}

export {
  ChartContainer,
  ChartTooltip,
  ChartTooltipContent,
  ChartLegend,
  ChartLegendContent,
  ChartStyle,
}

