    for (let i = 0; i < 10; i++) {
      expect(companies[i].id).toBe(String(i + 1).padStart(8, '0'));
    }
  });

  it('sample check: last company has ID 1000', () => {
    expect(companies[999].id).toBe(String(1000).padStart(8, '0'));
  });
});

