/**
 * logger.ts — Structured logger (replaces console.log across the codebase).
 *
 * Levels: debug, info, warn, error, fatal.
 * Output: JSON to stdout for production, pretty-printed in dev.
 *
 * Uses console.* methods (which Next.js routes work with across Node + Edge
 * runtimes) instead of process.stdout.write — same performance, better
 * runtime compatibility.
 *
 * Signature: `(message: string, meta?: LogMeta)` — message first, meta second.
 * This was previously documented backwards in this same file, which caused
 * the 92 caller files to copy the wrong order. The order is now correct here
 * and the callers are being fixed in a separate mechanical pass.
 *
 * Usage:
 *   import { logger } from "@/lib/logger";
 *   logger.info("user logged in", { userId, action });
 *   logger.error("request failed", { err, route });
 */

type Level = "debug" | "info" | "warn" | "error" | "fatal";

interface LogMeta {
  [key: string]: unknown;
}

const LEVEL_PRIORITY: Record<Level, number> = {
  debug: 10,
  info: 20,
  warn: 30,
  error: 40,
  fatal: 50,
};

const MIN_LEVEL: Level = (process.env.LOG_LEVEL as Level) || (process.env.NODE_ENV === "production" ? "info" : "debug");

const REDACT_KEYS = new Set([
  "password",
  "passwordHash",
  "token",
  "accessToken",
  "refreshToken",
  "secret",
  "authorization",
  "cookie",
  "set-cookie",
  "apiKey",
  "openrouterApiKey",
]);

const EMAIL_RE = /[A-Za-z0-9._%+-]+@([A-Za-z0-9.-]+\.[A-Za-z]{2,})/;

function redactMeta(meta: LogMeta): LogMeta {
  const result: LogMeta = {};
  for (const key of Object.keys(meta)) {
    if (REDACT_KEYS.has(key.toLowerCase())) {
      result[key] = "[REDACTED]";
      continue;
    }
    const value = meta[key];
    if (typeof value === "string") {
      result[key] = value.replace(EMAIL_RE, (match, domain) => {
        const local = match.substring(0, match.indexOf("@"));
        return local[0] + "***@" + domain;
      });
    } else if (value !== null && typeof value === "object" && !Array.isArray(value)) {
      result[key] = redactMeta(value as LogMeta);
    } else if (Array.isArray(value)) {
      result[key] = value.map((item) =>
        item !== null && typeof item === "object" ? redactMeta(item as LogMeta) : item,
      );
    } else {
      result[key] = value;
    }
  }
  return result;
}

function shouldLog(level: Level): boolean {
  return LEVEL_PRIORITY[level] >= LEVEL_PRIORITY[MIN_LEVEL];
}

function format(level: Level, msg: string, meta?: LogMeta): string {
  const ts = new Date().toISOString();
  // Extract requestId from meta and place it at the top level for easy correlation
  const requestId = meta?.requestId as string | undefined;
  const base: Record<string, unknown> = { ts, level, msg };
  if (requestId) base.requestId = requestId;
  const redactedMeta = meta ? redactMeta(meta) : undefined;
  // Remove requestId from data section since it's already at top level
  const filteredMeta = redactedMeta && requestId
    ? (() => { const m = { ...redactedMeta }; delete m.requestId; return Object.keys(m).length > 0 ? m : undefined; })()
    : redactedMeta;
  if (process.env.NODE_ENV === "production") {
    return JSON.stringify(filteredMeta ? { ...base, data: filteredMeta } : base);
  }
  const metaStr = filteredMeta && Object.keys(filteredMeta).length > 0
    ? " " + JSON.stringify(filteredMeta)
    : "";
  const reqStr = requestId ? ` [${requestId}]` : "";
  return `[${ts}] ${level.toUpperCase().padEnd(5)}${reqStr} ${msg}${metaStr}`;
}

export const logger = {
  debug(msg: string, meta?: LogMeta) {
    if (shouldLog("debug")) console.log(format("debug", msg, meta));
  },
  info(msg: string, meta?: LogMeta) {
    if (shouldLog("info")) console.log(format("info", msg, meta));
  },
  warn(msg: string, meta?: LogMeta) {
    if (shouldLog("warn")) console.warn(format("warn", msg, meta));
  },
  error(msg: string, meta?: LogMeta) {
    if (shouldLog("error")) console.error(format("error", msg, meta));
  },
  fatal(msg: string, meta?: LogMeta) {
    if (shouldLog("fatal")) {
      console.error(format("fatal", msg, meta));
      // Don't call process.exit here — let the caller decide
    }
  },
  /** Wrap an async fn — auto-catch and log errors. */
  async wrap<T>(label: string, fn: () => Promise<T>, meta?: LogMeta): Promise<T | undefined> {
    try {
      return await fn();
    } catch (err) {
      this.error(label, { err: err instanceof Error ? err.message : String(err), ...meta });
      return undefined;
    }
  },
};

export type { Level, LogMeta };

/**
 * storage.ts — External file storage for logos and other binary assets.
 *
 * Replaces the previous pattern of storing logoBase64 directly in the
 * companies table (E-17). Logos are now saved to /home/z/my-project/storage/
 * and served via /api/storage/[id]. The DB stores only the file path.
 *
 * In production: swap the fs operations with S3/GCS upload + signed URL.
 */

import fs from "node:fs/promises";
import path from "node:path";
import { randomUUID } from "node:crypto";
import { logger } from "./logger";

// EA-004 FIX: Use relative path based on cwd() instead of hardcoded /home/z/ path
// P0 NFT FIX: path.join(process.cwd(), ...) causes NFT to trace the entire project
// because cwd() is dynamic. Using /*turbopackIgnore: true*/ tells Turbopack/Webpack
// to NOT trace this path at build time — storage is a runtime-only filesystem concern.
const STORAGE_DIR = process.env.STORAGE_DIR || path.join(/*turbopackIgnore: true*/ process.cwd(), "storage");

/** MIME type allowlist — only these types may be saved to storage. */
const ALLOWED_MIME_TYPES = new Set([
  "image/png", "image/jpeg", "image/gif", "image/webp",
  "application/pdf",
]);

/**
 * SEC-M5C4 (Cycle 4): hard cap on saved file size. Previously saveBase64 had
 * no size limit — a 1 GB base64 string would decode to 750 MB on disk. The
 * global parseJsonBody cap (1 MiB) mitigates this for routes that go through
 * parseJsonBody, but saveBase64 is also called from migrateFromBase64 which
 * may bypass it.
 */
const MAX_FILE_BYTES = 5 * 1024 * 1024; // 5 MiB

/**
 * SEC-M5C4 (Cycle 4): magic-byte (file signature) verification. The MIME
 * allowlist above already constrains the declared type, but a malicious client
 * could send a polyglot or non-image payload labelled `image/png`. This map
 * defines the expected first bytes for each allowed MIME type.
 */
const MAGIC_BYTES: Record<string, { offset: number; bytes: number[] }> = {
  "image/png": { offset: 0, bytes: [0x89, 0x50, 0x4e, 0x47, 0x0d, 0x0a, 0x1a, 0x0a] },
  "image/jpeg": { offset: 0, bytes: [0xff, 0xd8, 0xff] },
  "image/gif": { offset: 0, bytes: [0x47, 0x49, 0x46, 0x38] }, // GIF87a / GIF89a
  "image/webp": { offset: 0, bytes: [0x52, 0x49, 0x46, 0x46] }, // RIFF....WEBP
  "application/pdf": { offset: 0, bytes: [0x25, 0x50, 0x44, 0x46] }, // %PDF
};

function verifyMagicBytes(buf: Buffer, mimeType: string): boolean {
  const sig = MAGIC_BYTES[mimeType];
  if (!sig) return false;
  if (buf.length < sig.offset + sig.bytes.length) return false;
  return sig.bytes.every((b, i) => buf[sig.offset + i] === b);
}

async function ensureStorageDir(): Promise<void> {
  try {
    await fs.mkdir(STORAGE_DIR, { recursive: true });
  } catch (err) {
    logger.error("[storage] failed to create storage dir", { err: err instanceof Error ? err.message : String(err) });
    throw err;
  }
}

/**
 * Save a base64-encoded file to disk. Returns the storage key (filename).
 * The key can later be passed to getPublicUrl() to construct a fetchable URL.
 */
export async function saveBase64(
  base64Data: string,
  mimeType: string = "image/png",
): Promise<string> {
  if (!ALLOWED_MIME_TYPES.has(mimeType)) {
    throw new Error(`MIME type "${mimeType}" is not allowed. Allowed types: ${[...ALLOWED_MIME_TYPES].join(", ")}`);
  }
  await ensureStorageDir();
  // Strip data URL prefix if present
  const cleaned = base64Data.replace(/^data:[^;]+;base64,/, "");
  const buffer = Buffer.from(cleaned, "base64");

  // SEC-M5C4 (Cycle 4): enforce size cap BEFORE writing to disk
  if (buffer.length > MAX_FILE_BYTES) {
    throw new Error(`File too large: ${buffer.length} bytes (max ${MAX_FILE_BYTES} bytes)`);
  }

  // SEC-M5C4 (Cycle 4): verify magic bytes match the declared MIME type
  if (!verifyMagicBytes(buffer, mimeType)) {
    throw new Error(`Magic bytes do not match declared MIME type "${mimeType}" — possible polyglot / mislabeled payload`);
  }

  const ext = mimeType.split("/")[1] || "bin";
  const key = `${randomUUID()}.${ext}`;
  const fullPath = path.join(STORAGE_DIR, key);
  await fs.writeFile(fullPath, buffer);
  logger.debug("[storage] file saved", { key, size: buffer.length });
  return key;
}

/** Read a file from storage as a Buffer. */
export async function readAsBuffer(key: string): Promise<Buffer | null> {
  try {
    const fullPath = path.join(STORAGE_DIR, key);
    return await fs.readFile(fullPath);
  } catch {
    return null;
  }
}

/** Delete a file from storage. */
export async function remove(key: string): Promise<void> {
  try {
    const fullPath = path.join(STORAGE_DIR, key);
    await fs.unlink(fullPath);
  } catch (err) {
    logger.warn("[storage] failed to delete file", { err: err instanceof Error ? err.message : String(err), key });
  }
}

/** Construct the public URL for a stored file. */
export function getPublicUrl(key: string): string {
  return `/api/storage/${key}`;
}

/** Migrate a base64 string from DB → file system. Returns the storage key. */
export async function migrateFromBase64(base64: string, mimeType?: string): Promise<string> {
  return saveBase64(base64, mimeType);
}

