/**
 * accountant-collab.ts — Phase 12: Accountant Collaboration
 *
 * Features:
 *  - External accountant access management (read_only, limited_edit, full_edit)
 *  - Excel export data generation (trial_balance, general_ledger, journal_entries, full_package)
 *  - Accounting-specific audit logging (separate from general AuditLog)
 *  - Accounting audit trail queries
 */

import { db } from "@/lib/db";
import { num } from "@/lib/money";
import { logger } from "@/lib/logger";

// ─── Types ────────────────────────────────────────────────────────────────────

export type AccountantAccessLevel = "read_only" | "limited_edit" | "full_edit";

export interface AccountantAccessResult {
  id: number;
  companySlug: string;
  accountantEmail: string;
  accessLevel: AccountantAccessLevel;
  permissionsGranted: string[];
  createdAt: Date;
}

export type ExportType = "trial_balance" | "general_ledger" | "journal_entries" | "full_package";

export interface ExportResult {
  fileName: string;
  data: Record<string, unknown>;
}

// ─── Permission Mapping ──────────────────────────────────────────────────────

const ACCESS_LEVEL_PERMISSIONS: Record<AccountantAccessLevel, string[]> = {
  read_only: ["finance_access"], // view only — the route checks permission but the role won't allow mutations
  limited_edit: ["finance_access", "create_journal_entry"], // can create JEs but not post
  full_edit: ["finance_access", "create_journal_entry", "post_journal_entry", "create_invoice", "create_voucher"],
};

// ─── 1. createExternalAccountantAccess ────────────────────────────────────────

export async function createExternalAccountantAccess(
  companySlug: string,
  accountantEmail: string,
  accessLevel: AccountantAccessLevel,
): Promise<AccountantAccessResult> {
  const permissions = ACCESS_LEVEL_PERMISSIONS[accessLevel];

  // Create a role for this accountant scoped to this company.
  // The role name encodes the company + email so it's unique.
  const roleName = `ext_accountant_${companySlug}_${accountantEmail.replace(/[^a-zA-Z0-9]/g, "_")}`;

  // Upsert RolePermission entries for each permission key
  for (const permKey of permissions) {
    await db.rolePermission.upsert({
      where: {
        role_permissionKey_companySlug: {
          role: roleName,
          permissionKey: permKey,
          companySlug,
        },
      },
      update: { value: 1 },
      create: {
        role: roleName,
        permissionKey: permKey,
        companySlug,
        value: 1,
      },
    });
  }

  // Also ensure the accountant user has this company in their companies list
  const user = await db.appUser.findUnique({ where: { email: accountantEmail } });
  if (user) {
    const companies: string[] = JSON.parse(user.companies || "[]");
    if (!companies.includes(companySlug)) {
      companies.push(companySlug);
      await db.appUser.update({
        where: { email: accountantEmail },
        data: { companies: JSON.stringify(companies) },
      });
    }
  }

  logger.info("[accountant-collab] access granted", { companySlug, accountantEmail, accessLevel, roleName });

  return {
    id: 0, // no dedicated table — role permissions serve as the record
    companySlug,
    accountantEmail,
    accessLevel,
    permissionsGranted: permissions,
    createdAt: new Date(),
  };
}

// ─── 2. exportToAccountantExcel ───────────────────────────────────────────────

export async function exportToAccountantExcel(
  companySlug: string,
  periodFrom: string,
  periodTo: string,
  exportType: ExportType,
): Promise<ExportResult> {
  const company = await db.company.findUnique({
    where: { slug: companySlug },
    select: { name: true, nameAr: true, currency: true },
  });
  if (!company) throw new Error("Company not found");

  const fileNameSuffix = `${companySlug}_${periodFrom}_${periodTo}_${exportType}`;

  if (exportType === "trial_balance" || exportType === "full_package") {
    const tbData = await generateTrialBalanceData(companySlug, periodFrom, periodTo, company);
    if (exportType === "trial_balance") {
      return { fileName: `ميزان_مراجعة_${fileNameSuffix}.xlsx`, data: tbData };
    }
    // full_package includes all — we'll accumulate
    const allData: Record<string, unknown> = { trialBalance: tbData };

    const glData = await generateGeneralLedgerData(companySlug, periodFrom, periodTo, company);
    allData.generalLedger = glData;

    const jeData = await generateJournalEntriesData(companySlug, periodFrom, periodTo, company);
    allData.journalEntries = jeData;

    return { fileName: `حزمة_كاملة_${fileNameSuffix}.xlsx`, data: allData };
  }

  if (exportType === "general_ledger") {
    const glData = await generateGeneralLedgerData(companySlug, periodFrom, periodTo, company);
    return { fileName: `دفتر_الأستاذ_${fileNameSuffix}.xlsx`, data: glData };
  }

  if (exportType === "journal_entries") {
    const jeData = await generateJournalEntriesData(companySlug, periodFrom, periodTo, company);
    return { fileName: `قيود_يومية_${fileNameSuffix}.xlsx`, data: jeData };
  }

  throw new Error(`Unknown export type: ${exportType}`);
}

async function generateTrialBalanceData(
  companySlug: string,
  periodFrom: string,
  periodTo: string,
  company: { name: string; nameAr: string | null; currency: string },
): Promise<Record<string, unknown>> {
  const accounts = await db.account.findMany({
    where: { companySlug, isActive: true },
    include: {
      journalEntryLines: {
        include: { entry: { select: { status: true, date: true } } },
      },
    },
    orderBy: { code: "asc" },
  });

  const rows: Record<string, unknown>[] = [];
  let grandDebit = 0;
  let grandCredit = 0;

  for (const acc of accounts) {
    let totalDebit = 0;
    let totalCredit = 0;
    for (const line of acc.journalEntryLines) {
      if (line.entry.status !== "posted" && line.entry.status !== "reversed") continue;
      if (line.entry.date < periodFrom || line.entry.date > periodTo) continue;
      const multiplier = line.entry.status === "reversed" ? -1 : 1;
      totalDebit += num(line.debit, 3) * multiplier;
      totalCredit += num(line.credit, 3) * multiplier;
    }
    grandDebit += totalDebit;
    grandCredit += totalCredit;

    rows.push({
      "رمز الحساب": acc.code,
      "اسم الحساب": acc.nameAr,
      "نوع الحساب": acc.type,
      "مدين": num(totalDebit, 3).toFixed(3),
      "دائن": num(totalCredit, 3).toFixed(3),
      "الرصيد": num(totalDebit - totalCredit, 3).toFixed(3),
    });
  }

  return {
    headers: ["رمز الحساب", "اسم الحساب", "نوع الحساب", "مدين", "دائن", "الرصيد"],
    companyName: company.nameAr || company.name,
    currency: company.currency,
    periodFrom,
    periodTo,
    title: "ميزان المراجعة",
    rows,
    totals: {
      "مدين": num(grandDebit, 3).toFixed(3),
      "دائن": num(grandCredit, 3).toFixed(3),
      "الرصيد": num(grandDebit - grandCredit, 3).toFixed(3),
    },
  };
}

async function generateGeneralLedgerData(
  companySlug: string,
  periodFrom: string,
  periodTo: string,
  company: { name: string; nameAr: string | null; currency: string },
): Promise<Record<string, unknown>> {
  const accounts = await db.account.findMany({
    where: { companySlug, isActive: true },
    orderBy: { code: "asc" },
  });

  const ledgerEntries: Record<string, unknown>[] = [];
  for (const acc of accounts) {
    const lines = await db.journalEntryLine.findMany({
      where: {
        accountId: acc.id,
        entry: {
          companySlug,
          status: { in: ["posted", "reversed"] },
          date: { gte: periodFrom, lte: periodTo },
        },
      },
      include: { entry: { select: { date: true, description: true, reference: true, status: true } } },
      orderBy: { entry: { date: "asc" } },
    });

    let runningBalance = 0;
    const isDebitNormal = acc.type === "asset" || acc.type === "expense";

    for (const line of lines) {
      const multiplier = line.entry.status === "reversed" ? -1 : 1;
      const debit = num(line.debit, 3) * multiplier;
      const credit = num(line.credit, 3) * multiplier;
      runningBalance += isDebitNormal ? debit - credit : credit - debit;

      ledgerEntries.push({
        "رمز الحساب": acc.code,
        "اسم الحساب": acc.nameAr,
        "التاريخ": line.entry.date,
        "المرجع": line.entry.reference || "",
        "البيان": line.entry.description || "",
        "مدين": debit.toFixed(3),
        "دائن": credit.toFixed(3),
        "الرصيد": num(runningBalance, 3).toFixed(3),
      });
    }
  }

  return {
    headers: ["رمز الحساب", "اسم الحساب", "التاريخ", "المرجع", "البيان", "مدين", "دائن", "الرصيد"],
    companyName: company.nameAr || company.name,
    currency: company.currency,
    periodFrom,
    periodTo,
    title: "دفتر الأستاذ العام",
    rows: ledgerEntries,
  };
}

async function generateJournalEntriesData(
  companySlug: string,
  periodFrom: string,
  periodTo: string,
  company: { name: string; nameAr: string | null; currency: string },
): Promise<Record<string, unknown>> {
  const entries = await db.journalEntry.findMany({
    where: {
      companySlug,
      date: { gte: periodFrom, lte: periodTo },
      status: { in: ["posted", "reversed", "draft"] },
    },
    include: { lines: { include: { account: { select: { code: true, nameAr: true } } } } },
    orderBy: { date: "asc" },
  });

  const rows: Record<string, unknown>[] = [];
  for (const entry of entries) {
    for (const line of entry.lines) {
      rows.push({
        "رقم القيد": entry.id,
        "التاريخ": entry.date,
        "البيان": entry.description || "",
        "المرجع": entry.reference || "",
        "الحالة": entry.status,
        "رمز الحساب": line.account.code,
        "اسم الحساب": line.account.nameAr,
        "مدين": num(line.debit, 3).toFixed(3),
        "دائن": num(line.credit, 3).toFixed(3),
        "وصف السطر": line.description || "",
      });
    }
  }

  return {
    headers: [
      "رقم القيد", "التاريخ", "البيان", "المرجع", "الحالة",
      "رمز الحساب", "اسم الحساب", "مدين", "دائن", "وصف السطر",
    ],
    companyName: company.nameAr || company.name,
    currency: company.currency,
    periodFrom,
    periodTo,
    title: "قيود اليومية",
    rows,
  };
}

// ─── 3. logAccountingChange ───────────────────────────────────────────────────

export async function logAccountingChange(
  companySlug: string,
  userEmail: string,
  action: string,
  entity: string,
  entityId: number | null | undefined,
  beforeState: Record<string, unknown> | null,
  afterState: Record<string, unknown> | null,
  reason: string | null,
): Promise<{ id: number; companySlug: string; userEmail: string; action: string; entity: string; entityId: number | null; createdAt: Date }> {
  const entry = await db.accountingAuditLog.create({
    data: {
      companySlug,
      userEmail,
      action,
      entity,
      entityId: entityId ?? null,
      beforeState: beforeState ? JSON.stringify(beforeState) : null,
      afterState: afterState ? JSON.stringify(afterState) : null,
      reason,
    },
  });

  logger.info("[accounting-audit] change logged", { companySlug, userEmail, action, entity, entityId });

  return {
    id: entry.id,
    companySlug: entry.companySlug,
    userEmail: entry.userEmail,
    action: entry.action,
    entity: entry.entity,
    entityId: entry.entityId,
    createdAt: entry.createdAt,
  };
}

// ─── 4. getAccountingAuditTrail ───────────────────────────────────────────────

export interface AuditTrailFilter {
  entity?: string;
  entityId?: number;
  fromDate?: string;
  toDate?: string;
}

export async function getAccountingAuditTrail(
  companySlug: string,
  filters?: AuditTrailFilter,
): Promise<Record<string, unknown>[]> {
  const where: Record<string, unknown> = { companySlug };

  if (filters?.entity) where.entity = filters.entity;
  if (filters?.entityId) where.entityId = filters.entityId;
  if (filters?.fromDate || filters?.toDate) {
    const dateFilter: Record<string, unknown> = {};
    if (filters.fromDate) dateFilter.gte = new Date(filters.fromDate);
    if (filters.toDate) dateFilter.lte = new Date(filters.toDate);
    where.createdAt = dateFilter;
  }

  const logs = await db.accountingAuditLog.findMany({
    where,
    orderBy: { createdAt: "desc" },
    take: 500,
  });

  return logs.map((log) => ({
    id: log.id,
    companySlug: log.companySlug,
    userEmail: log.userEmail,
    action: log.action,
    entity: log.entity,
    entityId: log.entityId,
    beforeState: log.beforeState ? JSON.parse(log.beforeState) : null,
    afterState: log.afterState ? JSON.parse(log.afterState) : null,
    reason: log.reason,
    createdAt: log.createdAt,
  }));
}

/**
 * arabic-amount-text.ts — Phase 13: Convert numbers to Arabic text
 * for invoices, checks, and vouchers.
 *
 * Supports: KWD, SAR, AED, EGP, BHD, OMR, QAR currencies.
 * Arabic grammar: proper gender agreement, plural forms, and "لا غير" suffix.
 *
 * Examples:
 *   500 KWD        → "خمسمائة دينار لا غير"
 *   1250.750 SAR   → "ألف ومائتان وخمسون ريال وسبعمائة وخمسون هللة لا غير"
 *   3.500 AED      → "ثلاثة دراهم وخمسمائة فلس لا غير"
 *   1 KWD          → "دينار واحد لا غير"
 *   2 SAR          → "ريالان لا غير"
 */

export type SupportedCurrency = "KWD" | "SAR" | "AED" | "EGP" | "BHD" | "OMR" | "QAR";

// ─── Arabic number words ────────────────────────────────────────────────

// Singles 0–19 (masculine form — used with دينار/ريال/درهم/جنيه which are all masculine)
const ONES_MASCULINE: string[] = [
  "",         // 0
  "واحد",     // 1
  "اثنان",    // 2
  "ثلاثة",    // 3
  "أربعة",    // 4
  "خمسة",     // 5
  "ستة",      // 6
  "سبعة",     // 7
  "ثمانية",   // 8
  "تسعة",     // 9
  "عشرة",     // 10
  "أحد عشر",  // 11
  "اثنا عشر", // 12
  "ثلاثة عشر",// 13
  "أربعة عشر",// 14
  "خمسة عشر", // 15
  "ستة عشر",  // 16
  "سبعة عشر", // 17
  "ثمانية عشر",// 18
  "تسعة عشر", // 19
];

// Tens 20–90
const TENS: string[] = [
  "",           // 0
  "",           // 10 (handled in ONES)
  "عشرون",      // 20
  "ثلاثون",     // 30
  "أربعون",     // 40
  "خمسون",      // 50
  "ستون",       // 60
  "سبعون",      // 70
  "ثمانون",     // 80
  "تسعون",      // 90
];

// Hundreds 100–900
const HUNDREDS: string[] = [
  "",           // 0
  "مائة",       // 100
  "مائتان",     // 200
  "ثلاثمائة",   // 300
  "أربعمائة",   // 400
  "خمسمائة",    // 500
  "ستمائة",     // 600
  "سبعمائة",    // 700
  "ثمانمائة",   // 800
  "تسعمائة",    // 900
];

// ─── Fraction (sub-unit) number words ───────────────────────────────────
// فلس/هللة/قرش are masculine nouns, so we use masculine forms

const FRACTION_ONES: string[] = [
  "",
  "واحد",
  "اثنان",
  "ثلاثة",
  "أربعة",
  "خمسة",
  "ستة",
  "سبعة",
  "ثمانية",
  "تسعة",
  "عشرة",
  "أحد عشر",
  "اثنا عشر",
  "ثلاثة عشر",
  "أربعة عشر",
  "خمسة عشر",
  "ستة عشر",
  "سبعة عشر",
  "ثمانية عشر",
  "تسعة عشر",
];

const FRACTION_TENS: string[] = TENS; // same tens words for fractions
const FRACTION_HUNDREDS: string[] = HUNDREDS; // same hundreds words for fractions

// ─── Currency names ─────────────────────────────────────────────────────

export interface CurrencyInfo {
  wholeSingular: string;   // دينار
  wholeDual: string;       // ديناران
  wholePlural: string;     // دينارات
  wholeGender: "masculine" | "feminine";
  fractionSingular: string; // فلس
  fractionDual: string;     // فلسان
  fractionPlural: string;   // فلسات (or فلوس for AED)
  fractionGender: "masculine" | "feminine";
  decimalPlaces: number;    // 3 for KWD/BHD, 2 for SAR/AED/EGP/QAR/OMR
}

const CURRENCY_INFO: Record<SupportedCurrency, CurrencyInfo> = {
  KWD: {
    wholeSingular: "دينار", wholeDual: "ديناران", wholePlural: "دينارات",
    wholeGender: "masculine",
    fractionSingular: "فلس", fractionDual: "فلسان", fractionPlural: "فلسات",
    fractionGender: "masculine", decimalPlaces: 3,
  },
  BHD: {
    wholeSingular: "دينار", wholeDual: "ديناران", wholePlural: "دينارات",
    wholeGender: "masculine",
    fractionSingular: "فلس", fractionDual: "فلسان", fractionPlural: "فلسات",
    fractionGender: "masculine", decimalPlaces: 3,
  },
  SAR: {
    wholeSingular: "ريال", wholeDual: "ريالان", wholePlural: "ريالات",
    wholeGender: "masculine",
    fractionSingular: "هللة", fractionDual: "هللتان", fractionPlural: "هللات",
    fractionGender: "feminine", decimalPlaces: 2,
  },
  QAR: {
    wholeSingular: "ريال", wholeDual: "ريالان", wholePlural: "ريالات",
    wholeGender: "masculine",
    fractionSingular: "هللة", fractionDual: "هللتان", fractionPlural: "هللات",
    fractionGender: "feminine", decimalPlaces: 2,
  },
  OMR: {
    wholeSingular: "ريال", wholeDual: "ريالان", wholePlural: "ريالات",
    wholeGender: "masculine",
    fractionSingular: "هللة", fractionDual: "هللتان", fractionPlural: "هللات",
    fractionGender: "feminine", decimalPlaces: 3,
  },
  AED: {
    wholeSingular: "درهم", wholeDual: "درهمان", wholePlural: "دراهم",
    wholeGender: "masculine",
    fractionSingular: "فلس", fractionDual: "فلسان", fractionPlural: "فلسات",
    fractionGender: "masculine", decimalPlaces: 2,
  },
  EGP: {
    wholeSingular: "جنيه", wholeDual: "جنيهان", wholePlural: "جنيهات",
    wholeGender: "masculine",
    fractionSingular: "قرش", fractionDual: "قرشان", fractionPlural: "قروش",
    fractionGender: "masculine", decimalPlaces: 2,
  },
};

// ─── Helper: get currency fraction name ─────────────────────────────────

export function getCurrencyFractionName(currency: SupportedCurrency): string {
  return CURRENCY_INFO[currency].fractionSingular;
}

// ─── Helper: get currency whole name (with proper singular/dual/plural) ──

export function getCurrencyWholeName(currency: SupportedCurrency, amount: number): string {
  const info = CURRENCY_INFO[currency];
  if (amount === 1) return info.wholeSingular;
  if (amount === 2) return info.wholeDual;
  if (amount >= 3 && amount <= 10) return info.wholePlural;
  if (amount >= 11 && amount <= 99) return info.wholeSingular; // Arabic grammar: 11-99 use singular
  return info.wholePlural; // 100+ uses plural
}

// ─── Helper: get fraction name with proper singular/dual/plural ────────

function getFractionName(currency: SupportedCurrency, amount: number): string {
  const info = CURRENCY_INFO[currency];
  if (amount === 1) return info.fractionSingular;
  if (amount === 2) return info.fractionDual;
  if (amount >= 3 && amount <= 10) return info.fractionPlural;
  if (amount >= 11 && amount <= 99) return info.fractionSingular;
  return info.fractionPlural;
}

// ─── Core conversion: number to Arabic text (whole portion) ─────────────

function convertWholeToArabic(n: number): string {
  if (n === 0) return "صفر";
  if (n < 0) return "سالب " + convertWholeToArabic(Math.abs(n));

  // For Arabic number grammar, we need to handle ranges differently:
  // 1: واحد (or just the currency name with واحد appended)
  // 2: اثنان
  // 3-10: plural number + plural currency
  // 11-99: singular number pattern
  // 100-999: hundreds
  // 1000-999999: thousands
  // 1000000+: millions

  const parts: string[] = [];

  // Millions (مليون)
  if (n >= 1000000) {
    const millions = Math.floor(n / 1000000);
    n %= 1000000;
    if (millions === 1) parts.push("مليون");
    else if (millions === 2) parts.push("مليونان");
    else if (millions <= 10) parts.push(convertSmallNumber(millions) + " ملايين");
    else parts.push(convertSmallNumber(millions) + " مليون");
  }

  // Hundred-thousands (part of thousands range in Arabic)
  // Arabic treats 100000 as "مائة ألف", 200000 as "مائتان ألف", etc.

  if (n >= 1000) {
    const thousands = Math.floor(n / 1000);
    n %= 1000;
    if (thousands === 1) parts.push("ألف");
    else if (thousands === 2) parts.push("ألفان");
    else if (thousands <= 10) parts.push(convertSmallNumber(thousands) + " آلاف");
    else if (thousands <= 99) parts.push(convertSmallNumber(thousands) + " ألف");
    else if (thousands === 100) parts.push("مائة ألف");
    else if (thousands === 200) parts.push("مائتان ألف");
    else if (thousands <= 999) parts.push(convertHundreds(thousands) + " ألف");
  }

  // Hundreds 100-999
  if (n >= 100) {
    const hundreds = Math.floor(n / 100);
    const remainder = n % 100;
    n %= 100;
    if (remainder === 0) {
      parts.push(HUNDREDS[hundreds]);
    } else {
      parts.push(HUNDREDS[hundreds]);
      // The remainder will be handled below
    }
  }

  // 1-99
  if (n > 0) {
    parts.push(convertSmallNumber(n));
  }

  return parts.filter(Boolean).join(" و");
}

// Convert numbers 1-99
function convertSmallNumber(n: number): string {
  if (n === 0) return "";
  if (n <= 19) return ONES_MASCULINE[n];
  const tens = Math.floor(n / 10);
  const ones = n % 10;
  if (ones === 0) return TENS[tens];
  // For 21, 31, etc.: "واحد وعشرون", "ثلاثة وثلاثون"
  return ONES_MASCULINE[ones] + " و" + TENS[tens];
}

// Convert hundreds portion (100-999) for thousands compound
function convertHundreds(n: number): string {
  if (n <= 999) {
    const hundreds = Math.floor(n / 100);
    const remainder = n % 100;
    if (remainder === 0) return HUNDREDS[hundreds];
    return HUNDREDS[hundreds] + " و" + convertSmallNumber(remainder);
  }
  return "";
}

// ─── Core conversion: fraction portion ──────────────────────────────────

function convertFractionToArabic(n: number, fractionGender: "masculine" | "feminine"): string {
  if (n === 0) return "";
  // Fractions use the same number system as whole amounts
  // For feminine fraction names (هللة), the ones 1-9 use feminine forms
  // But since the spec says هللة is feminine, we need feminine ones for 1-9 with هللة

  if (fractionGender === "feminine") {
    return convertSmallNumberFeminine(n);
  }
  return convertSmallNumber(n);
}

// Feminine forms for 1-19 (used with هللة which is feminine)
const ONES_FEMININE: string[] = [
  "",           // 0
  "واحدة",      // 1
  "اثنتان",     // 2
  "ثلاث",       // 3
  "أربع",       // 4
  "خمس",        // 5
  "ست",         // 6
  "سبع",        // 7
  "ثمان",       // 8
  "تسع",        // 9
  "عشر",        // 10 ( feminine: عشرة but for compound عشر )
  "إحدى عشر",   // 11
  "اثنتا عشر",  // 12
  "ثلاث عشر",   // 13
  "أربع عشر",   // 14
  "خمس عشر",    // 15
  "ست عشر",     // 16
  "سبع عشر",    // 17
  "ثمان عشر",   // 18
  "تسع عشر",    // 19
];

// Feminine tens are the same as masculine tens (عشرون, ثلاثون, etc.)
// Because Arabic tens have the same form regardless of gender

function convertSmallNumberFeminine(n: number): string {
  if (n === 0) return "";
  if (n <= 19) return ONES_FEMININE[n];
  const tens = Math.floor(n / 10);
  const ones = n % 10;
  if (ones === 0) return TENS[tens];
  return ONES_FEMININE[ones] + " و" + TENS[tens];
}

// ─── Main function: numberToArabicText ──────────────────────────────────

export function numberToArabicText(amount: number, currency: SupportedCurrency): string {
  const info = CURRENCY_INFO[currency];
  const decimalMultiplier = Math.pow(10, info.decimalPlaces);

  // Split into whole and fraction
  const wholePart = Math.floor(Math.abs(amount));
  const fractionPart = Math.round((Math.abs(amount) - wholePart) * decimalMultiplier);

  // Handle negative
  const isNegative = amount < 0;

  const parts: string[] = [];

  // ── Whole portion ────────────────────────────────────────────────
  if (wholePart === 0) {
    parts.push("صفر");
    parts.push(info.wholePlural); // zero uses plural form
  } else if (wholePart === 1) {
    // "دينار واحد" — the number واحد comes after the currency name for 1
    parts.push(info.wholeSingular + " واحد");
  } else if (wholePart === 2) {
    // "ديناران" — dual form already includes the number meaning
    parts.push(info.wholeDual);
  } else if (wholePart <= 10) {
    // "ثلاثة دينارات" — number before plural currency
    parts.push(convertWholeToArabic(wholePart));
    parts.push(info.wholePlural);
  } else if (wholePart <= 99) {
    // "خمسون دينار" — number before singular currency (Arabic grammar: 11-99 use singular)
    parts.push(convertWholeToArabic(wholePart));
    parts.push(info.wholeSingular);
  } else {
    // 100+: "خمسمائة دينار" — the number expression includes its own form
    // For hundreds+ the number text comes first, then the currency name
    parts.push(convertWholeToArabic(wholePart));
    parts.push(getCurrencyWholeName(currency, wholePart));
  }

  // ── Fraction portion ─────────────────────────────────────────────
  if (fractionPart > 0) {
    const fractionName = getFractionName(currency, fractionPart);

    if (fractionPart === 1) {
      parts.push(fractionName + " واحد");
    } else if (fractionPart === 2) {
      // Dual form already built into getFractionName
      parts.push(getFractionName(currency, 2));
    } else if (fractionPart <= 10) {
      parts.push(convertFractionToArabic(fractionPart, info.fractionGender));
      parts.push(info.fractionPlural);
    } else if (fractionPart <= 99) {
      parts.push(convertFractionToArabic(fractionPart, info.fractionGender));
      parts.push(info.fractionSingular); // 11-99 use singular for fraction name
    } else {
      parts.push(convertFractionToArabic(fractionPart, info.fractionGender));
      parts.push(fractionName);
    }
  }

  let result = parts.join(" و");

  if (isNegative) {
    result = "سالب " + result;
  }

  // Always end with "لا غير" (only) — standard for checks/vouchers
  result += " لا غير";

  return result;
}

/**
 * financial-dashboard.ts — Financial dashboard metrics engine (Phase 10).
 *
 * Provides dashboard metrics, period comparison, and budget vs actual reporting.
 * All monetary values stored as String; uses num() for arithmetic.
 */
import { db } from "@/lib/db";
import { num, toNum, subNums } from "@/lib/money";
import { logger } from "@/lib/logger";

// ─── Dashboard Metrics ───────────────────────────────────────────────────

export interface DashboardMetrics {
  revenue: number;
  expenses: number;
  netProfit: number;
  cashPosition: number;
  accountsReceivable: number;
  accountsPayable: number;
  inventoryValue: number;
  trends: {
    revenueChange: number | null;
    expenseChange: number | null;
    profitChange: number | null;
    cashChange: number | null;
  };
}

/**
 * Get dashboard metrics for a company within a date range.
 * Includes trend comparison vs previous period.
 */
export async function getDashboardMetrics(
  companySlug: string,
  periodFrom: string,
  periodTo: string,
): Promise<{ ok: boolean; metrics?: DashboardMetrics; error?: string }> {
  try {
    // Current period metrics
    const entries = await db.journalEntry.findMany({
      where: {
        companySlug,
        date: { gte: periodFrom, lte: periodTo },
        status: "posted",
        deletedAt: null,
      },
      include: { lines: { include: { account: true } } },
    });

    let revenue = 0;
    let expenses = 0;

    for (const entry of entries) {
      for (const line of entry.lines) {
        const acc = line.account;
        if (!acc) continue;
        const debit = num(line.debit, 3);
        const credit = num(line.credit, 3);

        if (acc.type === "revenue") {
          revenue += credit - debit;
        } else if (acc.type === "expense") {
          expenses += debit - credit;
        } else if (acc.type === "contra_revenue") {
          revenue -= (debit - credit);
        }
      }
    }

    const netProfit = revenue - expenses;

    // Cash position: sum of cash/bank account balances
    const cashAccounts = await db.account.findMany({
      where: {
        companySlug,
        type: "asset",
        isActive: true,
        OR: [
          { code: { startsWith: "1-1" } }, // Cash accounts typically 1-1xx
          { nameAr: { contains: "نقد" } },
          { nameAr: { contains: "بنك" } },
        ],
      },
    });
    const cashPosition = cashAccounts.reduce(
      (sum, acc) => sum + num(acc.balance, 3), 0
    );

    // Accounts receivable: outstanding invoices
    const outstandingInvoices = await db.invoice.findMany({
      where: {
        companySlug,
        deletedAt: null,
        status: { in: ["sent", "partial", "overdue"] },
      },
      select: { total: true, paid: true },
    });
    const accountsReceivable = outstandingInvoices.reduce(
      (sum, inv) => sum + num(inv.total, 3) - num(inv.paid, 3), 0
    );

    // Accounts payable: outstanding purchase invoices
    const outstandingPurchases = await db.purchaseInvoice.findMany({
      where: {
        companySlug,
        deletedAt: null,
      },
      select: { totalAmount: true },
    });
    const accountsPayable = outstandingPurchases.reduce(
      (sum, pi) => sum + num(pi.totalAmount, 3), 0
    );

    // Inventory value: sum of inventory items cost
    // FIX #10: ProductCatalog has `purchasePrice`, NOT `cost`.
    // FIX #11: Must include `product` relation in the query to access item.product.
    const inventoryItems = await db.inventoryItem.findMany({
      where: { companySlug },
      include: { product: { select: { purchasePrice: true } } },
    });
    const inventoryValue = inventoryItems.reduce(
      (sum, item) => sum + num(item.quantity, 3) * num(item.product?.purchasePrice ?? "0", 3), 0
    );

    // Previous period for trend comparison
    const fromDate = new Date(periodFrom);
    const toDate = new Date(periodTo);
    const periodDays = Math.ceil((toDate.getTime() - fromDate.getTime()) / (1000 * 60 * 60 * 24));
    const prevFrom = new Date(fromDate.getTime() - periodDays * 1000 * 60 * 60 * 24).toISOString().slice(0, 10);
    const prevTo = new Date(fromDate.getTime() - 1 * 1000 * 60 * 60 * 24).toISOString().slice(0, 10);

    const prevEntries = await db.journalEntry.findMany({
      where: {
        companySlug,
        date: { gte: prevFrom, lte: prevTo },
        status: "posted",
        deletedAt: null,
      },
      include: { lines: { include: { account: true } } },
    });

    let prevRevenue = 0;
    let prevExpenses = 0;

    for (const entry of prevEntries) {
      for (const line of entry.lines) {
        const acc = line.account;
        if (!acc) continue;
        const debit = num(line.debit, 3);
        const credit = num(line.credit, 3);

        if (acc.type === "revenue") prevRevenue += credit - debit;
        else if (acc.type === "expense") prevExpenses += debit - credit;
        else if (acc.type === "contra_revenue") prevRevenue -= (debit - credit);
      }
    }

    const prevProfit = prevRevenue - prevExpenses;

    const prevCashAccounts = await db.account.findMany({
      where: {
        companySlug,
        type: "asset",
        isActive: true,
        OR: [
          { code: { startsWith: "1-1" } },
          { nameAr: { contains: "نقد" } },
          { nameAr: { contains: "بنك" } },
        ],
      },
    });

    // For cash trend, we compare current balances vs what they would have been
    // Simplification: compare current cash position vs previous period's ending cash
    // (In production, this would use historical snapshots)
    let prevCash = 0;
    for (const acc of prevCashAccounts) {
      prevCash += num(acc.balance, 3) - (revenue - expenses) + (prevRevenue - prevExpenses);
    }

    const computeChange = (current: number, previous: number): number | null => {
      if (previous === 0) return current > 0 ? 100 : null;
      return ((current - previous) / Math.abs(previous)) * 100;
    };

    const metrics: DashboardMetrics = {
      revenue,
      expenses,
      netProfit,
      cashPosition,
      accountsReceivable,
      accountsPayable,
      inventoryValue,
      trends: {
        revenueChange: computeChange(revenue, prevRevenue),
        expenseChange: computeChange(expenses, prevExpenses),
        profitChange: computeChange(netProfit, prevProfit),
        cashChange: computeChange(cashPosition, prevCash),
      },
    };

    return { ok: true, metrics };
  } catch (err) {
    const msg = err instanceof Error ? err.message : String(err);
    logger.error("[financial-dashboard] getDashboardMetrics failed", { err: msg });
    return { ok: false, error: msg };
  }
}

/** Alias for dashboard route — delegates to getDashboardMetrics. */
export async function getFinancialDashboard(
  companySlug: string,
  periodFrom?: string,
  periodTo?: string,
) {
  const from = periodFrom || new Date(new Date().getFullYear(), 0, 1).toISOString().slice(0, 10);
  const to = periodTo || new Date().toISOString().slice(0, 10);
  return getDashboardMetrics(companySlug, from, to);
}

// ─── Period Comparison ───────────────────────────────────────────────────

export interface PeriodData {
  period: string;
  revenue: number;
  expenses: number;
  profit: number;
  cash: number;
}

export interface PeriodComparisonResult {
  periods: PeriodData[];
  changes: Array<{
    fromPeriod: string;
    toPeriod: string;
    revenueChange: number | null;
    expenseChange: number | null;
    profitChange: number | null;
    cashChange: number | null;
  }>;
}

/**
 * Compare 2+ periods side-by-side.
 * For each period: revenue, expenses, net profit, cash.
 * Calculate % change between consecutive periods.
 */
export async function getPeriodComparison(
  companySlug: string,
  periods: string[], // e.g. ["2024-01", "2024-02", "2024-03"]
): Promise<{ ok: boolean; result?: PeriodComparisonResult; error?: string }> {
  try {
    if (periods.length < 2) {
      return { ok: false, error: "يجب تقديم فترتين أو أكثر للمقارنة" };
    }

    const periodData: PeriodData[] = [];

    for (const period of periods) {
      // Parse period to date range
      let from: string;
      let to: string;

      if (period.length === 4) {
        // Year: 2024 → 2024-01-01 to 2024-12-31
        from = `${period}-01-01`;
        to = `${period}-12-31`;
      } else if (period.length === 7 && period.includes("-")) {
        // Month: 2024-01 → 2024-01-01 to 2024-01-31
        const [year, month] = period.split("-");
        const lastDay = new Date(parseInt(year), parseInt(month), 0).getDate();
        from = `${year}-${month}-01`;
        to = `${year}-${month}-${lastDay}`;
      } else if (period.includes("Q")) {
        // Quarter: 2024-Q1 → 2024-01-01 to 2024-03-31
        const [year, qStr] = period.split("-Q");
        const q = parseInt(qStr);
        const qFromMonth = (q - 1) * 3 + 1;
        from = `${year}-${String(qFromMonth).padStart(2, "0")}-01`;
        const qToMonth = q * 3;
        const lastDay = new Date(parseInt(year), qToMonth, 0).getDate();
        to = `${year}-${String(qToMonth).padStart(2, "0")}-${lastDay}`;
      } else {
        // Assume it's a date range already or invalid
        continue;
      }

      const entries = await db.journalEntry.findMany({
        where: {
          companySlug,
          date: { gte: from, lte: to },
          status: "posted",
          deletedAt: null,
        },
        include: { lines: { include: { account: true } } },
      });

      let revenue = 0;
      let expenses = 0;

      for (const entry of entries) {
        for (const line of entry.lines) {
          const acc = line.account;
          if (!acc) continue;
          const debit = num(line.debit, 3);
          const credit = num(line.credit, 3);

          if (acc.type === "revenue") revenue += credit - debit;
          else if (acc.type === "expense") expenses += debit - credit;
          else if (acc.type === "contra_revenue") revenue -= (debit - credit);
        }
      }

      const profit = revenue - expenses;

      // Cash position
      const cashAccounts = await db.account.findMany({
        where: {
          companySlug,
          type: "asset",
          isActive: true,
          OR: [
            { code: { startsWith: "1-1" } },
            { nameAr: { contains: "نقد" } },
            { nameAr: { contains: "بنك" } },
          ],
        },
      });
      const cash = cashAccounts.reduce(
        (sum, acc) => sum + num(acc.balance, 3), 0
      );

      periodData.push({ period, revenue, expenses, profit, cash });
    }

    // Calculate changes between consecutive periods
    const changes: Array<{
      fromPeriod: string;
      toPeriod: string;
      revenueChange: number | null;
      expenseChange: number | null;
      profitChange: number | null;
      cashChange: number | null;
    }> = [];

    const computeChange = (current: number, previous: number): number | null => {
      if (previous === 0) return current > 0 ? 100 : null;
      return ((current - previous) / Math.abs(previous)) * 100;
    };

    for (let i = 1; i < periodData.length; i++) {
      const prev = periodData[i - 1];
      const curr = periodData[i];
      changes.push({
        fromPeriod: prev.period,
        toPeriod: curr.period,
        revenueChange: computeChange(curr.revenue, prev.revenue),
        expenseChange: computeChange(curr.expenses, prev.expenses),
        profitChange: computeChange(curr.profit, prev.profit),
        cashChange: computeChange(curr.cash, prev.cash),
      });
    }

    return {
      ok: true,
      result: { periods: periodData, changes },
    };
  } catch (err) {
    const msg = err instanceof Error ? err.message : String(err);
    logger.error("[financial-dashboard] getPeriodComparison failed", { err: msg });
    return { ok: false, error: msg };
  }
}

// ─── Budget vs Actual ────────────────────────────────────────────────────

export interface BudgetVsActualAccount {
  code: string;
  nameAr: string;
  planned: number;
  actual: number;
  variance: number;
  variancePercent: number | null;
}

export interface BudgetVsActualResult {
  accounts: BudgetVsActualAccount[];
}

/**
 * Compare budgeted (planned) amounts vs actual GL amounts.
 * For each budgeted account: planned amount vs actual, variance and variance %.
 */
export async function getBudgetVsActual(
  companySlug: string,
  fiscalYear: number,
  periodName: string,
): Promise<{ ok: boolean; result?: BudgetVsActualResult; error?: string }> {
  try {
    // Get budget entries for this period
    const budgets = await db.budget.findMany({
      where: {
        companySlug,
        fiscalYear,
        periodName,
      },
      include: {
        account: { select: { id: true, code: true, nameAr: true, type: true } },
      },
    });

    if (budgets.length === 0) {
      return { ok: false, error: `لا توجد ميزانية للفترة ${periodName} من السنة ${fiscalYear}` };
    }

    // Parse periodName to date range for GL actuals
    let from: string;
    let to: string;

    if (periodName.includes("Q")) {
      // Quarter: 2024-Q1
      const [year, qStr] = periodName.split("-Q");
      const q = parseInt(qStr);
      const qFromMonth = (q - 1) * 3 + 1;
      from = `${year}-${String(qFromMonth).padStart(2, "0")}-01`;
      const qToMonth = q * 3;
      const lastDay = new Date(parseInt(year), qToMonth, 0).getDate();
      to = `${year}-${String(qToMonth).padStart(2, "0")}-${lastDay}`;
    } else if (periodName.length === 7 && periodName.includes("-")) {
      // Month: 2024-01
      const [year, month] = periodName.split("-");
      const lastDay = new Date(parseInt(year), parseInt(month), 0).getDate();
      from = `${year}-${month}-01`;
      to = `${year}-${month}-${lastDay}`;
    } else if (periodName.length === 4) {
      // Year: 2024
      from = `${periodName}-01-01`;
      to = `${periodName}-12-31`;
    } else {
      return { ok: false, error: `صيغة الفترة غير صالحة: ${periodName}` };
    }

    // Get actual GL amounts for each budgeted account
    const accountIds = budgets.map((b) => b.accountId);

    const entries = await db.journalEntry.findMany({
      where: {
        companySlug,
        date: { gte: from, lte: to },
        status: "posted",
        deletedAt: null,
      },
      include: {
        lines: {
          where: { accountId: { in: accountIds } },
          include: { account: true },
        },
      },
    });

    // Compute actual amounts per account
    const actualMap = new Map<number, number>();
    for (const entry of entries) {
      for (const line of entry.lines) {
        const acc = line.account;
        if (!acc) continue;
        const debit = num(line.debit, 3);
        const credit = num(line.credit, 3);
        const isDebitNormal = acc.type === "asset" || acc.type === "expense";
        const amount = isDebitNormal ? debit - credit : credit - debit;
        actualMap.set(acc.id, (actualMap.get(acc.id) || 0) + amount);
      }
    }

    // Build budget vs actual comparison
    const accounts: BudgetVsActualAccount[] = budgets.map((b) => {
      const planned = num(b.plannedAmount, 3);
      const actual = actualMap.get(b.accountId) || num(b.actualAmount, 3);
      const variance = actual - planned;
      const variancePercent = planned !== 0 ? ((variance / Math.abs(planned)) * 100) : null;

      return {
        code: b.account.code,
        nameAr: b.account.nameAr,
        planned,
        actual,
        variance,
        variancePercent,
      };
    });

    // Update budget actual amounts
    for (const b of budgets) {
      const actual = actualMap.get(b.accountId) || num(b.actualAmount, 3);
      const variance = actual - num(b.plannedAmount, 3);
      await db.budget.update({
        where: { id: b.id },
        data: {
          actualAmount: actual.toFixed(3),
          variance: variance.toFixed(3),
        },
      });
    }

    return { ok: true, result: { accounts } };
  } catch (err) {
    const msg = err instanceof Error ? err.message : String(err);
    logger.error("[financial-dashboard] getBudgetVsActual failed", { err: msg });
    return { ok: false, error: msg };
  }
}

/**
 * inventory-costing.ts — Inventory Costing Methods Engine (Phase 6)
 *
 * Provides FIFO, Weighted Average, and Standard Cost costing methods,
 * inventory valuation reports, landed cost allocation, and inventory
 * adjustment journal entries.
 *
 * ALL monetary values are String — use num()/toNum()/addNums()/mulNums() from money.ts.
 */
import { db } from "@/lib/db";
import { num, addNums, mulNums, subNums, toNum } from "@/lib/money";
import { logAudit } from "@/lib/audit";
import { logger } from "@/lib/logger";

// ── Types ──────────────────────────────────────────────────────────────────────

export type CostingMethod = "fifo" | "weighted_average" | "standard_cost";

export interface COGSResult {
  cogsPerUnit: string;
  totalCOGS: string;
  costingMethod: CostingMethod;
  remainingQty: string;
  remainingValue: string;
}

export interface InventoryValuationItem {
  itemId: number;
  name: string;
  qty: string;
  unitCost: string;
  totalValue: string;
  method: CostingMethod;
}

export interface InventoryValuationResult {
  items: InventoryValuationItem[];
  totalValue: string;
}

export interface LandedCostAllocationInput {
  allocationId: number;
  costType: string;
  totalCost: string;
  allocationMethod: "quantity" | "value" | "weight" | "volume";
  lines: LandedCostLineInput[];
}

export interface LandedCostLineInput {
  itemId?: number;
  productId?: number;
  baseQuantity?: string;
  baseValue?: string;
  weight?: string;
  volume?: string;
}

export interface LandedCostAllocationResult {
  lines: Array<{
    itemId?: number;
    productId?: number;
    allocatedCost: string;
    newUnitCost: string;
  }>;
}

export interface InventoryAdjustmentInput {
  companySlug: string;
  userEmail: string;
  userUid: string;
  itemId: number;
