/**
 * cron-runner.ts — Periodic job runner for AI Fabric maintenance tasks.
 *
 * In production, these should be wired to a real cron system (BullMQ repeatable
 * jobs, node-cron, or Vercel Cron). This module provides the functions and
 * a manual trigger for development/testing.
 */

import { logger } from "@/lib/logger";

// Phase 4: Worker scaling
import { scaleWorkers } from "./worker-scaler";
// Phase 11: Learning engine promotion
import { promoteCandidates } from "./learning-engine";
// Phase 14: AI Score computation
import { computeAndSaveScore } from "./ai-score";
// Phase 8: Profit snapshots
import { saveProfitSnapshot } from "./profit-engine";

interface CronJobResult {
  job: string;
  success: boolean;
  durationMs: number;
  error?: string;
  details?: string;
}

/** Run all scheduled AI Fabric maintenance jobs. */
export async function runAllCronJobs(): Promise<CronJobResult[]> {
  const results: CronJobResult[] = [];
  const companies = await getActiveCompanies();

  for (const company of companies) {
    // AI Score
    results.push(await safeRun("ai-score", async () => {
      const score = await computeAndSaveScore(company.slug);
      return `Score: ${score.score}`;
    }));

    // Profit snapshot (daily period: today 00:00 → now)
    results.push(await safeRun("profit-snapshots", async () => {
      const now = new Date();
      const dayStart = new Date(now.getFullYear(), now.getMonth(), now.getDate());
      await saveProfitSnapshot(company.slug, dayStart, now);
      return `Snapshot saved for ${company.slug}`;
    }));
  }

  // Worker scaling (platform-wide, no company arg)
  results.push(await safeRun("worker-scaling", async () => {
    await scaleWorkers();
    return "Worker scaling complete";
  }));

  // Learning engine promotion (platform-wide)
  results.push(await safeRun("learning-engine-promotion", async () => {
    const result = await promoteCandidates();
    return `Promoted ${result.promoted}, rejected ${result.rejected}`;
  }));

  const successCount = results.filter((r) => r.success).length;
  logger.info(`[cron-runner] Completed: ${successCount}/${results.length} jobs succeeded`);

  return results;
}

async function safeRun(job: string, fn: () => Promise<string>): Promise<CronJobResult> {
  const t0 = Date.now();
  try {
    const details = await fn();
    return { job, success: true, durationMs: Date.now() - t0, details };
  } catch (err) {
    const msg = err instanceof Error ? err.message : String(err);
    logger.error(`[cron-runner] ${job} failed`, { err: msg });
    return { job, success: false, durationMs: Date.now() - t0, error: msg };
  }
}

async function getActiveCompanies(): Promise<Array<{ slug: string }>> {
  try {
    const { db } = await import("@/lib/db");
    return db.company.findMany({
      select: { slug: true },
    });
  } catch {
    return [];
  }
}

/** Run a single named cron job. */
export async function runSingleJob(jobName: string): Promise<CronJobResult> {
  const jobs: Record<string, () => Promise<string>> = {
    "learning-engine-promotion": async () => {
      const result = await promoteCandidates();
      return `Promoted ${result.promoted}, rejected ${result.rejected}`;
    },
    "worker-scaling": async () => {
      await scaleWorkers();
      return "Worker scaling complete";
    },
  };

  const fn = jobs[jobName];
  if (!fn) {
    return { job: jobName, success: false, durationMs: 0, error: `Unknown job: ${jobName}` };
  }

  return safeRun(jobName, fn);
}

/**
 * heat-map.ts — Phase 10: Hourly request heat map and predictive scaling.
 *
 * Builds a 24×7 matrix (hour × dayOfWeek) of average request counts from
 * AIRequestLog data. Uses this to suggest optimal workerPoolSize for the
 * current hour via getPredictiveScale().
 *
 * Minimum data requirement: 7 complete days of data.
 * Returns null from getHeatMap() if insufficient data.
 *
 * Exports:
 *   getHeatMap(companySlug, daysNeeded?)  → number[][] | null  (24 rows × 7 cols)
 *   getPredictiveScale(companySlug)       → number | null
 *   hasEnoughData(companySlug, daysNeeded?) → boolean
 */

import { db } from "@/lib/db";
import { logger } from "@/lib/logger";

// ─── Constants ──────────────────────────────────────────────────────────────

/** Minimum days of data required to build a meaningful heat map. */
const MIN_DAYS_REQUIRED = 7;

/** Default number of days to look back. */
const DEFAULT_DAYS_NEEDED = 7;

/** Workers per average request per hour (tunable scaling factor). */
const WORKERS_PER_REQUEST_PER_HOUR = 0.5;

/** Minimum suggested worker pool size. */
const MIN_SUGGESTED_WORKERS = 1;

/** Maximum suggested worker pool size. */
const MAX_SUGGESTED_WORKERS = 64;

// ─── Types ──────────────────────────────────────────────────────────────────

/**
 * 24×7 matrix: heatMap[hour][dayOfWeek] = average request count.
 * dayOfWeek: 0=Sunday, 1=Monday, ..., 6=Saturday
 */
export type HeatMapMatrix = number[][];

// ─── Public API ─────────────────────────────────────────────────────────────

/**
 * Check if a company has enough historical data to build a heat map.
 *
 * @param companySlug - The company to check
 * @param daysNeeded - Number of days required (default: 7)
 * @returns true if the company has data spanning at least daysNeeded days
 */
export async function hasEnoughData(
  companySlug: string,
  daysNeeded: number = DEFAULT_DAYS_NEEDED,
): Promise<boolean> {
  const earliestLog = await db.aIRequestLog.findFirst({
    where: { companySlug },
    orderBy: { createdAt: "asc" },
    select: { createdAt: true },
  });

  if (!earliestLog) return false;

  const now = new Date();
  const daysSpan = (now.getTime() - earliestLog.createdAt.getTime()) / (1000 * 60 * 60 * 24);

  return daysSpan >= daysNeeded;
}

/**
 * Build a 24×7 heat map of average request counts for a company.
 *
 * Returns null if there is insufficient data (less than daysNeeded days
 * of history). The matrix is indexed as heatMap[hour][dayOfWeek].
 *
 * Each cell contains the AVERAGE number of requests in that hour+day slot
 * across all weeks in the lookback period.
 *
 * @param companySlug - The company to analyze
 * @param daysNeeded - Number of days to look back (default: 7)
 * @returns 24×7 matrix of average request counts, or null if insufficient data
 */
export async function getHeatMap(
  companySlug: string,
  daysNeeded: number = DEFAULT_DAYS_NEEDED,
): Promise<HeatMapMatrix | null> {
  // Check if we have enough data
  const enoughData = await hasEnoughData(companySlug, daysNeeded);
  if (!enoughData) return null;

  const since = new Date(Date.now() - daysNeeded * 24 * 60 * 60 * 1000);

  // Fetch all request logs in the period
  const logs = await db.aIRequestLog.findMany({
    where: {
      companySlug,
      createdAt: { gte: since },
    },
    select: { createdAt: true },
  });

  if (logs.length === 0) return null;

  // Build a 24×7 count matrix and a 24×7 day-count matrix
  // (track how many days contributed to each slot for averaging)
  const counts: number[][] = Array.from({ length: 24 }, () => Array(7).fill(0));
  const daySet: boolean[][] = Array.from({ length: 24 }, () => Array(7).fill(false));

  for (const log of logs) {
    const hour = log.createdAt.getHours(); // 0-23
    const dow = log.createdAt.getDay();    // 0=Sun, 6=Sat
    counts[hour][dow] += 1;
    daySet[hour][dow] = true;
  }

  // Compute averages: count / number_of_weeks_in_period
  const weeksInPeriod = daysNeeded / 7;
  const avgCounts: number[][] = Array.from({ length: 24 }, (_, h) =>
    Array.from({ length: 7 }, (_, d) => {
      if (!daySet[h][d]) return 0;
      return Math.round((counts[h][d] / weeksInPeriod) * 100) / 100;
    }),
  );

  return avgCounts;
}

/**
 * Suggest an optimal workerPoolSize based on current hour's historical load.
 *
 * Uses the heat map to look up the average request count for the current
 * hour and day-of-week, then applies a scaling factor.
 *
 * Returns null if there is insufficient historical data.
 *
 * @param companySlug - The company to analyze
 * @returns Suggested worker pool size, or null if insufficient data
 */
export async function getPredictiveScale(
  companySlug: string,
): Promise<number | null> {
  const heatMap = await getHeatMap(companySlug);
  if (!heatMap) return null;

  const now = new Date();
  const currentHour = now.getHours();
  const currentDow = now.getDay();

  const avgRequests = heatMap[currentHour][currentDow];

  // Apply scaling factor: workers = avgRequests * factor
  let suggested = Math.round(avgRequests * WORKERS_PER_REQUEST_PER_HOUR);

  // Clamp to bounds
  suggested = Math.max(MIN_SUGGESTED_WORKERS, Math.min(suggested, MAX_SUGGESTED_WORKERS));

  return suggested;
}

/**
 * ai-fabric/provider-optimizer.ts — Task-type → provider routing.
 *
 * Phase 3 of AI Fabric. Maps each AIRequestType to its optimal primary
 * and fallback provider. Unlike the existing smartRouter (which picks by
 * CAPABILITY: chat, invoice-extraction, reasoning, vision), this layer
 * routes by BUSINESS TASK TYPE (ocr, whatsapp, financial_analysis, matching).
 *
 * Default mapping (based on actual code audit of GarfiX's current usage):
 *
 *   ocr               → capability "invoice-extraction" → vision-capable model
 *   whatsapp          → capability "chat" → fast/cheap model
 *   financial_analysis → capability "reasoning" → reasoning model
 *   matching          → capability "chat" → same model as product matching
 *   other             → capability "chat" → general model
 *
 * Actual models used in current codebase (audited):
 *   - invoice-brain OCR: callAIWithFallback({ capability: "invoice-extraction" })
 *     → smartRouter picks best model for invoice-extraction from AIModelRegistry
 *   - product matching: callAI() with Arabic judge prompt → legacy provider chain
 *   - WhatsApp: logging only (AI not yet implemented)
 *   - financial_analysis: not yet implemented
 *
 * Fallback: if primaryProvider fails (timeout/rate-limit), automatically
 * switches to fallbackProvider + logs the reason.
 *
 * Source: ProviderConfig table (seeded in seed script), falls back to
 *         capability-based smartRouter if no config exists.
 */

import { db } from "@/lib/db";
import { logger } from "@/lib/logger";
import { callAIWithFallback, type RoutedChatOptions } from "@/lib/ai/smartRouter";
import type { AIRequestType, ProviderRoutingDecision } from "./types";
import { getCostRates } from "@/lib/ai/costTracker";

// ─── Task type → capability mapping (audited from actual code) ──────────────
//
// These map BUSINESS TASK TYPES to AI CAPABILITIES that the smartRouter
// understands. The smartRouter then picks the best healthy model for that
// capability from AIModelRegistry.

const TASK_CAPABILITY_MAP: Record<AIRequestType, string> = {
  // invoice-brain/aiFallback.ts:128 calls callAIWithFallback({ capability: "invoice-extraction" })
  ocr: "invoice-extraction",

  // WhatsApp webhook: currently logging only, but when AI is implemented
  // it will need fast/cheap responses for chat-like interactions
  whatsapp: "chat",

  // Financial analysis requires multi-step reasoning (not yet implemented)
  financial_analysis: "reasoning",

  // aiProductResolver.ts:17 uses callAI() (legacy chain) for Arabic product matching
  // This is a chat-style JSON extraction — maps to "chat" capability
  matching: "chat",

  // Default fallback
  other: "chat",
};

// ─── Default provider configs (seeded if ProviderConfig table is empty) ────
//
// These reflect the ACTUAL models used in the current codebase (not invented):
//   - Invoice OCR: smartRouter picks by "invoice-extraction" capability
//   - Product matching: legacy chain → z-ai-glm (sandbox) or company's openrouterModel
//   - WhatsApp: not yet AI-enabled
//   - Financial analysis: not yet implemented

const DEFAULT_PROVIDERS: Record<AIRequestType, { primary: string; fallback: string }> = {
  ocr: {
    // invoice-brain uses callAIWithFallback → smartRouter with capability "invoice-extraction"
    // Primary: best registry model, Fallback: legacy chain (z-ai-glm in sandbox)
    primary: "smart-router:invoice-extraction",
    fallback: "legacy:z-ai-glm",
  },
  whatsapp: {
    // Not yet AI-enabled — placeholder
    primary: "smart-router:chat",
    fallback: "legacy:z-ai-glm",
  },
  financial_analysis: {
    // Not yet implemented — placeholder
    primary: "smart-router:reasoning",
    fallback: "legacy:z-ai-glm",
  },
  matching: {
    // aiProductResolver uses callAI() (legacy chain)
    primary: "smart-router:chat",
    fallback: "legacy:z-ai-glm",
  },
  other: {
    primary: "smart-router:chat",
    fallback: "legacy:z-ai-glm",
  },
};

// ─── Cache (1-min TTL) to avoid DB hit on every request ────────────────────

interface CachedConfig {
  taskType: string;
  primaryProvider: string;
  fallbackProvider: string;
  expiresAt: number;
}
const configCache = new Map<string, CachedConfig>();
const CONFIG_CACHE_TTL_MS = 60_000;

/**
 * Get the provider routing for a task type.
 *
 * 1. Check in-memory cache (1-min TTL)
 * 2. Check ProviderConfig table
 * 3. Fall back to DEFAULT_PROVIDERS (based on code audit)
 *
 * Returns: { taskType, primaryProvider, fallbackProvider, usedFallback, fallbackReason? }
 */
export async function getProviderRouting(taskType: AIRequestType): Promise<ProviderRoutingDecision> {
  const cached = configCache.get(taskType);
  if (cached && cached.expiresAt > Date.now()) {
    return {
      taskType,
      primaryProvider: cached.primaryProvider,
      fallbackProvider: cached.fallbackProvider,
      usedFallback: false,
    };
  }

  // Check ProviderConfig table
  const config = await db.providerConfig.findUnique({
    where: { taskType },
  });

  let primaryProvider: string;
  let fallbackProvider: string;

  if (config) {
    primaryProvider = config.primaryProvider;
    fallbackProvider = config.fallbackProvider;
  } else {
    const defaults = DEFAULT_PROVIDERS[taskType] || DEFAULT_PROVIDERS.other;
    primaryProvider = defaults.primary;
    fallbackProvider = defaults.fallback;
  }

  // Cache the result
  configCache.set(taskType, {
    taskType,
    primaryProvider,
    fallbackProvider,
    expiresAt: Date.now() + CONFIG_CACHE_TTL_MS,
  });

  return {
    taskType,
    primaryProvider,
    fallbackProvider,
    usedFallback: false,
  };
}

/**
 * Call the AI provider for a task type, with automatic fallback.
 *
 * This integrates with the existing smartRouter when the provider is
 * "smart-router:*", and falls back to the legacy callAI chain otherwise.
 *
 * @param taskType - Business task type (ocr, whatsapp, etc.)
 * @param options - Chat options (messages, temperature, etc.)
 * @returns The AI response + routing decision
 */
export async function callWithProviderRouting(
  taskType: AIRequestType,
  options: Omit<RoutedChatOptions, "capability">,
): Promise<{
  content: string;
  provider: string;
  tokensIn?: number;
  tokensOut?: number;
  routingDecision: ProviderRoutingDecision;
}> {
  const routing = await getProviderRouting(taskType);
  const capability = TASK_CAPABILITY_MAP[taskType] || "chat" as const;

  try {
    // If primary is a smart-router reference, use callAIWithFallback
    if (routing.primaryProvider.startsWith("smart-router:")) {
      const result = await callAIWithFallback({
        ...options,
        capability: capability as "chat" | "invoice-extraction" | "reasoning" | "vision",
      });

      const provider = result.usedModel
        ? `${result.usedModel.provider}/${result.usedModel.model}`
        : "legacy-fallback";

      return {
        content: result.content,
        provider,
        tokensIn: result.usage?.prompt_tokens,
        tokensOut: result.usage?.completion_tokens,
        routingDecision: routing,
      };
    }

    // Otherwise use the legacy callAI
    const { callAI } = await import("@/lib/aiProvider");
    const result = await callAI(options as Parameters<typeof callAI>[0]);

    return {
      content: result.content,
      provider: `legacy:${result.model || "unknown"}`,
      tokensIn: result.usage?.prompt_tokens,
      tokensOut: result.usage?.completion_tokens,
      routingDecision: routing,
    };
  } catch (err) {
    // Primary failed — try fallback
    const errorMsg = err instanceof Error ? err.message : String(err);
    logger.warn("[provider-optimizer] primary failed, trying fallback", {
      taskType,
      primary: routing.primaryProvider,
      err: errorMsg.slice(0, 200),
    });

    routing.usedFallback = true;
    routing.fallbackReason = errorMsg.slice(0, 200);

    try {
      const { callAI } = await import("@/lib/aiProvider");
      const result = await callAI(options as Parameters<typeof callAI>[0]);

      return {
        content: result.content,
        provider: `fallback:${result.model || "unknown"}`,
        tokensIn: result.usage?.prompt_tokens,
        tokensOut: result.usage?.completion_tokens,
        routingDecision: routing,
      };
    } catch (fallbackErr) {
      const fbMsg = fallbackErr instanceof Error ? fallbackErr.message : String(fallbackErr);
      logger.error("[provider-optimizer] both primary and fallback failed", {
        taskType,
        fallback: routing.fallbackProvider,
        err: fbMsg.slice(0, 200),
      });
      throw fallbackErr;
    }
  }
}

/**
 * Seed the ProviderConfig table with defaults.
 * Run once during initial setup. Safe to re-run (upsert).
 */
export async function seedProviderConfigs(): Promise<void> {
  const tasks: AIRequestType[] = ["ocr", "whatsapp", "financial_analysis", "matching", "other"];

  for (const taskType of tasks) {
    const defaults = DEFAULT_PROVIDERS[taskType];
    await db.providerConfig.upsert({
      where: { taskType },
      create: {
        taskType,
        primaryProvider: defaults.primary,
        fallbackProvider: defaults.fallback,
      },
      update: {
        primaryProvider: defaults.primary,
        fallbackProvider: defaults.fallback,
      },
    });
  }

  logger.info("[provider-optimizer] seeded ProviderConfig table with defaults", {
    count: tasks.length,
  });
}

/**
 * scheduler.ts — Phase 5: Fair-share AI worker scheduler.
 *
 * Each company gets a base allocation equal to its workerPoolSize.
 * When a company is idle (empty queue), its excess capacity is temporarily
 * made available to other companies — but NEVER beyond their own tier ceiling,
 * and resources are returned IMMEDIATELY when the idle company sends a new
 * request (starvation prevention).
 *
 * This scheduler is stateless between calls — it queries the DB for current
 * queue depths and runtime configs on each invocation.
 *
 * Exports:
 *   scheduleNextJob()           → { companySlug, queueName } | null
 *   getAllocationMap()          → Record<string, AllocationInfo>
 *   requestSlot(companySlug)    → boolean (granted / denied)
 */

import { db } from "@/lib/db";
import { logger } from "@/lib/logger";
import { getValkeyClient } from "@/lib/valkey";
import { TIER_WORKER_LIMITS, planToTier, type SLATier } from "./types";

// ─── Types ───────────────────────────────────────────────────────────────────

export interface AllocationInfo {
  baseAllocation: number;   // company's own workerPoolSize
  borrowedSlots: number;    // extra slots borrowed from idle companies
  totalAvailable: number;   // baseAllocation + borrowedSlots
  tierCeiling: number;      // maximum allowed for this plan
  currentQueueDepth: number;
  isIdle: boolean;
}

// ─── Internal state ──────────────────────────────────────────────────────────

/**
 * Set of company slugs that are currently considered "active" (have sent a
 * request in this cycle). Used for starvation prevention: when an idle
 * company's queue goes non-empty, we immediately reclaim its borrowed slots.
 *
 * Valkey-backed: SET "ai-fabric:active-slugs" with 60s TTL (auto-refreshed).
 * Falls back to in-memory Set when Valkey is unavailable.
 */
const activeSlugs = new Set<string>();

const ACTIVE_SLUGS_KEY = "ai-fabric:active-slugs";
const ACTIVE_SLUGS_TTL = 60; // seconds — short TTL, refreshed on each requestSlot

// ─── Public API ─────────────────────────────────────────────────────────────

/**
 * Request a processing slot for a company.
 * Returns true if the company can proceed (has available capacity),
 * false if at/beyond its allocation.
 *
 * This is the starvation-prevention gate: if a company was previously idle
 * and now has work, we immediately mark it active and reclaim any borrowed slots.
 */
export async function requestSlot(companySlug: string): Promise<boolean> {
  // Mark this company as active (has pending work)
  activeSlugs.add(companySlug);

  // Persist to Valkey for multi-instance consistency
  try {
    const valkey = await getValkeyClient();
    if (valkey) {
      await valkey.sadd(ACTIVE_SLUGS_KEY, companySlug);
      await valkey.expire(ACTIVE_SLUGS_KEY, ACTIVE_SLUGS_TTL);
    }
  } catch {
    // Valkey failed — in-memory fallback is already set
  }

  const alloc = await getAllocationMap();
  const info = alloc[companySlug];
  if (!info) return false;

  // Count how many jobs are currently running for this company
  const runningCount = await db.jobQueue.count({
    where: {
      queue: `ai-queue:${companySlug}`,
      status: "running",
    },
  });

  return runningCount < info.totalAvailable;
}

/**
 * Get the full allocation map for all active companies.
 *
 * Fair-share algorithm:
 *  1. Every company gets baseAllocation = workerPoolSize
 *  2. Companies with empty queues are "idle" → their base slots become available
 *  3. Idle companies' excess slots are distributed to busy companies (up to their ceiling)
 *  4. When a previously idle company becomes active, its slots are reclaimed immediately
 */
export async function getAllocationMap(): Promise<Record<string, AllocationInfo>> {
  // Fetch all active runtimes with company info
  const runtimes = await db.companyRuntime.findMany({
    where: { status: "active" },
    include: { company: { select: { slug: true, plan: true } } },
  });

  // Build initial allocation map
  const map: Record<string, AllocationInfo> = {};
  const busySlugs: string[] = [];
  const idleSlugs: string[] = [];
  let totalIdleExcess = 0;

  for (const rt of runtimes) {
    const slug = rt.company.slug;
    const tier = planToTier(rt.company.plan);
    const ceiling = TIER_WORKER_LIMITS[tier] as number;
    const queueDepth = await getCompanyQueueDepth(slug);
    const isIdle = queueDepth === 0 && !activeSlugs.has(slug);

    // Also check Valkey for cross-instance active slugs
    if (isIdle) {
      try {
        const valkey = await getValkeyClient();
        if (valkey) {
          const isValkeyActive = await valkey.sismember(ACTIVE_SLUGS_KEY, slug);
          if (isValkeyActive) {
            activeSlugs.add(slug); // sync local cache
          }
          // Use the combined check: if active in Valkey, not idle
        }
      } catch {
        // Valkey failed — use in-memory only
      }
    }

    map[slug] = {
      baseAllocation: rt.workerPoolSize,
      borrowedSlots: 0,
      totalAvailable: rt.workerPoolSize,
      tierCeiling: ceiling,
      currentQueueDepth: queueDepth,
      isIdle,
    };

    if (isIdle) {
      // All of this company's slots are "excess" when idle
      idleSlugs.push(slug);
      totalIdleExcess += rt.workerPoolSize;
    } else {
      busySlugs.push(slug);
    }
  }

  // Distribute idle excess to busy companies (fair-share among them)
  if (busySlugs.length > 0 && totalIdleExcess > 0) {
    // Sort busy companies by queue depth descending (most urgent first)
    busySlugs.sort((a, b) => map[b].currentQueueDepth - map[a].currentQueueDepth);

    const perCompany = Math.floor(totalIdleExcess / busySlugs.length);
    let remainder = totalIdleExcess - perCompany * busySlugs.length;

    for (const slug of busySlugs) {
      const info = map[slug];
      const headroom = info.tierCeiling - info.baseAllocation;
      let borrow = Math.min(perCompany, headroom);
      // Distribute remainder one-by-one to companies that still have headroom
      if (remainder > 0 && borrow < headroom) {
        borrow += 1;
        remainder -= 1;
      }
      borrow = Math.max(borrow, 0);

      info.borrowedSlots = borrow;
      info.totalAvailable = info.baseAllocation + borrow;
    }
  }

  return map;
}

/**
 * Pick the next company that should get a worker assignment.
 * Priority: highest queue depth among companies that still have headroom.
 * Returns null if no company needs more capacity.
 */
export async function scheduleNextJob(): Promise<{
  companySlug: string;
  queueName: string;
} | null> {
  const alloc = await getAllocationMap();

  let bestSlug: string | null = null;
  let bestDepth = 0;

  for (const [slug, info] of Object.entries(alloc)) {
    if (info.isIdle) continue;
    if (info.currentQueueDepth <= 0) continue;

    // Count currently running jobs
    const runningCount = await db.jobQueue.count({
      where: {
        queue: `ai-queue:${slug}`,
        status: "running",
      },
    });

    // Only consider companies that can accept more work
    if (runningCount >= info.totalAvailable) continue;

    // Pick the one with highest queue depth
    if (info.currentQueueDepth > bestDepth) {
      bestDepth = info.currentQueueDepth;
      bestSlug = slug;
    }
  }

  if (!bestSlug) return null;

  return {
    companySlug: bestSlug,
    queueName: `ai-queue:${bestSlug}`,
  };
}

/**
 * Reset the active-slug set. Call between test cases or on a new scheduling cycle.
 */
export function __resetActiveSlugs(): void {
  activeSlugs.clear();
}

// ─── Helpers ────────────────────────────────────────────────────────────────

async function getCompanyQueueDepth(companySlug: string): Promise<number> {
  return db.jobQueue.count({
    where: {
      queue: `ai-queue:${companySlug}`,
      status: { in: ["pending", "running"] },
    },
  });
}

/**
 * worker-marketplace.ts — Phase 9: Global worker pool with SLA-based priority
 * and cross-tier preemption.
 *
 * Instead of per-company fixed worker pools, this module implements a single
 * shared "global pool" concept where workers are allocated based on SLA tier
 * priority and wait time. Enterprise requests always get higher priority.
 *
 * Key behaviours:
 *   - Priority function: f(slaTier, waitTimeMs) — enterprise >> business >> starter
 *   - Preemption: if an enterprise request is about to exceed maxAcceptableLatencyMs,
 *     it can grab a worker from a starter/business WAITING queue
 *   - NEVER interrupts a running job — only preempts from the waiting queue
 *   - SLA defaults: enterprise=200ms, business=800ms, starter=2000ms
 *
 * Exports:
 *   getGlobalPoolStatus()                              → GlobalPoolStatus
 *   prioritizeRequest(companySlug, requestType, waitTimeMs) → number (priority score)
 *   canPreempt(fromTier, toTier)                       → boolean
 */

import { db } from "@/lib/db";
import { logger } from "@/lib/logger";
import type { SLATier } from "./types";

// ─── SLA Latency Defaults (ms) ──────────────────────────────────────────────

export const SLA_LATENCY_DEFAULTS: Record<SLATier, number> = {
  enterprise: 200,
  business: 800,
  starter: 2000,
  trial: 5000,
};

// Tier priority weights — higher = more important
const TIER_BASE_PRIORITY: Record<string, number> = {
  enterprise: 1000,
  business: 500,
  starter: 100,
  trial: 50,
};

// ─── Types ──────────────────────────────────────────────────────────────────

export interface GlobalPoolStatus {
  totalWorkers: number;
  runningJobs: number;
  waitingJobs: number;
  /** Per-tier waiting counts. */
  waitingByTier: Record<string, number>;
  /** Per-tier running counts. */
  runningByTier: Record<string, number>;
}

export interface QueuedRequest {
  id: string;
  companySlug: string;
  requestType: string;
  slaTier: SLATier;
  waitTimeMs: number;
  maxAcceptableLatencyMs: number;
  priority: number;
}

// ─── Public API ─────────────────────────────────────────────────────────────

/**
 * Compute a priority score for a request. Higher = should be processed sooner.
 *
 * Formula:
 *   priority = tierBase + (waitTimeMs / maxAcceptableLatencyMs) * tierBase
 *
 * Enterprise requests start at 1000 and scale up as waitTime approaches their
 * 200ms SLA. Starter requests start at 100 and scale toward their 2000ms SLA.
 * This ensures enterprise requests are ALWAYS prioritized over lower tiers.
 */
export function prioritizeRequest(
  _companySlug: string,
  _requestType: string,
  waitTimeMs: number,
  slaTier: SLATier = "starter",
  maxAcceptableLatencyMs?: number,
): number {
  const tierBase = TIER_BASE_PRIORITY[slaTier] ?? 50;
  const maxLatency = maxAcceptableLatencyMs ?? SLA_LATENCY_DEFAULTS[slaTier];

  // Time-pressure factor: 0→1 as waitTime approaches/exceeds SLA
  const timePressure = Math.min(waitTimeMs / maxLatency, 2.0);

  return tierBase * (1 + timePressure);
}

/**
 * Determine if a request from toTier can preempt a waiting request in fromTier.
 *
 * Rules:
 *   - Can NEVER preempt from the same or higher tier
 *   - Can preempt from a LOWER tier ONLY
 *   - Enterprise can preempt from business and starter waiting queues
 *   - Business can preempt from starter waiting queues
 *   - Starter/trial can NEVER preempt
 */
export function canPreempt(fromTier: SLATier, toTier: SLATier): boolean {
  const tierOrder: Record<string, number> = {
    enterprise: 3,
    business: 2,
    starter: 1,
    trial: 0,
  };

  const toRank = tierOrder[toTier] ?? 0;
  const fromRank = tierOrder[fromTier] ?? 0;

  // Can only preempt from a LOWER tier (strictly)
  return toRank > fromRank;
}

/**
 * Get the current global pool status: total workers, running/waiting jobs
 * broken down by SLA tier.
 *
 * This queries CompanyRuntime + JobQueue to compute the current picture.
 */
export async function getGlobalPoolStatus(): Promise<GlobalPoolStatus> {
  // Get all active runtimes with their company's plan for tier info
  const runtimes = await db.companyRuntime.findMany({
    where: { status: "active" },
    include: { company: { select: { slug: true, plan: true } } },
  });

  let totalWorkers = 0;
  const tierMap = new Map<string, { running: number; waiting: number }>();

  // Initialize tier buckets
  for (const tier of ["enterprise", "business", "starter", "trial"]) {
    tierMap.set(tier, { running: 0, waiting: 0 });
  }

  for (const rt of runtimes) {
    const slug = rt.company.slug;
    totalWorkers += rt.workerPoolSize;

    // Determine SLA tier from CompanyRuntime (if set) or from plan
    const slaTier = (rt.slaTier as SLATier) || planToSlaTier(rt.company.plan);
    const queueName = `ai-queue:${slug}`;

    // Count running jobs for this company
    const running = await db.jobQueue.count({
      where: { queue: queueName, status: "running" },
    });

    // Count waiting (pending) jobs
    const waiting = await db.jobQueue.count({
      where: { queue: queueName, status: "pending" },
    });

    const bucket = tierMap.get(slaTier) ?? tierMap.get("starter")!;
    bucket.running += running;
    bucket.waiting += waiting;
  }

  let runningJobs = 0;
  let waitingJobs = 0;
  const waitingByTier: Record<string, number> = {};
  const runningByTier: Record<string, number> = {};

  for (const [tier, counts] of tierMap) {
    waitingByTier[tier] = counts.waiting;
    runningByTier[tier] = counts.running;
    runningJobs += counts.running;
    waitingJobs += counts.waiting;
  }

  return {
    totalWorkers,
    runningJobs,
    waitingJobs,
    waitingByTier,
    runningByTier,
  };
}

/**
 * Find a preemptable job from the waiting queue.
 *
 * Given a requesting tier (toTier) and the company slug, looks for the
 * LOWEST-priority waiting job across all companies with LOWER tiers.
 * Returns the job to preempt (to be re-queued) or null if no preemption possible.
 *
 * IMPORTANT: Only picks from "pending" jobs — NEVER from "running" jobs.
 */
export async function findPreemptableJob(
  toTier: SLATier,
  excludeCompanySlug?: string,
): Promise<{ jobQueueId: number; companySlug: string; queue: string } | null> {
  const tierOrder: Record<string, number> = {
    enterprise: 3,
    business: 2,
    starter: 1,
    trial: 0,
  };

  const toRank = tierOrder[toTier] ?? 0;

  // Get all active runtimes with their tiers
  const runtimes = await db.companyRuntime.findMany({
    where: { status: "active" },
    include: { company: { select: { slug: true, plan: true } } },
  });

  let bestCandidate: { jobQueueId: number; companySlug: string; queue: string; tierRank: number } | null = null;

  for (const rt of runtimes) {
    const slug = rt.company.slug;
    if (excludeCompanySlug && slug === excludeCompanySlug) continue;

    const slaTier = (rt.slaTier as SLATier) || planToSlaTier(rt.company.plan);
    const fromRank = tierOrder[slaTier] ?? 0;

    // Can only preempt from strictly lower tier
    if (fromRank >= toRank) continue;

    // Find the lowest-priority waiting job for this company
    const oldestPending = await db.jobQueue.findFirst({
      where: {
        queue: `ai-queue:${slug}`,
        status: "pending",
      },
      orderBy: { scheduledAt: "asc" }, // oldest = lowest priority (waited longest? No — most recent = least urgent for low tier)
      // Actually, we want the most recent pending job (least time invested)
      // But wait — we want to preempt the one that's LEAST urgent.
      // For a starter tier job, the one that's been waiting the LEAST is the best
      // candidate for preemption. So order by scheduledAt DESC.
      // Actually, we just need ANY pending job from a lower tier.
      // Let's pick the one that has been waiting the least (most recent).
    });

    // Re-query: pick the MOST RECENT pending job (least invested)
    const leastInvested = await db.jobQueue.findFirst({
      where: {
        queue: `ai-queue:${slug}`,
        status: "pending",
      },
      orderBy: { scheduledAt: "desc" },
    });

    if (leastInvested) {
      if (!bestCandidate || fromRank < bestCandidate.tierRank) {
        bestCandidate = {
          jobQueueId: leastInvested.id,
          companySlug: slug,
          queue: leastInvested.queue,
          tierRank: fromRank,
        };
      }
    }
  }

  return bestCandidate
    ? { jobQueueId: bestCandidate.jobQueueId, companySlug: bestCandidate.companySlug, queue: bestCandidate.queue }
    : null;
}

// ─── Helpers ────────────────────────────────────────────────────────────────

/**
 * Map a company plan string to an SLA tier for the marketplace.
 * Reuses the planToTier logic but only for marketplace-relevant tiers.
 */
function planToSlaTier(plan: string): SLATier {
  const p = plan.toLowerCase();
  if (p === "enterprise") return "enterprise";
  if (p === "business") return "business";
  if (p === "starter") return "starter";
  return "starter"; // default to starter (not trial — trial doesn't have SLA)
}

/**
 * worker-prediction.ts — Phase 13: Predictive worker pre-scaling.
 *
 * Predicts known demand spikes (first/last day of month — accounting closings)
 * and pre-scales worker pools 10 minutes before the event window.
 *
 * Key behaviours:
 *   - Known events: first day of month, last day of month
 *   - 10 minutes before event → increase workerPoolSize for affected companies
 *   - After event window → gradually decrease (reuses worker-scaler's gradual pattern)
 *   - Only activates if AIRequestLog shows the event historically causes a spike
 *     (need 2+ months of data)
 *
 * Exports:
 *   KNOWN_EVENTS             — list of defined event types
 *   getUpcomingEvents()      — events within the next 24 hours
 *   shouldPreScale(event, companySlug) — whether to pre-scale for this event
 *   getPostEventScaleDown()  — companies currently in post-event wind-down
 */

import { db } from "@/lib/db";
import { logger } from "@/lib/logger";

// ─── Types ──────────────────────────────────────────────────────────────────

export interface KnownEvent {
  type: "month_start" | "month_end";
  /** The actual date of the event (UTC). */
  eventDate: Date;
  /** Window start = 10 min before eventDate midnight UTC. */
  windowStart: Date;
  /** Window end = 2 hours after eventDate midnight UTC. */
  windowEnd: Date;
}

export interface UpcomingEvent extends KnownEvent {
  /** Milliseconds until windowStart. */
  msUntilWindow: number;
}

export interface ScaleDownTarget {
  companySlug: string;
  currentPoolSize: number;
  targetPoolSize: number;
  /** How many steps of −1 remain to reach target. */
  stepsRemaining: number;
}

// ─── Constants ──────────────────────────────────────────────────────────────

/** Minimum historical months of data required to validate spike. */
const MIN_HISTORY_MONTHS = 2;

/** Pre-scale lead time in ms (10 minutes). */
const PRE_SCALE_LEAD_MS = 10 * 60 * 1000;

/** Event window duration in ms (2 hours after event). */
const EVENT_WINDOW_MS = 2 * 60 * 60 * 1000;

/** Minimum spike multiplier to consider an event a real demand spike. */
const SPIKE_MULTIPLIER_THRESHOLD = 1.5;

/** Workers to add during pre-scale (capped by tier ceiling). */
const PRE_SCALE_WORKER_BOOST = 4;

/** Scale-down step size (−1 per step, matching worker-scaler pattern). */
const SCALE_DOWN_STEP = 1;

/** Number of minutes between scale-down steps. */
const SCALE_DOWN_INTERVAL_MS = 5 * 60 * 1000; // 5 minutes

// ─── Exported: KNOWN_EVENTS ─────────────────────────────────────────────────

export const KNOWN_EVENTS = ["month_start", "month_end"] as const;
export type KnownEventType = (typeof KNOWN_EVENTS)[number];

// ─── Internal state (in-process) ────────────────────────────────────────────

/** Tracks which companies have been pre-scaled for which event date. */
const preScaledMap = new Map<string, string>(); // "companySlug:eventDateStr" → true

/** Tracks post-event scale-down targets. */
const scaleDownTargets = new Map<string, { targetPoolSize: number; lastStepAt: number }>();

// ─── Exported: getUpcomingEvents ────────────────────────────────────────────

/**
 * Returns all known events within the next 24 hours.
 * For month_start/month_end, we look at the current month and next month boundaries.
 */
export function getUpcomingEvents(now: Date = new Date()): UpcomingEvent[] {
  const events: UpcomingEvent[] = [];
  const horizon = 24 * 60 * 60 * 1000; // 24 hours

  // Generate candidate events for this month and next month
  const candidates = generateMonthBoundaryEvents(now.getFullYear(), now.getMonth());
  const nextMonthCandidates = generateMonthBoundaryEvents(
    now.getFullYear(),
    now.getMonth() + 1,
  );
  candidates.push(...nextMonthCandidates);

  for (const event of candidates) {
    const msUntilWindow = event.windowStart.getTime() - now.getTime();
    // Include events whose window hasn't ended yet (including currently active)
    if (msUntilWindow <= horizon && now.getTime() < event.windowEnd.getTime()) {
      events.push({ ...event, msUntilWindow });
    }
  }

  return events;
}

/**
 * Generate month_start and month_end events for a given year/month.
 */
function generateMonthBoundaryEvents(year: number, month: number): KnownEvent[] {
  const events: KnownEvent[] = [];

  // First day of month
  const firstDay = new Date(Date.UTC(year, month, 1, 0, 0, 0));
  events.push({
    type: "month_start",
    eventDate: firstDay,
    windowStart: new Date(firstDay.getTime() - PRE_SCALE_LEAD_MS),
    windowEnd: new Date(firstDay.getTime() + EVENT_WINDOW_MS),
  });

  // Last day of month
  const lastDay = new Date(Date.UTC(year, month + 1, 0, 0, 0, 0));
  events.push({
    type: "month_end",
    eventDate: lastDay,
    windowStart: new Date(lastDay.getTime() - PRE_SCALE_LEAD_MS),
    windowEnd: new Date(lastDay.getTime() + EVENT_WINDOW_MS),
  });

  return events;
}

// ─── Exported: shouldPreScale ───────────────────────────────────────────────

/**
 * Determine whether a company should be pre-scaled for a given event.
 *
 * Only returns true if:
 *   1. We're within the pre-scale window (10 min before event)
 *   2. The company hasn't already been pre-scaled for this event
 *   3. Historical data shows the event causes a spike (2+ months, >= 1.5x normal)
 *
 * @param event    — the KnownEvent to evaluate
 * @param companySlug — the company to check
 * @param now     — current time (defaults to Date.now())
 */
export async function shouldPreScale(
  event: KnownEvent,
  companySlug: string,
  now: Date = new Date(),
): Promise<boolean> {
  // 1. Must be within the pre-scale window (between windowStart and eventDate)
  if (now.getTime() < event.windowStart.getTime() || now.getTime() > event.eventDate.getTime()) {
    return false;
  }

  // 2. Check if already pre-scaled for this event
  const eventKey = `${companySlug}:${event.eventDate.toISOString().slice(0, 10)}`;
  if (preScaledMap.has(eventKey)) {
    return false;
  }

  // 3. Check historical spike data (need 2+ months)
  const hasSpike = await checkHistoricalSpike(companySlug, event.type, now);
  if (!hasSpike) {
    logger.info("[worker-prediction] no historical spike — skipping pre-scale", {
      companySlug,
      eventType: event.type,
    });
    return false;
  }

  return true;
}

/**
 * Check if the given event type historically causes a request spike
 * for the company. Requires 2+ months of data with >= 1.5x normal rate.
 */
async function checkHistoricalSpike(
  companySlug: string,
  eventType: KnownEventType,
  now: Date = new Date(),
): Promise<boolean> {
  // Build date ranges for event days vs normal days over the past 3 months
  // All dates in UTC to match AIRequestLog storage
  const monthsToCheck = 3;
  const eventDayCounts: number[] = [];
  const normalDayCounts: number[] = [];

  const utcYear = now.getUTCFullYear();
  const utcMonth = now.getUTCMonth();

  for (let m = 1; m <= monthsToCheck; m++) {
    const lookbackYear = utcYear;
    const lookbackMonth = utcMonth - m;
    // Normalize month/year (handles negative months correctly)
    const eventDate = new Date(Date.UTC(lookbackYear, lookbackMonth, 1));
    const ey = eventDate.getUTCFullYear();
    const em = eventDate.getUTCMonth();

    let eventDay: Date;
    if (eventType === "month_start") {
      eventDay = new Date(Date.UTC(ey, em, 1));
    } else {
      eventDay = new Date(Date.UTC(ey, em + 1, 0));
    }

    // Count requests on the event day
    const nextDay = new Date(Date.UTC(ey, em, eventType === "month_start" ? 2 : 1));
    if (eventType === "month_end") {
      // For month_end, the event day is the last day, so next day is the 1st of next month
      nextDay.setTime(Date.UTC(ey, em + 1, 1));
    }

    const eventCount = await db.aIRequestLog.count({
      where: {
        companySlug,
        createdAt: { gte: eventDay, lt: nextDay },
      },
    });

    // Count requests on a "normal" day (15th of the same month)
    const normalDay = new Date(Date.UTC(ey, em, 15));
    const normalNextDay = new Date(Date.UTC(ey, em, 16));

    const normalCount = await db.aIRequestLog.count({
      where: {
        companySlug,
        createdAt: { gte: normalDay, lt: normalNextDay },
      },
    });

    eventDayCounts.push(eventCount);
    normalDayCounts.push(normalCount);
  }

  // Need at least MIN_HISTORY_MONTHS months with data
  const monthsWithData = eventDayCounts.filter((c) => c > 0 || normalDayCounts[eventDayCounts.indexOf(c)] > 0).length;
  if (monthsWithData < MIN_HISTORY_MONTHS) {
    return false;
  }

  // Calculate average event-day rate vs normal-day rate
  const totalEvent = eventDayCounts.reduce((a, b) => a + b, 0);
  const totalNormal = normalDayCounts.reduce((a, b) => a + b, 0);

  if (totalNormal === 0) return false; // Can't determine spike ratio without normal data

  const avgEventRate = totalEvent / monthsWithData;
  const avgNormalRate = totalNormal / monthsWithData;

  if (avgNormalRate === 0) return false;

  const spikeRatio = avgEventRate / avgNormalRate;

  logger.info("[worker-prediction] spike analysis", {
    companySlug,
    eventType,
    avgEventRate,
    avgNormalRate,
    spikeRatio,
    threshold: SPIKE_MULTIPLIER_THRESHOLD,
  });

  return spikeRatio >= SPIKE_MULTIPLIER_THRESHOLD;
}

/**
 * Execute the pre-scale: boost worker pool for a company.
 * Marks the company as pre-scaled so we don't double-boost.
 */
export async function executePreScale(
  event: KnownEvent,
  companySlug: string,
): Promise<void> {
  const company = await db.company.findUnique({
    where: { slug: companySlug },
    select: { id: true, plan: true },
  });

  if (!company) return;

  const tier = planToTier(company.plan);
  const ceiling = getTierCeiling(tier);

  const runtime = await db.companyRuntime.findUnique({
    where: { companyId: company.id },
  });

  if (!runtime || runtime.status !== "active") return;

  const newSize = Math.min(runtime.workerPoolSize + PRE_SCALE_WORKER_BOOST, ceiling);
  if (newSize === runtime.workerPoolSize) return; // already at ceiling

  // Record the pre-event pool size for scale-down target
  scaleDownTargets.set(companySlug, {
    targetPoolSize: runtime.workerPoolSize,
    lastStepAt: 0,
  });

  await db.companyRuntime.update({
    where: { id: runtime.id },
    data: { workerPoolSize: newSize },
  });

  // Mark as pre-scaled
  const eventKey = `${companySlug}:${event.eventDate.toISOString().slice(0, 10)}`;
  preScaledMap.set(eventKey, "true");

  logger.info("[worker-prediction] pre-scaled workers", {
    companySlug,
    eventType: event.type,
    oldSize: runtime.workerPoolSize,
    newSize,
    ceiling,
  });
}

// ─── Exported: getPostEventScaleDown ────────────────────────────────────────

/**
 * Returns companies that should be gradually scaled down after an event window.
 * Reuses the gradual scale-down pattern from worker-scaler (−1 per interval).
 *
 * Call this periodically (e.g. every 5 minutes) to step down worker pools.
 */
export async function getPostEventScaleDown(
  now: Date = new Date(),
): Promise<ScaleDownTarget[]> {
  const targets: ScaleDownTarget[] = [];

  for (const [companySlug, state] of scaleDownTargets.entries()) {
    const runtime = await db.companyRuntime.findFirst({
      where: {
        company: { slug: companySlug },
        status: "active",
      },
      include: { company: { select: { slug: true } } },
    });

    if (!runtime) {
      scaleDownTargets.delete(companySlug);
      continue;
    }

    // Check if enough time has passed for another step
    const interval = _overrideScaleDownInterval ?? SCALE_DOWN_INTERVAL_MS;
    if (now.getTime() - state.lastStepAt < interval) {
      targets.push({
        companySlug,
        currentPoolSize: runtime.workerPoolSize,
        targetPoolSize: state.targetPoolSize,
        stepsRemaining: runtime.workerPoolSize - state.targetPoolSize,
      });
      continue;
    }

    // Execute one scale-down step
    const newSize = Math.max(runtime.workerPoolSize - SCALE_DOWN_STEP, state.targetPoolSize);
    if (newSize !== runtime.workerPoolSize) {
      await db.companyRuntime.update({
        where: { id: runtime.id },
        data: { workerPoolSize: newSize },
      });

      logger.info("[worker-prediction] gradual scale-down step", {
        companySlug,
        oldSize: runtime.workerPoolSize,
        newSize,
        target: state.targetPoolSize,
      });
    }

    // Update last step time
    const stepsRemaining = newSize - state.targetPoolSize;
    if (stepsRemaining <= 0) {
      // Reached target — clean up
      scaleDownTargets.delete(companySlug);
    } else {
      state.lastStepAt = now.getTime();
      targets.push({
        companySlug,
        currentPoolSize: newSize,
        targetPoolSize: state.targetPoolSize,
        stepsRemaining,
      });
    }
  }

  return targets;
}

// ─── Testing helpers ────────────────────────────────────────────────────────

let _overrideScaleDownInterval: number | null = null;

/** Override scale-down interval for testing. */
export function __setScaleDownIntervalMs(ms: number | null): void {
  _overrideScaleDownInterval = ms;
}

/** Reset internal state for testing. */
