}

// ─── Helpers ────────────────────────────────────────────────────────────────

function planToTier(plan: string): string {
  const p = plan.toLowerCase();
  if (p === "enterprise") return "enterprise";
  if (p === "business") return "business";
  if (p === "starter") return "starter";
  return "trial";
}

function getTierCeiling(tier: string): number {
  const limits: Record<string, number> = {
    enterprise: 64,
    business: 4,
    starter: 1,
    trial: 1,
  };
  return limits[tier] ?? 1;
}

/**
 * worker-scaler.ts — Phase 4: Per-company AI worker pool auto-scaler.
 *
 * Each company has a CompanyRuntime row that tracks its current workerPoolSize.
 * The scaler runs periodically (via scaleWorkers()) and adjusts pool sizes
 * based on per-company queue depth and system resource pressure.
 *
 * Key behaviours:
 *   - Queue length > 200 for a sustained period → scale up (+2, capped by tier)
 *   - CPU or memory > 80% → suppress scale-up (don't add workers)
 *   - Queue empty for a sustained period → scale down gradually (−1 at a time)
 *   - Trial/starter plans are hard-capped at their tier ceiling immediately
 *
 * Exports:
 *   getOrCreateRuntime(companyId, plan) → CompanyRuntime
 *   scaleWorkers()                       → void  (call on interval)
 *   getActiveWorkerCounts()              → Record<string, number>
 */

import { db } from "@/lib/db";
import { logger } from "@/lib/logger";
import { TIER_WORKER_LIMITS, planToTier, type SLATier, type RuntimeStatus } from "./types";

// ─── Constants ──────────────────────────────────────────────────────────────

/** Queue name prefix for per-company AI queues. */
export const AI_QUEUE_PREFIX = "ai-queue:";

/** Queue depth threshold that triggers scale-up consideration. */
const QUEUE_OVERFLOW_THRESHOLD = 200;

/** How many consecutive checks with queue > threshold before scaling up. */
const SUSTAINED_OVERFLOW_CHECKS = 2;

/** How many consecutive checks with empty queue before scaling down. */
const SUSTAINED_IDLE_CHECKS = 3;

/** Workers added per scale-up step. */
const SCALE_UP_STEP = 2;

/** Workers removed per scale-down step (gradual). */
const SCALE_DOWN_STEP = 1;

/** System resource ceiling — above this we don't add workers. */
const RESOURCE_CEILING_PCT = 80;

// ─── Internal state (in-process, per-instance) ──────────────────────────────

/** Tracks consecutive overflow counts per companySlug. */
const overflowCounters = new Map<string, number>();

/** Tracks consecutive idle counts per companySlug. */
const idleCounters = new Map<string, number>();

// ─── Public API ─────────────────────────────────────────────────────────────

/**
 * Get or create a CompanyRuntime row for the given company.
 * Initialises workerPoolSize to the tier default if creating new.
 */
export async function getOrCreateRuntime(
  companyId: number,
  plan: string,
): Promise<{
  id: number;
  companyId: number;
  workerPoolSize: number;
  status: RuntimeStatus;
}> {
  const existing = await db.companyRuntime.findUnique({
    where: { companyId },
  });

  if (existing) {
    return {
      id: existing.id,
      companyId: existing.companyId,
      workerPoolSize: existing.workerPoolSize,
      status: existing.status as RuntimeStatus,
    };
  }

  const tier = planToTier(plan);
  const poolSize = TIER_WORKER_LIMITS[tier] as number;

  const created = await db.companyRuntime.create({
    data: {
      companyId,
      workerPoolSize: poolSize,
      status: "active",
    },
  });

  logger.info("[worker-scaler] created runtime for company", {
    companyId,
    tier,
    initialPoolSize: poolSize,
  });

  return {
    id: created.id,
    companyId: created.companyId,
    workerPoolSize: created.workerPoolSize,
    status: created.status as RuntimeStatus,
  };
}

/**
 * Run one scaling pass across all active companies.
 * Call this on an interval (e.g. every 60 seconds).
 */
export async function scaleWorkers(): Promise<void> {
  // 1. Check system resource pressure
  const resourcePressure = getSystemResourcePct();
  if (resourcePressure > RESOURCE_CEILING_PCT) {
    logger.warn("[worker-scaler] system resource pressure too high — skipping scale-up", {
      resourcePressure,
    });
  }

  // 2. Fetch all active runtimes with their company's plan
  const runtimes = await db.companyRuntime.findMany({
    where: { status: "active" },
    include: { company: { select: { id: true, slug: true, plan: true } } },
  });

  for (const rt of runtimes) {
    const slug = rt.company.slug;
    const tier = planToTier(rt.company.plan);
    const ceiling = TIER_WORKER_LIMITS[tier] as number;
    const queueName = `${AI_QUEUE_PREFIX}${slug}`;
    const queueLength = await getQueueLength(queueName);

    if (queueLength > QUEUE_OVERFLOW_THRESHOLD) {
      // ── Scale up path ──────────────────────────────────────
      const prev = overflowCounters.get(slug) ?? 0;
      overflowCounters.set(slug, prev + 1);
      idleCounters.delete(slug); // reset idle tracker

      if (
        prev + 1 >= SUSTAINED_OVERFLOW_CHECKS &&
        rt.workerPoolSize < ceiling &&
        resourcePressure <= RESOURCE_CEILING_PCT
      ) {
        const newSize = Math.min(rt.workerPoolSize + SCALE_UP_STEP, ceiling);
        await db.companyRuntime.update({
          where: { id: rt.id },
          data: { workerPoolSize: newSize },
        });
        logger.info("[worker-scaler] scaled up", {
          slug,
          old: rt.workerPoolSize,
          new: newSize,
          ceiling,
          queueLength,
        });
        // Reset counter after scaling
        overflowCounters.set(slug, 0);
      }
    } else if (queueLength === 0) {
      // ── Scale down path (gradual) ──────────────────────────
      const prev = idleCounters.get(slug) ?? 0;
      idleCounters.set(slug, prev + 1);
      overflowCounters.delete(slug); // reset overflow tracker

      if (prev + 1 >= SUSTAINED_IDLE_CHECKS && rt.workerPoolSize > 1) {
        const newSize = Math.max(rt.workerPoolSize - SCALE_DOWN_STEP, 1);
        await db.companyRuntime.update({
          where: { id: rt.id },
          data: { workerPoolSize: newSize },
        });
        logger.info("[worker-scaler] scaled down (idle)", {
          slug,
          old: rt.workerPoolSize,
          new: newSize,
        });
        idleCounters.set(slug, 0);
      }
    } else {
      // Queue is between 1 and threshold — reset both counters
      overflowCounters.set(slug, 0);
      idleCounters.set(slug, 0);
    }
  }
}

/**
 * Return a map of companySlug → current workerPoolSize for all active runtimes.
 */
export async function getActiveWorkerCounts(): Promise<Record<string, number>> {
  const runtimes = await db.companyRuntime.findMany({
    where: { status: "active" },
    include: { company: { select: { slug: true } } },
  });

  const map: Record<string, number> = {};
  for (const rt of runtimes) {
    map[rt.company.slug] = rt.workerPoolSize;
  }
  return map;
}

// ─── Helpers ────────────────────────────────────────────────────────────────

/**
 * Get queue length for a per-company AI queue.
 * In BullMQ mode this would query Valkey; in fallback mode we count DB rows.
 */
async function getQueueLength(queueName: string): Promise<number> {
  // Use the JobQueue table to count pending/running jobs for this queue
  const count = await db.jobQueue.count({
    where: {
      queue: queueName,
      status: { in: ["pending", "running"] },
    },
  });
  return count;
}

/**
 * Approximate system resource usage (CPU + memory).
 * In production this would query a real metrics endpoint.
 * For sandbox / dev: returns a synthetic value that can be overridden in tests.
 */
let _overrideResourcePct: number | null = null;

export function __setResourcePctForTesting(pct: number | null): void {
  _overrideResourcePct = pct;
}

function getSystemResourcePct(): number {
  if (_overrideResourcePct !== null) return _overrideResourcePct;
  // Default: low resource usage in dev/sandbox
  return 30;
}

/**
 * contextWindow.ts — AI-002 FIX: Context window management
 * Estimates token count and trims conversation history to fit.
 */

// Rough estimate: 1 token ≈ 4 chars for English, ≈ 2 chars for Arabic
export function estimateTokens(text: string): number {
  if (!text) return 0;
  // Arabic chars are roughly 2 chars/token, English 4 chars/token
  const arabicChars = (text.match(/[\u0600-\u06FF]/g) || []).length;
  const otherChars = text.length - arabicChars;
  return Math.ceil(arabicChars / 2 + otherChars / 4);
}

export interface TokenBudget {
  systemPrompt: number;
  history: number;
  userMessage: number;
  response: number;
  total: number;
}

/**
 * Calculate token budget for an AI call.
 * Default context window: 8,000 tokens (safe for most models)
 * Reserve: 1,000 for response, 2,000 for system prompt
 */
export function calculateBudget(options?: {
  contextWindow?: number;
  responseReserve?: number;
  systemPromptTokens?: number;
}): TokenBudget {
  const contextWindow = options?.contextWindow || 8000;
  const responseReserve = options?.responseReserve || 1000;
  const systemPromptTokens = options?.systemPromptTokens || 2000;

  const remaining = contextWindow - responseReserve - systemPromptTokens;
  return {
    systemPrompt: systemPromptTokens,
    history: Math.floor(remaining * 0.6), // 60% of remaining for history
    userMessage: Math.floor(remaining * 0.3), // 30% for current message
    response: responseReserve,
    total: contextWindow,
  };
}

/**
 * Trim conversation history to fit within the token budget.
 * Keeps the most recent messages.
 */
export function trimHistory(
  messages: Array<{ role: string; content: string }>,
  maxTokens: number,
): Array<{ role: string; content: string }> {
  let totalTokens = 0;
  const trimmed: Array<{ role: string; content: string }> = [];

  // Iterate from most recent to oldest
  for (let i = messages.length - 1; i >= 0; i--) {
    const msg = messages[i];
    const tokens = estimateTokens(msg.content);
    if (totalTokens + tokens > maxTokens) break;
    trimmed.unshift(msg);
    totalTokens += tokens;
  }

  // Ensure we always keep at least the last message
  if (trimmed.length === 0 && messages.length > 0) {
    trimmed.push(messages[messages.length - 1]);
  }

  return trimmed;
}

/**
 * costOptimizer.ts — AI Orchestration Layer: request-level cost decision tree.
 *
 * The final layer before an AI call is made. For every incoming request it
 * answers: "do we even need to call the AI, and if so, which tier?"
 *
 * Decision chain (cheap → expensive):
 *
 *   1. PATTERN?      — Invoice-Brain already learned this document shape.
 *                      Return the cached template extraction. Zero AI tokens.
 *   2. CACHE?        — Identical prompt seen recently. Return cached reply.
 *                      Zero AI tokens. (TTL 1h, keyed by sha256(prompt).)
 *   3. SIMPLE TASK?  — Greeting, FAQ, small-talk. Route to a FREE-tier model
 *                      via the Smart Router.
 *   4. COMPLEX TASK? — Invoice extraction on a novel format, multi-step
 *                      reasoning, report generation. Route to the best HEALTHY
 *                      model regardless of tier (may be paid).
 *
 * The optimizer is advisory: callers consult `decide()` and act on the result.
 * It never calls the AI itself — that stays in the route handler so the
 * optimizer remains a pure function of the request context (testable,
 * fast, no side effects).
 */
import { db } from "@/lib/db";
import { logger } from "@/lib/logger";
import { getModelsForCapability, type AICapability } from "./modelRegistry";

export type CostDecisionAction =
  | "use-pattern" // Invoice-Brain template hit — no AI call
  | "use-cache" // Recent identical prompt — no AI call
  | "route-free" // Simple task → free-tier model
  | "route-best"; // Complex task → best healthy model (any tier)

export interface CostDecision {
  action: CostDecisionAction;
  /** Preferred tier when action is route-free / route-best. */
  tier: "free" | "paid" | "any";
  /** Cache key (sha256) when action is use-cache. */
  cacheKey?: string;
  /** Reasoning trail for the dashboard. */
  reason: string;
  /** Estimated savings vs. always-calling-AI (0-1). */
  estimatedSavings: number;
}

// ─── Prompt cache ───────────────────────────────────────────────────────────
//
// A tiny in-memory LRU of recent AI replies, keyed by sha256(messages hash).
// Survives only within the current server process — that's intentional: we
// want to dedupe burst traffic (a user clicking the same button twice) without
// permanently serving stale data. TTL 1 hour.

interface CacheEntry {
  reply: string;
  expiresAt: number;
}
const REPLY_CACHE = new Map<string, CacheEntry>();
const CACHE_TTL_MS = 60 * 60 * 1000; // 1h
const CACHE_MAX = 200;

// Periodic sweep (lazy — runs on every decide() call if 5min elapsed)
let lastSweep = Date.now();
function sweepIfNeeded(): void {
  const now = Date.now();
  if (now - lastSweep < 5 * 60 * 1000) return;
  lastSweep = now;
  for (const [k, v] of REPLY_CACHE) {
    if (v.expiresAt < now) REPLY_CACHE.delete(k);
  }
}

async function sha256(s: string): Promise<string> {
  // Cache keys don't need cryptographic strength — collisions just mean a
  // cache miss. Use a fast non-crypto hash (djb2 + FNV mix) to avoid pulling
  // in the webcrypto subsystem, which can crash Turbopack in some sandboxed
  // runtimes. 16-byte hex output is plenty for deduping prompts.
  let h1 = 5381;
  let h2 = 2166136261;
  for (let i = 0; i < s.length; i++) {
    const c = s.charCodeAt(i);
    h1 = ((h1 << 5) + h1 + c) | 0;
    h2 = Math.imul(h2 ^ c, 16777619) | 0;
  }
  return (
    (h1 >>> 0).toString(16).padStart(8, "0") +
    (h2 >>> 0).toString(16).padStart(8, "0")
  );
}

export function getCachedReply(cacheKey: string): string | null {
  const entry = REPLY_CACHE.get(cacheKey);
  if (!entry) return null;
  if (entry.expiresAt < Date.now()) {
    REPLY_CACHE.delete(cacheKey);
    return null;
  }
  return entry.reply;
}

export function setCachedReply(cacheKey: string, reply: string): void {
  if (REPLY_CACHE.size >= CACHE_MAX) {
    // Evict oldest (first inserted) — simple LRU approximation
    const firstKey = REPLY_CACHE.keys().next().value;
    if (firstKey) REPLY_CACHE.delete(firstKey);
  }
  REPLY_CACHE.set(cacheKey, { reply, expiresAt: Date.now() + CACHE_TTL_MS });
}

// ─── Complexity heuristics ──────────────────────────────────────────────────

const SIMPLE_INTENTS = [
  "مرحبا", "السلام", "اهلا", "أهلا", "هاي", "hi", "hello", "صباح", "مساء",
  "شكرا", "thanks", "تمام", "ok", "okay", "ايوة", "لا",
];

function isSimpleChatPrompt(userText: string): boolean {
  const trimmed = userText.trim().toLowerCase();
  if (trimmed.length < 30) {
    // Short message — likely greeting / acknowledgement
    if (SIMPLE_INTENTS.some((kw) => trimmed.includes(kw))) return true;
  }
  // Single short question without entity keywords
  if (trimmed.length < 80 && !/(فاتورة|عميل|تقرير|مبيعات|مخزون|تحليل|قائمة|إضافة|create|report|invoice|report)/i.test(trimmed)) {
    return true;
  }
  return false;
}

// ─── Decision API ───────────────────────────────────────────────────────────

export interface OptimizeInput {
  capability: AICapability;
  /** The user-visible prompt (last user message). */
  prompt: string;
  /** True when Invoice-Brain already matched a learned template. */
  patternMatched?: boolean;
  /** Set to false to bypass the cache (e.g. for non-deterministic tools). */
  cacheable?: boolean;
}

export async function decide(params: OptimizeInput): Promise<CostDecision> {
  sweepIfNeeded();

  // 1. Pattern — highest priority, zero cost
  if (params.patternMatched) {
    return {
      action: "use-pattern",
      tier: "any",
      reason: "Invoice-Brain template matched — returning learned extraction without an AI call.",
      estimatedSavings: 1.0,
    };
  }

  // 2. Cache — second priority, near-zero cost
  if (params.cacheable !== false && params.prompt.trim().length > 0) {
    const cacheKey = await sha256(`${params.capability}:${params.prompt.trim()}`);
    if (getCachedReply(cacheKey)) {
      return {
        action: "use-cache",
        tier: "any",
        cacheKey,
        reason: "Identical prompt seen in the last hour — returning cached reply.",
        estimatedSavings: 1.0,
      };
    }
    // Even on a miss, pre-compute the key so the caller can store the reply.
    return {
      action: params.capability === "chat" && isSimpleChatPrompt(params.prompt) ? "route-free" : "route-best",
      tier: params.capability === "chat" && isSimpleChatPrompt(params.prompt) ? "free" : "any",
      cacheKey,
      reason:
        params.capability === "chat" && isSimpleChatPrompt(params.prompt)
          ? "Simple chat prompt (greeting / short) → routing to a free-tier model."
          : `Complex task (${params.capability}) → routing to the best healthy model.`,
      estimatedSavings: 0.0,
    };
  }

  // 3. / 4. Non-cacheable — route by complexity
  if (params.capability === "chat" && isSimpleChatPrompt(params.prompt)) {
    return {
      action: "route-free",
      tier: "free",
      reason: "Simple chat prompt → free-tier model.",
      estimatedSavings: 0.0,
    };
  }

  return {
    action: "route-best",
    tier: "any",
    reason: `Complex task (${params.capability}) → best healthy model.`,
    estimatedSavings: 0.0,
  };
}

// ─── Tier availability check ────────────────────────────────────────────────

/**
 * Does a free-tier model exist for this capability? Used by the dashboard to
 * show whether "route-free" decisions can actually be served for free.
 */
export async function hasFreeModelFor(cap: AICapability): Promise<boolean> {
  const models = await getModelsForCapability(cap);
  return models.some((m) => m.tier === "free");
}

// ─── Stats for the dashboard ────────────────────────────────────────────────

/**
 * Aggregate counts of each decision action over the last N hours, computed
 * from a lightweight in-memory counter (reset on server restart). This gives
 * the founder a live "cost optimizer impact" widget without a DB round-trip.
 */
const decisionCounts: Record<CostDecisionAction, number> = {
  "use-pattern": 0,
  "use-cache": 0,
  "route-free": 0,
  "route-best": 0,
};

export function recordDecision(action: CostDecisionAction): void {
  decisionCounts[action] += 1;
}

export function getOptimizerStats(): Record<CostDecisionAction, number> {
  return { ...decisionCounts };
}

/** Estimated cost avoided = (pattern + cache hits) × avg cost per AI call. */
export function getEstimatedSavings(avgCostPerCall = 0.0002): {
  callsAvoided: number;
  estSavingsUsd: number;
} {
  const callsAvoided = decisionCounts["use-pattern"] + decisionCounts["use-cache"];
  return {
    callsAvoided,
    estSavingsUsd: Math.round(callsAvoided * avgCostPerCall * 1e6) / 1e6,
  };
}

// ─── Persistence (optional, best-effort) ────────────────────────────────────
//
// Persist the running decision counts to PlatformSetting every Nth call so a
// server restart doesn't zero the "cost optimizer impact" widget. Best-effort:
// failures are swallowed (the in-memory counter is the source of truth).

let persistCounter = 0;
const PERSIST_EVERY = 25;

export async function maybePersistStats(): Promise<void> {
  persistCounter += 1;
  if (persistCounter < PERSIST_EVERY) return;
  persistCounter = 0;
  try {
    const key = "ai.cost_optimizer.stats";
    const value = JSON.stringify({
      counts: decisionCounts,
      updatedAt: new Date().toISOString(),
    });
    const existing = await db.platformSettings.findUnique({ where: { key } });
    if (existing) {
      await db.platformSettings.update({ where: { key }, data: { value, updatedAt: new Date() } });
    } else {
      await db.platformSettings.create({
        data: { key, category: "ai", valueType: "string", value },
      });
    }
  } catch (err) {
    logger.warn("[costOptimizer] failed to persist stats", {
      err: err instanceof Error ? err.message : String(err),
    });
  }
}

/**
 * costTracker.ts — AI Usage logging + estimated cost calculation.
 *
 * Every AI call should invoke logAiUsage() once it completes (success or failure).
 * Cost rates are in USD per 1K tokens. z-ai-glm is free in the sandbox.
 *
 * Records are stored in the `ai_usage_logs` table and surfaced in the founder's
 * /api/platform-admin/ai-usage dashboard.
 */
import { db } from "@/lib/db";

const COST_PER_1K_TOKENS: Record<string, { input: number; output: number }> = {
  "z-ai-glm": { input: 0, output: 0 }, // free in sandbox
  // ── FREE OpenRouter models (cost = $0) ──
  "tencent/hy3:free": { input: 0, output: 0 },                         // best free model for GarfiX (Arabic + JSON)
  "openai/gpt-oss-20b:free": { input: 0, output: 0 },                  // strong alternative free model
  "meta-llama/llama-3.3-70b-instruct:free": { input: 0, output: 0 },
  "qwen/qwen3-next-80b-a3b-instruct:free": { input: 0, output: 0 },
  "google/gemma-4-31b-it:free": { input: 0, output: 0 },
  // ── DeepSeek via OpenRouter (official DeepSeek API pricing, passthrough) ──
  "deepseek/deepseek-chat": { input: 0.00014, output: 0.00028 },        // DeepSeek V3 — $0.14/$0.28 per 1M
  "deepseek/deepseek-chat:free": { input: 0, output: 0 },               // free tier
  "deepseek/deepseek-r1": { input: 0.00055, output: 0.00219 },          // DeepSeek R1 — $0.55/$2.19 per 1M
  "deepseek/deepseek-r1:free": { input: 0, output: 0 },                 // free tier
  // ── OpenAI ──
  "gpt-4o-mini": { input: 0.00015, output: 0.0006 },
  "gpt-4o": { input: 0.005, output: 0.015 },
  // ── Anthropic ──
  "claude-3-5-haiku-20241022": { input: 0.0008, output: 0.004 },
  "claude-3-5-sonnet-20241022": { input: 0.003, output: 0.015 },
  default: { input: 0.001, output: 0.002 },
};

export interface LogAiUsageParams {
  companySlug?: string | null;
  userUid?: string | null;
  provider: string;
  model: string;
  endpoint: string;
  tokensIn: number;
  tokensOut: number;
  success: boolean;
  processingMs?: number | null;
  errorMessage?: string | null;
}

/**
 * Persist an AI usage record with estimated cost.
 *
 * Safe to call from inside try/catch blocks — failures here are logged but
 * never propagated (the calling request must still succeed).
 *
 * `processingMs` should be the wall-clock latency of the actual AI provider
 * call (measured with Date.now() around callAI), NOT the whole request
 * handler. Pass `null` or omit if not measured.
 */
export async function logAiUsage(params: LogAiUsageParams): Promise<void> {
  const rates = COST_PER_1K_TOKENS[params.model] || COST_PER_1K_TOKENS.default;
  const estimatedCost =
    (params.tokensIn / 1000) * rates.input +
    (params.tokensOut / 1000) * rates.output;

  try {
    await db.aIUsageLog.create({
      data: {
        companySlug: params.companySlug || null,
        userUid: params.userUid || null,
        provider: params.provider,
        model: params.model,
        endpoint: params.endpoint,
        tokensIn: params.tokensIn,
        tokensOut: params.tokensOut,
        totalTokens: params.tokensIn + params.tokensOut,
        estimatedCost,
        processingMs: params.processingMs ?? null,
        success: params.success,
        errorMessage: params.errorMessage || null,
      },
    });
  } catch (err) {
    // Non-critical — log but never throw
    console.error("[costTracker] failed to log:", err);
  }
}

/**
 * Look up cost rates for a model — useful for displaying projected costs
 * before a call is made.
 */
export function getCostRates(model: string): { input: number; output: number } {
  return COST_PER_1K_TOKENS[model] || COST_PER_1K_TOKENS.default;
}

/**
 * modelRegistry.ts — AI Orchestration Layer: Model Registry.
 *
 * A live, self-tuning catalog of every AI model GarfiX knows about. Each model
 * declares which capabilities it supports (chat, invoice-extraction, reasoning,
 * vision), its tier (free/paid), and its cost. A periodic auto-benchmark rolls
 * real success-rate / latency / quality measurements into a single 0-10
 * `healthScore`.
 *
 * The Smart Router queries this registry at request time to pick the best
 * healthy model for the requested capability — so the system NEVER hard-binds
 * to a model name that might be removed from OpenRouter next month.
 *
 * Health score formula (0-10):
 *   successRate   × 0.50   (0-100  → scaled to 0-10)
 *   latencyScore  × 0.30   (lower is better: 10 - min(avgLatency/1000, 10))
 *   costScore     × 0.10   (free=10, paid scaled inversely by cost)
 *   qualityScore  × 0.10   (0-10 heuristic from benchmark)
 */
import { db } from "@/lib/db";
import { logger } from "@/lib/logger";

export type AICapability = "chat" | "invoice-extraction" | "reasoning" | "vision";

export const ALL_CAPABILITIES: AICapability[] = [
  "chat",
  "invoice-extraction",
  "reasoning",
  "vision",
];

export interface RegistryEntry {
  id: number;
  provider: string;
  model: string;
  displayName: string;
  capabilities: AICapability[];
  tier: "free" | "paid";
  costPer1kIn: number;
  costPer1kOut: number;
  maxTokens: number;
  contextWindow: number;
  isEnabled: boolean;
  isHealthy: boolean;
  healthScore: number;
  successRate: number;
  avgLatencyMs: number;
  p95LatencyMs: number;
  avgQualityScore: number;
  totalBenchmarks: number;
  lastBenchmarkAt: Date | null;
  lastError: string | null;
}

// ─── Cache ──────────────────────────────────────────────────────────────────

let cachedRegistry: RegistryEntry[] | null = null;
let cacheExpiry = 0;
const CACHE_TTL_MS = 300_000; // RI-019 FIX: 5 min cache — avoids DB query per AI request

export function invalidateRegistryCache(): void {
  cachedRegistry = null;
  cacheExpiry = 0;
}

// ─── Row mapper ──────────────────────────────────────────────────────────────

function mapRow(row: {
  id: number;
  provider: string;
  model: string;
  displayName: string;
  capabilities: string;
  tier: string;
  costPer1kIn: number;
  costPer1kOut: number;
  maxTokens: number;
  contextWindow: number;
  isEnabled: boolean;
  isHealthy: boolean;
  healthScore: number;
  successRate: number;
  avgLatencyMs: number;
  p95LatencyMs: number;
  avgQualityScore: number;
  totalBenchmarks: number;
  lastBenchmarkAt: Date | null;
  lastError: string | null;
}): RegistryEntry {
  let caps: AICapability[] = [];
  try {
    caps = JSON.parse(row.capabilities) as AICapability[];
  } catch {
    caps = [];
  }
  return {
    ...row,
    capabilities: caps,
    tier: row.tier === "paid" ? "paid" : "free",
    lastBenchmarkAt: row.lastBenchmarkAt,
  };
}

// ─── Read operations ────────────────────────────────────────────────────────

export async function getRegistry(): Promise<RegistryEntry[]> {
  if (cachedRegistry && Date.now() < cacheExpiry) return cachedRegistry;
  try {
    const rows = await db.aIModelRegistry.findMany({
      orderBy: [{ isEnabled: "desc" }, { healthScore: "desc" }, { tier: "asc" }],
    });
    cachedRegistry = rows.map(mapRow);
    cacheExpiry = Date.now() + CACHE_TTL_MS;
    return cachedRegistry!;
  } catch (err) {
    logger.error("[modelRegistry] getRegistry failed", {
      err: err instanceof Error ? err.message : String(err),
    });
    return [];
  }
}

export async function getEnabledModels(): Promise<RegistryEntry[]> {
  const all = await getRegistry();
  return all.filter((m) => m.isEnabled);
}

export async function getModelsForCapability(cap: AICapability): Promise<RegistryEntry[]> {
  const all = await getEnabledModels();
  return all.filter((m) => m.capabilities.includes(cap) && m.isHealthy);
}

export async function findByProviderModel(
  provider: string,
  model: string,
): Promise<RegistryEntry | null> {
  const all = await getRegistry();
  return all.find((m) => m.provider === provider && m.model === model) ?? null;
}

// ─── Write operations ───────────────────────────────────────────────────────

export interface UpsertRegistryInput {
  provider: string;
  model: string;
  displayName: string;
  capabilities: AICapability[];
  tier?: "free" | "paid";
  costPer1kIn?: number;
  costPer1kOut?: number;
  maxTokens?: number;
  contextWindow?: number;
  isEnabled?: boolean;
}

export async function upsertModel(input: UpsertRegistryInput): Promise<RegistryEntry> {
  const row = await db.aIModelRegistry.upsert({
    where: { provider_model: { provider: input.provider, model: input.model } },
    create: {
      provider: input.provider,
      model: input.model,
      displayName: input.displayName,
      capabilities: JSON.stringify(input.capabilities),
      tier: input.tier ?? "free",
      costPer1kIn: input.costPer1kIn ?? 0,
      costPer1kOut: input.costPer1kOut ?? 0,
      maxTokens: input.maxTokens ?? 4096,
      contextWindow: input.contextWindow ?? 8192,
      isEnabled: input.isEnabled ?? true,
    },
    update: {
      displayName: input.displayName,
      capabilities: JSON.stringify(input.capabilities),
      tier: input.tier ?? "free",
      costPer1kIn: input.costPer1kIn ?? 0,
      costPer1kOut: input.costPer1kOut ?? 0,
      maxTokens: input.maxTokens ?? 4096,
      contextWindow: input.contextWindow ?? 8192,
    },
  });
  invalidateRegistryCache();
  return mapRow(row);
}

export async function setModelEnabled(
  provider: string,
  model: string,
  isEnabled: boolean,
): Promise<void> {
  await db.aIModelRegistry.updateMany({
    where: { provider, model },
    data: { isEnabled },
  });
  invalidateRegistryCache();
}

// ─── Health score computation ───────────────────────────────────────────────
//
// Composite 0-10 score from the last N benchmark results for a model.
// Weights chosen so that a model with 100% success + <2s latency + free +
// good quality scores ~9-10, and a model with <80% success or >8s latency
// scores <5 and gets marked unhealthy.

const HEALTH_WINDOW = 20; // last N benchmarks per model
const UNHEALTHY_THRESHOLD = 4.0; // below this → isHealthy = false

export function computeHealthScore(metrics: {
  successRate: number; // 0-100
  avgLatencyMs: number;
  tier: "free" | "paid";
  costPer1kOut: number;
  avgQualityScore: number; // 0-10
}): number {
  // Success: 0-100 → 0-10
  const successComponent = Math.min(10, metrics.successRate / 10);

  // Latency: 10 - min(avgLatencySec, 10). 0s→10, 5s→5, 10s+→0
  const latencySec = metrics.avgLatencyMs / 1000;
  const latencyComponent = Math.max(0, 10 - Math.min(latencySec, 10));

  // Cost: free=10, paid scaled inversely (cheaper paid = higher)
  // $0.01/1k → ~9, $0.10/1k → ~8, $1/1k → ~5, $5+/1k → ~0
  const costComponent =
    metrics.tier === "free"
      ? 10
      : Math.max(0, 10 - Math.log10(Math.max(metrics.costPer1kOut, 0.0001) * 100));

  // Quality: already 0-10
  const qualityComponent = Math.min(10, Math.max(0, metrics.avgQualityScore));

  const score =
    successComponent * 0.5 +
    latencyComponent * 0.3 +
    costComponent * 0.1 +
    qualityComponent * 0.1;

  return Math.round(score * 100) / 100;
}

/**
 * Recompute health metrics for a model from its recent benchmark results.
 * Called by the auto-benchmark runner after each round.
 */
export async function recomputeHealth(modelRegistryId: number): Promise<void> {
  const recent = await db.aIBenchmarkResult.findMany({
    where: { modelRegistryId },
    orderBy: { createdAt: "desc" },
    take: HEALTH_WINDOW,
  });

  if (recent.length === 0) return;

  const successCount = recent.filter((r) => r.success).length;
  const successRate = (successCount / recent.length) * 100;
  const latencies = recent.map((r) => r.latencyMs).sort((a, b) => a - b);
  const avgLatencyMs = Math.round(
    latencies.reduce((s, v) => s + v, 0) / latencies.length,
  );
  // p95 via nearest-rank
  const p95Idx = Math.max(0, Math.min(latencies.length - 1, Math.ceil(0.95 * latencies.length) - 1));
  const p95LatencyMs = latencies[p95Idx] ?? avgLatencyMs;
  const avgQualityScore =
    recent.reduce((s, r) => s + (r.responseQuality || 0), 0) / recent.length;
  const lastErrorRow = recent.find((r) => !r.success);

  const model = await db.aIModelRegistry.findUnique({
    where: { id: modelRegistryId },
    select: { tier: true, costPer1kOut: true },
  });
  if (!model) return;

  const healthScore = computeHealthScore({
    successRate,
    avgLatencyMs,
    tier: model.tier === "paid" ? "paid" : "free",
    costPer1kOut: model.costPer1kOut,
    avgQualityScore,
  });

  await db.aIModelRegistry.update({
    where: { id: modelRegistryId },
    data: {
      healthScore,
      successRate: Math.round(successRate * 100) / 100,
      avgLatencyMs,
      p95LatencyMs,
      avgQualityScore: Math.round(avgQualityScore * 100) / 100,
      totalBenchmarks: { increment: recent.length },
      lastBenchmarkAt: new Date(),
      lastError: lastErrorRow?.errorMessage?.slice(0, 500) ?? null,
      isHealthy: healthScore >= UNHEALTHY_THRESHOLD,
    },
  });

  invalidateRegistryCache();
  logger.info("[modelRegistry] health recomputed", {
    modelRegistryId,
    healthScore,
    successRate,
    avgLatencyMs,
    isHealthy: healthScore >= UNHEALTHY_THRESHOLD,
  });
}

/**
 * Record a benchmark result and trigger health recomputation.
 */
export async function recordBenchmarkResult(params: {
  modelRegistryId: number;
  capability: AICapability;
  success: boolean;
  latencyMs: number;
  tokensIn: number;
  tokensOut: number;
  responseQuality: number;
  responseSample?: string;
  errorMessage?: string;
}): Promise<void> {
  await db.aIBenchmarkResult.create({
    data: {
      modelRegistryId: params.modelRegistryId,
      capability: params.capability,
      success: params.success,
      latencyMs: params.latencyMs,
      tokensIn: params.tokensIn,
      tokensOut: params.tokensOut,
      responseQuality: params.responseQuality,
      responseSample: params.responseSample?.slice(0, 500) ?? null,
      errorMessage: params.errorMessage?.slice(0, 500) ?? null,
    },
  });
  await recomputeHealth(params.modelRegistryId);
}

// ─── Registry → aiProvider config bridge ────────────────────────────────────
//
// The Smart Router selects a RegistryEntry; we then need to resolve its
// decrypted API key + baseUrl from the existing PlatformSetting store so the
// existing OpenAICompatibleProvider / ZaiProvider classes can call it without
// changes. This keeps the orchestration layer additive — no rewrite of the
// provider call path.

export async function resolveProviderConfigForModel(
  entry: RegistryEntry,
): Promise<{
  provider: string;
  model: string;
  apiKey: string | null;
  baseUrl?: string;
  isEnabled: boolean;
  priority: number;
} | null> {
  // Defer the import to avoid a circular dependency at module-load time
  // (aiProvider.ts imports from db; this file imports from db; both fine,
  // but getAiProviders is heavy and only needed here).
  const { getAiProviders } = await import("@/lib/aiProvider");
  const providers = await getAiProviders();
  const match = providers.find((p) => p.provider === entry.provider);
  if (!match) return null;
  return {
    provider: match.provider,
    model: entry.model,
    apiKey: match.apiKey,
    baseUrl: match.baseUrl,
    isEnabled: true,
    priority: 1,
  };
}

/**
 * api.ts — Shared Route Handler helpers.
 */
import { NextRequest, NextResponse } from "next/server";
import { resolveAuth, type AuthPayload } from "@/lib/auth";
import { isFounderEmail } from "@/lib/founder";
import { logger } from "@/lib/logger";
import { z, ZodError } from "zod";

export interface ApiContext {
  user: AuthPayload;
}

/** Resolve auth, return null + 401 response if unauthenticated. */
export async function requireAuth(req: NextRequest): Promise<{ user: AuthPayload } | NextResponse> {
  const result = await resolveAuth(req);
  if (!result.ok || !result.user) {
    return NextResponse.json(
      { error: result.error || "غير مصرّح" },
      { status: result.status || 401 },
    );
  }
  return { user: result.user };
}

/**
 * Require founder — returns null if user IS the founder (proceed),
 * or a 403 NextResponse if NOT the founder.
 *
 * Checks both that the user's email matches FOUNDER_EMAIL (via isFounderEmail)
 * and that the founder's email is verified (emailVerified), matching the
 * defense-in-depth check in middleware.ts.
 */
export async function requireFounder(user: AuthPayload): Promise<NextResponse | null> {
  if (!isFounderEmail(user.email)) {
    return NextResponse.json(
      { error: "هذه العملية متاحة للمؤسس فقط" },
      { status: 403 },
    );
  }
  // SEC: Founder must have verified email — defense-in-depth
  const { db } = await import("@/lib/db");
  const dbUser = await db.appUser.findUnique({
    where: { uid: user.uid },
    select: { emailVerified: true },
  });
  if (!dbUser?.emailVerified) {
    return NextResponse.json(
      { error: "حساب المؤسس يجب أن يكون موثّق البريد الإلكتروني" },
      { status: 403 },
    );
  }
  return null;
}

/** Validate body against a zod schema, return parsed or 400 response. */
export function validateBody<T>(
  schema: z.ZodSchema<T>,
  body: unknown,
): { ok: true; data: T } | { ok: false; response: NextResponse } {
  try {
    const data = schema.parse(body);
    return { ok: true, data };
  } catch (err) {
    if (err instanceof ZodError) {
      return {
        ok: false,
        response: NextResponse.json(
          { error: err.issues[0]?.message || "Invalid input", details: err.issues },
          { status: 400 },
        ),
      };
    }
    return {
      ok: false,
      response: NextResponse.json({ error: "Invalid input" }, { status: 400 }),
    };
  }
}

/** Standard error response. */
export function apiError(message: string, status = 400): NextResponse {
  return NextResponse.json({ error: message }, { status });
}

/** Standard success response. */
export function apiOk(data: unknown, status = 200): NextResponse {
  return NextResponse.json(data, { status });
}

/** Wrap an async handler with try/catch for clean error responses. */
export function withErrorHandler<T extends unknown[]>(
  fn: (...args: T) => Promise<NextResponse>,
): (...args: T) => Promise<NextResponse> {
  return async (...args: T) => {
    try {
      return await fn(...args);
    } catch (err) {
      // Log the real error server-side for debugging
      const internalMessage = err instanceof Error ? err.message : String(err);
      logger.error("[api] unhandled error", { err: internalMessage });
      // Return a generic message to the client — never leak internal details
      return NextResponse.json({ error: "Internal server error" }, { status: 500 });
    }
  };
}

/**
 * Parse JSON body from a NextRequest.
 *
 * LOW-005 FIX (Cycle 3): enforce a maximum request body size to prevent
 * memory-exhaustion DoS. Next.js Route Handlers don't expose a built-in
 * body-size limit (unlike the Pages API `bodyParser.sizeLimit` config), so
 * we enforce it here by reading the Content-Length header and rejecting
 * oversize payloads BEFORE calling `req.json()` (which would buffer the
 * entire body into memory).
 *
 * Default limit: 1 MiB (matches Next.js Pages API default). Configurable
 * via MAX_JSON_BODY_BYTES env var. Routes that legitimately need larger
 * payloads (e.g. file uploads) bypass parseJsonBody and read the body
 * directly via req.body / req.formData().
 *
 * Returns:
 *   - parsed JSON on success
 *   - null on parse failure OR oversize body (caller should treat both
 *     as "invalid input" and return 400; the distinction is logged but
 *     not exposed to the client to avoid information leakage)
 */
export async function parseJsonBody(req: NextRequest): Promise<unknown> {
  // LOW-005 FIX (Cycle 3): reject oversize bodies before buffering.
  const maxBytes = parseInt(
    process.env.MAX_JSON_BODY_BYTES || String(1024 * 1024),
    10,
  );
  const contentLength = parseInt(req.headers.get("content-length") || "0", 10);
  if (Number.isFinite(contentLength) && contentLength > maxBytes) {
    logger.warn("[api] rejected oversize JSON body", {
      contentLength,
      maxBytes,
      path: req.nextUrl.pathname,
    });
    return null;
  }
  try {
    return await req.json();
  } catch {
    return null;
  }
}

/** Parse query params as a record. */
export function getQuery(req: NextRequest): Record<string, string> {
  const result: Record<string, string> = {};
  req.nextUrl.searchParams.forEach((value, key) => {
    result[key] = value;
  });
  return result;
}

/** Helper to apply JSON parsing to fields stored as JSON strings. */
export function parseJsonField<T = unknown>(s: string | null | undefined, fallback: T): T {
  if (!s) return fallback;
  try {
    return JSON.parse(s) as T;
  } catch {
    return fallback;
  }
}

// ═══════════════════════════════════════════════════════════════════════════════
// Rate Limit Middleware — P0 API Policy Enforcement
// ═══════════════════════════════════════════════════════════════════════════════

import { rateLimitResponse, getClientIp, LIMITS, type RateLimitConfig } from "@/lib/rateLimit";
import { trackApiRequest } from "@/lib/observability";

/**
 * withRateLimit — Enforce rate limiting on any API route handler.
 *
 * Wraps a route handler with rate limit checking before the handler executes.
 * If the rate limit is exceeded, returns 429 immediately without calling the handler.
 *
 * Usage:
 *   export const GET = withRateLimit<[NextRequest, RouteParams]>(
 *     LIMITS.API_READ,
 *     async (req, { params }) => { ... },
 *     "optional-prefix"
 *   );
 *
 * Rate limit categories (from LIMITS):
 *   - LOGIN: 5 per 15min (lockout)
 *   - REGISTER: 3 per hour
 *   - OTP_VERIFY: 5 per 5min
 *   - PASSWORD_RESET: 3 per hour
 *   - AI_CHAT: 10 per minute
 *   - AI_BULK: 3 per minute
 *   - API_READ: 60 per minute (default for GET routes)
 *   - API_WRITE: 30 per minute (default for POST/PUT/PATCH/DELETE routes)
 */
export function withRateLimit<T extends unknown[]>(
  config: RateLimitConfig,
  fn: (...args: T) => Promise<NextResponse>,
  keyPrefix?: string,
): (...args: T) => Promise<NextResponse> {
  return async (...args: T) => {
    // Extract the request from the first argument
    const req = args[0] as NextRequest;

    // Rate limit key: prefix + route path + client IP
    const route = req.nextUrl.pathname;
    const prefix = keyPrefix || `api:${route}`;
    const rlResponse = await rateLimitResponse(req, prefix, config);

    if (rlResponse) {
      // Rate limit exceeded — track as error and return 429
      trackApiRequest(route, req.method, 0, 429);
      return rlResponse;
    }

    // Rate limit OK — add headers and proceed to handler
    const start = Date.now();
    try {
      const response = await fn(...args);

      // Add rate limit headers to successful responses
      const remaining = config.maxAttempts; // Approximate — actual count is per-window
      response.headers.set("X-RateLimit-Limit", String(config.maxAttempts));
      response.headers.set("X-RateLimit-Window", String(Math.ceil(config.windowMs / 1000)));

      // Track successful request
      trackApiRequest(route, req.method, Date.now() - start, response.status);

      return response;
    } catch (err) {
      // Track error request
      trackApiRequest(route, req.method, Date.now() - start, 500);
      throw err;
    }
  };
}

/**
 * audit.ts — Audit logging helper.
 */
import { db } from "@/lib/db";
import { logger } from "./logger";
import { appendToChain } from "./tamperAudit";

export interface AuditInput {
  userEmail: string;
  userUid: string;
  action: string;
  entity: string;
  entityId?: string | number | null;
  companySlug?: string | null;
  details?: Record<string, unknown> | null;
}

/**
 * SEC-M4C4 (Cycle 4): redact sensitive fields from audit log details before
 * JSON serialization. The previous implementation passed details raw — any
 * route that logged user-supplied details (e.g. login failures with the
 * attempted password, or webhook payloads containing API keys) would write
 * PII / secrets to the audit_logs table in plaintext.
 *
 * The redaction is recursive (handles nested objects + arrays) and matches
 * keys case-insensitively against a known-sensitive pattern.
 */
const SENSITIVE_KEY_RE = /(password|passwd|pwd|token|secret|apiKey|api_key|authorization|bearer|iban|cvv|cvc|ssn|nationalId|creditCard|cardNumber|refreshToken|accessToken|privateKey|signingKey)/i;

function redactSensitive(value: unknown, depth = 0): unknown {
  if (depth > 8) return "[max-depth-reached]"; // prevent cycles / runaway recursion
  if (value === null || value === undefined) return value;
  if (typeof value === "string") return value;
  if (typeof value !== "object") return value;
  if (Array.isArray(value)) {
    return value.map((v) => redactSensitive(v, depth + 1));
  }
  const obj = value as Record<string, unknown>;
  const out: Record<string, unknown> = {};
  for (const key of Object.keys(obj)) {
    if (SENSITIVE_KEY_RE.test(key)) {
      out[key] = "[REDACTED]";
    } else {
      out[key] = redactSensitive(obj[key], depth + 1);
    }
  }
  return out;
}

export async function logAudit(input: AuditInput): Promise<void> {
  try {
    // SEC-M4C4 (Cycle 4): redact sensitive fields before persisting
    const redactedDetails = input.details
      ? (redactSensitive(input.details) as Record<string, unknown>)
      : null;
    const created = await db.auditLog.create({
      data: {
        userEmail: input.userEmail,
        userUid: input.userUid,
        action: input.action,
        entity: input.entity,
        entityId: input.entityId !== null && input.entityId !== undefined ? String(input.entityId) : null,
        companySlug: input.companySlug ?? null,
        details: redactedDetails ? JSON.stringify(redactedDetails) : null,
      },
    });
    // SEC-A1C4 (Cycle 4): wire appendToChain into logAudit. Previously the
    // TamperEvidenceChain table was permanently empty in production — the
    // entire hash-chain machinery was dead code. Now every audit entry gets
    // a chain link appended (best-effort: failures don't block the audit write).
    // We pass the redacted details so the chain hash matches what's stored.
    void appendToChain({
      entryId: String(created.id),
      content: {
        userEmail: input.userEmail,
        action: input.action,
        entity: input.entity,
        entityId: input.entityId !== null && input.entityId !== undefined ? String(input.entityId) : null,
        companySlug: input.companySlug ?? null,
        details: redactedDetails,
        createdAt: created.createdAt,
      },
      companySlug: input.companySlug ?? null,
    }).catch((err) => {
      // Best-effort — never block the main audit write
      logger.error("[audit] failed to append to tamper-evidence chain", {
        err: err instanceof Error ? err.message : String(err),
        auditId: created.id,
      });
    });
  } catch (err) {
    // Non-critical — log but never throw
    logger.error("[audit] failed to write audit log", { err: err instanceof Error ? err.message : String(err), action: input.action, entity: input.entity });
  }
}

export async function logAdminAction(input: {
  adminEmail: string;
  action: string;
  targetType?: string;
  targetId?: string;
  changes?: Record<string, unknown> | null;
  ipAddress?: string;
  userAgent?: string;
}): Promise<void> {
  try {
    // SEC-M4C4 (Cycle 4): redact sensitive fields in admin audit changes too
    const redactedChanges = input.changes
      ? (redactSensitive(input.changes) as Record<string, unknown>)
      : null;
    await db.adminAuditLog.create({
      data: {
        adminEmail: input.adminEmail,
        action: input.action,
        targetType: input.targetType ?? null,
        targetId: input.targetId ?? null,
        changes: redactedChanges ? JSON.stringify(redactedChanges) : null,
        ipAddress: input.ipAddress ?? null,
        userAgent: input.userAgent ?? null,
      },
    });
  } catch (err) {
    logger.error("[admin-audit] failed to write admin audit log", { err: err instanceof Error ? err.message : String(err), action: input.action });
  }
}

/**
 * auth.ts — JWT auth + bcrypt password hashing.
 * Ported from v10 authMiddleware.ts + auth.ts, adapted to Next.js Route Handlers.
 *
 * Tokens:
 *   - Access token (short TTL, 30 min): carries uid/email/role/companies/perms/tv
 *   - Refresh token (long TTL, 30 days): carries uid + tv (token version)
 *
 * Token versioning: incrementing `User.tokenVersion` invalidates all outstanding
 * refresh tokens (used on logout-all, password reset, email verify).
 */

import bcrypt from "bcryptjs";
import jwt from "jsonwebtoken";
import { cookies } from "next/headers";
import { NextRequest, NextResponse } from "next/server";
import { db } from "@/lib/db";
import { isFounderEmail } from "@/lib/founder";
import { computeEffectivePermissions } from "@/lib/permissions";
import { getValkeyClient } from "@/lib/valkey";

// SEC-002 FIX: No fallback secrets — throw if missing in production
// P0 BUILD FIX: Lazy secret resolution — module-level const resolution throws
// during `next build` because NODE_ENV=production is set at build time.
// Using getters defers resolution to first actual use (at runtime), not at import.
// During build, the module is imported for type analysis only — no secrets needed.
function resolveSecret(envVar: string, name: string): string {
  const val = process.env[envVar];
  if (!val) {
    // P0 FIX: During `next build`, do NOT throw — secrets are not needed for
    // static page compilation. Next.js sets NEXT_PHASE during build phases.
    const isBuildPhase = process.env.NEXT_PHASE === "phase-production-build"
      || (process.env.NODE_ENV === "production" && typeof window === "undefined" && !process.env.RUNTIME_STARTUP);
    if (isBuildPhase) {
      console.warn(`⚠️  ${name} not set during build — will be validated at runtime. DO NOT deploy without setting this.`);
      return `build-placeholder-${name.toLowerCase()}-not-for-runtime-use`;
    }
    if (process.env.NODE_ENV === "production") {
      throw new Error(`FATAL: ${name} environment variable is not set. Refusing to start with insecure defaults.`);
    }
    // In dev only, use a deterministic but clearly-marked dev secret
    console.warn(`⚠️  ${name} not set — using dev default. DO NOT use in production.`);
    return `dev-only-${name.toLowerCase()}-not-for-production-static-key`;
  }
  if (val.length < 16) {
    throw new Error(`FATAL: ${name} must be at least 16 characters.`);
  }
  return val;
}

// P0 FIX: Lazy getter pattern — secrets resolved only on first access at runtime.
// This prevents module-level throws during `next build`'s "Collecting page data" phase.
let _jwtSecret: string | undefined;
let _jwtRefreshSecret: string | undefined;

function getJwtSecret(): string {
  if (!_jwtSecret) _jwtSecret = resolveSecret("JWT_SECRET", "JWT_SECRET");
  return _jwtSecret;
}
function getJwtRefreshSecret(): string {
  if (!_jwtRefreshSecret) _jwtRefreshSecret = resolveSecret("JWT_REFRESH_SECRET", "JWT_REFRESH_SECRET");
  return _jwtRefreshSecret;
}

// Backward-compatible getters: most code references JWT_SECRET / JWT_REFRESH_SECRET
// as if they were const — these getters return the resolved value lazily.
// Token signing/verification functions below use getJwtSecret()/getJwtRefreshSecret().
const JWT_SECRET_PROXY = { get: () => getJwtSecret() } as const;
const JWT_REFRESH_SECRET_PROXY = { get: () => getJwtRefreshSecret() } as const;
const ACCESS_TTL = parseInt(process.env.JWT_ACCESS_TTL_SECONDS || "1800", 10); // 30 min
const REFRESH_TTL = parseInt(process.env.JWT_REFRESH_TTL_SECONDS || "2592000", 10); // 30 days
const BCRYPT_ROUNDS = parseInt(process.env.BCRYPT_ROUNDS || "10", 10);

export const ACCESS_COOKIE = "inv_token";
export const REFRESH_COOKIE = "inv_refresh";

export interface AuthPayload {
  uid: string;
  email: string;
  role: string;
  companies: string[];
  permissions: Record<string, number>;
  tv: number;
  jti?: string;
}

export interface SessionUser {
  uid: string;
  email: string;
  displayName: string;
  role: string;
  companies: string[];
  permissions: Record<string, number>;
  emailVerified: boolean;
  tokenVersion: number;
}

// ── Password hashing ─────────────────────────────────────────────────────

export async function hashPassword(plain: string): Promise<string> {
  return bcrypt.hash(plain, BCRYPT_ROUNDS);
}

export async function verifyPassword(plain: string, hash: string): Promise<boolean> {
  try {
    return await bcrypt.compare(plain, hash);
  } catch {
    return false;
  }
}

// ── Token signing ─────────────────────────────────────────────────────────

export function signToken(payload: AuthPayload): string {
  const jti = crypto.randomUUID();
  return jwt.sign({ ...payload, jti, type: "access" }, getJwtSecret(), { expiresIn: ACCESS_TTL });
}

export function signRefreshToken(uid: string, tv: number): string {
  return jwt.sign({ uid, tv, type: "refresh" }, getJwtRefreshSecret(), { expiresIn: REFRESH_TTL });
}

export function verifyToken(token: string): AuthPayload | null {
  try {
    const decoded = jwt.verify(token, getJwtSecret()) as jwt.JwtPayload & AuthPayload & { type?: string };
    if (decoded.type !== "access") return null;
    return {
      uid: decoded.uid,
      email: decoded.email,
      role: decoded.role,
      companies: decoded.companies || [],
      permissions: decoded.permissions || {},
      tv: decoded.tv,
      jti: decoded.jti,
    };
  } catch {
    return null;
  }
}

export function verifyRefreshToken(token: string): { uid: string; tv: number } | null {
  try {
    const decoded = jwt.verify(token, getJwtRefreshSecret()) as jwt.JwtPayload & {
      uid: string;
      tv: number;
      type?: string;
    };
    if (decoded.type !== "refresh") return null;
    return { uid: decoded.uid, tv: decoded.tv };
  } catch {
    return null;
  }
}

// ── Token blacklist (Valkey-backed, M3 FIX) ───────────────────────────────
// When an admin force-logs out a user, their JTI is added to Valkey with
// TTL = remaining token lifetime. verifyToken checks this before accepting.
// Uses the centralized valkey.ts connection manager.

/**
 * Check if a token's JTI is blacklisted.
 * Returns true if blacklisted (token should be rejected).
 */
export async function isTokenBlacklisted(jti: string): Promise<boolean> {
  const client = await getValkeyClient();
  if (!client) return false; // No Valkey = no blacklist = accept
  try {
    return (await client.exists(`token:blacklist:${jti}`)) > 0;
  } catch {
    return false; // Fail-open
  }
}

/**
 * Blacklist a token by its JTI for the remaining TTL.
 */
export async function blacklistToken(jti: string, remainingTtlSeconds: number): Promise<void> {
  const client = await getValkeyClient();
  if (!client || remainingTtlSeconds <= 0) return;
  try {
    await client.set(`token:blacklist:${jti}`, "1", "EX", remainingTtlSeconds);
  } catch {
    // Fail silently — blacklist is best-effort
  }
}

/**
 * Async token verification that also checks the Valkey blacklist.
 * Use this for sensitive operations where revocation must be enforced.
 */
export async function verifyTokenWithBlacklist(token: string): Promise<AuthPayload | null> {
  const payload = verifyToken(token);
  if (!payload) return null;
  if (payload.jti && await isTokenBlacklisted(payload.jti)) return null;
  return payload;
}

// ── Cookie helpers ─────────────────────────────────────────────────────────

const COOKIE_OPTS = {
  httpOnly: true,
  secure: process.env.NODE_ENV === "production",
  sameSite: "lax" as const,
  path: "/",
  maxAge: ACCESS_TTL,
};

const REFRESH_COOKIE_OPTS = {
  httpOnly: true,
  secure: process.env.NODE_ENV === "production",
  sameSite: "lax" as const,
  path: "/",
  maxAge: REFRESH_TTL,
};

export async function issueSession(response: NextResponse, user: SessionUser): Promise<void> {
  const payload: AuthPayload = {
    uid: user.uid,
    email: user.email,
    role: user.role,
    companies: user.companies,
    permissions: user.permissions,
    tv: user.tokenVersion,
  };
  response.cookies.set(ACCESS_COOKIE, signToken(payload), COOKIE_OPTS);
  response.cookies.set(REFRESH_COOKIE, signRefreshToken(user.uid, user.tokenVersion), REFRESH_COOKIE_OPTS);
}

export async function clearSession(response: NextResponse): Promise<void> {
  response.cookies.set(ACCESS_COOKIE, "", { ...COOKIE_OPTS, maxAge: 0 });
  response.cookies.set(REFRESH_COOKIE, "", { ...REFRESH_COOKIE_OPTS, maxAge: 0 });
}

export function getAccessToken(req: NextRequest): string | undefined {
  return req.cookies.get(ACCESS_COOKIE)?.value;
}

export function getRefreshToken(req: NextRequest): string | undefined {
  return req.cookies.get(REFRESH_COOKIE)?.value;
}

// ── Request-time auth (Route Handler helpers) ────────────────────────────

export interface AuthResult {
  ok: boolean;
  user?: AuthPayload;
  rotatedRefreshToken?: string | null;
  error?: string;
  status?: number;
}

/**
 * Resolve the authenticated user from the request's access cookie.
 * On expired access token, attempts to refresh from the refresh cookie.
 */
export async function resolveAuth(req: NextRequest): Promise<AuthResult> {
  const access = getAccessToken(req);
  if (access) {
    // SEC-C1 FIX (Cycle 1): use verifyTokenWithBlacklist so that a
    // force-logged-out or password-changed user is immediately rejected,
    // even if the JWT signature is still valid for the remaining TTL.
    const payload = await verifyTokenWithBlacklist(access);
    if (payload) return { ok: true, user: payload };
  }

  // Try refresh
  const refresh = getRefreshToken(req);
  if (!refresh) return { ok: false, error: "Unauthorized", status: 401 };

  const refreshPayload = verifyRefreshToken(refresh);
  if (!refreshPayload) return { ok: false, error: "Unauthorized", status: 401 };

  // Look up user — verify token version matches (invalidates old sessions)
  const user = await db.appUser.findUnique({ where: { uid: refreshPayload.uid } });
  if (!user) return { ok: false, error: "Unauthorized", status: 401 };
  if (user.tokenVersion !== refreshPayload.tv) {
    return { ok: false, error: "Session revoked", status: 401 };
  }

  // Issue a fresh access token payload
  const companies = parseJsonArr(user.companies);
  const permissions = parseJsonObj(user.permissions);
  const payload: AuthPayload = {
    uid: user.uid,
    email: user.email,
    role: user.role,
    companies,
    permissions,
    tv: user.tokenVersion,
  };
  return { ok: true, user: payload };
}

export function hasUnrestrictedScope(user: AuthPayload): boolean {
  return user.role === "admin" || isFounderEmail(user.email);
}

export function assertCompanyAccess(user: AuthPayload, companySlug?: string | null): boolean {
  if (!companySlug) return hasUnrestrictedScope(user);
  if (hasUnrestrictedScope(user)) return true;
  return Array.isArray(user.companies) && user.companies.includes(companySlug);
}

// ── Profile ────────────────────────────────────────────────────────────────

export async function buildUserProfile(user: SessionUser) {
  const founder = isFounderEmail(user.email);
  const effective = computeEffectivePermissions(user.role, user.permissions, founder);
  return {
    uid: user.uid,
    email: user.email,
    displayName: user.displayName,
    role: user.role,
    companies: user.companies,
    permissions: user.permissions,
    effectivePermissions: effective,
    emailVerified: user.emailVerified,
    isFounder: founder,
  };
}

// ── JSON parse helpers ────────────────────────────────────────────────────

function parseJsonArr(s: string | null | undefined): string[] {
  if (!s) return [];
  try {
    const v = JSON.parse(s);
    return Array.isArray(v) ? v : [];
  } catch {
    return [];
  }
}

function parseJsonObj(s: string | null | undefined): Record<string, number> {
  if (!s) return {};
  try {
    const v = JSON.parse(s);
    return v && typeof v === "object" ? v : {};
  } catch {
    return {};
  }
}

// ── Cookie helpers (for client-side reads where needed) ──────────────────

export async function getRequestCookies(): Promise<{
  access?: string;
  refresh?: string;
}> {
  const store = await cookies();
  return {
    access: store.get(ACCESS_COOKIE)?.value,
    refresh: store.get(REFRESH_COOKIE)?.value,
  };
}

// ── Additional auth helpers ──────────────────────────────────────────────────

/**
 * Persist a rotated refresh token cookie on the response.
 * Called by middleware when resolveAuth rotates the refresh token silently.
 */
export function persistRotatedRefreshToken(
  response: NextResponse,
  rotatedToken: string | null | undefined,
): void {
  if (!rotatedToken) return;
  response.cookies.set(REFRESH_COOKIE, rotatedToken, REFRESH_COOKIE_OPTS);
}

/**
 * Revoke the current access session by blacklisting the access token's JTI.
 * Used on logout and password change to immediately invalidate the session.
 */
export async function revokeAccessSession(req: NextRequest): Promise<void> {
  const access = getAccessToken(req);
  if (!access) return;
  const payload = verifyToken(access);
  if (!payload?.jti) return;
  // Estimate remaining TTL from the token's exp claim
  const decoded = jwt.decode(access) as jwt.JwtPayload | null;
  const exp = decoded?.exp ?? 0;
  const now = Math.floor(Date.now() / 1000);
  const remaining = Math.max(0, exp - now);
  if (remaining > 0) {
    await blacklistToken(payload.jti, remaining);
  }
}

/**
 * Verify a password and rehash it if the bcrypt cost factor is lower than
 * the current configured rounds. Returns { ok, rehashed }.
 */
export async function verifyPasswordAndMaybeRehash(
  plain: string,
  hash: string,
  uid: string,
): Promise<{ ok: boolean; rehashed?: boolean }> {
  const match = await verifyPassword(plain, hash);
  if (!match) return { ok: false };

  // Check if the hash cost is lower than our current rounds — rehash if so
  const hashRounds = parseInt(hash.split("$")[2], 10);
  if (hashRounds < BCRYPT_ROUNDS) {
    const newHash = await hashPassword(plain);
    await db.appUser.update({ where: { uid }, data: { passwordHash: newHash } });
    return { ok: true, rehashed: true };
  }
  return { ok: true, rehashed: false };
}

/**
 * Verify a refresh token AND check its JTI against the Valkey blacklist.
 * Returns the { uid, tv, jti } payload or null if invalid/blacklisted.
 */
export async function verifyRefreshTokenWithBlacklist(
  token: string,
): Promise<{ uid: string; tv: number; jti?: string } | null> {
  const payload = verifyRefreshToken(token);
  if (!payload) return null;

  // Decode to get JTI — refresh tokens issued after HIGH-004 FIX include a JTI
  const decoded = jwt.decode(token) as jwt.JwtPayload | null;
  const jti = decoded?.jti;
  if (jti && await isTokenBlacklisted(jti)) return null;

  return { ...payload, jti };
}

/**
 * engine.ts — Rule-based Automation Engine.
 *
 * Triggers fire events; events are matched against active rules per company;
 * matching rules run their configured actions (send_whatsapp / create_task /
 * send_email). Each execution is recorded in `automation_execution_logs` with
 * status (success | failed | skipped) and duration.
 *
 * Usage:
 *   import { fireEvent } from "@/lib/automation/engine";
 *   await fireEvent({ type: "invoice_created", companySlug: "acme", data: { ... } });
 */
import { db } from "@/lib/db";
import { logger } from "@/lib/logger";

export interface TriggerEvent {
  type: string; // invoice_created | stock_low | payment_overdue
  companySlug: string;
  data: Record<string, unknown>;
}

export interface RuleShape {
  id: number;
  name: string;
  condition: string;
  actions: string;
  companySlug: string;
}

export interface ActionShape {
  type: string;
  params?: Record<string, unknown>;
}

/**
 * Find all active rules for the given company + trigger and run them in order.
 * Errors in one rule never affect the next.
 */
export async function fireEvent(event: TriggerEvent): Promise<void> {
  let rules: Awaited<ReturnType<typeof db.automationRule.findMany>> = [];
  try {
    rules = await db.automationRule.findMany({
      where: { companySlug: event.companySlug, trigger: event.type, isActive: true },
    });
  } catch (err) {
    logger.error("[automation] failed to load rules", {
      err: err instanceof Error ? err.message : String(err),
      trigger: event.type,
      company: event.companySlug,
    });
    return;
  }

  logger.info("[automation] firing event", {
    trigger: event.type,
    company: event.companySlug,
    rulesMatched: rules.length,
  });

  for (const rule of rules) {
    try {
      await executeRule(
        {
          id: rule.id,
          name: rule.name,
          condition: rule.condition,
          actions: rule.actions,
          companySlug: rule.companySlug,
        },
        event,
      );
    } catch (err) {
      // Should never happen — executeRule swallows its own errors — but
      // guard anyway so one bad rule can't break the rest of the loop.
      logger.error("[automation] executeRule threw (unexpected)", {
        ruleId: rule.id,
        err: err instanceof Error ? err.message : String(err),
      });
    }
  }
}

/**
 * Execute one rule: evaluate the condition, run each action, write the log.
 * Never throws — every failure is captured and persisted.
 */
export async function executeRule(rule: RuleShape, event: TriggerEvent): Promise<void> {
  const start = Date.now();
  let status = "pending";
  let error: string | null = null;

  try {
    const condition = JSON.parse(rule.condition || "{}") as {
      minAmount?: number;
      maxAmount?: number;
      equals?: unknown;
      [k: string]: unknown;
    };

    // ─── Condition checks (simple, additive) ───────────────────────────────
    if (typeof condition.minAmount === "number" && event.data.amount !== undefined) {
      if (Number(event.data.amount) < condition.minAmount) {
        status = "skipped";
        return;
      }
    }
    if (typeof condition.maxAmount === "number" && event.data.amount !== undefined) {
      if (Number(event.data.amount) > condition.maxAmount) {
        status = "skipped";
        return;
      }
    }
    if ("equals" in condition && condition.equals !== undefined) {
      // `equals` is a map of { fieldPath: expectedValue } — all must match
      const eq = condition.equals as Record<string, unknown> | undefined;
      if (eq && typeof eq === "object") {
        for (const [k, v] of Object.entries(eq)) {
          if (event.data[k] !== v) {
            status = "skipped";
            return;
          }
        }
      }
    }

    // ─── Run actions ───────────────────────────────────────────────────────
    let actions: ActionShape[] = [];
    try {
      actions = JSON.parse(rule.actions || "[]") as ActionShape[];
    } catch {
      actions = [];
    }

    for (const action of actions) {
      await executeAction(action, event);
    }
    status = "success";
  } catch (err) {
    status = "failed";
    error = err instanceof Error ? err.message : String(err);
    logger.error("[automation] rule execution failed", {
      ruleId: rule.id,
      err: error,
    });
  } finally {
    try {
      await db.automationExecutionLog.create({
        data: {
          ruleId: rule.id,
          status,
          triggerData: JSON.stringify(event.data),
          error,
          durationMs: Date.now() - start,
        },
      });
    } catch (logErr) {
      // Last-ditch — never throw from finally
      logger.error("[automation] failed to persist execution log", {
        ruleId: rule.id,
        err: logErr instanceof Error ? logErr.message : String(logErr),
      });
    }
  }
}

/**
 * Run a single action. Unknown action types log a warning (don't fail the rule).
 */
