export {
  ZATCA_AUTHORITY,
  ZATCA_CURRENCY,
  ZATCA_DECIMAL_PLACES,
  ZATCA_VAT_RATE,
  ZATCA_REGULATION,
  ZATCA_MAX_FINE_SAR,
  ZATCA_PORTAL_BASE_URL,
};

