/**
 * myfatoorah-webhook.ts — MyFatoorah webhook signature verification & event parsing.
 *
 * The callback route currently doesn't verify MyFatoorah webhook signatures.
 * This module provides:
 *   - HMAC-SHA256 signature verification using the API key
 *   - Webhook event parsing: payment_success, payment_failed, refund_completed
 *   - Rate-limit tracking for webhook processing
 *
 * MyFatoorah webhook format:
 *   - The webhook payload is sent as a POST with JSON body
 *   - Signature is in the `Signature` header
 *   - Signature = HMAC-SHA256(apiKey, JSON.stringify(payload))
 *
 * RUNTIME: Node.js only — uses crypto, db, logger
 */
'use node';

import crypto from 'node:crypto';
import { db } from '@/lib/db';
import { logger } from '@/lib/logger';
import { getIntegrationConfig } from '@/lib/integrations/registry';
import { safeCompare } from '@/lib/cryptoVault';

// ─── Webhook event types ───────────────────────────────────────────────────

export type MyFatoorahEventType =
  | 'payment_success'
  | 'payment_failed'
  | 'refund_completed';

export interface MyFatoorahWebhookPayload {
  EventType: string;
  Data: {
    InvoiceId: number;
    InvoiceStatus: string;
    InvoiceValue: number;
    CurrencyIso: string;
    PaymentMethodId: number;
    PaymentGateway: string;
    CustomerReference: string;
    TrackId: string;
    RefId: string;
    TransId: number;
    PaymentId: number;
    RefundId?: number;
    RefundStatus?: string;
    RefundReference?: string;
    Error?: string;
  };
}

export interface ParsedWebhookEvent {
  eventType: MyFatoorahEventType;
  invoiceId: number;
  invoiceStatus: string;
  invoiceValue: number;
  currencyIso: string;
  paymentId: number;
  refundId?: number;
  refundStatus?: string;
  customerReference: string;
  error?: string;
  raw: MyFatoorahWebhookPayload;
}

// ─── Rate limiting ─────────────────────────────────────────────────────────

/** In-memory rate limit tracker for webhook processing. */
const webhookRateLimiter = new Map<string, { count: number; lastReset: number }>();
const RATE_LIMIT_MAX = 100; // max webhooks per provider per minute
const RATE_LIMIT_WINDOW_MS = 60_000; // 1 minute

function checkRateLimit(provider: string): boolean {
  const entry = webhookRateLimiter.get(provider);
  const now = Date.now();

  if (!entry || now - entry.lastReset > RATE_LIMIT_WINDOW_MS) {
    webhookRateLimiter.set(provider, { count: 1, lastReset: now });
    return true;
  }

  if (entry.count >= RATE_LIMIT_MAX) {
    logger.warn('[myfatoorah-webhook] rate limit exceeded', { provider, count: entry.count });
    return false;
  }

  entry.count++;
  return true;
}

// ─── Signature verification ────────────────────────────────────────────────

/**
 * Verify a MyFatoorah webhook signature using HMAC-SHA256.
 *
 * MyFatoorah signs the webhook payload using the API key as the HMAC secret.
 * The signature is computed as: HMAC-SHA256(apiKey, JSON.stringify(payload))
 *
 * @param payload - The raw JSON payload string from the webhook request body
 * @param signature - The `Signature` header value from the request
 * @returns true if the signature is valid, false otherwise
 */
export async function verifyWebhookSignature(
  payload: string,
  signature: string,
): Promise<{ valid: boolean; error?: string }> {
  // Get the API key from stored credentials
  const cfg = await getIntegrationConfig('myfatoorah');
  if (!cfg?.api_key) {
    return { valid: false, error: 'بيانات MyFatoorah غير مُهيّأة — لا يمكن التحقق من التوقيع' };
  }

  try {
    // Compute expected signature: HMAC-SHA256(apiKey, payload)
    const expectedSignature = crypto
      .createHmac('sha256', cfg.api_key)
      .update(payload, 'utf8')
      .digest('hex');

    // Constant-time comparison to prevent timing attacks
    if (safeCompare(signature, expectedSignature)) {
      return { valid: true };
    }

    logger.warn('[myfatoorah-webhook] signature mismatch', {
      providedSignature: signature.substring(0, 8) + '...',
      expectedPrefix: expectedSignature.substring(0, 8) + '...',
    });
    return { valid: false, error: 'توقيع webhook غير صالح — لا يتطابق مع HMAC-SHA256' };
  } catch (err) {
    logger.error('[myfatoorah-webhook] signature verification error', {
      error: err instanceof Error ? err.message : String(err),
    });
    return { valid: false, error: 'خطأ في التحقق من التوقيع' };
  }
}

// ─── Event parsing ─────────────────────────────────────────────────────────

/**
 * Parse a raw webhook payload into a structured event.
 *
 * MyFatoorah doesn't have explicit event types in their webhook — instead,
 * the InvoiceStatus field determines the event:
 *   - Paid → payment_success
 *   - Failed / Cancelled → payment_failed
 *   - Refunded (with RefundId) → refund_completed
 */
export function parseWebhookEvent(payload: MyFatoorahWebhookPayload): ParsedWebhookEvent {
  const { EventType, Data } = payload;
  const invoiceStatus = (Data.InvoiceStatus || '').toLowerCase();

  let eventType: MyFatoorahEventType;
  if (Data.RefundId && Data.RefundStatus) {
    eventType = 'refund_completed';
  } else if (invoiceStatus === 'paid') {
    eventType = 'payment_success';
  } else {
    eventType = 'payment_failed';
  }

  // Override with EventType if explicitly provided (MyFatoorah may add this later)
  if (EventType) {
    const mapped = mapEventType(EventType);
    if (mapped) eventType = mapped;
  }

  return {
    eventType,
    invoiceId: Data.InvoiceId,
    invoiceStatus: Data.InvoiceStatus,
    invoiceValue: Data.InvoiceValue,
    currencyIso: Data.CurrencyIso,
    paymentId: Data.PaymentId,
    refundId: Data.RefundId,
    refundStatus: Data.RefundStatus,
    customerReference: Data.CustomerReference,
    error: Data.Error,
    raw: payload,
  };
}

function mapEventType(raw: string): MyFatoorahEventType | null {
  switch (raw.toLowerCase()) {
    case 'payment_success':
    case 'paymentsuccess':
      return 'payment_success';
    case 'payment_failed':
    case 'paymentfailed':
      return 'payment_failed';
    case 'refund_completed':
    case 'refundcompleted':
      return 'refund_completed';
    default:
      return null;
  }
}

// ─── Webhook processing ────────────────────────────────────────────────────

/**
 * Process a verified webhook event.
 *
 * Called after signature verification succeeds. Updates the database
 * based on the event type:
 *   - payment_success: mark PaymentTransaction as paid, update company plan
 *   - payment_failed: mark PaymentTransaction as failed
 *   - refund_completed: mark RefundTransaction as completed
 */
export async function processWebhookEvent(
  event: ParsedWebhookEvent,
): Promise<{ ok: boolean; error?: string }> {
  // Rate limit check
  if (!checkRateLimit('myfatoorah')) {
    return { ok: false, error: 'تم تجاوز حد معدل webhook — يرجى المحاولة لاحقاً' };
  }

  logger.info('[myfatoorah-webhook] processing event', {
    eventType: event.eventType,
    invoiceId: event.invoiceId,
    paymentId: event.paymentId,
  });

  try {
    switch (event.eventType) {
      case 'payment_success':
        return await handlePaymentSuccess(event);
      case 'payment_failed':
        return await handlePaymentFailed(event);
      case 'refund_completed':
        return await handleRefundCompleted(event);
      default:
        return { ok: false, error: `نوع webhook غير معروف: ${event.eventType}` };
    }
  } catch (err) {
    logger.error('[myfatoorah-webhook] error processing event', {
      eventType: event.eventType,
      invoiceId: event.invoiceId,
      error: err instanceof Error ? err.message : String(err),
    });
    return { ok: false, error: 'خطأ في معالجة webhook' };
  }
}

async function handlePaymentSuccess(event: ParsedWebhookEvent): Promise<{ ok: boolean; error?: string }> {
  const txn = await db.paymentTransaction.findFirst({
    where: { providerPaymentId: String(event.invoiceId), provider: 'myfatoorah' },
  });

  if (!txn) {
    logger.warn('[myfatoorah-webhook] payment_success: no matching transaction', {
      invoiceId: event.invoiceId,
    });
    return { ok: false, error: 'معاملة الدفع غير موجودة' };
  }

  const existingMeta = (() => { try { return JSON.parse(txn.metadata || '{}'); } catch { return {}; } })();
  await db.paymentTransaction.update({
    where: { id: txn.id },
    data: {
      status: 'paid',
      providerEventId: String(event.paymentId),
      metadata: JSON.stringify({
        ...existingMeta,
        webhookPaymentId: event.paymentId,
        webhookInvoiceStatus: event.invoiceStatus,
        webhookProcessedAt: new Date().toISOString(),
      }),
    },
  });

  // Update company plan if this is a subscription upgrade
  if (txn.plan && txn.plan !== 'trial') {
    await db.company.update({
      where: { slug: txn.companySlug },
      data: {
        plan: txn.plan,
        subscriptionStatus: 'active',
      },
    });
  }

  logger.info('[myfatoorah-webhook] payment_success processed', {
    txnId: txn.id,
    invoiceId: event.invoiceId,
    companySlug: txn.companySlug,
    plan: txn.plan,
  });

  return { ok: true };
}

async function handlePaymentFailed(event: ParsedWebhookEvent): Promise<{ ok: boolean; error?: string }> {
  const txn = await db.paymentTransaction.findFirst({
    where: { providerPaymentId: String(event.invoiceId), provider: 'myfatoorah' },
  });

  if (!txn) {
    logger.warn('[myfatoorah-webhook] payment_failed: no matching transaction', {
      invoiceId: event.invoiceId,
    });
    return { ok: false, error: 'معاملة الدفع غير موجودة' };
  }

  const existingMeta = (() => { try { return JSON.parse(txn.metadata || '{}'); } catch { return {}; } })();
  await db.paymentTransaction.update({
    where: { id: txn.id },
    data: {
      status: 'failed',
      failureReason: event.error || 'فشل الدفع عبر webhook',
      providerEventId: String(event.paymentId),
      metadata: JSON.stringify({
        ...existingMeta,
        webhookPaymentId: event.paymentId,
        webhookInvoiceStatus: event.invoiceStatus,
        webhookError: event.error,
        webhookProcessedAt: new Date().toISOString(),
      }),
    },
  });

  logger.info('[myfatoorah-webhook] payment_failed processed', {
    txnId: txn.id,
    invoiceId: event.invoiceId,
    error: event.error,
  });

  return { ok: true };
}

async function handleRefundCompleted(event: ParsedWebhookEvent): Promise<{ ok: boolean; error?: string }> {
  if (!event.refundId) {
    return { ok: false, error: 'بيانات الاسترجاع غير مكتملة — RefundId مفقود' };
  }

  const refund = await db.refundTransaction.findFirst({
    where: { providerRefundId: String(event.refundId) },
  });

  if (!refund) {
    logger.warn('[myfatoorah-webhook] refund_completed: no matching refund record', {
      refundId: event.refundId,
    });
    return { ok: false, error: 'سجل الاسترجاع غير موجود' };
  }

  await db.refundTransaction.update({
    where: { id: refund.id },
    data: {
      status: 'completed',
    },
  });

  logger.info('[myfatoorah-webhook] refund_completed processed', {
    refundId: refund.id,
    providerRefundId: event.refundId,
  });

  return { ok: true };
}

// ─── Utility exports ────────────────────────────────────────────────────────

/** Reset the rate limiter (for testing / admin purposes). */
export function resetRateLimiter(): void {
  webhookRateLimiter.clear();
}

/** Get current rate limiter stats. */
export function getRateLimiterStats(): Record<string, { count: number; remaining: number }> {
  const stats: Record<string, { count: number; remaining: number }> = {};
  for (const [key, entry] of webhookRateLimiter.entries()) {
    stats[key] = {
      count: entry.count,
      remaining: RATE_LIMIT_MAX - entry.count,
    };
  }
  return stats;
}

/**
 * registry.ts — Integration Provider Registry + Encrypted Credential Storage.
 *
 * Providers register themselves at module load via `registerProvider`.
 * Credentials live in the `platform_settings` table at key
 *   `integration.<type>.credentials`
 * stored as a JSON map of { field: encryptedValue }.
 *
 * Read/write paths:
 *   getIntegrationConfig(type)  → decrypt all fields for one provider
 *   setIntegrationConfig(type)  → encrypt + upsert credentials
 *   disconnectIntegration(type) → delete the row entirely
 */
import { db } from "@/lib/db";
import { decryptSecret, encryptSecret } from "@/lib/cryptoVault";
import { logger } from "@/lib/logger";
import type { IntegrationProvider } from "./types";

const providers = new Map<string, IntegrationProvider>();

/** Register a provider implementation under its type key. */
export function registerProvider(type: string, provider: IntegrationProvider): void {
  providers.set(type, provider);
  logger.info("[integrations] provider registered", { type });
}

/** Look up a registered provider by type. Returns null if not registered. */
export function getProvider(type: string): IntegrationProvider | null {
  return providers.get(type) || null;
}

/** Return all registered provider type keys (for diagnostics). */
export function listRegisteredProviders(): string[] {
  return Array.from(providers.keys());
}

// ─── Credential storage ────────────────────────────────────────────────────

function settingKey(type: string): string {
  return `integration.${type}.credentials`;
}

/**
 * Read + decrypt credentials for one integration.
 * Returns null if no credentials are stored or JSON is malformed.
 */
export async function getIntegrationConfig(
  type: string,
): Promise<Record<string, string> | null> {
  const key = settingKey(type);
  const setting = await db.platformSettings.findUnique({ where: { key } });
  if (!setting) return null;
  try {
    const encrypted = JSON.parse(setting.value) as Record<string, string>;
    const decrypted: Record<string, string> = {};
    for (const [k, v] of Object.entries(encrypted)) {
      decrypted[k] = decryptSecret(v);
    }
    return decrypted;
  } catch (err) {
    logger.error("[integrations] failed to read config", {
      type,
      err: err instanceof Error ? err.message : String(err),
    });
    return null;
  }
}

/**
 * Encrypt + persist credentials for one integration. Upserts the row.
 */
export async function setIntegrationConfig(
  type: string,
  credentials: Record<string, string>,
): Promise<void> {
  const key = settingKey(type);
  const encrypted: Record<string, string> = {};
  for (const [k, v] of Object.entries(credentials)) {
    encrypted[k] = encryptSecret(v);
  }
  const value = JSON.stringify(encrypted);
  const existing = await db.platformSettings.findUnique({ where: { key } });
  if (existing) {
    await db.platformSettings.update({ where: { key }, data: { value } });
  } else {
    await db.platformSettings.create({
      data: { key, category: "integration", valueType: "json", value },
    });
  }
  logger.info("[integrations] credentials saved", {
    type,
    fields: Object.keys(credentials),
  });
}

/**
 * Remove all stored credentials for one integration.
 */
export async function disconnectIntegration(type: string): Promise<void> {
  const key = settingKey(type);
  await db.platformSettings.deleteMany({ where: { key } });
  logger.info("[integrations] credentials removed", { type });
}

/**
 * inventorySync.ts — Shared inventory-update logic for ALL invoice-creation paths.
 *
 * Features:
 * - Bilingual product matching via matchProduct()
 * - Collision recovery (race condition on new product creation)
 * - Oversell BLOCKING (Task 24: block with warning, not backorder)
 * - StockMovement ledger recording (every quantity change)
 * - [REVIEW-QUEUE] + [OVERSELL] warnings surfaced to callers
 */

import { db } from "./db";
import { num } from "./money";
import { logger } from "./logger";
import { matchProduct } from "./productMatcher";

export interface InventoryLineItem {
  description: string;
  qty: number;
  price: number;
}

export function isReviewQueueWarning(w: string): boolean {
  return w.startsWith("[REVIEW-QUEUE]");
}

export async function recordStockMovement(
  tx: any, companySlug: string, productId: number | null, warehouseId: number,
  signedQty: number, sourceType: string, sourceId: number | null,
  note?: string, createdBy: string = "system",
): Promise<void> {
  try {
    await tx.stockMovement.create({
      data: { companySlug, productId, warehouseId, qty: signedQty.toFixed(3), sourceType, sourceId, note: note ?? null, createdBy },
    });
  } catch (err) {
    logger.error("[inventory-sync] failed to record stock movement", { companySlug, productId, signedQty, sourceType, err: err instanceof Error ? err.message : String(err) });
  }
}

export interface InventorySyncResult {
  productsCreated: number;
  inventoryUpdated: number;
  warehouseUsed: string | null;
  warnings: string[];
}

export async function syncInventoryOnSale(
  tx: any, companySlug: string, items: InventoryLineItem[], invoiceId: number,
): Promise<InventorySyncResult> {
  const warnings: string[] = [];
  let productsCreated = 0;
  let inventoryUpdated = 0;

  const warehouse = await tx.warehouse.findFirst({ where: { companySlug, isActive: true }, orderBy: { id: "asc" } });
  if (!warehouse) {
    warnings.push(`No active warehouse found for company "${companySlug}" — inventory update skipped`);
    return { productsCreated: 0, inventoryUpdated: 0, warehouseUsed: null, warnings };
  }

  for (let idx = 0; idx < items.length; idx++) {
    const item = items[idx];
    const qty = num(item.qty, 3);
    if (qty <= 0) continue;

    const match = await matchProduct({ description: item.description, qty, price: item.price, companySlug, invoiceId, lineItemIndex: idx }, tx);

    let product;
    if (match.productId) {
      product = await tx.productCatalog.findUnique({ where: { id: match.productId } });
    }

    if (!product) {
      try {
        product = await tx.productCatalog.create({ data: { name: item.description, code: null, sellingPrice: item.price.toFixed(3), companySlug } });
        productsCreated++;
        await tx.productAlias.create({ data: { productCatalogId: product.id, companySlug, alias: item.description, language: "unspecified", source: "auto", confidence: 0.5, isVerified: false, createdBy: "inventory-sync" } });
      } catch (createErr: any) {
        logger.warn("[inventory-sync] product create collision — re-querying", { companySlug, description: item.description, err: createErr?.message });
        const reMatch = await matchProduct({ description: item.description, qty, price: item.price, companySlug, invoiceId, lineItemIndex: idx }, tx);
        if (reMatch.productId) product = await tx.productCatalog.findUnique({ where: { id: reMatch.productId } });
        if (!product) {
          const warningMsg = `[REVIEW-QUEUE] Invoice #${invoiceId} line ${idx}: product "${item.description}" orphaned (collision-recovery failed; inventory NOT decremented for qty ${qty})`;
          warnings.push(warningMsg);
          logger.error("[inventory-sync] collision-recovery failed — orphan invoice item", { companySlug, invoiceId, lineItemIndex: idx, description: item.description, qty });
          try {
            await tx.productMatchAudit.create({ data: { companySlug, inputText: item.description, matchedProductId: null, matchedAlias: null, confidence: 0, tier: "collision-recovery-failed", action: "collision-recovery-skipped", invoiceId, createdBy: "inventory-sync-collision-fallback" } });
            await recordStockMovement(tx, companySlug, null, warehouse.id, 0, "collision-recovery", invoiceId, `orphan item: "${item.description}" qty ${qty} — inventory NOT decremented`);
          } catch (auditErr) {
            logger.error("[inventory-sync] failed to write collision-recovery audit entry", { companySlug, invoiceId, err: auditErr instanceof Error ? auditErr.message : String(auditErr) });
          }
          continue;
        }
      }
    }

    const invItem = await tx.inventoryItem.findUnique({ where: { warehouseId_productId: { warehouseId: warehouse.id, productId: product.id } } });

    if (invItem) {
      const currentQty = num(invItem.quantity, 3);
      const newQty = currentQty - qty;
      // TASK 24: oversell BLOCKED
      if (newQty < 0) {
        const overQty = Math.abs(newQty).toFixed(3);
        warnings.push(`[OVERSELL] المنتج "${item.description}" (id=${product.id}): المخزون الحالي ${currentQty.toFixed(3)}، الكمية المطلوبة ${qty.toFixed(3)}، النقص ${overQty}. لم يتم خصم المخزون.`);
        logger.warn("[inventory-sync] oversell blocked", { companySlug, invoiceId, description: item.description, productId: product.id, currentQty, requestedQty: qty, overQty });
        await recordStockMovement(tx, companySlug, product.id, warehouse.id, 0, "sale", invoiceId, `oversell blocked: requested ${qty}, available ${currentQty}, shortage ${overQty}`);
        continue;
      }
      await tx.inventoryItem.update({ where: { id: invItem.id }, data: { quantity: newQty.toFixed(3) } });
      await recordStockMovement(tx, companySlug, product.id, warehouse.id, -qty, "sale", invoiceId);
      inventoryUpdated++;
    } else {
      // TASK 24: no existing inventory = oversell BLOCKED
      warnings.push(`[OVERSELL] المنتج "${item.description}" (id=${product.id}): لا يوجد مخزون مسجل لهذا المنتج. لم يتم خصم المخزون.`);
      logger.warn("[inventory-sync] oversell blocked — no existing inventory", { companySlug, invoiceId, description: item.description, productId: product.id, requestedQty: qty });
      await recordStockMovement(tx, companySlug, product.id, warehouse.id, 0, "sale", invoiceId, `oversell blocked: no existing inventory, requested ${qty}`);
      continue;
    }
  }

  return { productsCreated, inventoryUpdated, warehouseUsed: warehouse.name, warnings };
}

export async function syncInventoryOnPurchase(
  tx: any, companySlug: string, items: InventoryLineItem[], purchaseInvoiceId: number,
): Promise<InventorySyncResult> {
  const warnings: string[] = [];
  let productsCreated = 0;
  let inventoryUpdated = 0;

  const warehouse = await tx.warehouse.findFirst({ where: { companySlug, isActive: true }, orderBy: { id: "asc" } });
  if (!warehouse) {
    warnings.push(`No active warehouse for "${companySlug}"`);
    return { productsCreated: 0, inventoryUpdated: 0, warehouseUsed: null, warnings };
  }

  for (let idx = 0; idx < items.length; idx++) {
    const item = items[idx];
    const qty = num(item.qty, 3);
    if (qty <= 0) continue;

    const match = await matchProduct({ description: item.description, qty, price: item.price, companySlug, invoiceId: purchaseInvoiceId, lineItemIndex: idx }, tx);

    let product;
    if (match.productId) product = await tx.productCatalog.findUnique({ where: { id: match.productId } });

    if (!product) {
      try {
        product = await tx.productCatalog.create({ data: { name: item.description, code: null, purchasePrice: item.price.toFixed(3), companySlug } });
        productsCreated++;
        await tx.productAlias.create({ data: { productCatalogId: product.id, companySlug, alias: item.description, language: "unspecified", source: "auto", confidence: 0.5, isVerified: false, createdBy: "inventory-sync-purchase" } });
      } catch (createErr: any) {
        logger.warn("[inventory-sync-purchase] collision", { companySlug, description: item.description, err: createErr?.message });
        const reMatch = await matchProduct({ description: item.description, qty, price: item.price, companySlug, invoiceId: purchaseInvoiceId, lineItemIndex: idx }, tx);
        if (reMatch.productId) product = await tx.productCatalog.findUnique({ where: { id: reMatch.productId } });
        if (!product) {
          warnings.push(`[REVIEW-QUEUE] Purchase invoice #${purchaseInvoiceId} line ${idx}: product "${item.description}" orphaned`);
          try {
            await tx.productMatchAudit.create({ data: { companySlug, inputText: item.description, matchedProductId: null, matchedAlias: null, confidence: 0, tier: "collision-recovery-failed", action: "collision-recovery-skipped", invoiceId: purchaseInvoiceId, createdBy: "inventory-sync-purchase-collision-fallback" } });
            await recordStockMovement(tx, companySlug, null, warehouse.id, 0, "collision-recovery", purchaseInvoiceId, `orphan purchase item: "${item.description}" qty ${qty}`);
          } catch (auditErr) { logger.error("[inventory-sync-purchase] audit failed", { err: auditErr instanceof Error ? auditErr.message : String(auditErr) }); }
          continue;
        }
      }
    }

    const invItem = await tx.inventoryItem.findUnique({ where: { warehouseId_productId: { warehouseId: warehouse.id, productId: product.id } } });
    if (invItem) {
      const currentQty = num(invItem.quantity, 3);
      await tx.inventoryItem.update({ where: { id: invItem.id }, data: { quantity: (currentQty + qty).toFixed(3) } });
      await recordStockMovement(tx, companySlug, product.id, warehouse.id, qty, "purchase", purchaseInvoiceId);
    } else {
      await tx.inventoryItem.create({ data: { companySlug, warehouseId: warehouse.id, productId: product.id, quantity: qty.toFixed(3), reorderLevel: "0", reorderQty: "0" } });
      await recordStockMovement(tx, companySlug, product.id, warehouse.id, qty, "purchase", purchaseInvoiceId, "initial stock: no existing inventory");
    }
    inventoryUpdated++;
  }

  return { productsCreated, inventoryUpdated, warehouseUsed: warehouse.name, warnings };
}

/**
 * invoice-brain/excelParser.ts — xlsx/csv parsing with header-mapping memory.
 *
 * FIXES from original:
 *  1. Multi-sheet: original only read the FIRST sheet. Now reads all sheets
 *     (or a caller-specified subset) — a workbook with "Orders" + "Returns"
 *     no longer silently drops the second sheet.
 *  2. Batching (checklist 5.3): original loaded the entire file into memory
 *     and parsed all rows in one pass — fine for 1k rows, fatal for 100k.
 *     Now `extractFromTabularBatched` yields results in configurable chunks
 *     so a 100k-row file streams through without OOM. The simple
 *     `extractFromTabular` is kept for small files / backward compat.
 */
import ExcelJS from "exceljs";
import { InvoiceSchema, INVOICE_FIELDS, type InvoiceField } from "./schema";
import type { ExtractionResult } from "./extractInvoice";
import { fingerprintHeaders, type HeaderMapStore } from "./headerMapStore";
import { logger } from "@/lib/logger";

const HEADER_SYNONYMS: Record<InvoiceField, string[]> = {
  name: ["اسم", "الاسم", "اسم العميل", "name", "customer", "client", "client name"],
  address: ["عنوان", "العنوان", "address", "shipping address"],
  price: ["سعر", "السعر", "price", "unit price", "subtotal"],
  currency: ["عملة", "العملة", "currency"],
  discount: ["خصم", "الخصم", "discount"],
  tax: ["ضريبة", "الضريبة", "ضريبة القيمة المضافة", "tax", "vat"],
  total: ["اجمالي", "الإجمالي", "الاجمالي", "المجموع", "total", "grand total"],
  notes: ["ملاحظات", "ملاحظة", "notes", "note", "comment", "comments"],
};

function normalizeHeader(h: string): string {
  return h.trim().toLowerCase().replace(/\s+/g, " ");
}

function matchBySynonym(header: string): InvoiceField | null {
  const norm = normalizeHeader(header);
  for (const field of INVOICE_FIELDS) {
    if (HEADER_SYNONYMS[field].some((s) => normalizeHeader(s) === norm)) {
      return field;
    }
  }
  return null;
}

export interface ParsedSheet {
  sheetName: string;
  rows: Record<string, unknown>[];
}

/** FIX #1: read ALL sheets (not just the first). Returns one entry per sheet. */
export async function parseTabularAllSheets(buffer: Buffer): Promise<ParsedSheet[]> {
  const workbook = new ExcelJS.Workbook();
  await workbook.xlsx.load(buffer as unknown as ArrayBuffer);
  const results: ParsedSheet[] = [];
  workbook.eachSheet((worksheet) => {
    const sheetHeaders: string[] = [];
    const sheetRows: Record<string, unknown>[] = [];
    let isFirstRow = true;
    worksheet.eachRow((row, rowNumber) => {
      if (isFirstRow) {
        row.eachCell((cell, colNumber) => {
          sheetHeaders[colNumber] = String(cell.value ?? "");
        });
        isFirstRow = false;
        return;
      }
      const obj: Record<string, unknown> = {};
      row.eachCell((cell, colNumber) => {
        const header = sheetHeaders[colNumber] || `col${colNumber}`;
        obj[header] = cell.value ?? "";
      });
      sheetRows.push(obj);
    });
    if (sheetRows.length > 0) {
      results.push({ sheetName: worksheet.name, rows: sheetRows });
    }
  });
  return results;
}

/** Backward-compat: first sheet only. */
export async function parseTabular(buffer: Buffer): Promise<Record<string, unknown>[]> {
  const sheets = await parseTabularAllSheets(buffer);
  return sheets[0]?.rows ?? [];
}

export function autoMapHeaders(headers: string[]): {
  mapping: Record<string, InvoiceField>;
  unresolved: string[];
} {
  const mapping: Record<string, InvoiceField> = {};
  const unresolved: string[] = [];
  for (const h of headers) {
    const field = matchBySynonym(h);
    if (field) mapping[h] = field;
    else unresolved.push(h);
  }
  return { mapping, unresolved };
}

/**
 * Resolve the mapping for a sheet's headers (cache → synonyms → AI once).
 * Returns the mapping + whether AI was used.
 */
async function resolveMapping(
  headers: string[],
  headerStore: HeaderMapStore,
  resolveUnknownHeaders?: (headers: string[]) => Promise<Record<string, InvoiceField>>
): Promise<{ mapping: Record<string, InvoiceField>; usedAI: boolean; fingerprint: string }> {
  const fingerprint = fingerprintHeaders(headers);
  const cached = await headerStore.get(fingerprint);
  if (cached) {
    await headerStore.touch(fingerprint);
    return { mapping: cached.mapping, usedAI: false, fingerprint };
  }

  const auto = autoMapHeaders(headers);
  let mapping = auto.mapping;
  let usedAI = false;

  if (auto.unresolved.length > 0 && resolveUnknownHeaders) {
    try {
      const aiMapping = await resolveUnknownHeaders(auto.unresolved);
      mapping = { ...mapping, ...aiMapping };
      usedAI = true;
    } catch (err) {
      logger.warn("[brain] header AI resolution failed — using synonym-only mapping", { err: (err as Error).message, unresolved: auto.unresolved.length });
    }
  }

  await headerStore.save({
    headerFingerprint: fingerprint,
    mapping,
    sampleCount: 1,
    createdAt: new Date().toISOString(),
    lastUsedAt: new Date().toISOString(),
  });

  return { mapping, usedAI, fingerprint };
}

/** Parse rows of one sheet into ExtractionResult[] using the resolved mapping. */
function parseRows(
  rows: Record<string, unknown>[],
  mapping: Record<string, InvoiceField>,
  fingerprint: string,
  source: "pattern" | "ai"
): ExtractionResult[] {
  const results: ExtractionResult[] = [];
  for (const row of rows) {
    const record: Record<string, unknown> = {};
    for (const [header, field] of Object.entries(mapping)) {
      record[field] = row[header];
    }
    const parsed = InvoiceSchema.safeParse(record);
    if (parsed.success) {
      results.push({ data: parsed.data, source, fingerprint });
    }
  }
  return results;
}

/** Simple (whole-file) extraction — fine for small files. */
export async function extractFromTabular(
  buffer: Buffer,
  headerStore: HeaderMapStore,
  resolveUnknownHeaders?: (headers: string[]) => Promise<Record<string, InvoiceField>>
): Promise<ExtractionResult[]> {
  const sheets = await parseTabularAllSheets(buffer);
  if (sheets.length === 0) return [];

  const results: ExtractionResult[] = [];
  for (const sheet of sheets) {
    const headers = Object.keys(sheet.rows[0]);
    const { mapping, usedAI, fingerprint } = await resolveMapping(headers, headerStore, resolveUnknownHeaders);
    const source: "pattern" | "ai" = usedAI ? "ai" : "pattern";
    results.push(...parseRows(sheet.rows, mapping, fingerprint, source));
  }
  return results;
}

/**
 * FIX #2 — Batched extraction for large files (checklist 5.3).
 * Yields results sheet-by-sheet, chunk-by-chunk, so a 100k-row file never
 * holds all parsed results in memory at once. Caller consumes the async
 * iterator and can flush to DB / stream to client incrementally.
 */
export async function* extractFromTabularBatched(
  buffer: Buffer,
  headerStore: HeaderMapStore,
  resolveUnknownHeaders?: (headers: string[]) => Promise<Record<string, InvoiceField>>,
  chunkSize = 1000
): AsyncGenerator<{ sheetName: string; results: ExtractionResult[]; totalRows: number }> {
  const sheets = await parseTabularAllSheets(buffer);
  for (const sheet of sheets) {
    if (sheet.rows.length === 0) continue;
    const headers = Object.keys(sheet.rows[0]);
    const { mapping, usedAI, fingerprint } = await resolveMapping(headers, headerStore, resolveUnknownHeaders);
    const source: "pattern" | "ai" = usedAI ? "ai" : "pattern";

    for (let i = 0; i < sheet.rows.length; i += chunkSize) {
      const chunk = sheet.rows.slice(i, i + chunkSize);
      yield {
        sheetName: sheet.sheetName,
        results: parseRows(chunk, mapping, fingerprint, source),
        totalRows: sheet.rows.length,
      };
    }
  }
}

/**
 * invoice-brain/headerMapStore.ts — header-mapping memory for tabular sources.
 *
 * Same dual-impl pattern as patternStore.ts: JSON file (dev) + Prisma (GarfiX).
 * Backed by the HeaderMapping table (see prisma/schema.prisma).
 */
import { readFile, writeFile, mkdir } from "node:fs/promises";
import { dirname } from "node:path";
import { createHash } from "node:crypto";
import { db } from "@/lib/db";
import { logger } from "@/lib/logger";
import type { InvoiceField } from "./schema";

export interface HeaderMapping {
  headerFingerprint: string;
  mapping: Record<string, InvoiceField>;
  sampleCount: number;
  createdAt: string;
  lastUsedAt: string;
}

export interface HeaderMapStore {
  get(fingerprint: string): Promise<HeaderMapping | null>;
  save(mapping: HeaderMapping): Promise<void>;
  touch(fingerprint: string): Promise<void>;
}

/** Fingerprint a set of column headers, order-independent. */
export function fingerprintHeaders(headers: string[]): string {
  const key = headers.map((h) => h.trim().toLowerCase()).sort().join("|");
  return createHash("sha256").update(key).digest("hex").slice(0, 16);
}

// ── JSON file impl ───────────────────────────────────────────────────────────

export class JsonFileHeaderMapStore implements HeaderMapStore {
  private cache: Record<string, HeaderMapping> | null = null;
  constructor(private filePath: string) {}

  private async load(): Promise<Record<string, HeaderMapping>> {
    if (this.cache) return this.cache;
    try {
      this.cache = JSON.parse(await readFile(this.filePath, "utf-8"));
    } catch {
      this.cache = {};
    }
    return this.cache!;
  }

  private async persist(): Promise<void> {
    await mkdir(dirname(this.filePath), { recursive: true });
    await writeFile(this.filePath, JSON.stringify(this.cache, null, 2), "utf-8");
  }

  async get(fingerprint: string): Promise<HeaderMapping | null> {
    return (await this.load())[fingerprint] ?? null;
  }

  async save(mapping: HeaderMapping): Promise<void> {
    const db = await this.load();
    db[mapping.headerFingerprint] = mapping;
    await this.persist();
  }

  async touch(fingerprint: string): Promise<void> {
    const db = await this.load();
    const m = db[fingerprint];
    if (!m) return;
    m.sampleCount += 1;
    m.lastUsedAt = new Date().toISOString();
    await this.persist();
  }
}

// ── Prisma impl ──────────────────────────────────────────────────────────────

export class PrismaHeaderMapStore implements HeaderMapStore {
  async get(fingerprint: string): Promise<HeaderMapping | null> {
    const row = await db.invoiceBrainHeaderMap.findUnique({ where: { headerFingerprint: fingerprint } });
    if (!row) return null;
    return {
      headerFingerprint: row.headerFingerprint,
      mapping: typeof row.mapping === "string" ? JSON.parse(row.mapping) : row.mapping,
      sampleCount: row.sampleCount,
      createdAt: row.createdAt.toISOString(),
      lastUsedAt: row.lastUsedAt.toISOString(),
    };
  }

  async save(mapping: HeaderMapping): Promise<void> {
    const now = new Date();
    await db.invoiceBrainHeaderMap.upsert({
      where: { headerFingerprint: mapping.headerFingerprint },
      create: {
        headerFingerprint: mapping.headerFingerprint,
        mapping: JSON.stringify(mapping.mapping),
        sampleCount: mapping.sampleCount,
        createdAt: now,
        lastUsedAt: now,
      },
      update: {
        mapping: JSON.stringify(mapping.mapping),
        lastUsedAt: now,
      },
    });
  }

  async touch(fingerprint: string): Promise<void> {
    try {
      await db.invoiceBrainHeaderMap.update({
        where: { headerFingerprint: fingerprint },
        data: {
          sampleCount: { increment: 1 },
          lastUsedAt: new Date(),
        },
      });
    } catch (err) {
      logger.debug("[brain] header touch missed", { fingerprint, err: (err as Error).message });
    }
  }
}

/**
 * invoice-brain/patternParser.ts — fast/free extraction using saved regex.
 *
 * Returns null if ANY required field fails → caller falls back to AI.
 * (No correctness change from original; the .trim() on capture already
 *  handles trailing whitespace. Kept as-is — audited, no bug.)
 *
 * N-04: the input `text` is now normalized line-by-line (via normalizeLine
 * from ./normalize) BEFORE running text.match(re). This is the critical fix
 * — matching must happen against the same normalized shape the regex was
 * learned from (aiFallback.ts:parseLabelValuePairs, N-03), or N-03 alone
 * does nothing. A regex learned from "السعر: ٥٠" (Arabic-Indic) wouldn't
 * match input "السعر: 50" (ASCII) without this normalization at match time.
 *
 * Lines are split on \r?\n, normalized individually, then joined back with
 * \n so the RegExp `m` flag and `^` anchors still work correctly — each
 * normalized line becomes a regex-line for matching purposes.
 */
import type { InvoiceTemplate } from "./patternStore";
import { normalizeLine } from "./normalize";

export function extractWithTemplate(
  text: string,
  template: InvoiceTemplate
): Record<string, string> | null {
  // N-04: normalize the input text line-by-line so the match-time shape
  // equals the learn-time shape. Join with \n (not the original line endings)
  // so the `m` flag and `^` anchors work uniformly regardless of whether the
  // original text used \n, \r\n, or \r.
  const normalizedText = text
    .split(/\r?\n/)
    .map((line) => normalizeLine(line))
    .join("\n");

  const result: Record<string, string> = {};

  for (const f of template.fields) {
    let re: RegExp;
    try {
      re = new RegExp(f.regex, "m");
    } catch {
      return null; // corrupted regex in storage — let AI handle it
    }

    const match = normalizedText.match(re);
    if (!match || !match[1] || !match[1].trim()) {
      return null;
    }
    // Keep .trim() on the captured value — unchanged behavior. The captured
    // value is already from a normalized line, so trailing whitespace is rare,
    // but .trim() is belt-and-suspenders against regex `(.+)` greedily
    // capturing a trailing space before the line-end.
    result[f.field] = match[1].trim();
  }

  return result;
}

/**
 * invoice-brain/patternStore.ts — template memory (interface + 2 impls).
 *
 * Two implementations:
 *   - JsonFilePatternStore: dev/standalone (JSON file, in-process cache)
 *   - PrismaPatternStore: GarfiX production (InvoiceTemplate table)
 *
 * Both implement the same interface, so extractInvoice.ts doesn't change
 * when you swap stores (checklist 2.2).
 */
import { readFile, writeFile, mkdir } from "node:fs/promises";
import { dirname } from "node:path";
import { db } from "@/lib/db";
import { logger } from "@/lib/logger";
import type { InvoiceField } from "./schema";

export interface FieldTemplate {
  field: InvoiceField;
  label: string; // the label text next to the value (documentation only)
  regex: string; // the extraction pattern
}

export interface InvoiceTemplate {
  fingerprint: string;
  fields: FieldTemplate[];
  sampleCount: number;
  createdAt: string;
  lastUsedAt: string;
}

export interface PatternStore {
  get(fingerprint: string): Promise<InvoiceTemplate | null>;
  save(template: InvoiceTemplate): Promise<void>;
  touch(fingerprint: string): Promise<void>;
  stats(): Promise<{ totalTemplates: number; totalHits: number }>;
}

// ── JSON file impl (dev / standalone) ────────────────────────────────────────

export class JsonFilePatternStore implements PatternStore {
  private cache: Record<string, InvoiceTemplate> | null = null;
  constructor(private filePath: string) {}

  private async load(): Promise<Record<string, InvoiceTemplate>> {
    if (this.cache) return this.cache;
    try {
      this.cache = JSON.parse(await readFile(this.filePath, "utf-8"));
    } catch {
      this.cache = {};
    }
    return this.cache!;
  }

  private async persist(): Promise<void> {
    await mkdir(dirname(this.filePath), { recursive: true });
    await writeFile(this.filePath, JSON.stringify(this.cache, null, 2), "utf-8");
  }

  async get(fingerprint: string): Promise<InvoiceTemplate | null> {
    return (await this.load())[fingerprint] ?? null;
  }

  async save(template: InvoiceTemplate): Promise<void> {
    const db = await this.load();
    db[template.fingerprint] = template;
    await this.persist();
  }

  async touch(fingerprint: string): Promise<void> {
    const db = await this.load();
    const t = db[fingerprint];
    if (!t) return;
    t.sampleCount += 1;
    t.lastUsedAt = new Date().toISOString();
    await this.persist();
  }

  async stats(): Promise<{ totalTemplates: number; totalHits: number }> {
    const db = await this.load();
    const templates = Object.values(db);
    return {
      totalTemplates: templates.length,
      totalHits: templates.reduce((sum, t) => sum + t.sampleCount, 0),
    };
  }
}

// ── Prisma impl (GarfiX production) ──────────────────────────────────────────
// Backed by the InvoiceTemplate table (see prisma/schema.prisma, P1-invoice-brain).
// fields[] is stored as a JSON string (SQLite-compatible; PostgreSQL Json type
// works too — see P1-A schema comment).

export class PrismaPatternStore implements PatternStore {
  async get(fingerprint: string): Promise<InvoiceTemplate | null> {
    const row = await db.invoiceBrainTemplate.findUnique({ where: { fingerprint } });
    if (!row) return null;
    return {
      fingerprint: row.fingerprint,
      fields: typeof row.fields === "string" ? JSON.parse(row.fields) : row.fields,
      sampleCount: row.sampleCount,
      createdAt: row.createdAt.toISOString(),
      lastUsedAt: row.lastUsedAt.toISOString(),
    };
  }

  async save(template: InvoiceTemplate): Promise<void> {
    const now = new Date();
    await db.invoiceBrainTemplate.upsert({
      where: { fingerprint: template.fingerprint },
      create: {
        fingerprint: template.fingerprint,
        fields: JSON.stringify(template.fields),
        sampleCount: template.sampleCount,
        createdAt: now,
        lastUsedAt: now,
      },
      update: {
        fields: JSON.stringify(template.fields),
        sampleCount: template.sampleCount,
        lastUsedAt: now,
      },
    });
  }

  async touch(fingerprint: string): Promise<void> {
    // Atomic increment to avoid lost updates under concurrency
    try {
      await db.invoiceBrainTemplate.update({
        where: { fingerprint },
        data: {
          sampleCount: { increment: 1 },
          lastUsedAt: new Date(),
        },
      });
    } catch (err) {
      // fingerprint not found → nothing to touch (can happen if template was pruned)
      logger.debug("[brain] touch missed", { fingerprint, err: (err as Error).message });
    }
  }

  async stats(): Promise<{ totalTemplates: number; totalHits: number }> {
    const agg = await db.invoiceBrainTemplate.aggregate({
      _count: { fingerprint: true },
      _sum: { sampleCount: true },
    });
    return {
      totalTemplates: agg._count.fingerprint,
      totalHits: agg._sum.sampleCount ?? 0,
    };
  }
}

/**
 * mfa.ts — TOTP-based MFA for admin/founder accounts.
 *
 * Uses the otpauth URI standard (Google Authenticator / Authy compatible).
 * Secrets are encrypted at rest via cryptoVault.
 * Recovery codes are hashed (SHA-256) before storage — one-time use.
 */

import crypto from "node:crypto";
import { db } from "@/lib/db";
import { encryptSecret, decryptSecret, hashToken, safeCompare } from "@/lib/cryptoVault";
import { logger } from "./logger";

// TOTP parameters (RFC 6238)
const TOTP_PERIOD = 30; // seconds
const TOTP_DIGITS = 6;
const TOTP_ALGORITHM = "sha1" as const;
const RECOVERY_CODE_COUNT = 10;

function base32Encode(buffer: Buffer): string {
  const alphabet = "ABCDEFGHIJKLMNOPQRSTUVWXYZ234567";
  let bits = "";
  for (const byte of buffer) {
    bits += byte.toString(2).padStart(8, "0");
  }
  let result = "";
  for (let i = 0; i + 5 <= bits.length; i += 5) {
    result += alphabet[parseInt(bits.substring(i, i + 5), 2)];
  }
  return result;
}

/**
 * Base32 decode — required because TOTP secrets are Base32-encoded (RFC 6238),
 * but the old code mistakenly used base64 decode, producing wrong HMAC keys.
 * Authenticator apps (Google Authenticator, Authy) expect Base32 secrets.
 */
function base32Decode(str: string): Buffer {
  const alphabet = "ABCDEFGHIJKLMNOPQRSTUVWXYZ234567";
  const clean = str.replace(/=+$/, "");
  let bits = "";
  for (const ch of clean) {
    const idx = alphabet.indexOf(ch.toUpperCase());
    if (idx === -1) continue; // skip invalid chars
    bits += idx.toString(2).padStart(5, "0");
  }
  const bytes: number[] = [];
  for (let i = 0; i + 8 <= bits.length; i += 8) {
    bytes.push(parseInt(bits.substring(i, i + 8), 2));
  }
  return Buffer.from(bytes);
}

function generateTOTPSecret(): string {
  const secret = crypto.randomBytes(20);
  return base32Encode(secret);
}

function buildTOTPUri(secret: string, email: string): string {
  const encoded = encodeURIComponent(email);
  return `otpauth://totp/GarfiX:${encoded}?secret=${secret}&issuer=GarfiX&algorithm=SHA1&digits=${TOTP_DIGITS}&period=${TOTP_PERIOD}`;
}

function generateRecoveryCodes(count: number): string[] {
  const codes: string[] = [];
  for (let i = 0; i < count; i++) {
    const bytes = crypto.randomBytes(4);
    const code = bytes.toString("hex").toUpperCase().match(/.{1,4}/g)!.join("-");
    codes.push(code);
  }
  return codes;
}

/** Generate a new TOTP secret for a user. Returns the secret (plaintext) and recovery codes. */
export async function setupMFA(userUid: string): Promise<{ secret: string; uri: string; recoveryCodes: string[] }> {
  const secret = generateTOTPSecret();
  const uri = buildTOTPUri(secret, userUid);
  const recoveryCodes = generateRecoveryCodes(RECOVERY_CODE_COUNT);

  // Hash recovery codes for storage
  const hashedCodes = recoveryCodes.map((c) => hashToken(c));
  const encryptedSecret = encryptSecret(secret);
  const encryptedCodes = encryptSecret(JSON.stringify(hashedCodes));

  await db.mFASecret.upsert({
    where: { id: `mfa-${userUid}` },
    create: {
      id: `mfa-${userUid}`,
      userUid,
      secret: encryptedSecret,
      recoveryCodes: encryptedCodes,
      enabled: false, // Not enabled until verified
    },
    update: {
      secret: encryptedSecret,
      recoveryCodes: encryptedCodes,
      enabled: false,
      verifiedAt: null,
    },
  });

  return { secret, uri, recoveryCodes };
}

/** Verify a TOTP code during setup (enables MFA if valid). */
export async function verifyAndEnableMFA(userUid: string, code: string): Promise<boolean> {
  const record = await db.mFASecret.findUnique({ where: { id: `mfa-${userUid}` } });
  if (!record) return false;

  const secret = decryptSecret(record.secret);
  if (verifyTOTPCode(secret, code)) {
    await db.mFASecret.update({
      where: { id: `mfa-${userUid}` },
      data: { enabled: true, verifiedAt: new Date() },
    });
    return true;
  }
  return false;
}

/** Validate a TOTP code for an already-enabled MFA. */
export async function validateMFA(userUid: string, code: string): Promise<boolean> {
  const record = await db.mFASecret.findUnique({ where: { id: `mfa-${userUid}` } });
  if (!record || !record.enabled) return false;

  const secret = decryptSecret(record.secret);
  const valid = verifyTOTPCode(secret, code);

  if (valid) {
    await db.mFASecret.update({
      where: { id: `mfa-${userUid}` },
      data: { lastUsedAt: new Date() },
    });
  }
  return valid;
}

/** Use a recovery code (one-time use). */
export async function useRecoveryCode(userUid: string, code: string): Promise<boolean> {
  const record = await db.mFASecret.findUnique({ where: { id: `mfa-${userUid}` } });
  if (!record || !record.enabled) return false;

  const hashedCodes: string[] = JSON.parse(decryptSecret(record.recoveryCodes));
  const hashedInput = hashToken(code);

  const idx = hashedCodes.indexOf(hashedInput);
  if (idx === -1) return false;

  // Remove used code
  hashedCodes.splice(idx, 1);
  await db.mFASecret.update({
    where: { id: `mfa-${userUid}` },
    data: {
      recoveryCodes: encryptSecret(JSON.stringify(hashedCodes)),
      lastUsedAt: new Date(),
    },
  });

  return true;
}

/** Check if MFA is enabled for a user. */
export async function isMFAEnabled(userUid: string): Promise<boolean> {
  const record = await db.mFASecret.findUnique({ where: { id: `mfa-${userUid}` } });
  return record?.enabled === true;
}

/** Check if MFA is required (admin/founder roles). */
export function isMFARequired(role: string, isFounder: boolean): boolean {
  return role === "admin" || isFounder;
}

/** Internal TOTP verification — matches RFC 6238. */
function verifyTOTPCode(secret: string, userCode: string): boolean {
  try {
    // Accept current and previous/next time slot (30s window each)
    const now = Math.floor(Date.now() / 1000 / TOTP_PERIOD);
    for (const offset of [0, -1, 1]) {
      const counter = now + offset;
      const counterBuf = Buffer.alloc(8);
      counterBuf.writeBigUInt64BE(BigInt(counter));

      // FIX: Use base32Decode (not base64) — TOTP secrets are Base32 per RFC 6238
      const key = base32Decode(secret);
      if (key.length === 0) continue;

      const hmac = crypto.createHmac(TOTP_ALGORITHM, key);
      hmac.update(counterBuf);
      const digest = hmac.digest();

      const byteOffset = digest[digest.length - 1] & 0x0f;
      const binary =
        ((digest[byteOffset] & 0x7f) << 24) |
        ((digest[byteOffset + 1] & 0xff) << 16) |
        ((digest[byteOffset + 2] & 0xff) << 8) |
        (digest[byteOffset + 3] & 0xff);

      const otp = (binary % Math.pow(10, TOTP_DIGITS)).toString().padStart(TOTP_DIGITS, "0");
      if (safeCompare(otp, userCode)) return true;
    }
    return false;
  } catch {
    return false;
  }
}

/** Disable MFA for a user (admin action). */
export async function disableMFA(userUid: string): Promise<void> {
  await db.mFASecret.delete({ where: { id: `mfa-${userUid}` } }).catch(() => {});
  logger.info("[mfa] MFA disabled for user", { userUid });
}

/** Get remaining recovery code count. */
export async function getRecoveryCodeCount(userUid: string): Promise<number> {
  const record = await db.mFASecret.findUnique({ where: { id: `mfa-${userUid}` } });
  if (!record) return 0;
  try {
    const hashedCodes: string[] = JSON.parse(decryptSecret(record.recoveryCodes));
    return hashedCodes.length;
  } catch {
    return 0;
  }
}

/**
 * middleware.ts — Composable middleware factories for API route handlers.
 *
 * The old pattern repeated auth + tenant-scope + plan-limits checks inline
 * in every route. This module exports factories that return ready-to-use
 * helpers, ensuring consistent enforcement and DRY code.
 *
 * Usage:
 *   import { requireCompanyAccess, withValidation } from "@/lib/middleware";
 *   import { z } from "zod";
 *
 *   const Schema = z.object({ name: z.string() });
 *
 *   export const POST = withValidation(Schema, async (req, ctx) => {
 *     const access = await requireCompanyAccess(req, ctx.body.companySlug);
 *     if (access.error) return access.error;
 *     // ... business logic
 *   });
 */

import { NextRequest, NextResponse } from "next/server";
import { resolveAuth, assertCompanyAccess, type AuthPayload } from "./auth";
import { canAccessCompany } from "./tenantScope";
import { logAudit } from "./audit";
import { logger } from "./logger";
import { z, ZodError } from "zod";

// Note: isFounderEmail is imported later in the file (near requireFounder)
// to keep the founder-related imports grouped with the founder-related code.

export interface AuthContext {
  user: AuthPayload;
}

export type AuthedHandler<T = unknown> = (
  req: NextRequest,
  ctx: AuthContext & { body?: T; params?: Record<string, string> },
) => Promise<NextResponse>;

// ─── requireAuth ────────────────────────────────────────────────────────────

export async function requireAuth(req: NextRequest): Promise<{ user: AuthPayload } | NextResponse> {
  const result = await resolveAuth(req);
  if (!result.ok || !result.user) {
    return NextResponse.json(
      { error: result.error || "غير مصرّح" },
      { status: result.status || 401 },
    );
  }
  return { user: result.user };
}

// ─── requireCompanyAccess ───────────────────────────────────────────────────

export interface CompanyAccessResult {
  ok: boolean;
  user?: AuthPayload;
  error?: NextResponse;
}

/**
 * Verify the user can access the given company. Use for routes that take
 * a companySlug in the body or query string.
 */
export async function requireCompanyAccess(
  req: NextRequest,
  companySlug: string,
): Promise<CompanyAccessResult> {
  const authResult = await requireAuth(req);
  if (authResult instanceof NextResponse) {
    return { ok: false, error: authResult };
  }
  if (!canAccessCompany(authResult.user, companySlug)) {
    return {
      ok: false,
      error: NextResponse.json({ error: "ليس لديك صلاحية للوصول إلى هذه الشركة" }, { status: 403 }),
    };
  }
  return { ok: true, user: authResult.user };
}

// ─── requirePermission ──────────────────────────────────────────────────────

/**
 * Check if the authenticated user has a specific permission.
 * Uses the permissions map from the JWT payload (computed by computeEffectivePermissions).
 * Founder and admin always pass.
 *
 * This is the CRITICAL security guard that was missing in v11 — without it,
 * any authenticated user could call any endpoint regardless of their role.
 *
 * P0 FIX (audit finding): the previous implementation only checked
 * `user.role === "admin"` — but the founder is identified by EMAIL match
 * (isFounderEmail), not by role. If the founder's role is ever set to
 * something other than "admin" (e.g. if a future migration changes the
 * default), they would be denied access to their own platform. We now
 * explicitly check isFounderEmail(user.email) so the founder always passes
 * regardless of their role value, matching the documented behavior.
 */
export function hasPermission(user: AuthPayload, permKey: string): boolean {
  // Founder (by email) and admin (by role) both bypass all permission checks
  if (isFounderEmail(user.email)) return true;
  if (user.role === "admin") return true;
  // Check the effective permissions map
  const perms = user.permissions || {};
  return !!perms[permKey];
}

/**
 * Require a specific permission. Returns {user} on success or {error} on failure.
 * Use this in every mutating endpoint (POST/PATCH/DELETE) to enforce RBAC.
 *
 * Example:
 *   const access = await requirePermission(req, "create_invoice");
 *   if (access.error) return access.error;
 */
export async function requirePermission(
  req: NextRequest,
  permKey: string,
): Promise<{ user: AuthPayload } | { error: NextResponse }> {
  const authResult = await requireAuth(req);
  if (authResult instanceof NextResponse) {
    return { error: authResult };
  }
  if (!hasPermission(authResult.user, permKey)) {
    return {
      error: NextResponse.json(
        { error: `ليس لديك صلاحية: ${permKey}` },
        { status: 403 },
      ),
    };
  }
  return { user: authResult.user };
}

/**
 * Require both auth + company access + a specific permission.
 * The most common guard for tenant-scoped mutating endpoints.
 *
 * Example:
 *   const access = await requirePermissionForCompany(req, "create_invoice", companySlug);
 *   if ("error" in access) return access.error;
 */
export async function requirePermissionForCompany(
  req: NextRequest,
  permKey: string,
  companySlug: string,
): Promise<{ user: AuthPayload } | { error: NextResponse }> {
  const authResult = await requireAuth(req);
  if (authResult instanceof NextResponse) {
    return { error: authResult };
  }
  if (!hasPermission(authResult.user, permKey)) {
    return {
      error: NextResponse.json(
        { error: `ليس لديك صلاحية: ${permKey}` },
        { status: 403 },
      ),
    };
  }
  if (!canAccessCompany(authResult.user, companySlug)) {
    return {
      error: NextResponse.json(
        { error: "ليس لديك صلاحية للوصول إلى هذه الشركة" },
        { status: 403 },
      ),
    };
  }
  return { user: authResult.user };
}

// ─── requireFounder ─────────────────────────────────────────────────────────

import { isFounderEmail } from "./founder";

export async function requireFounder(req: NextRequest): Promise<{ user: AuthPayload } | NextResponse> {
  const authResult = await requireAuth(req);
  if (authResult instanceof NextResponse) return authResult;
  if (!isFounderEmail(authResult.user.email)) {
    return NextResponse.json({ error: "هذه العملية متاحة للمؤسس فقط" }, { status: 403 });
  }
  // SEC-005 FIX: Founder must have verified email
  const { db } = await import("./db");
  const dbUser = await db.appUser.findUnique({
    where: { uid: authResult.user.uid },
    select: { emailVerified: true },
  });
  if (!dbUser?.emailVerified) {
    return NextResponse.json({ error: "حساب المؤسس يجب أن يكون موثّق البريد الإلكتروني" }, { status: 403 });
  }
  return authResult;
}

// ─── requireAdmin ───────────────────────────────────────────────────────────

export async function requireAdmin(req: NextRequest): Promise<{ user: AuthPayload } | NextResponse> {
  const authResult = await requireAuth(req);
  if (authResult instanceof NextResponse) return authResult;
  if (authResult.user.role !== "admin" && !isFounderEmail(authResult.user.email)) {
    return NextResponse.json({ error: "هذه العملية متاحة للمدراء فقط" }, { status: 403 });
  }
  return authResult;
}

// ─── withValidation ─────────────────────────────────────────────────────────

export function withValidation<T>(
  schema: z.ZodSchema<T>,
  handler: (req: NextRequest, ctx: { body: T }) => Promise<NextResponse>,
): (req: NextRequest) => Promise<NextResponse> {
  return async (req: NextRequest) => {
    let body: unknown;
    try {
      body = await req.json();
    } catch {
      return NextResponse.json({ error: "صيغة JSON غير صحيحة" }, { status: 400 });
    }
    try {
      const parsed = schema.parse(body);
      // CODE-005 FIX: Don't pass undefined as AuthPayload — handler should call requireAuth itself
      return handler(req, { body: parsed });
    } catch (err) {
      if (err instanceof ZodError) {
        return NextResponse.json(
          { error: err.issues[0]?.message || "مدخلات غير صالحة", details: err.issues },
          { status: 400 },
        );
      }
      return NextResponse.json({ error: "مدخلات غير صالحة" }, { status: 400 });
    }
  };
}

// ─── withAuth ───────────────────────────────────────────────────────────────

/**
 * Wrap a handler with auth + optional validation. The wrapper handles:
 *   - resolveAuth → 401 if not authenticated
 *   - parse JSON body
 *   - validate body against schema (if provided)
 *   - call handler with { user, body, params }
 *   - catch unhandled errors → 500 with structured response
 */
export function withAuth<T = unknown>(
  handler: AuthedHandler<T>,
  options: { schema?: z.ZodSchema<T> } = {},
): (req: NextRequest) => Promise<NextResponse> {
  return async (req: NextRequest) => {
    const authResult = await requireAuth(req);
    if (authResult instanceof NextResponse) return authResult;
    const user = authResult.user;

    let body: T | undefined;
    if (options.schema) {
      try {
        body = await req.json();
      } catch {
        return NextResponse.json({ error: "صيغة JSON غير صحيحة" }, { status: 400 });
      }
      try {
        body = options.schema.parse(body);
      } catch (err) {
        if (err instanceof ZodError) {
          return NextResponse.json(
            { error: err.issues[0]?.message || "مدخلات غير صالحة", details: err.issues },
            { status: 400 },
          );
        }
        return NextResponse.json({ error: "مدخلات غير صالحة" }, { status: 400 });
      }
    }

    try {
      return await handler(req, { user, body });
    } catch (err) {
      const detail = err instanceof Error ? err.message : String(err);
      logger.error("[withAuth] unhandled", { err: detail, route: req.url });
      return NextResponse.json({ error: "خطأ داخلي في الخادم" }, { status: 500 });
    }
  };
}

// ─── withAudit ──────────────────────────────────────────────────────────────

/**
 * Wrap a mutation handler with automatic audit logging.
 * Use after withAuth: const handler = withAudit(withAuth(inner, {schema}), {action: "...", entity: "..."})
 */
export function withAudit<T>(
  handler: AuthedHandler<T>,
  auditInfo: { action: string; entity: string },
): AuthedHandler<T> {
  return async (req, ctx) => {
    const response = await handler(req, ctx);
    // Only log if the request succeeded (2xx)
    if (response.status >= 200 && response.status < 300 && ctx.user) {
      await logAudit({
        userEmail: ctx.user.email,
        userUid: ctx.user.uid,
        action: auditInfo.action,
        entity: auditInfo.entity,
        companySlug: ctx.body && typeof ctx.body === "object" && "companySlug" in ctx.body
          ? String((ctx.body as Record<string, unknown>).companySlug)
          : null,
      });
    }
    return response;
  };
}

/**
 * observability.ts — GarfiX Observability Stack
 *
 * Provides OpenTelemetry-compatible metrics, tracing, and SLO definitions.
 * Built on the existing structured logger (logger.ts) foundation.
 *
 * Architecture:
 *   - MetricsRegistry: Application-level metrics (latency, throughput, errors)
 *   - TraceContext: Request-level distributed tracing with trace/span IDs
 *   - SLO definitions: Documented service level objectives with thresholds
 *   - MetricsExporter: OTLP-compatible JSON export format
 *
 * Key principles:
 *   - Zero external dependencies (pure TypeScript, no @opentelemetry/*)
 *   - Production-grade: redaction, sampling, cardinality limits
 *   - Compatible with OpenTelemetry OTLP/JSON for future collector integration
 *   - Lightweight: ~5KB, no Edge Runtime issues
 *
 * Usage:
 *   import { metrics, traceContext, SLOs } from "@/lib/observability";
 *   metrics.increment("api.request", { route: "/api/invoices", method: "GET" });
 *   metrics.histogram("api.latency", durationMs, { route: "/api/invoices" });
 *   const ctx = traceContext.start("invoice-creation");
 *   ctx.span("validate-input", ...);
 *   ctx.end();
 */

import { logger } from "./logger";

// ═══════════════════════════════════════════════════════════════════════════════
// SECTION 1: Metrics Registry
// ═══════════════════════════════════════════════════════════════════════════════

export interface MetricPoint {
  name: string;
  type: "counter" | "gauge" | "histogram";
  value: number;
  labels: Record<string, string>;
  timestamp: string; // ISO 8601
}

export interface HistogramBucket {
  le: number; // less-than-or-equal boundary
  count: number;
}

export interface HistogramSummary {
  count: number;
  sum: number;
  min: number;
  max: number;
  avg: number;
  p50: number;
  p90: number;
  p95: number;
  p99: number;
  buckets: HistogramBucket[];
}

export interface OTLPExportMetric {
  name: string;
  kind: string;
  unit: string;
  value: number;
  labels: Record<string, string | undefined>;
  timestamp: string;
  summary?: HistogramSummary;
}

export interface OTLPExport {
  resource: {
    attributes: Record<string, string>;
  };
  scopeMetrics: Array<{
    scope: { name: string; version: string };
    metrics: OTLPExportMetric[];
  }>;
  exportedAt: string;
}

const DEFAULT_HISTOGRAM_BUCKETS = [5, 10, 25, 50, 100, 250, 500, 1000, 2500, 5000];

// Cardinality limit — prevent label explosion from high-cardinality fields
const MAX_LABEL_CARDINALITY = 1000;
const labelValueSets: Record<string, Set<string>> = {};

function checkCardinality(labelName: string, labelValue: string): string {
  if (!labelValueSets[labelName]) labelValueSets[labelName] = new Set();
  const set = labelValueSets[labelName];
  if (set.size < MAX_LABEL_CARDINALITY) {
    set.add(labelValue);
    return labelValue;
  }
  if (set.has(labelValue)) return labelValue;
  // Cardinality exceeded — return "overflow" to prevent metric explosion
  return "cardinality_overflow";
}

type MetricStore = Map<string, { value: number; labels: Record<string, string>; updatedAt: string }>;
type HistogramStore = Map<string, { values: number[]; labels: Record<string, string>; updatedAt: string }>;

class MetricsRegistry {
  private counters: MetricStore = new Map();
  private gauges: MetricStore = new Map();
  private histograms: HistogramStore = new Map();
  private metricKey(name: string, labels: Record<string, string>): string {
    // Sort labels for deterministic key generation
    const sortedLabels = Object.entries(labels)
      .sort(([a], [b]) => a.localeCompare(b))
      .map(([k, v]) => `${k}=${v}`)
      .join(",");
    return `${name}|${sortedLabels}`;
  }

  /** Increment a counter metric by n */
  increment(name: string, labels: Record<string, string> = {}, n: number = 1): void {
    const safeLabels = this.sanitizeLabels(labels);
    const key = this.metricKey(name, safeLabels);
    const existing = this.counters.get(key);
    this.counters.set(key, {
      value: (existing?.value ?? 0) + n,
      labels: safeLabels,
      updatedAt: new Date().toISOString(),
    });
  }

  /** Set a gauge metric to a specific value */
  gauge(name: string, value: number, labels: Record<string, string> = {}): void {
    const safeLabels = this.sanitizeLabels(labels);
    const key = this.metricKey(name, safeLabels);
    this.gauges.set(key, { value, labels: safeLabels, updatedAt: new Date().toISOString() });
  }

  /** Record a histogram observation (latency, size, etc.) */
  histogram(name: string, value: number, labels: Record<string, string> = {}): void {
    const safeLabels = this.sanitizeLabels(labels);
    const key = this.metricKey(name, safeLabels);
    const existing = this.histograms.get(key);
    this.histograms.set(key, {
      values: [...(existing?.values ?? []), value],
      labels: safeLabels,
      updatedAt: new Date().toISOString(),
    });
  }

  /** Measure a function's execution time and record as histogram */
  async measure<T>(name: string, fn: () => Promise<T>, labels: Record<string, string> = {}): Promise<T> {
    const start = Date.now();
    try {
      const result = await fn();
      this.histogram(name, Date.now() - start, { ...labels, status: "success" });
      return result;
    } catch (err) {
      this.histogram(name, Date.now() - start, { ...labels, status: "error" });
      this.increment(`${name}.error`, labels);
      throw err;
    }
  }

  /** Sanitize labels — enforce cardinality limits and remove sensitive values */
  private sanitizeLabels(labels: Record<string, string>): Record<string, string> {
    const safe: Record<string, string> = {};
    for (const [key, value] of Object.entries(labels)) {
      // Skip sensitive labels (already handled by logger redaction, but double-check)
      if (key.toLowerCase().includes("token") || key.toLowerCase().includes("secret") || key.toLowerCase().includes("password")) {
        safe[key] = "[REDACTED]";
        continue;
      }
      // Enforce cardinality limits
      safe[key] = checkCardinality(key, String(value).substring(0, 64));
    }
    return safe;
  }

  /** Export all metrics as OTLP-compatible JSON */
  exportOTLP(): OTLPExport {
    const now = new Date().toISOString();

    const counterMetrics = Array.from(this.counters.entries()).map(([key, data]) => ({
      name: data.labels._name || key.split("|")[0],
      kind: "COUNTER",
      unit: "1",
      value: data.value,
      labels: { ...data.labels, _name: undefined },
      timestamp: data.updatedAt,
    }));

    const gaugeMetrics = Array.from(this.gauges.entries()).map(([key, data]) => ({
      name: data.labels._name || key.split("|")[0],
      kind: "GAUGE",
      unit: "1",
      value: data.value,
      labels: { ...data.labels, _name: undefined },
      timestamp: data.updatedAt,
    }));

    const histogramMetrics = Array.from(this.histograms.entries()).map(([key, data]) => ({
      name: data.labels._name || key.split("|")[0],
      kind: "HISTOGRAM",
      unit: "ms",
      summary: this.computeHistogramSummary(data.values),
      labels: { ...data.labels, _name: undefined },
      timestamp: data.updatedAt,
    }));

    return {
      resource: {
        attributes: {
          "service.name": getOtelServiceName(),
          "service.version": "12.1.0",
          "service.instance.id": process.env.HOSTNAME || "local",
          "telemetry.sdk.name": "garfix-observability",
          "telemetry.sdk.version": "1.0.0",
        },
      },
      scopeMetrics: [
        {
          scope: { name: "garfix.metrics", version: "1.0.0" },
          metrics: [...counterMetrics, ...gaugeMetrics, ...histogramMetrics] as OTLPExportMetric[],
        },
      ],
      exportedAt: now,
    };
  }

  /** Compute histogram summary with percentile calculations */
  private computeHistogramSummary(values: number[]): HistogramSummary {
    if (values.length === 0) {
      return {
        count: 0, sum: 0, min: 0, max: 0, avg: 0,
        p50: 0, p90: 0, p95: 0, p99: 0,
        buckets: DEFAULT_HISTOGRAM_BUCKETS.map((le) => ({ le, count: 0 })),
      };
    }

    const sorted = [...values].sort((a, b) => a - b);
    const sum = values.reduce((a, b) => a + b, 0);
    const count = values.length;

    const percentile = (p: number): number => {
      const idx = Math.ceil((p / 100) * count) - 1;
      return sorted[Math.max(0, Math.min(idx, count - 1))];
    };

    const buckets = DEFAULT_HISTOGRAM_BUCKETS.map((le) => ({
      le,
      count: sorted.filter((v) => v <= le).length,
    }));

    return {
      count,
      sum,
      min: sorted[0],
      max: sorted[count - 1],
      avg: sum / count,
      p50: percentile(50),
      p90: percentile(90),
      p95: percentile(95),
      p99: percentile(99),
      buckets,
    };
  }

  /** Get all metric points (flat list for simple exporters) */
  getAllPoints(): MetricPoint[] {
    const points: MetricPoint[] = [];
    const now = new Date().toISOString();

    for (const [, data] of this.counters) {
      points.push({ name: data.labels._name || "unknown", type: "counter", value: data.value, labels: data.labels, timestamp: now });
    }
    for (const [, data] of this.gauges) {
      points.push({ name: data.labels._name || "unknown", type: "gauge", value: data.value, labels: data.labels, timestamp: now });
    }
    return points;
  }

  /** Reset all metrics (useful for testing or periodic flush) */
  reset(): void {
    this.counters.clear();
    this.gauges.clear();
    this.histograms.clear();
  }

  /** Get metric counts for monitoring dashboard */
  stats(): { counters: number; gauges: number; histograms: number; totalObservations: number } {
    const histogramObservations = Array.from(this.histograms.values()).reduce((sum, h) => sum + h.values.length, 0);
    return {
      counters: this.counters.size,
      gauges: this.gauges.size,
      histograms: this.histograms.size,
      totalObservations: this.counters.size + this.gauges.size + histogramObservations,
    };
  }
}

export const metrics = new MetricsRegistry();

