  /** No access */
  none = 0,
  /** Read-only access */
  read = 1,
  /** Create and edit */
  write = 2,
  /** Approve / authorize */
  approve = 3,
  /** Full control (admin) */
  admin = 4,
  /** Delete records (special action) */
  delete = 10,
