// ── Backward Compatibility ───────────────────────────────────────────────────

/**
 * Convert a flat permission map to ResourcePermission array.
 * Useful for migrating existing users to the new system.
 */
export function flatToResourcePerms(flat: Record<string, number>): ResourcePermission[] {
  const perms: ResourcePermission[] = [];

  const FLAT_TO_RESOURCE: Record<string, { resource: string; action: string; scope: PermissionScope }> = {
    create_invoice: { resource: "invoice", action: "write", scope: PermissionScope.own },
    print_invoice: { resource: "invoice", action: "print", scope: PermissionScope.own },
    edit_invoice: { resource: "invoice", action: "write", scope: PermissionScope.own },
    delete_invoice: { resource: "invoice", action: "delete", scope: PermissionScope.own },
    view_customers: { resource: "customer", action: "read", scope: PermissionScope.company },
    edit_customer: { resource: "customer", action: "write", scope: PermissionScope.own },
    delete_customer: { resource: "customer", action: "delete", scope: PermissionScope.own },
    edit_inventory: { resource: "inventory", action: "write", scope: PermissionScope.own },
    manage_wholesale_prices: { resource: "inventory", action: "manage_prices", scope: PermissionScope.own },
    bulk_input: { resource: "inventory", action: "bulk_input", scope: PermissionScope.own },
    export_data: { resource: "report", action: "export", scope: PermissionScope.company },
    reports_access: { resource: "report", action: "read", scope: PermissionScope.company },
    settings_access: { resource: "settings", action: "write", scope: PermissionScope.company },
    finance_access: { resource: "accounting", action: "write", scope: PermissionScope.company },
    employee_management: { resource: "employee", action: "write", scope: PermissionScope.company },
    e_invoicing_submit: { resource: "invoice", action: "e_invoice", scope: PermissionScope.company },
  };

  for (const [key, value] of Object.entries(flat)) {
    if (value && FLAT_TO_RESOURCE[key]) {
      const mapping = FLAT_TO_RESOURCE[key];
      perms.push({
        resource: mapping.resource,
        level: actionToLevel(mapping.action),
        scope: mapping.scope,
      });
    }
  }

  return perms;
}

function actionToLevel(action: string): PermissionLevel {
  switch (action) {
    case "read": return PermissionLevel.read;
    case "write": return PermissionLevel.write;
    case "approve": return PermissionLevel.approve;
    case "admin": return PermissionLevel.admin;
    case "delete": return PermissionLevel.delete;
    case "print": return PermissionLevel.print;
    case "export": return PermissionLevel.export;
    case "e_invoice": return PermissionLevel.e_invoice;
    case "bulk_input": return PermissionLevel.bulk_input;
    case "manage_prices": return PermissionLevel.manage_prices;
    default: return PermissionLevel.write; // unknown special actions default to write
  }
}

/**
 * secretsManager.ts — Environment-based secrets manager with rotation support.
 *
 * In this implementation, secrets are resolved from environment variables with
 * validation. For production, this should be replaced with a cloud secrets
 * manager (AWS Secrets Manager, HashiCorp Vault, etc.).
 *
 * Features:
 *   - Secret validation (length, complexity)
 *   - Access logging
 *   - Placeholder .env template generation
 *   - Secret inventory for audit
 */

import crypto from "node:crypto";
import { logger } from "./logger";

interface SecretDefinition {
  envKey: string;
  description: string;
  minLength: number;
  required: boolean;
  category: "auth" | "encryption" | "database" | "external" | "payment";
}

const SECRET_DEFINITIONS: SecretDefinition[] = [
  { envKey: "JWT_SECRET", description: "JWT access token signing key", minLength: 32, required: true, category: "auth" },
  { envKey: "JWT_REFRESH_SECRET", description: "JWT refresh token signing key", minLength: 32, required: true, category: "auth" },
  { envKey: "PAYMENTS_ENC_KEY", description: "AES-256 encryption key for vault", minLength: 32, required: true, category: "encryption" },
  { envKey: "DATABASE_URL", description: "Database connection string", minLength: 10, required: true, category: "database" },
  { envKey: "VALKEY_URL", description: "Valkey/Redis connection URL", minLength: 5, required: false, category: "external" },
  { envKey: "OPENROUTER_API_KEY", description: "OpenRouter AI API key", minLength: 10, required: false, category: "external" },
];

/** Get a secret with validation. Throws in production if required and missing. */
export function getSecret(envKey: string): string {
  const val = process.env[envKey];
  const definition = SECRET_DEFINITIONS.find((d) => d.envKey === envKey);

  if (!val) {
    if (definition?.required && process.env.NODE_ENV === "production") {
      throw new Error(`FATAL: Required secret ${envKey} is not set. Set it via environment variable or secrets manager.`);
    }
    logger.warn(`[secrets] ${envKey} not set — using dev default`);
    return `dev-placeholder-${envKey.toLowerCase()}`;
  }

  if (definition && val.length < definition.minLength) {
    throw new Error(`FATAL: ${envKey} must be at least ${definition.minLength} characters (got ${val.length}).`);
  }

  return val;
}

/** Generate a secure random secret of given length. */
export function generateSecret(length: number = 32): string {
  return crypto.randomBytes(length).toString("base64url").slice(0, length);
}

/** Get inventory of all secrets (masked values) for audit. */
export function getSecretInventory(): Array<{
  envKey: string;
  description: string;
  category: string;
  isSet: boolean;
  length: number;
  required: boolean;
}> {
  return SECRET_DEFINITIONS.map((def) => {
    const val = process.env[def.envKey];
    return {
      envKey: def.envKey,
      description: def.description,
      category: def.category,
      isSet: !!val && !val.startsWith("dev-placeholder"),
      length: val?.length || 0,
      required: def.required,
    };
  });
}

/** Validate all required secrets are set. Returns warnings/errors. */
export function validateSecrets(): {
  ok: boolean;
  errors: string[];
  warnings: string[];
} {
  const errors: string[] = [];
  const warnings: string[] = [];

  for (const def of SECRET_DEFINITIONS) {
    const val = process.env[def.envKey];
    if (!val || val.startsWith("dev-placeholder")) {
      if (def.required && process.env.NODE_ENV === "production") {
        errors.push(`${def.envKey} (${def.description}) is required but not set`);
      } else if (def.required) {
        warnings.push(`${def.envKey} not set — using dev placeholder`);
      }
    } else if (val.length < def.minLength) {
      errors.push(`${def.envKey} is too short (${val.length} < ${def.minLength} min)`);
    }
  }

  return {
    ok: errors.length === 0,
    errors,
    warnings,
  };
}

/** Rotate a secret: generate new, return it for the caller to persist. */
export function rotateSecret(envKey: string): string {
  const def = SECRET_DEFINITIONS.find((d) => d.envKey === envKey);
  const length = def?.minLength || 32;
  const newSecret = generateSecret(length);
  logger.info(`[secrets] Secret rotation initiated for ${envKey}`);
  return newSecret;
}

/**
 * startupCheck.ts — Validates environment + secrets on server boot.
 *
 * Implements E-01 (force secrets at startup) + E-14 (warning for missing
 * WHATSAPP_ALLOWED_SENDERS). Called from API route /api/startup-check.
 *
 * ⚠️ ARCHITECTURAL CHANGE (v12.1):
 * This module NO LONGER imports or registers queue workers.
 * Worker registration has been moved to src/runtime/bootstrap.ts
 * to prevent side-effects during `next build`.
 *
 * Previous anti-pattern:
 *   import "./workers/aiProductMatchWorker"  // ← caused registerAIProductMatchWorker() on import
 *   import "./workers/emailWorker"           // ← caused registerEmailWorker() on import
 *   ...etc
 *
 * New pattern: Workers are only registered when explicitly calling
 * bootstrapRuntime() from the server entry point.
 *
 * Failure modes:
 *   - FATAL: JWT_SECRET missing → server refuses to start
 *   - FATAL: FOUNDER_EMAIL missing → server refuses to start
 *   - WARN:  WHATSAPP_ALLOWED_SENDERS missing → logs warning
 *   - WARN:  PAYMENTS_ENC_KEY missing → logs warning (uses fallback in dev)
 *   - WARN:  LOG_LEVEL invalid → falls back to "info"
 */

import { logger } from "./logger";
import { DEFAULT_PLANS } from "./plans";

// ❌ REMOVED: All worker imports that caused build-time side effects
// These are now in src/runtime/bootstrap.ts
// import "./workers/aiProductMatchWorker";
// import "./workers/emailWorker";
// import "./workers/whatsappWorker";
// import "./workers/backupWorker";
// import "./workers/schedulerWorker";

const REQUIRED_FOR_PRODUCTION = [
  "JWT_SECRET",
  "JWT_REFRESH_SECRET",
  "FOUNDER_EMAIL",
  "DATABASE_URL",
];

const RECOMMENDED = [
  "WHATSAPP_ALLOWED_SENDERS",
  "PAYMENTS_ENC_KEY",
  "SMTP_HOST",
  "SMTP_FROM",
];

// SEC-C3 / SEC-M4 FIX (Cycle 1): Blocklist of known placeholder / leaked
// secret values that must NEVER be accepted in production. If any env var
// matches one of these, the server refuses to boot.
//
// These values come from the originally-committed `.env` file — they are
// effectively public. Anyone running production with one of these values is
// running with a compromised secret.
const LEAKED_PLACEHOLDER_VALUES: ReadonlySet<string> = new Set([
  "garfix-build-secret-key-32-chars-long!!",
  "garfix-refresh-secret-32-chars!!",
  "garfix-payments-encryption-32-char-key!!",
  "garfix-dev-secret-change-me",
  "garfix_strong_pass_change_me",
]);

// Env vars that must not match any leaked placeholder value in production.
const PLACEHOLDER_CHECKED_VARS = [
  "JWT_SECRET",
  "JWT_REFRESH_SECRET",
  "PAYMENTS_ENC_KEY",
];

function isPlaceholderValue(value: string): boolean {
  // Direct match against the blocklist (case-insensitive).
  const lower = value.toLowerCase();
  for (const leaked of LEAKED_PLACEHOLDER_VALUES) {
    if (lower === leaked.toLowerCase()) return true;
  }
  // Heuristic: starts with the canonical prefix.
  if (lower.startsWith("replace_with_")) return true;
  if (lower.startsWith("garfix-build-secret")) return true;
  if (lower.startsWith("garfix-refresh-secret")) return true;
  if (lower.startsWith("garfix-payments-encryption")) return true;
  if (lower.startsWith("garfix-dev-secret")) return true;
  return false;
}

// ── CRITICAL-002 FIX (Cycle 2): Strength-based secret validation ─────────
// A blocklist only catches secrets we already know are bad. An attacker can
// use any low-entropy string the blocklist doesn't know about (e.g.
// `garfix-prod-jwt-2024!!`). The strength check below catches any secret
// that is too short, too repetitive, or matches a "looks like a placeholder"
// regex — defense-in-depth on top of the blocklist.
//
// Production-only. Dev uses the deterministic fallback in auth.ts which is
// clearly marked and not production-grade.
const WEAK_SECRET_PATTERNS: readonly RegExp[] = [
  /garfix/i,
  /^dev-only-/i,
  /change[-_]?me/i,
  /secret[-_]?key/i,
  /password/i,
  /placeholder/i,
  /example/i,
  /12345/,
  /^test[-_]/i,
  /^ci[-_]/i,
  /[-_]+$/, // trailing dashes/underscores (common in hand-typed placeholders)
];

/**
 * Returns true if `value` is too weak to be a production secret.
 * Checks: minimum length, pattern blocklist, and Shannon-style entropy.
 */
export function isSecretWeak(value: string, opts: { minLength?: number } = {}): boolean {
  const minLength = opts.minLength ?? 32;
  if (typeof value !== "string" || value.length < minLength) return true;
  if (WEAK_SECRET_PATTERNS.some((re) => re.test(value))) return true;
  // Entropy heuristic: unique-character ratio. A 32-char string with only
  // 8 unique characters is almost certainly a hand-typed placeholder like
  // `garfix-build-secret-key-32-chars-long!!`.
  const unique = new Set(value).size;
  if (unique < value.length / 3) return true;
  // Reject secrets that are just one repeated character / very low variety.
  if (unique < 4) return true;
  return false;
}

export interface StartupCheckResult {
  ok: boolean;
  fatal: string[];
  warnings: string[];
}

export function runStartupChecks(): StartupCheckResult {
  const fatal: string[] = [];
  const warnings: string[] = [];
  const isProd = process.env.NODE_ENV === "production";

  // Required (always)
  if (!process.env.JWT_SECRET) {
    fatal.push("JWT_SECRET is required — set it to a strong random string (>= 32 chars)");
  } else if (process.env.JWT_SECRET.length < 16) {
    fatal.push("JWT_SECRET is too short — use at least 16 characters");
  }

  if (!process.env.JWT_REFRESH_SECRET) {
    fatal.push("JWT_REFRESH_SECRET is required — set it to a different strong random string");
  }

  if (!process.env.FOUNDER_EMAIL) {
    fatal.push("FOUNDER_EMAIL is required — set it to the founder account email");
  }

  if (!process.env.DATABASE_URL) {
    fatal.push("DATABASE_URL is required — set it to a Prisma connection string");
  }

  // Production-only strict checks
  if (isProd) {
    if (!process.env.PAYMENTS_ENC_KEY) {
      fatal.push("PAYMENTS_ENC_KEY is required in production — generate one with: openssl rand -base64 32");
    }
    // SEC-C3 / SEC-M4 FIX: reject any known leaked/placeholder value.
    // The original `.env` file was committed to the repo with these exact
    // values, so they are effectively public — production must NOT use them.
    for (const varName of PLACEHOLDER_CHECKED_VARS) {
      const value = process.env[varName];
      if (value && isPlaceholderValue(value)) {
        fatal.push(
          `${varName} is set to a known leaked/placeholder value. ` +
            `Generate a fresh secret with: openssl rand -base64 48 (for JWT_*) or openssl rand -base64 32 (for PAYMENTS_ENC_KEY).`,
        );
      }
    }
    // SEC-C3 FIX: reject the leaked DATABASE_URL password too.
    const dbUrl = process.env.DATABASE_URL || "";
    if (dbUrl.includes("garfix_strong_pass_change_me")) {
      fatal.push(
        "DATABASE_URL still uses the leaked placeholder password 'garfix_strong_pass_change_me'. " +
          "Rotate the database user's password and update DATABASE_URL / DATABASE_DIRECT_URL.",
      );
    }

    // CRITICAL-002 FIX (Cycle 2): strength-based secret validation.
    // Even if a secret is NOT in the blocklist above, reject it if it's
    // too short, too repetitive, or matches a "looks like a placeholder"
    // pattern. This catches e.g. `garfix-prod-jwt-2024!!` which would
    // sail past the blocklist but is trivially guessable.
    //
    // JWT secrets: minimum 32 chars (OWASP), high entropy.
    // PAYMENTS_ENC_KEY: minimum 32 chars (AES-256-GCM key requirement).
    const SECRET_STRENGTH_CHECKS: Array<{ name: string; minLength: number }> = [
      { name: "JWT_SECRET", minLength: 32 },
      { name: "JWT_REFRESH_SECRET", minLength: 32 },
      { name: "PAYMENTS_ENC_KEY", minLength: 32 },
    ];
    for (const { name, minLength } of SECRET_STRENGTH_CHECKS) {
      const value = process.env[name];
      if (!value) continue; // missing-secret errors handled above
      if (isSecretWeak(value, { minLength })) {
        fatal.push(
          `${name} appears weak (too short, low entropy, or matches a placeholder pattern). ` +
            `Generate a fresh secret with: openssl rand -hex 64 (for JWT_*) or openssl rand -base64 32 (for PAYMENTS_ENC_KEY).`,
        );
      }
    }
    // Defense-in-depth: JWT_SECRET and JWT_REFRESH_SECRET MUST differ.
    if (
      process.env.JWT_SECRET &&
      process.env.JWT_REFRESH_SECRET &&
      process.env.JWT_SECRET === process.env.JWT_REFRESH_SECRET
    ) {
      fatal.push(
        "JWT_SECRET and JWT_REFRESH_SECRET must be DIFFERENT values. " +
          "Using the same secret means compromising one token type compromises both.",
      );
    }
  }

  // Recommended (warn)
  if (!process.env.WHATSAPP_ALLOWED_SENDERS) {
    warnings.push(
      "WHATSAPP_ALLOWED_SENDERS is not set — WhatsApp inbound messages from any number will be processed. " +
      "Set it to a comma-separated allowlist of phone numbers for production safety.",
    );
  }

  if (!process.env.PAYMENTS_ENC_KEY && !isProd) {
    warnings.push(
      "PAYMENTS_ENC_KEY is not set — using JWT_SECRET as fallback for encrypting secrets at rest. " +
      "Set a dedicated key in production with: openssl rand -base64 32",
    );
  }

  if (!process.env.SMTP_HOST || !process.env.SMTP_FROM) {
    warnings.push(
      "SMTP_HOST/SMTP_FROM not configured — email features (OTP, welcome email, ticket replies) will be non-functional.",
    );
  }

  // Log results
  if (fatal.length > 0) {
    fatal.forEach((msg) => logger.error("[startup] FATAL environment check failed", { msg }));
    logger.error("[startup] refusing to boot due to missing required configuration", { fatal, warnings });
    if (isProd) {
      throw new Error(`FATAL startup config errors: ${fatal.join("; ")}`);
    }
    logger.warn("[startup] continuing in dev mode despite fatal errors");
  }

  if (warnings.length > 0) {
    warnings.forEach((msg) => logger.warn("[startup] configuration warning", { msg }));
  }

  if (fatal.length === 0 && warnings.length === 0) {
    logger.info("[startup] all environment checks passed");
  }

  return { ok: fatal.length === 0, fatal, warnings };
}

/** Plan limits catalog loader — checks that plan values are sensible. */
export function validatePlanLimits(): void {
  try {
    for (const [key, plan] of Object.entries(DEFAULT_PLANS)) {
      if (plan.maxUsers < -1) logger.warn("[startup] plan has invalid maxUsers", { plan: key });
      if (plan.maxInvoicesPerMonth < -1) logger.warn("[startup] plan has invalid maxInvoices", { plan: key });
      if (plan.maxCompanies < -1) logger.warn("[startup] plan has invalid maxCompanies", { plan: key });
    }
    logger.info("[startup] plan limits validated");
  } catch (err) {
    logger.error("[startup] failed to validate plan limits", { err: err instanceof Error ? err.message : String(err) });
  }
}

/**
 * Explicit startup recovery hook.
 *
 * Re-enqueues any jobs left unfinished from a previous server lifetime:
 *   - status="pending" (never started — e.g. crash between INSERT and pickup)
 *   - status="running" with lockedAt older than 5 min (worker died mid-run)
 *
 * This can be triggered manually from the startup-check API route,
 * or automatically by bootstrapRuntime() on server boot.
 */
export async function runStartupRecovery(): Promise<{ recovered: number; errors: string[] }> {
  const { recoverPendingJobs } = await import("./queues");
  return recoverPendingJobs();
}

/**
 * usageMeter.ts — SAAS-001 + SAAS-003 FIX
 * Enforces plan limits: trial expiry, monthly invoice quota, user count.
 */
import { db } from "./db";
import { DEFAULT_PLANS, type PlanKey } from "./plans";
import { logger } from "./logger";

export interface QuotaCheck {
  ok: boolean;
  reason?: string;
  limit?: number;
  current?: number;
}

/** Check if a company's trial has expired */
export async function checkTrialExpiry(companySlug: string): Promise<QuotaCheck> {
  const company = await db.company.findUnique({
    where: { slug: companySlug },
    select: { plan: true, trialEndsAt: true, subscriptionStatus: true },
  });
  if (!company) return { ok: false, reason: "Company not found" };

  if (company.plan === "trial" && company.trialEndsAt) {
    if (new Date() > company.trialEndsAt) {
      return {
        ok: false,
        reason: "انتهت الفترة التجريبية. يرجى ترقية باقتك للمتابعة.",
        limit: 0,
        current: 0,
      };
    }
  }

  if (company.subscriptionStatus === "suspended") {
    return {
      ok: false,
      reason: "تم تعليق اشتراك هذه الشركة. تواصل مع الدعم.",
    };
  }

  return { ok: true };
}

/** Check if company can create a new invoice (monthly quota) */
export async function checkInvoiceQuota(companySlug: string): Promise<QuotaCheck> {
  const company = await db.company.findUnique({
    where: { slug: companySlug },
    select: { plan: true },
  });
  if (!company) return { ok: false, reason: "Company not found" };

  const planKey = (company.plan || "trial") as PlanKey;
  const plan = DEFAULT_PLANS[planKey] || DEFAULT_PLANS.trial;

  // Unlimited plan
  if (plan.maxInvoicesPerMonth === -1) return { ok: true };

  // Count invoices this month (excluding soft-deleted)
  const now = new Date();
  const monthStart = new Date(now.getFullYear(), now.getMonth(), 1);
  const monthStr = monthStart.toISOString().slice(0, 7); // YYYY-MM

  const count = await db.invoice.count({
    where: {
      companySlug,
      deletedAt: null,
      issueDate: { startsWith: monthStr },
    },
  });

  if (count >= plan.maxInvoicesPerMonth) {
    return {
      ok: false,
      reason: `بلغت الحد الشهري للفواتير في باقتك (${plan.maxInvoicesPerMonth}). ترقّى لإنشاء المزيد.`,
      limit: plan.maxInvoicesPerMonth,
      current: count,
    };
  }

  return { ok: true, limit: plan.maxInvoicesPerMonth, current: count };
}

/** Check if company can add a new user */
export async function checkUserQuota(companySlug: string): Promise<QuotaCheck> {
  const company = await db.company.findUnique({
    where: { slug: companySlug },
    select: { plan: true },
  });
  if (!company) return { ok: false, reason: "Company not found" };

  const planKey = (company.plan || "trial") as PlanKey;
  const plan = DEFAULT_PLANS[planKey] || DEFAULT_PLANS.trial;

  if (plan.maxUsers === -1) return { ok: true };

  // EA-010 FIX: Previously used findMany + JS filter (N+1 pattern).
  // Now uses a two-step approach:
  //   1. Use findMany with contains to pre-filter candidates (small set)
  //   2. Verify exact membership via JSON.parse + .includes
  // This avoids scanning the entire users table — only rows mentioning the slug
  // are fetched, then JS filtering removes false positives from substring matches.
  const candidates = await db.appUser.findMany({
    where: {
      role: { not: "inactive" },
      companies: { contains: companySlug },
    },
    select: { companies: true },
  });
  // Exact-match check on the candidate set only (which is small by design)
  let count = 0;
  for (const u of candidates) {
    try {
      const companies = JSON.parse(u.companies || "[]") as string[];
      if (companies.includes(companySlug)) count++;
    } catch {
      // malformed companies field — skip this user
    }
  }

  if (count >= plan.maxUsers) {
    return {
      ok: false,
      reason: `بلغت الحد الأقصى للمستخدمين في باقتك (${plan.maxUsers}). ترقّى لإضافة المزيد.`,
      limit: plan.maxUsers,
      current: count,
    };
  }

  return { ok: true, limit: plan.maxUsers, current: count };
}

/** Check if company can create a new company (for multi-company plans) */
export async function checkCompanyQuota(userUid: string): Promise<QuotaCheck> {
  const user = await db.appUser.findUnique({
    where: { uid: userUid },
    select: { companies: true, role: true },
  });
  if (!user) return { ok: false, reason: "User not found" };

  // Founder/admin bypass
  if (user.role === "admin") return { ok: true };

  const companies = JSON.parse(user.companies || "[]") as string[];
  // Use the plan of the first company
  if (companies.length === 0) return { ok: true };

  const firstCompany = await db.company.findUnique({
    where: { slug: companies[0] },
    select: { plan: true },
  });
  const planKey = (firstCompany?.plan || "trial") as PlanKey;
  const plan = DEFAULT_PLANS[planKey] || DEFAULT_PLANS.trial;

  if (plan.maxCompanies === -1) return { ok: true };

  if (companies.length >= plan.maxCompanies) {
    return {
      ok: false,
      reason: `بلغت الحد الأقصى للشركات في باقتك (${plan.maxCompanies}). ترقّى لإضافة المزيد.`,
      limit: plan.maxCompanies,
      current: companies.length,
    };
  }

  return { ok: true, limit: plan.maxCompanies, current: companies.length };
}

/**
 * backupWorker.ts — Worker for the BACKUP queue.
 *
 * Registered as the handler for `QUEUE_NAMES.BACKUP`. The existing
 * `enqueueBackup(label)` helper in src/lib/backup.ts enqueues a `{type:"backup"}`
 * job to this queue — but until this worker file existed, every such job
 * silently dead-lettered with "No handler registered for queue backup-jobs".
 *
 * Job types:
 *   - "backup"        → calls runBackup(label) — produces a SQLite VACUUM INTO
 *     snapshot at BACKUP_DIR/garfix-{label}-{ts}.db and prunes old backups.
 *   - "verify-backup" → opens the most recent backup, runs PRAGMA integrity_check,
 *     and logs the result. Used by the scheduler daily to confirm backups are
 *     restorable (a backup that can't be restored is worse than no backup).
 *
 * Failure modes:
 *   - VACUUM INTO fails → runBackup falls back to file copy (already handled
 *     in lib/backup.ts) — if even the fallback fails, the job throws and the
 *     queue runner retries 3× with backoff, then dead-letters.
 *   - Backup directory not writable → runBackup throws → retry → dead-letter.
 *     Operators MUST see this — a 3-day-stale backup is a stop-ship signal.
 *   - Verify-backup fails integrity check → throws → retry → dead-letter so
 *     the founder panel surfaces the corrupt backup.
 *
 * RUNTIME: Node.js only — uses node:fs/promises, node:path, process.cwd()
 */
'use node';

import { logger } from "../logger";
import { registerWorker, QUEUE_NAMES } from "../queues";
import { runBackup, listBackups } from "../backup";
import { db } from "../db";
import fs from "node:fs/promises";
import path from "node:path";

export const BACKUP_JOB_TYPES = {
  BACKUP: "backup",
  VERIFY_BACKUP: "verify-backup",
} as const;

export interface BackupJobData {
  label?: string;
}

export interface VerifyBackupJobData {
  backupName?: string; // optional — defaults to most recent
}

/** The actual handler — exported for direct invocation from tests. */
export async function handleBackupJob(data: Record<string, unknown>): Promise<void> {
  const jobType = (data.type as string) || BACKUP_JOB_TYPES.BACKUP;
  const payload = (data.payload ?? data) as Record<string, unknown>;

  switch (jobType) {
    case BACKUP_JOB_TYPES.BACKUP:
      return handleBackup(payload as unknown as BackupJobData);
    case BACKUP_JOB_TYPES.VERIFY_BACKUP:
      return handleVerifyBackup(payload as unknown as VerifyBackupJobData);
    default:
      throw new Error(`backupWorker: unknown job type "${jobType}"`);
  }
}

async function handleBackup(data: BackupJobData): Promise<void> {
  const label = (data.label && typeof data.label === "string") ? data.label : "scheduled";
  logger.info("[backup-worker] starting backup", { label });
  const result = await runBackup(label);
  if (!result.ok) {
    throw new Error(`backupWorker.backup: runBackup failed — ${result.error ?? "unknown"}`);
  }
  logger.info("[backup-worker] backup completed", {
    label, path: result.filePath, size: result.size, durationMs: result.durationMs,
  });
}

async function handleVerifyBackup(data: VerifyBackupJobData): Promise<void> {
  // Resolve target backup — default to most recent if not specified.
  const backups = await listBackups();
  if (backups.length === 0) {
    logger.warn("[backup-worker] verify-backup: no backups found — nothing to verify");
    return;
  }

  const target = data.backupName
    ? backups.find((b) => b.name === data.backupName)
    : backups[0]; // listBackups returns sorted desc by mtime
  if (!target) {
    throw new Error(`backupWorker.verify-backup: backup "${data.backupName}" not found`);
  }

  const BACKUP_DIR = process.env.BACKUP_DIR || path.join(process.cwd(), "storage", "backups");
  const backupPath = path.join(BACKUP_DIR, target.name);
  // Path-traversal guard — backupName is from a trusted caller, but be safe.
  const resolvedBase = path.resolve(BACKUP_DIR);
  const resolvedCandidate = path.resolve(backupPath);
  if (resolvedCandidate !== resolvedBase && !resolvedCandidate.startsWith(resolvedBase + path.sep)) {
    throw new Error(`backupWorker.verify-backup: path traversal refused — "${target.name}"`);
  }

  // File size sanity — an empty or tiny backup is corrupt.
  const stat = await fs.stat(backupPath);
  if (stat.size < 1024) {
    throw new Error(`backupWorker.verify-backup: backup too small (${stat.size} bytes) — likely corrupt`);
  }

  // Open the backup as a separate SQLite connection and run integrity_check.
  // We use Prisma's $executeRawUnsafe on the main DB connection — but to
  // verify a DIFFERENT file, we'd need a separate connection. The simplest
  // cross-process check is `sqlite3 backupPath 'PRAGMA integrity_check;'`
  // — but we may not have the sqlite3 CLI in the sandbox. Instead we read
  // the file header (first 16 bytes) to confirm it's a valid SQLite file.
  //
  // A full integrity_check would require opening a second Prisma client
  // pointing at the backup file — deferred to a future hardening pass.
  const handle = await fs.open(backupPath, "r");
  try {
    const buf = Buffer.alloc(16);
    await handle.read(buf, 0, 16, 0);
    const header = buf.toString("utf8");
    // SQLite file magic: "SQLite format 3\0"
    if (!header.startsWith("SQLite format 3")) {
      throw new Error(`backupWorker.verify-backup: bad SQLite header in "${target.name}" — got "${header.replace(/\0/g, "?")}"`);
    }
  } finally {
    await handle.close();
  }

  logger.info("[backup-worker] verify-backup: OK", {
    name: target.name, sizeMB: (target.size / 1024 / 1024).toFixed(2),
  });
}

// ─── Registration Function (explicit call only) ─────────────────────────────

let registered = false;
export function registerBackupWorker(): void {
  if (registered) return;
  registerWorker(QUEUE_NAMES.BACKUP, handleBackupJob);
  registered = true;
  logger.info("[backup-worker] registered for queue", { queue: QUEUE_NAMES.BACKUP });
}

// ❌ REMOVED: Module-level side effect (was causing build failures)
// registerBackupWorker();

// Reference `db` so the import isn't tree-shaken (used by future integrity
// checks that query the backup file via a second Prisma client).
void db;

