            <table className="w-full border-collapse">
              <thead><tr className="border-b border-border bg-muted">
                <th scope="col" className={thStyle}>الموظف</th>
                <th scope="col" className={cn(thStyle, "text-end")}>الأساسي</th>
                <th scope="col" className={cn(thStyle, "text-end")}>البدلات</th>
                <th scope="col" className={cn(thStyle, "text-end")}>التأمينات</th>
                <th scope="col" className={cn(thStyle, "text-end")}>الاستقطاعات</th>
                <th scope="col" className={cn(thStyle, "text-end")}>الصافي</th>
                <th scope="col" className={thStyle}>العملة</th>
