                    <td className={tdStyle}><span className={cn("py-0.5 px-2.5 rounded-[12px] text-[11px] font-bold", c.compliant ? "bg-emerald-500/15 text-emerald-500" : "bg-red-500/15 text-red-500")}>{c.compliant ? "متوافق ✓" : "غير متوافق ✗"}</span></td>
                  </tr>
                ))}</tbody>
              </table>
            </div>
          </div>
        ))
      )}
    </div>
  );
}

