  const [lcs, setLcs] = useState<LetterOfCredit[]>([]);
  const [fxEntries, setFxEntries] = useState<FXRevaluation[]>([]);
  const [loading, setLoading] = useState(true);
  const [showLcForm, setShowLcForm] = useState(false);
  const [showFxForm, setShowFxForm] = useState(false);

  /* LC form state */
  const [lcNumber, setLcNumber] = useState("");
  const [lcSupplier, setLcSupplier] = useState("");
  const [lcBank, setLcBank] = useState("");
  const [lcAmount, setLcAmount] = useState("");
  const [lcCurrency, setLcCurrency] = useState("KWD");
  const [lcIssueDate, setLcIssueDate] = useState("");
  const [lcExpiryDate, setLcExpiryDate] = useState("");

  /* FX form state */
  const [fxFrom, setFxFrom] = useState("USD");
  const [fxTo, setFxTo] = useState("KWD");
  const [fxRate, setFxRate] = useState("");
  const [fxPeriod, setFxPeriod] = useState("Q1");

  const slug = activeCompany ? `companySlug=${encodeURIComponent(activeCompany.slug)}` : "";

  const loadLcs = useCallback(async () => {
    if (!activeCompany) { setLoading(false); return; }
    setLoading(true);
    try {
      const res = await authedFetch(`/api/accounting/letters-of-credit?${slug}`);
      if (!res.ok) { const e = await res.json().catch(() => ({})); throw new Error(e.error || `فشل تحميل الاعتمادات (${res.status})`); }
      const d = await res.json();
      setLcs(d.lettersOfCredit || []);
    } catch (err) {
      toast.error(err instanceof Error ? err.message : "تعذّر تحميل اعتمادات مستندية");
      setLcs([]);
    } finally { setLoading(false); }
  }, [activeCompany, slug]);

  const loadFx = useCallback(async () => {
    if (!activeCompany) return;
    setLoading(true);
    try {
      const res = await authedFetch(`/api/accounting/fx-revaluation?${slug}`);
      if (!res.ok) { const e = await res.json().catch(() => ({})); throw new Error(e.error || `فشل تحميل تقييم FX (${res.status})`); }
      const d = await res.json();
      setFxEntries(d.revaluations || []);
    } catch (err) {
      toast.error(err instanceof Error ? err.message : "تعذّر تحميل تقييم العملات");
      setFxEntries([]);
    } finally { setLoading(false); }
  }, [activeCompany, slug]);

  useEffect(() => { if (tab === "lc") loadLcs(); else loadFx(); }, [tab, loadLcs, loadFx]);

  const switchTab = (t: Tab) => { setTab(t); setShowLcForm(false); setShowFxForm(false); };

  /* ── Create LC ──────────────────────────────────────────────────────────── */
  const handleCreateLc = async () => {
    if (!activeCompany) return;
    if (!lcNumber || !lcSupplier || !lcBank || !lcAmount) { toast.error("يرجى ملء جميع الحقول المطلوبة"); return; }
    try {
      const res = await authedFetch("/api/accounting/letters-of-credit", {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({
          companySlug: activeCompany.slug,
          lcNumber, supplier: lcSupplier, bank: lcBank,
          amount: parseFloat(lcAmount), currency: lcCurrency,
          issueDate: lcIssueDate, expiryDate: lcExpiryDate, status: "issued",
        }),
      });
      if (!res.ok) { const e = await res.json().catch(() => ({})); throw new Error(e.error || "فشل إنشاء الاعتماد"); }
      toast.success("تم إنشاء الاعتماد المستندي");
      setShowLcForm(false); resetLcForm(); loadLcs();
    } catch (err) { toast.error(err instanceof Error ? err.message : "تعذّر إنشاء الاعتماد"); }
  };

  const resetLcForm = () => { setLcNumber(""); setLcSupplier(""); setLcBank(""); setLcAmount(""); setLcCurrency("KWD"); setLcIssueDate(""); setLcExpiryDate(""); };

  /* ── Create FX Revaluation ─────────────────────────────────────────────── */
  const handleCreateFx = async () => {
    if (!activeCompany) return;
    if (!fxRate) { toast.error("يرجى إدخال سعر الصرف"); return; }
    try {
      const res = await authedFetch("/api/accounting/fx-revaluation", {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({
          companySlug: activeCompany.slug,
          fromCurrency: fxFrom, toCurrency: fxTo,
          rate: parseFloat(fxRate), period: fxPeriod,
        }),
      });
      if (!res.ok) { const e = await res.json().catch(() => ({})); throw new Error(e.error || "فشل حساب تقييم العملات"); }
      toast.success("تم حساب تقييم العملات");
      setShowFxForm(false); resetFxForm(); loadFx();
    } catch (err) { toast.error(err instanceof Error ? err.message : "تعذّر حساب تقييم العملات"); }
  };

  const resetFxForm = () => { setFxFrom("USD"); setFxTo("KWD"); setFxRate(""); setFxPeriod("Q1"); };

  if (!activeCompany) return <div className="p-12 text-center text-muted-foreground">اختر شركة</div>;

  const tabs: Array<{ key: Tab; label: string; icon: React.ComponentType<{ size?: number }> }> = [
    { key: "lc", label: "اعتمادات مستندية", icon: Landmark },
    { key: "fx", label: "تقييم العملات", icon: ArrowRightLeft },
  ];

  const fmt = (n: number) => n.toLocaleString("ar-EG", { maximumFractionDigits: 3 });

  return (
    <div className="flex flex-col gap-4">
      {/* Header */}
      <div className="flex flex-wrap justify-between items-center gap-3">
        <div>
          <h1 className="text-2xl font-extrabold flex items-center gap-2"><ShieldCheck size={20} /> التمويل التجاري</h1>
          <p className="text-[13px] text-muted-foreground">{activeCompany.nameAr || activeCompany.name}</p>
        </div>
        <button onClick={() => tab === "lc" ? setShowLcForm(true) : setShowFxForm(true)} className="inline-flex items-center gap-1.5 py-2.5 px-[18px] rounded-[10px] bg-primary text-primary-foreground border-none text-[13px] font-bold cursor-pointer"><Plus size={16} /> {tab === "lc" ? "اعتماد جديد" : "حساب تقييم"}</button>
      </div>

      {/* Tabs */}
      <div className="flex gap-1.5 flex-wrap">
        {tabs.map((t) => {
          const Icon = t.icon;
          return (
            <button key={t.key} onClick={() => switchTab(t.key)} className={cn(
              "py-2 px-4 rounded-[10px] border border-border text-[12px] font-bold cursor-pointer inline-flex items-center gap-1.5",
              tab === t.key ? "bg-primary text-primary-foreground" : "bg-card text-muted-foreground",
            )}>
              {Icon && <Icon size={14} />} {t.label}
            </button>
          );
        })}
      </div>

      {loading ? <div className="p-12 text-center text-muted-foreground">جارٍ التحميل…</div> : tab === "lc" ? (
        /* ── LC Tab ──────────────────────────────────────────────────────────── */
        showLcForm ? (
          <div className="bg-card rounded-[14px] border border-border p-5">
            <div className="flex items-center justify-between mb-4">
              <h2 className="text-base font-bold">اعتماد مستندي جديد</h2>
              <button onClick={() => { setShowLcForm(false); resetLcForm(); }} className="w-7 h-7 rounded-md border border-border flex items-center justify-center cursor-pointer"><X size={14} /></button>
            </div>
            <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
              <div><label className={labelStyle}>رقم الاعتماد *</label><input value={lcNumber} onChange={(e) => setLcNumber(e.target.value)} className={inputStyle} placeholder="LC-2025-001" /></div>
              <div><label className={labelStyle}>المورد *</label><input value={lcSupplier} onChange={(e) => setLcSupplier(e.target.value)} className={inputStyle} placeholder="اسم المورد" /></div>
              <div><label className={labelStyle}>البنك *</label><input value={lcBank} onChange={(e) => setLcBank(e.target.value)} className={inputStyle} placeholder="اسم البنك" /></div>
              <div><label className={labelStyle}>المبلغ *</label><input value={lcAmount} onChange={(e) => setLcAmount(e.target.value)} className={inputStyle} type="number" placeholder="0.000" /></div>
              <div><label className={labelStyle}>العملة</label>
                <select value={lcCurrency} onChange={(e) => setLcCurrency(e.target.value)} className={selectStyle}>
                  <option value="KWD">KWD — دينار كويتي</option>
                  <option value="USD">USD — دولار أمريكي</option>
                  <option value="EUR">EUR — يورو</option>
                  <option value="GBP">GBP — جنيه بريطاني</option>
                  <option value="SAR">SAR — ريال سعودي</option>
                </select>
              </div>
              <div><label className={labelStyle}>تاريخ الإصدار</label><input value={lcIssueDate} onChange={(e) => setLcIssueDate(e.target.value)} className={inputStyle} type="date" /></div>
              <div><label className={labelStyle}>تاريخ الانتهاء</label><input value={lcExpiryDate} onChange={(e) => setLcExpiryDate(e.target.value)} className={inputStyle} type="date" /></div>
            </div>
            <div className="flex gap-2 justify-end mt-5">
              <button onClick={() => { setShowLcForm(false); resetLcForm(); }} className="px-4 py-2 rounded-md border border-border bg-transparent text-foreground text-sm font-semibold cursor-pointer">إلغاء</button>
              <button onClick={handleCreateLc} className="px-4 py-2 rounded-md bg-primary text-primary-foreground text-sm font-bold cursor-pointer inline-flex items-center gap-1.5"><Landmark size={14} /> إنشاء</button>
            </div>
          </div>
        ) : lcs.length === 0 ? <Empty label="اعتمادات مستندية" /> : (
          <div className="bg-card rounded-[14px] border border-border overflow-hidden">
            <div className="overflow-x-auto garfix-scroll">
              <table className="w-full border-collapse">
                <thead><tr className="border-b border-border bg-muted">
                  <th scope="col" className={thStyle}>رقم الاعتماد</th><th scope="col" className={thStyle}>المورد</th>
                  <th scope="col" className={thStyle}>البنك</th><th scope="col" className={thStyle}>المبلغ</th>
                  <th scope="col" className={thStyle}>العملة</th><th scope="col" className={thStyle}>تاريخ الإصدار</th>
                  <th scope="col" className={thStyle}>الانتهاء</th><th scope="col" className={thStyle}>الحالة</th>
                </tr></thead>
                <tbody>
                  {lcs.map((lc) => {
                    const st = LC_STATUS_MAP[lc.status] || { label: lc.status, badge: "bg-gray-500/15 text-gray-500" };
                    return (
                      <tr key={lc.id} className="border-b border-border">
                        <td className={cn(tdStyle, "font-mono font-bold")}>{lc.lcNumber}</td>
                        <td className={tdStyle}>{lc.supplier}</td>
                        <td className={tdStyle}>{lc.bank}</td>
                        <td className={cn(tdStyle, "[direction:ltr] text-end font-bold")}>{fmt(lc.amount)}</td>
                        <td className={tdStyle}>{lc.currency}</td>
                        <td className={tdStyle}>{lc.issueDate}</td>
                        <td className={tdStyle}>{lc.expiryDate}</td>
                        <td className={tdStyle}>
                          <span className={cn("py-0.5 px-2.5 rounded-[12px] text-[11px] font-bold", st.badge)}>{st.label}</span>
                        </td>
                      </tr>
                    );
                  })}
                </tbody>
              </table>
            </div>
            <div className="py-3 px-4 border-t border-border text-[12px] text-muted-foreground">{lcs.length} اعتماد</div>
          </div>
        )
      ) : (
        /* ── FX Tab ──────────────────────────────────────────────────────────── */
        showFxForm ? (
          <div className="bg-card rounded-[14px] border border-border p-5">
            <div className="flex items-center justify-between mb-4">
              <h2 className="text-base font-bold">حساب تقييم العملات</h2>
              <button onClick={() => { setShowFxForm(false); resetFxForm(); }} className="w-7 h-7 rounded-md border border-border flex items-center justify-center cursor-pointer"><X size={14} /></button>
            </div>
            <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
              <div><label className={labelStyle}>من عملة</label>
                <select value={fxFrom} onChange={(e) => setFxFrom(e.target.value)} className={selectStyle}>
                  <option value="USD">USD — دولار أمريكي</option>
                  <option value="EUR">EUR — يورو</option>
                  <option value="GBP">GBP — جنيه بريطاني</option>
                  <option value="SAR">SAR — ريال سعودي</option>
                  <option value="AED">AED — درهم إماراتي</option>
                </select>
              </div>
              <div><label className={labelStyle}>إلى عملة</label>
                <select value={fxTo} onChange={(e) => setFxTo(e.target.value)} className={selectStyle}>
                  <option value="KWD">KWD — دينار كويتي</option>
                  <option value="USD">USD — دولار أمريكي</option>
                  <option value="EUR">EUR — يورو</option>
                </select>
              </div>
              <div><label className={labelStyle}>سعر الصرف *</label><input value={fxRate} onChange={(e) => setFxRate(e.target.value)} className={inputStyle} type="number" step="0.0001" placeholder="0.3057" /></div>
              <div><label className={labelStyle}>الفترة</label>
                <select value={fxPeriod} onChange={(e) => setFxPeriod(e.target.value)} className={selectStyle}>
                  <option value="Q1">Q1 — الربع الأول</option>
                  <option value="Q2">Q2 — الربع الثاني</option>
                  <option value="Q3">Q3 — الربع الثالث</option>
                  <option value="Q4">Q4 — الربع الرابع</option>
                  <option value="YTD">YTD — منذ بداية السنة</option>
                </select>
              </div>
            </div>
            <div className="flex gap-2 justify-end mt-5">
              <button onClick={() => { setShowFxForm(false); resetFxForm(); }} className="px-4 py-2 rounded-md border border-border bg-transparent text-foreground text-sm font-semibold cursor-pointer">إلغاء</button>
              <button onClick={handleCreateFx} className="px-4 py-2 rounded-md bg-primary text-primary-foreground text-sm font-bold cursor-pointer inline-flex items-center gap-1.5"><ArrowRightLeft size={14} /> حساب</button>
            </div>
          </div>
        ) : fxEntries.length === 0 ? <Empty label="تقييمات عملات" /> : (
          <div className="bg-card rounded-[14px] border border-border overflow-hidden">
            {/* Summary cards */}
            <div className="grid grid-cols-2 md:grid-cols-4 gap-3 p-4 border-b border-border">
              {(() => {
                const totalRealizedGain = fxEntries.reduce((s, f) => s + f.realizedGain, 0);
                const totalRealizedLoss = fxEntries.reduce((s, f) => s + f.realizedLoss, 0);
                const totalUnrealizedGain = fxEntries.reduce((s, f) => s + f.unrealizedGain, 0);
                const totalUnrealizedLoss = fxEntries.reduce((s, f) => s + f.unrealizedLoss, 0);
                return [
                  { label: "أرباح محققة", value: totalRealizedGain, badgeClass: "bg-emerald-500/20 text-emerald-500", textClass: "text-emerald-500", icon: <TrendingUp size={16} /> },
                  { label: "خسائر محققة", value: totalRealizedLoss, badgeClass: "bg-red-500/20 text-red-500", textClass: "text-red-500", icon: <TrendingDown size={16} /> },
                  { label: "أرباح غير محققة", value: totalUnrealizedGain, badgeClass: "bg-blue-500/20 text-blue-500", textClass: "text-blue-500", icon: <TrendingUp size={16} /> },
                  { label: "خسائر غير محققة", value: totalUnrealizedLoss, badgeClass: "bg-amber-500/20 text-amber-500", textClass: "text-amber-500", icon: <TrendingDown size={16} /> },
                ].map((m, i) => (
                  <div key={i} className="bg-background rounded-[10px] border border-border p-3 flex items-center gap-2">
                    <div className={cn("w-8 h-8 rounded-md flex items-center justify-center", m.badgeClass)}>{m.icon}</div>
                    <div><p className="text-[11px] text-muted-foreground">{m.label}</p><p className={cn("text-[15px] font-bold", m.textClass)}>{fmt(m.value)}</p></div>
                  </div>
                ));
              })()}
            </div>
            <div className="overflow-x-auto garfix-scroll">
              <table className="w-full border-collapse">
                <thead><tr className="border-b border-border bg-muted">
                  <th scope="col" className={thStyle}>من</th><th scope="col" className={thStyle}>إلى</th>
                  <th scope="col" className={thStyle}>السعر</th><th scope="col" className={thStyle}>الفترة</th>
                  <th scope="col" className={thStyle}>أرباح محققة</th><th scope="col" className={thStyle}>خسائر محققة</th>
                  <th scope="col" className={thStyle}>أرباح غير محققة</th><th scope="col" className={thStyle}>خسائر غير محققة</th>
                  <th scope="col" className={thStyle}>صافي الأثر</th>
                </tr></thead>
                <tbody>
                  {fxEntries.map((fx) => (
                    <tr key={fx.id} className="border-b border-border">
                      <td className={tdStyle}>{fx.fromCurrency}</td>
                      <td className={tdStyle}>{fx.toCurrency}</td>
                      <td className={cn(tdStyle, "[direction:ltr] text-end font-mono")}>{fx.rate}</td>
                      <td className={tdStyle}>{fx.period}</td>
                      <td className={cn(cn(tdStyle, "[direction:ltr] text-end font-bold"), "text-emerald-500")}>{fmt(fx.realizedGain)}</td>
                      <td className={cn(cn(tdStyle, "[direction:ltr] text-end font-bold"), "text-red-500")}>{fmt(fx.realizedLoss)}</td>
                      <td className={cn(cn(tdStyle, "[direction:ltr] text-end font-bold"), "text-blue-500")}>{fmt(fx.unrealizedGain)}</td>
                      <td className={cn(cn(tdStyle, "[direction:ltr] text-end font-bold"), "text-amber-500")}>{fmt(fx.unrealizedLoss)}</td>
                      <td className={cn(tdStyle, "[direction:ltr] text-end font-bold", fx.netEffect >= 0 ? "text-emerald-500" : "text-red-500")}>{fmt(fx.netEffect)}</td>
                    </tr>
                  ))}
                </tbody>
              </table>
            </div>
            <div className="py-3 px-4 border-t border-border text-[12px] text-muted-foreground">{fxEntries.length} تقييم</div>
          </div>
        )
      )}
    </div>
  );
}

"use client";

import { useEffect, useState, useCallback } from "react";
import { useBrand } from "@/context/BrandContext";
import { authedFetch } from "@/context/AuthContext";
import { toast } from "sonner";
import {
  Plus, X, FileText, Receipt, ShoppingCart, Scale,
  Users, DollarSign, Calendar, CheckCircle2, XCircle,
  Printer, ArrowRight, CreditCard, BookOpen, Percent,
  HandCoins,
} from "lucide-react";
import { cn } from "@/lib/utils";

/* ─── Interfaces ──────────────────────────────────────────────────────────── */
interface Voucher {
  id: number; voucherType: string; date: string; amount: number;
  currency: string; payee: string; payer: string; status: string;
  amountTextAr?: string;
}
interface Quotation {
  id: number; clientName: string; date: string; validUntil: string;
  lineItems: LineItem[]; totalAmount: number; status: string;
}
interface PurchaseOrder {
  id: number; supplierName: string; date: string; expectedDelivery: string;
  lineItems: LineItem[]; totalAmount: number; status: string;
}
interface LineItem { id?: number; description: string; quantity: number; unitPrice: number; total: number; }
interface OpeningBalance { id: number; accountId: number; accountCode: string; accountNameAr: string; amount: number; posted: boolean; }
interface Commission { id: number; salesperson: string; totalSales: number; commissionAmount: number; posted: boolean; }
interface ProfitDistribution { id: number; partnerName: string; ownershipPercent: number; profitShare: number; posted: boolean; }

type Tab = "vouchers" | "quotations" | "purchase-orders" | "opening-balances" | "commissions" | "profit-distribution";

/* ─── Shared Styles ─────────────────────────────────────────────────────────── */
const thStyle = "text-start py-2.5 px-3 text-[11px] text-muted-foreground font-bold";
const tdStyle = "py-2.5 px-3 text-[13px]";
const inputStyle = "w-full py-2 px-3 rounded-sm bg-background border border-border text-foreground text-[13px] outline-none";
const labelStyle = "block text-[11px] font-semibold text-muted-foreground mb-1";
const selectStyle = "w-full py-2 px-3 rounded-sm bg-background border border-border text-foreground text-[13px] outline-none cursor-pointer";

function Empty({ label }: { label: string }) {
  return <div className="p-12 text-center text-muted-foreground">لا توجد {label} بعد</div>;
}

/* ─── Main Component ────────────────────────────────────────────────────────── */
export function VouchersDetailView() {
  const { activeCompany } = useBrand();
  const [tab, setTab] = useState<Tab>("vouchers");
  const [vouchers, setVouchers] = useState<Voucher[]>([]);
  const [quotations, setQuotations] = useState<Quotation[]>([]);
  const [purchaseOrders, setPurchaseOrders] = useState<PurchaseOrder[]>([]);
  const [openingBalances, setOpeningBalances] = useState<OpeningBalance[]>([]);
  const [commissions, setCommissions] = useState<Commission[]>([]);
  const [profitDistributions, setProfitDistributions] = useState<ProfitDistribution[]>([]);
  const [loading, setLoading] = useState(true);
  const [showForm, setShowForm] = useState(false);

  /* Voucher form */
  const [vType, setVType] = useState("receipt");
  const [vDate, setVDate] = useState("");
  const [vAmount, setVAmount] = useState("");
  const [vCurrency, setVCurrency] = useState("KWD");
  const [vPayee, setVPayee] = useState("");
  const [vPayer, setVPayer] = useState("");

  /* Quotation form */
  const [qClient, setQClient] = useState("");
  const [qDate, setQDate] = useState("");
  const [qValidUntil, setQValidUntil] = useState("");
  const [qLineItems, setQLineItems] = useState<LineItem[]>([{ description: "", quantity: 1, unitPrice: 0, total: 0 }]);

  /* PO form */
  const [poSupplier, setPoSupplier] = useState("");
  const [poDate, setPoDate] = useState("");
  const [poDelivery, setPoDelivery] = useState("");
  const [poLineItems, setPoLineItems] = useState<LineItem[]>([{ description: "", quantity: 1, unitPrice: 0, total: 0 }]);

  /* Opening Balance form */
  const [obAccountId, setObAccountId] = useState("");
  const [obAmount, setObAmount] = useState("");

  /* Commission dates */
  const [commFrom, setCommFrom] = useState("");
  const [commTo, setCommTo] = useState("");

  const slug = activeCompany ? `companySlug=${encodeURIComponent(activeCompany.slug)}` : "";

  /* ── Loaders ──────────────────────────────────────────────────────────────── */
  const loadVouchers = useCallback(async () => {
    if (!activeCompany) { setLoading(false); return; }
    setLoading(true);
    try {
      const res = await authedFetch(`/api/accounting/vouchers?${slug}`);
      if (!res.ok) { const e = await res.json().catch(() => ({})); throw new Error(e.error || "فشل تحميل السندات"); }
      const d = await res.json(); setVouchers(d.vouchers || []);
    } catch (err) { toast.error(err instanceof Error ? err.message : "تعذّر تحميل السندات"); setVouchers([]); }
    finally { setLoading(false); }
  }, [activeCompany, slug]);

  const loadQuotations = useCallback(async () => {
    if (!activeCompany) return; setLoading(true);
    try {
      const res = await authedFetch(`/api/accounting/quotations?${slug}`);
      if (!res.ok) { const e = await res.json().catch(() => ({})); throw new Error(e.error || "فشل تحميل عروض الأسعار"); }
      const d = await res.json(); setQuotations(d.quotations || []);
    } catch (err) { toast.error(err instanceof Error ? err.message : "تعذّر تحميل عروض الأسعار"); setQuotations([]); }
    finally { setLoading(false); }
  }, [activeCompany, slug]);

  const loadPOs = useCallback(async () => {
    if (!activeCompany) return; setLoading(true);
    try {
      const res = await authedFetch(`/api/accounting/purchase-orders?${slug}`);
      if (!res.ok) { const e = await res.json().catch(() => ({})); throw new Error(e.error || "فشل تحميل أوامر الشراء"); }
      const d = await res.json(); setPurchaseOrders(d.purchaseOrders || []);
    } catch (err) { toast.error(err instanceof Error ? err.message : "تعذّر تحميل أوامر الشراء"); setPurchaseOrders([]); }
    finally { setLoading(false); }
  }, [activeCompany, slug]);

  const loadOBs = useCallback(async () => {
    if (!activeCompany) return; setLoading(true);
    try {
      const res = await authedFetch(`/api/accounting/opening-balances?${slug}`);
      if (!res.ok) { const e = await res.json().catch(() => ({})); throw new Error(e.error || "فشل تحميل أرصدة افتتاحية"); }
      const d = await res.json(); setOpeningBalances(d.openingBalances || []);
    } catch (err) { toast.error(err instanceof Error ? err.message : "تعذّر تحميل أرصدة افتتاحية"); setOpeningBalances([]); }
    finally { setLoading(false); }
  }, [activeCompany, slug]);

  const loadCommissions = useCallback(async () => {
    if (!activeCompany) return; setLoading(true);
    try {
      const res = await authedFetch(`/api/accounting/commissions?${slug}&from=${commFrom}&to=${commTo}`);
      if (!res.ok) { const e = await res.json().catch(() => ({})); throw new Error(e.error || "فشل تحميل العمولات"); }
      const d = await res.json(); setCommissions(d.commissions || []);
    } catch (err) { toast.error(err instanceof Error ? err.message : "تعذّر تحميل العمولات"); setCommissions([]); }
    finally { setLoading(false); }
  }, [activeCompany, slug, commFrom, commTo]);

  const loadProfitDist = useCallback(async () => {
    if (!activeCompany) return; setLoading(true);
    try {
      const res = await authedFetch(`/api/accounting/profit-distribution?${slug}`);
      if (!res.ok) { const e = await res.json().catch(() => ({})); throw new Error(e.error || "فشل تحميل توزيع الأرباح"); }
      const d = await res.json(); setProfitDistributions(d.distributions || []);
    } catch (err) { toast.error(err instanceof Error ? err.message : "تعذّر تحميل توزيع الأرباح"); setProfitDistributions([]); }
    finally { setLoading(false); }
  }, [activeCompany, slug]);

  useEffect(() => {
    const loaders: Record<Tab, () => void> = {
      vouchers: loadVouchers, quotations: loadQuotations,
      "purchase-orders": loadPOs, "opening-balances": loadOBs,
      commissions: loadCommissions, "profit-distribution": loadProfitDist,
    };
    if (activeCompany) loaders[tab]();
  }, [tab, activeCompany, loadVouchers, loadQuotations, loadPOs, loadOBs, loadCommissions, loadProfitDist]);

  const switchTab = (t: Tab) => { setTab(t); setShowForm(false); };

  /* ── Line Items helper ───────────────────────────────────────────────────── */
  const updateLineItem = (items: LineItem[], idx: number, field: keyof LineItem, value: string | number): LineItem[] => {
    const updated = [...items];
    const item = { ...updated[idx] };
    if (field === "description") item.description = String(value);
    else if (field === "quantity") item.quantity = Number(value);
    else if (field === "unitPrice") item.unitPrice = Number(value);
    else if (field === "total") item.total = Number(value);
    item.total = item.quantity * item.unitPrice;
    updated[idx] = item;
    return updated;
  };

  /* ── Create Voucher ─────────────────────────────────────────────────────── */
  const handleCreateVoucher = async () => {
    if (!activeCompany || !vAmount || !vDate) { toast.error("يرجى ملء جميع الحقول المطلوبة"); return; }
    try {
      const res = await authedFetch("/api/accounting/vouchers", {
        method: "POST", headers: { "Content-Type": "application/json" },
        body: JSON.stringify({ companySlug: activeCompany.slug, voucherType: vType, date: vDate, amount: parseFloat(vAmount), currency: vCurrency, payee: vPayee, payer: vPayer }),
      });
      if (!res.ok) { const e = await res.json().catch(() => ({})); throw new Error(e.error || "فشل إنشاء السند"); }
      toast.success("تم إنشاء السند"); setShowForm(false); resetVoucherForm(); loadVouchers();
    } catch (err) { toast.error(err instanceof Error ? err.message : "تعذّر إنشاء السند"); }
  };
  const resetVoucherForm = () => { setVType("receipt"); setVDate(""); setVAmount(""); setVCurrency("KWD"); setVPayee(""); setVPayer(""); };

  /* ── Approve / Cancel Voucher ────────────────────────────────────────────── */
  const handleApproveVoucher = async (id: number) => {
    if (!activeCompany) return;
    try {
      const res = await authedFetch(`/api/accounting/vouchers/${id}/approve?${slug}`, { method: "POST" });
      if (!res.ok) { const e = await res.json().catch(() => ({})); throw new Error(e.error || "فشل اعتماد السند"); }
      toast.success("تم اعتماد السند"); loadVouchers();
    } catch (err) { toast.error(err instanceof Error ? err.message : "تعذّر اعتماد السند"); }
  };
  const handleCancelVoucher = async (id: number) => {
    if (!activeCompany) return;
    try {
      const res = await authedFetch(`/api/accounting/vouchers/${id}/cancel?${slug}`, { method: "POST" });
      if (!res.ok) { const e = await res.json().catch(() => ({})); throw new Error(e.error || "فشل إلغاء السند"); }
      toast.success("تم إلغاء السند"); loadVouchers();
    } catch (err) { toast.error(err instanceof Error ? err.message : "تعذّر إلغاء السند"); }
  };

  /* ── Create Quotation ────────────────────────────────────────────────────── */
  const handleCreateQuotation = async () => {
    if (!activeCompany || !qClient || !qDate) { toast.error("يرجى ملء جميع الحقول المطلوبة"); return; }
    try {
      const res = await authedFetch("/api/accounting/quotations", {
        method: "POST", headers: { "Content-Type": "application/json" },
        body: JSON.stringify({ companySlug: activeCompany.slug, clientName: qClient, date: qDate, validUntil: qValidUntil, lineItems: qLineItems }),
      });
      if (!res.ok) { const e = await res.json().catch(() => ({})); throw new Error(e.error || "فشل إنشاء عرض السعر"); }
      toast.success("تم إنشاء عرض السعر"); setShowForm(false); loadQuotations();
    } catch (err) { toast.error(err instanceof Error ? err.message : "تعذّر إنشاء عرض السعر"); }
  };

  /* ── Convert Quotation to Invoice ─────────────────────────────────────────── */
  const handleConvertToInvoice = async (id: number) => {
    if (!activeCompany) return;
    try {
      const res = await authedFetch(`/api/accounting/quotations/${id}/convert-to-invoice?${slug}`, { method: "POST" });
      if (!res.ok) { const e = await res.json().catch(() => ({})); throw new Error(e.error || "فشل التحويل"); }
      toast.success("تم التحويل إلى فاتورة"); loadQuotations();
    } catch (err) { toast.error(err instanceof Error ? err.message : "تعذّر التحويل إلى فاتورة"); }
  };

  /* ── Create PO ────────────────────────────────────────────────────────────── */
  const handleCreatePO = async () => {
    if (!activeCompany || !poSupplier || !poDate) { toast.error("يرجى ملء جميع الحقول المطلوبة"); return; }
    try {
      const res = await authedFetch("/api/accounting/purchase-orders", {
        method: "POST", headers: { "Content-Type": "application/json" },
        body: JSON.stringify({ companySlug: activeCompany.slug, supplierName: poSupplier, date: poDate, expectedDelivery: poDelivery, lineItems: poLineItems }),
      });
      if (!res.ok) { const e = await res.json().catch(() => ({})); throw new Error(e.error || "فشل إنشاء أمر الشراء"); }
      toast.success("تم إنشاء أمر الشراء"); setShowForm(false); loadPOs();
    } catch (err) { toast.error(err instanceof Error ? err.message : "تعذّر إنشاء أمر الشراء"); }
  };

  /* ── Create Opening Balance ──────────────────────────────────────────────── */
  const handleCreateOB = async () => {
    if (!activeCompany || !obAccountId || !obAmount) { toast.error("يرجى ملء جميع الحقول المطلوبة"); return; }
    try {
      const res = await authedFetch("/api/accounting/opening-balances", {
        method: "POST", headers: { "Content-Type": "application/json" },
        body: JSON.stringify({ companySlug: activeCompany.slug, accountId: parseInt(obAccountId), amount: parseFloat(obAmount) }),
      });
      if (!res.ok) { const e = await res.json().catch(() => ({})); throw new Error(e.error || "فشل إنشاء رصيد افتتاحي"); }
      toast.success("تم إنشاء الرصيد الافتتاحي"); setShowForm(false); setObAccountId(""); setObAmount(""); loadOBs();
    } catch (err) { toast.error(err instanceof Error ? err.message : "تعذّر إنشاء الرصيد الافتتاحي"); }
  };

  /* ── Post all opening balances ────────────────────────────────────────────── */
  const handlePostAllOB = async () => {
    if (!activeCompany) return;
    if (!confirm("ترحيل جميع الأرصدة الافتتاحية؟ لا يمكن التراجع عن هذا الإجراء.")) return;
    try {
      const res = await authedFetch(`/api/accounting/opening-balances/post?${slug}`, { method: "POST" });
      if (!res.ok) { const e = await res.json().catch(() => ({})); throw new Error(e.error || "فشل ترحيل الأرصدة"); }
      toast.success("تم ترحيل جميع الأرصدة الافتتاحية"); loadOBs();
    } catch (err) { toast.error(err instanceof Error ? err.message : "تعذّر ترحيل الأرصدة الافتتاحية"); }
  };

  /* ── Post Commission as JE ────────────────────────────────────────────────── */
  const handlePostCommission = async (id: number) => {
    if (!activeCompany) return;
    try {
      const res = await authedFetch(`/api/accounting/commissions/${id}/post-as-journal-entry?${slug}`, { method: "POST" });
      if (!res.ok) { const e = await res.json().catch(() => ({})); throw new Error(e.error || "فشل ترحيل العمولة"); }
      toast.success("تم ترحيل العمولة كقيد يومية"); loadCommissions();
    } catch (err) { toast.error(err instanceof Error ? err.message : "تعذّر ترحيل العمولة"); }
  };

  /* ── Post Profit Distribution as JE ───────────────────────────────────────── */
  const handlePostProfitDist = async (id: number) => {
    if (!activeCompany) return;
    try {
      const res = await authedFetch(`/api/accounting/profit-distribution/${id}/post-as-journal-entry?${slug}`, { method: "POST" });
      if (!res.ok) { const e = await res.json().catch(() => ({})); throw new Error(e.error || "فشل ترحيل التوزيع"); }
      toast.success("تم ترحيل التوزيع كقيد يومية"); loadProfitDist();
    } catch (err) { toast.error(err instanceof Error ? err.message : "تعذّر ترحيل توزيع الأرباح"); }
  };

  if (!activeCompany) return <div className="p-12 text-center text-muted-foreground">اختر شركة</div>;

  const tabs: Array<{ key: Tab; label: string; icon: React.ComponentType<{ size?: number }> }> = [
    { key: "vouchers", label: "سندات", icon: Receipt },
    { key: "quotations", label: "عروض أسعار", icon: FileText },
    { key: "purchase-orders", label: "أوامر الشراء", icon: ShoppingCart },
    { key: "opening-balances", label: "أرصدة افتتاحية", icon: BookOpen },
    { key: "commissions", label: "عمولات", icon: Percent },
    { key: "profit-distribution", label: "توزيع أرباح", icon: HandCoins },
  ];

  const fmt = (n: number) => n.toLocaleString("ar-EG", { maximumFractionDigits: 3 });

  return (
    <div className="flex flex-col gap-4">
      {/* Header */}
      <div className="flex flex-wrap justify-between items-center gap-3">
        <div>
          <h1 className="text-2xl font-extrabold flex items-center gap-2"><Receipt size={20} /> السندات والتفاصيل</h1>
          <p className="text-[13px] text-muted-foreground">{activeCompany.nameAr || activeCompany.name}</p>
        </div>
        {!showForm && (
          <button onClick={() => setShowForm(true)} className="inline-flex items-center gap-1.5 py-2.5 px-[18px] rounded-[10px] bg-primary text-primary-foreground border-none text-[13px] font-bold cursor-pointer"><Plus size={16} /> إضافة</button>
        )}
      </div>

      {/* Tabs */}
      <div className="flex gap-1.5 flex-wrap">
        {tabs.map((t) => { const Icon = t.icon; return (
          <button key={t.key} onClick={() => switchTab(t.key)} className={cn(
            "py-2 px-4 rounded-[10px] border border-border text-[12px] font-bold cursor-pointer inline-flex items-center gap-1.5",
            tab === t.key ? "bg-primary text-primary-foreground" : "bg-card text-muted-foreground",
          )}>{Icon && <Icon size={14} />} {t.label}</button>
        ); })}
      </div>

      {/* Commissions date filter */}
      {tab === "commissions" && !showForm && (
        <div className="flex gap-3 items-end bg-card rounded-[10px] border border-border p-3">
          <div><label className={labelStyle}>من</label><input value={commFrom} onChange={(e) => setCommFrom(e.target.value)} className={cn(inputStyle, "w-36")} type="date" /></div>
          <div><label className={labelStyle}>إلى</label><input value={commTo} onChange={(e) => setCommTo(e.target.value)} className={cn(inputStyle, "w-36")} type="date" /></div>
        </div>
      )}

      {loading ? <div className="p-12 text-center text-muted-foreground">جارٍ التحميل…</div> : (() => {
        /* ── Vouchers Tab ─────────────────────────────────────────────────────── */
        if (tab === "vouchers") {
          if (showForm) return (
            <div className="bg-card rounded-[14px] border border-border p-5">
              <div className="flex items-center justify-between mb-4">
                <h2 className="text-base font-bold">سند جديد</h2>
                <button onClick={() => { setShowForm(false); resetVoucherForm(); }} className="w-7 h-7 rounded-md border border-border flex items-center justify-center cursor-pointer"><X size={14} /></button>
              </div>
              <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
                <div><label className={labelStyle}>نوع السند *</label>
                  <select value={vType} onChange={(e) => setVType(e.target.value)} className={selectStyle}>
                    <option value="receipt">سند قبض</option><option value="payment">سند دفع</option>
                  </select>
                </div>
                <div><label className={labelStyle}>التاريخ *</label><input value={vDate} onChange={(e) => setVDate(e.target.value)} className={inputStyle} type="date" /></div>
                <div><label className={labelStyle}>المبلغ *</label><input value={vAmount} onChange={(e) => setVAmount(e.target.value)} className={inputStyle} type="number" placeholder="0.000" /></div>
                <div><label className={labelStyle}>العملة</label>
                  <select value={vCurrency} onChange={(e) => setVCurrency(e.target.value)} className={selectStyle}>
                    <option value="KWD">KWD</option><option value="USD">USD</option><option value="EUR">EUR</option><option value="SAR">SAR</option>
                  </select>
                </div>
                <div><label className={labelStyle}>المستفيد</label><input value={vPayee} onChange={(e) => setVPayee(e.target.value)} className={inputStyle} placeholder="اسم المستفيد" /></div>
                <div><label className={labelStyle}>الدافع</label><input value={vPayer} onChange={(e) => setVPayer(e.target.value)} className={inputStyle} placeholder="اسم الدافع" /></div>
              </div>
              <div className="flex gap-2 justify-end mt-5">
                <button onClick={() => { setShowForm(false); resetVoucherForm(); }} className="px-4 py-2 rounded-md border border-border bg-transparent text-foreground text-sm font-semibold cursor-pointer">إلغاء</button>
                <button onClick={handleCreateVoucher} className="px-4 py-2 rounded-md bg-primary text-primary-foreground text-sm font-bold cursor-pointer inline-flex items-center gap-1.5"><Receipt size={14} /> إنشاء</button>
              </div>
            </div>
          );
          if (vouchers.length === 0) return <Empty label="سندات" />;
          return (
            <div className="bg-card rounded-[14px] border border-border overflow-hidden">
              <div className="overflow-x-auto garfix-scroll">
                <table className="w-full border-collapse">
                  <thead><tr className="border-b border-border bg-muted">
                    <th scope="col" className={thStyle}>النوع</th><th scope="col" className={thStyle}>التاريخ</th>
                    <th scope="col" className={thStyle}>المبلغ</th><th scope="col" className={thStyle}>العملة</th>
                    <th scope="col" className={thStyle}>المستفيد</th><th scope="col" className={thStyle}>الدافع</th>
                    <th scope="col" className={thStyle}>الحالة</th><th scope="col" className={thStyle}>إجراء</th>
                  </tr></thead>
                  <tbody>
                    {vouchers.map((v) => {
                      const statusMap: Record<string, { label: string; color: string; badge: string }> = {
                        draft: { label: "مسودة", color: "#f59e0b", badge: "bg-amber-500/15 text-amber-500" }, approved: { label: "معتمد", color: "#10b981", badge: "bg-emerald-500/15 text-emerald-500" }, cancelled: { label: "ملغى", color: "#ef4444", badge: "bg-red-500/15 text-red-500" },
                      };
                      const st = statusMap[v.status] || { label: v.status, color: "#999", badge: "bg-gray-400/15 text-gray-400" };
                      return (
                        <tr key={v.id} className="border-b border-border">
                          <td className={tdStyle}><span className={cn("py-0.5 px-2.5 rounded-[12px] text-[11px] font-bold", v.voucherType === "receipt" ? "bg-emerald-500/15 text-emerald-500" : "bg-red-500/15 text-red-500")}>{v.voucherType === "receipt" ? "قبض" : "دفع"}</span></td>
                          <td className={tdStyle}>{v.date}</td>
                          <td className={cn(tdStyle, "[direction:ltr] text-end font-bold")}>{fmt(v.amount)}</td>
                          <td className={tdStyle}>{v.currency}</td>
                          <td className={tdStyle}>{v.payee || "—"}</td>
                          <td className={tdStyle}>{v.payer || "—"}</td>
                          <td className={tdStyle}><span className={cn("py-0.5 px-2.5 rounded-[12px] text-[11px] font-bold", st.badge)}>{st.label}</span></td>
                          <td className={tdStyle}>
                            <div className="flex items-center gap-1">
                              {v.status === "draft" && (<>
                                <button onClick={() => handleApproveVoucher(v.id)} title="اعتماد" className="w-7 h-7 rounded-md border border-border flex items-center justify-center cursor-pointer hover:bg-emerald-500/10"><CheckCircle2 size={13} className="text-emerald-600" /></button>
                                <button onClick={() => handleCancelVoucher(v.id)} title="إلغاء" className="w-7 h-7 rounded-md border border-border flex items-center justify-center cursor-pointer hover:bg-red-500/10"><XCircle size={13} className="text-red-500" /></button>
                              </>)}
                              <button title="طباعة" className="w-7 h-7 rounded-md border border-border flex items-center justify-center cursor-pointer hover:bg-muted"><Printer size={13} /></button>
                            </div>
                          </td>
                        </tr>
                      );
                    })}
                  </tbody>
                </table>
              </div>
              <div className="py-3 px-4 border-t border-border text-[12px] text-muted-foreground">{vouchers.length} سند</div>
            </div>
          );
        }

        /* ── Quotations Tab ───────────────────────────────────────────────────── */
        if (tab === "quotations") {
          if (showForm) return (
            <div className="bg-card rounded-[14px] border border-border p-5">
              <div className="flex items-center justify-between mb-4">
                <h2 className="text-base font-bold">عرض سعر جديد</h2>
                <button onClick={() => setShowForm(false)} className="w-7 h-7 rounded-md border border-border flex items-center justify-center cursor-pointer"><X size={14} /></button>
              </div>
              <div className="grid grid-cols-1 md:grid-cols-3 gap-4 mb-4">
                <div><label className={labelStyle}>العميل *</label><input value={qClient} onChange={(e) => setQClient(e.target.value)} className={inputStyle} /></div>
                <div><label className={labelStyle}>التاريخ *</label><input value={qDate} onChange={(e) => setQDate(e.target.value)} className={inputStyle} type="date" /></div>
                <div><label className={labelStyle}>صالح حتى</label><input value={qValidUntil} onChange={(e) => setQValidUntil(e.target.value)} className={inputStyle} type="date" /></div>
              </div>
              {/* Line items */}
              <div className="mb-3"><label className={labelStyle}>بنود عرض السعر</label></div>
              {qLineItems.map((li, idx) => (
                <div key={idx} className="grid grid-cols-4 gap-2 mb-2 items-end">
                  <input value={li.description} onChange={(e) => setQLineItems(updateLineItem(qLineItems, idx, "description", e.target.value))} className={inputStyle} placeholder="الوصف" />
                  <input value={li.quantity} onChange={(e) => setQLineItems(updateLineItem(qLineItems, idx, "quantity", parseFloat(e.target.value) || 0))} className={inputStyle} type="number" placeholder="الكمية" />
                  <input value={li.unitPrice} onChange={(e) => setQLineItems(updateLineItem(qLineItems, idx, "unitPrice", parseFloat(e.target.value) || 0))} className={inputStyle} type="number" placeholder="سعر الوحدة" />
                  <div className="text-[13px] font-bold text-end py-2">{fmt(li.total)}</div>
                </div>
              ))}
              <button onClick={() => setQLineItems([...qLineItems, { description: "", quantity: 1, unitPrice: 0, total: 0 }])} className="text-[12px] text-primary font-bold cursor-pointer inline-flex items-center gap-1"><Plus size={12} /> بند جديد</button>
              <div className="flex gap-2 justify-end mt-5">
                <button onClick={() => setShowForm(false)} className="px-4 py-2 rounded-md border border-border bg-transparent text-foreground text-sm font-semibold cursor-pointer">إلغاء</button>
                <button onClick={handleCreateQuotation} className="px-4 py-2 rounded-md bg-primary text-primary-foreground text-sm font-bold cursor-pointer"><FileText size={14} /> إنشاء</button>
              </div>
            </div>
          );
          if (quotations.length === 0) return <Empty label="عروض أسعار" />;
          return (
            <div className="bg-card rounded-[14px] border border-border overflow-hidden">
              <div className="overflow-x-auto garfix-scroll">
                <table className="w-full border-collapse">
                  <thead><tr className="border-b border-border bg-muted">
                    <th scope="col" className={thStyle}>العميل</th><th scope="col" className={thStyle}>التاريخ</th><th scope="col" className={thStyle}>صالح حتى</th>
                    <th scope="col" className={thStyle}>المبلغ</th><th scope="col" className={thStyle}>البنود</th><th scope="col" className={thStyle}>إجراء</th>
                  </tr></thead>
                  <tbody>
                    {quotations.map((q) => (
                      <tr key={q.id} className="border-b border-border">
                        <td className={cn(tdStyle, "font-bold")}>{q.clientName}</td>
                        <td className={tdStyle}>{q.date}</td><td className={tdStyle}>{q.validUntil}</td>
                        <td className={cn(tdStyle, "[direction:ltr] text-end font-bold")}>{fmt(q.totalAmount)}</td>
                        <td className={tdStyle}>{q.lineItems?.length || 0}</td>
                        <td className={tdStyle}>
                          <button onClick={() => handleConvertToInvoice(q.id)} title="تحويل إلى فاتورة" className="w-7 h-7 rounded-md border border-border flex items-center justify-center cursor-pointer hover:bg-emerald-500/10"><ArrowRight size={13} className="text-emerald-600" /></button>
                        </td>
                      </tr>
                    ))}
                  </tbody>
                </table>
              </div>
            </div>
          );
        }

        /* ── Purchase Orders Tab ──────────────────────────────────────────────── */
        if (tab === "purchase-orders") {
          if (showForm) return (
            <div className="bg-card rounded-[14px] border border-border p-5">
              <div className="flex items-center justify-between mb-4">
                <h2 className="text-base font-bold">أمر شراء جديد</h2>
                <button onClick={() => setShowForm(false)} className="w-7 h-7 rounded-md border border-border flex items-center justify-center cursor-pointer"><X size={14} /></button>
              </div>
              <div className="grid grid-cols-1 md:grid-cols-3 gap-4 mb-4">
                <div><label className={labelStyle}>المورد *</label><input value={poSupplier} onChange={(e) => setPoSupplier(e.target.value)} className={inputStyle} /></div>
                <div><label className={labelStyle}>التاريخ *</label><input value={poDate} onChange={(e) => setPoDate(e.target.value)} className={inputStyle} type="date" /></div>
                <div><label className={labelStyle}>التسليم المتوقع</label><input value={poDelivery} onChange={(e) => setPoDelivery(e.target.value)} className={inputStyle} type="date" /></div>
              </div>
              {poLineItems.map((li, idx) => (
                <div key={idx} className="grid grid-cols-4 gap-2 mb-2 items-end">
                  <input value={li.description} onChange={(e) => setPoLineItems(updateLineItem(poLineItems, idx, "description", e.target.value))} className={inputStyle} placeholder="الوصف" />
                  <input value={li.quantity} onChange={(e) => setPoLineItems(updateLineItem(poLineItems, idx, "quantity", parseFloat(e.target.value) || 0))} className={inputStyle} type="number" placeholder="الكمية" />
                  <input value={li.unitPrice} onChange={(e) => setPoLineItems(updateLineItem(poLineItems, idx, "unitPrice", parseFloat(e.target.value) || 0))} className={inputStyle} type="number" placeholder="سعر الوحدة" />
                  <div className="text-[13px] font-bold text-end py-2">{fmt(li.total)}</div>
                </div>
              ))}
              <button onClick={() => setPoLineItems([...poLineItems, { description: "", quantity: 1, unitPrice: 0, total: 0 }])} className="text-[12px] text-primary font-bold cursor-pointer inline-flex items-center gap-1"><Plus size={12} /> بند جديد</button>
              <div className="flex gap-2 justify-end mt-5">
                <button onClick={() => setShowForm(false)} className="px-4 py-2 rounded-md border border-border bg-transparent text-foreground text-sm font-semibold cursor-pointer">إلغاء</button>
                <button onClick={handleCreatePO} className="px-4 py-2 rounded-md bg-primary text-primary-foreground text-sm font-bold cursor-pointer"><ShoppingCart size={14} /> إنشاء</button>
              </div>
            </div>
          );
          if (purchaseOrders.length === 0) return <Empty label="أوامر شراء" />;
          return (
            <div className="bg-card rounded-[14px] border border-border overflow-hidden">
              <div className="overflow-x-auto garfix-scroll">
                <table className="w-full border-collapse">
                  <thead><tr className="border-b border-border bg-muted">
                    <th scope="col" className={thStyle}>المورد</th><th scope="col" className={thStyle}>التاريخ</th><th scope="col" className={thStyle}>التسليم</th>
                    <th scope="col" className={thStyle}>المبلغ</th><th scope="col" className={thStyle}>البنود</th>
                  </tr></thead>
                  <tbody>
                    {purchaseOrders.map((po) => (
                      <tr key={po.id} className="border-b border-border">
                        <td className={cn(tdStyle, "font-bold")}>{po.supplierName}</td>
                        <td className={tdStyle}>{po.date}</td><td className={tdStyle}>{po.expectedDelivery}</td>
                        <td className={cn(tdStyle, "[direction:ltr] text-end font-bold")}>{fmt(po.totalAmount)}</td>
                        <td className={tdStyle}>{po.lineItems?.length || 0}</td>
                      </tr>
                    ))}
                  </tbody>
                </table>
              </div>
            </div>
          );
        }

        /* ── Opening Balances Tab ─────────────────────────────────────────────── */
        if (tab === "opening-balances") {
          if (showForm) return (
            <div className="bg-card rounded-[14px] border border-border p-5">
              <div className="flex items-center justify-between mb-4">
                <h2 className="text-base font-bold">رصيد افتتاحي جديد</h2>
                <button onClick={() => setShowForm(false)} className="w-7 h-7 rounded-md border border-border flex items-center justify-center cursor-pointer"><X size={14} /></button>
              </div>
              <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
                <div><label className={labelStyle}>رقم الحساب *</label><input value={obAccountId} onChange={(e) => setObAccountId(e.target.value)} className={inputStyle} type="number" placeholder="1" /></div>
                <div><label className={labelStyle}>المبلغ *</label><input value={obAmount} onChange={(e) => setObAmount(e.target.value)} className={inputStyle} type="number" placeholder="0.000" /></div>
              </div>
              <div className="flex gap-2 justify-end mt-5">
                <button onClick={() => setShowForm(false)} className="px-4 py-2 rounded-md border border-border bg-transparent text-foreground text-sm font-semibold cursor-pointer">إلغاء</button>
                <button onClick={handleCreateOB} className="px-4 py-2 rounded-md bg-primary text-primary-foreground text-sm font-bold cursor-pointer"><BookOpen size={14} /> إنشاء</button>
              </div>
            </div>
          );
          if (openingBalances.length === 0) return <Empty label="أرصدة افتتاحية" />;
          return (
            <div className="flex flex-col gap-3">
              <div className="flex justify-end">
                <button onClick={handlePostAllOB} className="px-4 py-2 rounded-md bg-primary text-primary-foreground text-[13px] font-bold cursor-pointer inline-flex items-center gap-1.5"><CheckCircle2 size={14} /> ترحيل جميع الأرصدة</button>
              </div>
              <div className="bg-card rounded-[14px] border border-border overflow-hidden">
                <div className="overflow-x-auto garfix-scroll">
                  <table className="w-full border-collapse">
                    <thead><tr className="border-b border-border bg-muted">
                      <th scope="col" className={thStyle}>كود الحساب</th><th scope="col" className={thStyle}>اسم الحساب</th>
                      <th scope="col" className={thStyle}>المبلغ</th><th scope="col" className={thStyle}>الحالة</th>
                    </tr></thead>
                    <tbody>
                      {openingBalances.map((ob) => (
                        <tr key={ob.id} className="border-b border-border">
                          <td className={cn(tdStyle, "font-mono font-bold")}>{ob.accountCode}</td>
                          <td className={tdStyle}>{ob.accountNameAr}</td>
                          <td className={cn(tdStyle, "[direction:ltr] text-end font-bold")}>{fmt(ob.amount)}</td>
                          <td className={tdStyle}><span className={cn("py-0.5 px-2.5 rounded-[12px] text-[11px] font-bold", ob.posted ? "bg-emerald-500/15 text-emerald-500" : "bg-amber-500/15 text-amber-500")}>{ob.posted ? "مُرحّل" : "مسودة"}</span></td>
                        </tr>
                      ))}
                    </tbody>
                  </table>
                </div>
              </div>
            </div>
          );
        }

        /* ── Commissions Tab ───────────────────────────────────────────────────── */
        if (tab === "commissions") {
          if (commissions.length === 0) return <Empty label="عمولات" />;
          return (
            <div className="bg-card rounded-[14px] border border-border overflow-hidden">
              <div className="overflow-x-auto garfix-scroll">
                <table className="w-full border-collapse">
                  <thead><tr className="border-b border-border bg-muted">
                    <th scope="col" className={thStyle}>المندوب</th><th scope="col" className={thStyle}>إجمالي المبيعات</th>
                    <th scope="col" className={thStyle}>العمولة</th><th scope="col" className={thStyle}>الحالة</th><th scope="col" className={thStyle}>إجراء</th>
                  </tr></thead>
                  <tbody>
                    {commissions.map((c) => (
                      <tr key={c.id} className="border-b border-border">
                        <td className={cn(tdStyle, "font-bold")}>{c.salesperson}</td>
                        <td className={cn(tdStyle, "[direction:ltr] text-end font-bold")}>{fmt(c.totalSales)}</td>
                        <td className={cn(cn(tdStyle, "[direction:ltr] text-end font-bold"), "text-emerald-500")}>{fmt(c.commissionAmount)}</td>
                        <td className={tdStyle}><span className={cn("py-0.5 px-2.5 rounded-[12px] text-[11px] font-bold", c.posted ? "bg-emerald-500/15 text-emerald-500" : "bg-amber-500/15 text-amber-500")}>{c.posted ? "مُرحّل" : "مسودة"}</span></td>
                        <td className={tdStyle}>
                          {!c.posted && <button onClick={() => handlePostCommission(c.id)} title="ترحيل كقيد يومية" className="w-7 h-7 rounded-md border border-border flex items-center justify-center cursor-pointer hover:bg-emerald-500/10"><CheckCircle2 size={13} className="text-emerald-600" /></button>}
                        </td>
                      </tr>
                    ))}
                  </tbody>
                </table>
              </div>
            </div>
          );
        }

        /* ── Profit Distribution Tab ──────────────────────────────────────────── */
        if (tab === "profit-distribution") {
          if (profitDistributions.length === 0) return <Empty label="توزيعات أرباح" />;
          return (
            <div className="bg-card rounded-[14px] border border-border overflow-hidden">
              <div className="overflow-x-auto garfix-scroll">
                <table className="w-full border-collapse">
                  <thead><tr className="border-b border-border bg-muted">
                    <th scope="col" className={thStyle}>الشريك</th><th scope="col" className={thStyle}>نسبة الملكية %</th>
                    <th scope="col" className={thStyle}>حصة الأرباح</th><th scope="col" className={thStyle}>الحالة</th><th scope="col" className={thStyle}>إجراء</th>
                  </tr></thead>
                  <tbody>
                    {profitDistributions.map((pd) => (
                      <tr key={pd.id} className="border-b border-border">
                        <td className={cn(tdStyle, "font-bold")}>{pd.partnerName}</td>
                        <td className={cn(tdStyle, "[direction:ltr] text-end")}>{pd.ownershipPercent}%</td>
                        <td className={cn(cn(tdStyle, "[direction:ltr] text-end font-bold"), "text-emerald-500")}>{fmt(pd.profitShare)}</td>
                        <td className={tdStyle}><span className={cn("py-0.5 px-2.5 rounded-[12px] text-[11px] font-bold", pd.posted ? "bg-emerald-500/15 text-emerald-500" : "bg-amber-500/15 text-amber-500")}>{pd.posted ? "مُرحّل" : "مسودة"}</span></td>
                        <td className={tdStyle}>
                          {!pd.posted && <button onClick={() => handlePostProfitDist(pd.id)} title="ترحيل كقيد يومية" className="w-7 h-7 rounded-md border border-border flex items-center justify-center cursor-pointer hover:bg-emerald-500/10"><CheckCircle2 size={13} className="text-emerald-600" /></button>}
                        </td>
                      </tr>
                    ))}
                  </tbody>
                </table>
              </div>
            </div>
          );
        }
        return null;
      })()}
    </div>
  );
}

"use client";

import { useEffect, useState, useCallback } from "react";
import { authedFetch } from "@/context/AuthContext";
import { toast } from "sonner";
import { Network, RefreshCw, Zap, Gauge, Activity } from "lucide-react";
import { decorativeIconProps } from "@/lib/a11y";
import { Switch } from "@/components/ui/switch";
import { KpiCard } from "./shared-helpers";

/**
 * AI Orchestration Layer — Model Registry + Smart Router + Health Score +
 * Cost Optimizer dashboard.
 *
 * Surfaces the self-tuning AI model fleet: each model's live health score
 * (success + latency + cost + quality), the capability→primary-model routing
 * matrix, the cost-optimizer decision counts (pattern/cache hits = savings),
 * and a "Run Benchmark Now" button that re-tests every enabled model.
 */
export function AiOrchestrationTab() {
  const [data, setData] = useState<null | {
    registry: Array<{
      id: number; provider: string; model: string; displayName: string;
      capabilities: string[]; tier: string; costPer1kIn: number; costPer1kOut: number;
      maxTokens: number; contextWindow: number; isEnabled: boolean; isHealthy: boolean;
      healthScore: number; successRate: number; avgLatencyMs: number; p95LatencyMs: number;
      avgQualityScore: number; totalBenchmarks: number;
      lastBenchmarkAt: string | null; lastError: string | null;
    }>;
    routingMatrix: Array<{
      capability: string;
      primary: { provider: string; model: string; displayName: string; healthScore: number; tier: string } | null;
      candidateCount: number;
    }>;
    optimizerStats: {
      counts: { "use-pattern": number; "use-cache": number; "route-free": number; "route-best": number };
      callsAvoided: number;
      estSavingsUsd: number;
    };
    recentBenchmarks: Array<{
      id: number; modelRegistryId: number; capability: string; success: boolean;
      latencyMs: number; tokensIn: number; tokensOut: number; responseQuality: number;
      errorMessage: string | null; createdAt: string;
    }>;
  }>(null);
  const [loading, setLoading] = useState(true);
  const [running, setRunning] = useState(false);

  const load = useCallback(async () => {
    setLoading(true);
    try {
      const res = await authedFetch("/api/platform-admin/ai-orchestration");
      const d = await res.json();
      if (res.ok) setData(d);
      else toast.error(d.error || "تعذّر التحميل");
    } finally {
      setLoading(false);
    }
  }, []);

  // eslint-disable-next-line react-hooks/set-state-in-effect
  useEffect(() => { load(); }, [load]);

  const runBenchmark = useCallback(async () => {
    setRunning(true);
    try {
      const res = await authedFetch("/api/platform-admin/ai-orchestration/run-benchmark", { method: "POST" });
      const d = await res.json();
      if (res.ok) {
        toast.success(`اكتمل الاختبار: ${d.passed}/${d.totalTests} اختبار ناجح`);
        await load();
      } else {
        toast.error(d.error || "فشل تشغيل الاختبار");
      }
    } catch (err) {
      toast.error(err instanceof Error ? err.message : "فشل الاتصال");
    } finally {
      setRunning(false);
    }
  }, [load]);

  const toggleModel = useCallback(async (provider: string, model: string, isEnabled: boolean) => {
    try {
      const res = await authedFetch("/api/platform-admin/ai-orchestration", {
        method: "PATCH",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({ provider, model, isEnabled }),
      });
      if (res.ok) {
        toast.success(isEnabled ? "تم تفعيل النموذج" : "تم تعطيل النموذج");
        await load();
      } else {
        toast.error("فشل التحديث");
      }
    } catch {
      toast.error("فشل الاتصال");
    }
  }, [load]);

  if (loading) return <div className="p-6 md:p-12 text-center text-[var(--muted-foreground)]">جارٍ التحميل…</div>;
  if (!data) return <div className="p-6 md:p-12 text-center text-[var(--muted-foreground)]">تعذّر تحميل البيانات</div>;

  const fmtMs = (ms: number | null): string => {
    if (!ms) return "—";
    if (ms >= 1000) return `${(ms / 1000).toFixed(1)}s`;
    return `${ms}ms`;
  };
  const healthClass = (s: number) => s >= 7 ? "text-emerald-500" : s >= 4 ? "text-amber-500" : "text-red-500";
  const tierBadge = (tier: string) => tier === "free"
    ? { bg: "bg-green-100", fg: "text-green-600", label: "مجاني" }
    : { bg: "bg-amber-100", fg: "text-amber-600", label: "مدفوع" };
  const capLabel: Record<string, string> = {
    chat: "محادثة", "invoice-extraction": "استخراج الفواتير", reasoning: "استدلال", vision: "رؤية",
  };

  const successRateClass = (r: number) => r >= 95 ? "text-emerald-500" : r >= 80 ? "text-amber-500" : "text-red-500";
  const latencyClass = (ms: number | null) => (ms ?? 0) > 5000 ? "text-red-500" : (ms ?? 0) > 2000 ? "text-amber-500" : "text-[var(--foreground)]";

  return (
    <div className="flex flex-col gap-4">
      {/* Header + Run Benchmark button */}
      <div className="flex justify-between items-center gap-3 flex-wrap">
        <div>
          <h3 className="text-base font-extrabold flex items-center gap-2">
            <Network className="text-violet-600" size={18} {...decorativeIconProps} /> طبقة تنسيق الذكاء الاصطناعي
          </h3>
          <p className="text-xs text-[var(--muted-foreground)] mt-1">
            سجل النماذج + درجة الصحة + التوجيه الذكي + مُحسّن التكلفة — اختيار النموذج آلي بناءً على بيانات الأداء الحية
          </p>
        </div>
        <button
          onClick={runBenchmark}
          disabled={running}
          className={`inline-flex items-center gap-2 px-4.5 py-2.5 rounded-[10px] border border-[var(--border)] font-inherit text-[13px] font-bold ${
            running
              ? "bg-[var(--muted)] text-[var(--muted-foreground)] cursor-not-allowed opacity-70"
              : "bg-violet-600 text-white cursor-pointer"
          }`}
        >
          {running ? <RefreshCw size={15} className="animate-spin" {...decorativeIconProps} /> : <Zap size={15} {...decorativeIconProps} />}
          {running ? "جارٍ الاختبار…" : "تشغيل الاختبار الآن"}
        </button>
      </div>

      {/* KPI row: optimizer impact */}
      <div className="grid grid-cols-[repeat(auto-fit,minmax(150px,1fr))] gap-3">
        <KpiCard label="نداءات وُفّرت (Pattern)" value={data.optimizerStats.counts["use-pattern"]} color="#10b981" />
        <KpiCard label="نداءات وُفّرت (Cache)" value={data.optimizerStats.counts["use-cache"]} color="#3b82f6" />
        <KpiCard label="تُوجّه لمجاني" value={data.optimizerStats.counts["route-free"]} color="#7c3aed" />
        <KpiCard label="تُوجّه للأفضل" value={data.optimizerStats.counts["route-best"]} color="#f59e0b" />
        <KpiCard label="إجمالي نداءات متجنّبة" value={data.optimizerStats.callsAvoided} color="#10b981" />
        <KpiCard label="توفير تقديري ($)" value={data.optimizerStats.estSavingsUsd.toFixed(4)} color="#10b981" />
      </div>

      {/* Routing matrix — primary model per capability */}
      <div className="bg-[var(--card)] rounded-2xl border border-[var(--border)] overflow-hidden">
        <div className="px-4 py-3 border-b border-b-[var(--border)]">
          <h3 className="text-sm font-bold flex items-center gap-2">
            <Gauge className="text-violet-600" size={16} {...decorativeIconProps} /> مصفوفة التوجيه (النموذج الأساسي لكل قدرة)
          </h3>
          <p className="text-[11px] text-[var(--muted-foreground)] mt-1">
            لكل قدرة، يختار النظام تلقائيًا النموذج الأعلى صحةً والمتاح — لا ربط دائم باسم نموذج
          </p>
        </div>
        <div className="garfix_scroll overflow-x-auto">
          <table className="w-full [border-collapse:collapse]">
            <thead><tr className="bg-[var(--muted)]">
              <th scope="col" className="text-right px-3 py-2.5 text-[11px] text-[var(--muted-foreground)] font-bold">القدرة</th><th scope="col" className="text-right px-3 py-2.5 text-[11px] text-[var(--muted-foreground)] font-bold">النموذج الأساسي</th>
              <th scope="col" className="text-right px-3 py-2.5 text-[11px] text-[var(--muted-foreground)] font-bold">المزوّد</th><th scope="col" className="text-right px-3 py-2.5 text-[11px] text-[var(--muted-foreground)] font-bold">درجة الصحة</th>
              <th scope="col" className="text-right px-3 py-2.5 text-[11px] text-[var(--muted-foreground)] font-bold">الطبقة</th><th scope="col" className="text-right px-3 py-2.5 text-[11px] text-[var(--muted-foreground)] font-bold">عدد المرشحين</th>
            </tr></thead>
            <tbody>
              {data.routingMatrix.map((r) => {
                const tb = r.primary ? tierBadge(r.primary.tier) : null;
                return (
                  <tr className="border-b border-b-[var(--border)]" key={r.capability}>
                    <td className="px-3 py-2.5 text-[13px] font-bold">{capLabel[r.capability] || r.capability}</td>
                    <td className="px-3 py-2.5 font-mono text-[12px] [direction:ltr] text-right">
                      {r.primary ? r.primary.displayName : <span className="text-[var(--muted-foreground)]">— لا يوجد مرشح سليم —</span>}
                    </td>
                    <td className="px-3 py-2.5 text-[12px]">{r.primary?.provider || "—"}</td>
                    <td className="px-3 py-2.5 text-[13px] font-bold">
                      {r.primary ? (
                        <span className={healthClass(r.primary.healthScore)}>{r.primary.healthScore.toFixed(1)} / 10</span>
                      ) : "—"}
                    </td>
                    <td className="px-3 py-2.5 text-[13px]">
                      {tb ? (
                        <span className={`px-2 py-0.5 rounded-md text-[11px] font-bold ${tb.bg} ${tb.fg}`}>{tb.label}</span>
                      ) : "—"}
                    </td>
                    <td className="px-3 py-2.5 text-[13px]">{r.candidateCount}</td>
                  </tr>
                );
              })}
            </tbody>
          </table>
        </div>
      </div>

      {/* Model Registry table */}
      <div className="bg-[var(--card)] rounded-2xl border border-[var(--border)] overflow-hidden">
        <div className="px-4 py-3 border-b border-b-[var(--border)]">
          <h3 className="text-sm font-bold flex items-center gap-2">
            <Network className="text-violet-600" size={16} {...decorativeIconProps} /> سجل النماذج ({data.registry.length})
          </h3>
          <p className="text-[11px] text-[var(--muted-foreground)] mt-1">
            كل نموذج + قدراته + طبقته + تكلفته + مقاييس الصحة الحية (تُحدّث تلقائيًا بعد كل اختبار)
          </p>
        </div>
        {data.registry.length === 0 ? (
          <div className="p-6 text-center text-[var(--muted-foreground)] text-xs">
            السجل فارغ — شغّل <code className="bg-[var(--muted)] px-1.5 py-0.5 rounded">bun run scripts/seed-model-registry.ts</code> لملئه
          </div>
        ) : (
          <div className="max-h-[420px] garfix_scroll overflow-x-auto overflow-y-auto">
            <table className="w-full [border-collapse:collapse]">
              <thead><tr className="bg-[var(--muted)] sticky top-0 z-[1]">
                <th scope="col" className="text-right px-3 py-2.5 text-[11px] text-[var(--muted-foreground)] font-bold">النموذج</th><th scope="col" className="text-right px-3 py-2.5 text-[11px] text-[var(--muted-foreground)] font-bold">القدرات</th>
                <th scope="col" className="text-right px-3 py-2.5 text-[11px] text-[var(--muted-foreground)] font-bold">الطبقة</th><th scope="col" className="text-right px-3 py-2.5 text-[11px] text-[var(--muted-foreground)] font-bold">درجة الصحة</th>
                <th scope="col" className="text-right px-3 py-2.5 text-[11px] text-[var(--muted-foreground)] font-bold">النجاح</th><th scope="col" className="text-right px-3 py-2.5 text-[11px] text-[var(--muted-foreground)] font-bold">p50</th>
                <th scope="col" className="text-right px-3 py-2.5 text-[11px] text-[var(--muted-foreground)] font-bold">p95</th><th scope="col" className="text-right px-3 py-2.5 text-[11px] text-[var(--muted-foreground)] font-bold">الجودة</th>
                <th scope="col" className="text-right px-3 py-2.5 text-[11px] text-[var(--muted-foreground)] font-bold">التكلفة/1k</th><th scope="col" className="text-right px-3 py-2.5 text-[11px] text-[var(--muted-foreground)] font-bold">الاختبارات</th>
                <th scope="col" className="text-right px-3 py-2.5 text-[11px] text-[var(--muted-foreground)] font-bold">آخر اختبار</th><th scope="col" className="text-right px-3 py-2.5 text-[11px] text-[var(--muted-foreground)] font-bold">الحالة</th>
              </tr></thead>
              <tbody>
                {data.registry.map((m) => {
                  const tb = tierBadge(m.tier);
                  const costStr = m.tier === "free" ? "$0" : `$${m.costPer1kIn.toFixed(4)}/${m.costPer1kOut.toFixed(4)}`;
                  const last = m.lastBenchmarkAt ? new Date(m.lastBenchmarkAt).toLocaleString("ar-EG", { hour: "2-digit", minute: "2-digit", day: "2-digit", month: "2-digit" }) : "—";
                  return (
                    <tr className="border-b border-b-[var(--border)]" key={m.id}>
                      <td className="px-3 py-2.5 font-mono text-[11px] [direction:ltr] text-right font-bold">
                        {m.provider}/{m.model}
                      </td>
                      <td className="px-3 py-2.5 text-[13px]">
                        <div className="flex gap-1 flex-wrap">
                          {m.capabilities.map((c) => (
                            <span key={c} className="bg-[var(--muted)] px-1.5 py-px rounded text-[10px] font-semibold">{capLabel[c] || c}</span>
                          ))}
                        </div>
                      </td>
                      <td className="px-3 py-2.5 text-[13px]"><span className={`px-2 py-0.5 rounded-md text-[11px] font-bold ${tb.bg} ${tb.fg}`}>{tb.label}</span></td>
                      <td className={`px-3 py-2.5 text-[13px] font-extrabold ${healthClass(m.healthScore)}`}>{m.healthScore.toFixed(1)}</td>
                      <td className={`px-3 py-2.5 text-[13px] font-bold ${successRateClass(m.successRate)}`}>
                        {m.totalBenchmarks > 0 ? `${m.successRate.toFixed(0)}%` : "—"}
                      </td>
                      <td className="px-3 py-2.5 text-[13px] [direction:ltr] text-right">{fmtMs(m.avgLatencyMs)}</td>
                      <td className={`px-3 py-2.5 text-[13px] [direction:ltr] text-right font-bold ${latencyClass(m.p95LatencyMs)}`}>{fmtMs(m.p95LatencyMs)}</td>
                      <td className="px-3 py-2.5 text-[13px] font-bold">{m.totalBenchmarks > 0 ? m.avgQualityScore.toFixed(1) : "—"}</td>
                      <td className="px-3 py-2.5 text-[11px] [direction:ltr] text-right">{costStr}</td>
                      <td className="px-3 py-2.5 text-[13px]">{m.totalBenchmarks}</td>
                      <td className="px-3 py-2.5 text-[11px] text-[var(--muted-foreground)]">{last}</td>
                      <td className="px-3 py-2.5 text-[13px]">
                        <div className="flex items-center gap-1.5">
                          {!m.isHealthy && m.isEnabled && (
                            <span className="bg-red-100 text-red-600 px-1.5 py-px rounded text-[10px] font-bold">غير صحي</span>
                          )}
                          <Switch checked={m.isEnabled} onCheckedChange={(v) => toggleModel(m.provider, m.model, v)} />
                        </div>
                      </td>
                    </tr>
                  );
                })}
              </tbody>
            </table>
          </div>
        )}
      </div>

      {/* Recent benchmark results */}
      {data.recentBenchmarks.length > 0 && (
        <div className="bg-[var(--card)] rounded-2xl border border-[var(--border)] overflow-hidden">
          <div className="px-4 py-3 border-b border-b-[var(--border)]">
            <h3 className="text-sm font-bold flex items-center gap-2">
              <Activity className="text-violet-600" size={16} {...decorativeIconProps} /> آخر نتائج الاختبارات ({data.recentBenchmarks.length})
            </h3>
          </div>
          <div className="max-h-[260px] garfix_scroll overflow-x-auto overflow-y-auto">
            <table className="w-full [border-collapse:collapse]">
              <thead><tr className="bg-[var(--muted)] sticky top-0 z-[1]">
                <th scope="col" className="text-right px-3 py-2.5 text-[11px] text-[var(--muted-foreground)] font-bold">القدرة</th><th scope="col" className="text-right px-3 py-2.5 text-[11px] text-[var(--muted-foreground)] font-bold">الحالة</th><th scope="col" className="text-right px-3 py-2.5 text-[11px] text-[var(--muted-foreground)] font-bold">الزمن</th>
                <th scope="col" className="text-right px-3 py-2.5 text-[11px] text-[var(--muted-foreground)] font-bold">الرموز</th><th scope="col" className="text-right px-3 py-2.5 text-[11px] text-[var(--muted-foreground)] font-bold">الجودة</th><th scope="col" className="text-right px-3 py-2.5 text-[11px] text-[var(--muted-foreground)] font-bold">الوقت</th>
              </tr></thead>
              <tbody>
                {data.recentBenchmarks.slice(0, 20).map((b) => (
                  <tr className="border-b border-b-[var(--border)]" key={b.id}>
                    <td className="px-3 py-2.5 text-[13px] font-bold">{capLabel[b.capability] || b.capability}</td>
                    <td className={`px-3 py-2.5 text-[13px] font-bold ${b.success ? "text-emerald-500" : "text-red-500"}`}>{b.success ? "✓ نجاح" : "✗ فشل"}</td>
                    <td className="px-3 py-2.5 text-[13px] [direction:ltr] text-right">{fmtMs(b.latencyMs)}</td>
                    <td className="px-3 py-2.5 text-[11px] [direction:ltr] text-right">{b.tokensIn}/{b.tokensOut}</td>
                    <td className="px-3 py-2.5 text-[13px] font-bold">{b.responseQuality.toFixed(1)}</td>
                    <td className="px-3 py-2.5 text-[11px] text-[var(--muted-foreground)]">{new Date(b.createdAt).toLocaleTimeString("ar-EG")}</td>
                  </tr>
                ))}
              </tbody>
            </table>
          </div>
        </div>
      )}
    </div>
  );
}

"use client";

import { useEffect, useState, useCallback } from "react";
import { authedFetch } from "@/context/AuthContext";
import { toast } from "sonner";
import { cn } from "@/lib/utils";
import {
  CheckCircle2, XCircle, Loader2, Eye, EyeOff, Save, Zap, KeyRound,
} from "lucide-react";

interface ProviderInfo {
  type: "z-ai" | "openrouter" | "anthropic" | "openai" | "gemini" | "deepseek" | "custom";
  name: string;
  description: string;
  defaultModel: string;
  keyPrefix: string;
  model: string;
  isEnabled: boolean;
  priority: number;
  hasApiKey: boolean;
  apiKeyMasked: string | null;
  baseUrl: string | null;
}

type TestState = "idle" | "testing" | "success" | "fail";

interface CardState {
  apiKey: string;       // local editable field
  model: string;
  priority: string;
  baseUrl: string;
  isEnabled: boolean;
  showKey: boolean;
  testState: TestState;
  testMessage?: string;
  testLatency?: number;
  saving: boolean;
  dirty: boolean;
}

function makeInitialCardState(p: ProviderInfo): CardState {
  return {
    apiKey: "",
    model: p.model || p.defaultModel,
    priority: String(p.priority === 99 ? "" : p.priority),
    baseUrl: p.baseUrl || "",
    isEnabled: p.isEnabled,
    showKey: false,
    testState: "idle",
    saving: false,
    dirty: false,
  };
}

const labelCls = "block text-[11px] font-bold text-muted-foreground mb-1";
const inputCls = "w-full px-3 py-2 rounded-lg bg-background border border-border text-foreground font-[inherit] text-xs outline-none";

export function AiProviderSettings() {
  const [providers, setProviders] = useState<ProviderInfo[] | null>(null);
  const [cards, setCards] = useState<Record<string, CardState>>({});
  const [loading, setLoading] = useState(true);

  const load = useCallback(async () => {
    setLoading(true);
    try {
      const res = await authedFetch("/api/platform-admin/ai-providers");
      if (!res.ok) {
        const e = await res.json().catch(() => ({}));
        throw new Error(e.error || "تعذّر تحميل الإعدادات");
      }
      const data = await res.json();
      const list: ProviderInfo[] = data.providers || [];
      setProviders(list);
      const next: Record<string, CardState> = {};
      for (const p of list) {
        next[p.type] = makeInitialCardState(p);
      }
      setCards(next);
    } catch (err) {
      toast.error(err instanceof Error ? err.message : "خطأ");
      setProviders([]);
    } finally {
      setLoading(false);
    }
  }, []);

  // setState runs inside async .then() callback in load (after await authedFetch) — not synchronous in effect body; no cascading render.
  // eslint-disable-next-line react-hooks/set-state-in-effect
  useEffect(() => { load(); }, [load]);

  const updateCard = (type: string, patch: Partial<CardState>) => {
    setCards((prev) => ({
      ...prev,
      [type]: { ...prev[type], ...patch, dirty: true },
    }));
  };

  const save = async (p: ProviderInfo) => {
    const c = cards[p.type];
    if (!c) return;
    if (c.priority && !/^[1-9]$/.test(c.priority)) {
      toast.error("الأولوية يجب أن تكون رقماً بين 1 و 9");
      return;
    }
    setCards((prev) => ({ ...prev, [p.type]: { ...prev[p.type], saving: true } }));
    try {
      const body: Record<string, unknown> = {
        provider: p.type,
        model: c.model,
        isEnabled: c.isEnabled,
      };
      if (c.priority) body.priority = Number(c.priority);
      if (c.apiKey.trim()) body.apiKey = c.apiKey.trim();
      if (p.type === "custom" && c.baseUrl.trim()) body.baseUrl = c.baseUrl.trim();

      const res = await authedFetch("/api/platform-admin/ai-providers", {
        method: "PATCH",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify(body),
      });
      if (!res.ok) {
        const e = await res.json().catch(() => ({}));
        throw new Error(e.error || "فشل الحفظ");
      }
      toast.success(`تم حفظ إعدادات ${p.name}`);
      // Reload to refresh masked key + hasApiKey flag
      await load();
    } catch (err) {
      toast.error(err instanceof Error ? err.message : "خطأ");
      setCards((prev) => ({ ...prev, [p.type]: { ...prev[p.type], saving: false } }));
    }
  };

  const test = async (p: ProviderInfo) => {
    // If user typed a new key but hasn't saved, prompt them to save first.
    const c = cards[p.type];
    if (!c) return;
    if (c.apiKey.trim() && c.dirty) {
      toast.warning("احفظ المفتاح الجديد أولاً قبل اختبار الاتصال");
      return;
    }
    updateCard(p.type, { testState: "testing", testMessage: undefined, testLatency: undefined });
    try {
      const res = await authedFetch("/api/platform-admin/ai-providers/test", {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({ provider: p.type }),
      });
      const data = await res.json();
      if (data.ok) {
        updateCard(p.type, {
          testState: "success",
          testMessage: `نجح الاتصال (${data.latencyMs || 0}ms)`,
          testLatency: data.latencyMs,
        });
        toast.success(`الاتصال بـ ${p.name} يعمل`);
      } else {
        updateCard(p.type, {
          testState: "fail",
          testMessage: data.error || "فشل الاتصال",
        });
        toast.error(`فشل اتصال ${p.name}: ${data.error || "غير معروف"}`);
      }
    } catch (err) {
      updateCard(p.type, {
        testState: "fail",
        testMessage: err instanceof Error ? err.message : "خطأ",
      });
      toast.error("فشل الاتصال");
    }
  };

  if (loading) {
    return (
      <div className="p-8 sm:p-12 text-center text-muted-foreground">
        <Loader2 size={24} className="animate-spin block mx-auto mb-3" />
        جارٍ تحميل إعدادات مزودي الذكاء الاصطناعي…
      </div>
    );
  }

  if (!providers || providers.length === 0) {
    return (
      <div className="p-6 sm:p-8 text-center text-muted-foreground">
        تعذّر تحميل المزودين. تحقّق من صلاحيات المؤسس.
      </div>
    );
  }

  return (
    <div className="flex flex-col gap-3 sm:gap-4">
      <div className="flex items-center gap-2.5 px-3 sm:px-4 py-2 sm:py-3 rounded-xl bg-card border border-border">
        <img src="/logo.svg" alt="" className="w-5 h-5 rounded shrink-0" />
        <div className="flex-1">
          <div className="text-sm font-extrabold">إعدادات مزودي الذكاء الاصطناعي</div>
          <div className="text-xs text-muted-foreground">
            اضبط المزودين بترتيب الأولوية — عند فشل المزود الأساسي ينتقل النظام تلقائياً للتالي.
          </div>
        </div>
      </div>

      <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-3 gap-3 sm:gap-4">
        {providers.map((p) => {
          const c = cards[p.type];
          if (!c) return null;
          const isCustom = p.type === "custom";
          const needsKey = p.type !== "z-ai";
          return (
            <div
              key={p.type}
              className={cn(
                "bg-card rounded-[14px] p-3 sm:p-[18px] flex flex-col gap-3 transition-all duration-200",
                p.isEnabled ? "border border-purple-500/35 opacity-100 shadow-[0_4px_16px_rgba(124,58,237,0.08)]" : "border border-border opacity-[0.85] shadow-none"
              )}
            >
              {/* Header row */}
              <div className="flex items-start gap-2.5">
                <div
                  className={cn(
                    "w-10 h-10 rounded-[10px] flex items-center justify-center shrink-0",
                    p.isEnabled ? "bg-gradient-to-br from-violet-600 to-violet-400 text-white" : "bg-muted text-muted-foreground"
                  )}
                >
                  <img src="/logo.svg" alt="" className="w-5 h-5 rounded" />
                </div>
                <div className="flex-1 min-w-0">
                  <div className="flex items-center gap-2">
                    <span className="text-sm font-extrabold">{p.name}</span>
                    {/* Status dot */}
                    <span
                      title={p.isEnabled ? "مفعّل" : "معطّل"}
                      className={cn(
                        "w-[9px] h-[9px] rounded-full inline-block",
                        p.isEnabled ? "bg-green-500 shadow-[0_0_6px_#22c55e]" : "bg-gray-400 shadow-none"
                      )}
                    />
                  </div>
                  <div className="text-xs text-muted-foreground mt-0.5 leading-[1.5]">
                    {p.description}
                  </div>
                </div>
                {/* Enable/disable toggle */}
                <button
                  role="switch"
                  aria-checked={c.isEnabled}
                  aria-label={`تفعيل ${p.name}`}
                  onClick={() => updateCard(p.type, { isEnabled: !c.isEnabled })}
                  className={cn(
                    "w-11 h-6 rounded-full border border-border relative shrink-0 transition-[background] duration-150 cursor-pointer",
                    c.isEnabled ? "bg-green-500" : "bg-muted"
                  )}
                >
                  <span
                    className={cn("absolute top-0.5 w-[18px] h-[18px] rounded-full bg-white shadow-[0_1px_3px_rgba(0,0,0,0.3)] transition-[left] duration-150", c.isEnabled ? "left-[22px]" : "left-[2px]")}
                  />
                </button>
              </div>

              {/* Model field */}
              <div>
                <label className={labelCls}>الموديل (Model)</label>
                <input
                  value={c.model}
                  onChange={(e) => updateCard(p.type, { model: e.target.value })}
                  placeholder={p.defaultModel || "model-name"}
                  className={inputCls}
                />
              </div>

              {/* Base URL for custom only */}
              {isCustom && (
                <div>
                  <label className={labelCls}>Base URL (OpenAI-compatible)</label>
                  <input
                    value={c.baseUrl}
                    onChange={(e) => updateCard(p.type, { baseUrl: e.target.value })}
                    placeholder="https://my-llm.example.com/v1"
                    dir="ltr"
                    className={cn(inputCls, "text-left")}
                  />
                </div>
              )}

              {/* API key field (masked) */}
              {needsKey && (
                <div>
                  <label className={labelCls}>
                    <span className="inline-flex items-center gap-1.5">
                      <KeyRound size={11} /> مفتاح API
                    </span>
                  </label>
                  <div className="flex gap-1.5">
                    <input
                      type={c.showKey ? "text" : "password"}
                      value={c.apiKey}
                      onChange={(e) => updateCard(p.type, { apiKey: e.target.value })}
                      placeholder={p.hasApiKey ? (p.apiKeyMasked || "••••••••") : (p.keyPrefix ? `يبدأ بـ ${p.keyPrefix}…` : "أدخل المفتاح")}
                      dir="ltr"
                      className={cn(inputCls, "text-left flex-1")}
                    />
                    <button
                      type="button"
                      onClick={() => updateCard(p.type, { showKey: !c.showKey })}
                      title={c.showKey ? "إخفاء" : "إظهار"}
                      className="w-9 rounded-lg bg-muted border border-border text-muted-foreground cursor-pointer flex items-center justify-center"
                    >
                      {c.showKey ? <EyeOff size={14} /> : <Eye size={14} />}
                    </button>
                  </div>
                  {p.hasApiKey && !c.apiKey && (
                    <div className="text-[10px] text-muted-foreground mt-1">
                      مفتاح محفوظ ({p.apiKeyMasked}). اترك الحقل فارغاً للاحتفاظ به، أو اكتب مفتاحاً جديداً للاستبدال.
                    </div>
                  )}
                </div>
              )}

              {/* Priority field */}
              <div className="grid grid-cols-1 sm:grid-cols-2 gap-2 sm:gap-2.5">
                <div>
                  <label className={labelCls}>الأولوية (1 = أساسي)</label>
                  <input
                    type="number" min={1} max={9}
                    value={c.priority}
                    onChange={(e) => updateCard(p.type, { priority: e.target.value })}
                    placeholder="99"
                    className={inputCls}
                  />
                </div>
                {/* Test result */}
                <div>
                  <label className={labelCls}>حالة الاتصال</label>
                  <div
                    className={cn(
                      "w-full px-2.5 py-2 rounded-lg font-[inherit] text-[11px] outline-none flex items-center gap-1.5 text-foreground",
                      c.testState === "success" ? "bg-green-500/10 border border-green-500/40" : "",
                      c.testState === "fail" ? "bg-red-500/10 border border-red-500/40" : "",
                      (c.testState === "idle" || c.testState === "testing") ? "bg-background border border-border" : ""
                    )}
                  >
                    {c.testState === "testing" && <Loader2 size={12} className="animate-spin" />}
                    {c.testState === "success" && <CheckCircle2 size={12} color="#22c55e" />}
                    {c.testState === "fail" && <XCircle size={12} color="#ef4444" />}
                    <span className="overflow-hidden text-ellipsis whitespace-nowrap">
                      {c.testState === "idle" && "لم يُختبر بعد"}
                      {c.testState === "testing" && "جارٍ الاختبار…"}
                      {c.testState === "success" && (c.testMessage || "نجح")}
                      {c.testState === "fail" && (c.testMessage || "فشل")}
                    </span>
                  </div>
                </div>
              </div>

              {/* Action buttons */}
              <div className="flex gap-2 mt-1">
                <button
                  onClick={() => test(p)}
                  disabled={c.testState === "testing"}
                  className={cn(
                    "inline-flex items-center gap-1.5 px-3.5 py-2 rounded-[9px] bg-muted text-foreground border border-border font-[inherit] text-xs font-bold",
                    c.testState === "testing" ? "cursor-not-allowed opacity-60" : "cursor-pointer"
                  )}
                >
                  {c.testState === "testing" ? <Loader2 size={13} className="animate-spin" /> : <Zap size={13} />}
                  اختبار اتصال
                </button>
                <button
                  onClick={() => save(p)}
                  disabled={c.saving || !c.dirty}
                  className={cn(
                    "inline-flex items-center gap-1.5 px-3.5 py-2 rounded-[9px] flex-1 font-[inherit] text-xs font-bold transition-all duration-200",
                    c.dirty ? "bg-gradient-to-br from-violet-600 to-violet-400 text-white border-none shadow-[0_4px_12px_rgba(124,58,237,0.25)]" : "bg-muted text-muted-foreground border border-border shadow-none",
                    c.saving ? "opacity-70 cursor-not-allowed" : (c.dirty ? "cursor-pointer" : "cursor-not-allowed")
                  )}
                >
                  {c.saving ? <Loader2 size={13} className="animate-spin" /> : <Save size={13} />}
                  حفظ
                </button>
              </div>
            </div>
          );
        })}
      </div>
    </div>
  );
}

export default AiProviderSettings;

