"use client";

import { useEffect, useState, useCallback, useMemo } from "react";
import { authedFetch } from "@/context/AuthContext";
import {
  History, Search, Download, Filter, RefreshCw, ChevronLeft, ChevronRight,
  Eye, Wifi, WifiOff, X, FileSpreadsheet, User, Building2, Calendar,
  Shield, Clock,
} from "lucide-react";
import { cn } from "@/lib/utils";
import { Card, CardContent, CardHeader, CardTitle, CardDescription } from "@/components/ui/card";
import { Button } from "@/components/ui/button";
import { Badge } from "@/components/ui/badge";
import { Input } from "@/components/ui/input";
import {
  Select, SelectContent, SelectItem, SelectTrigger, SelectValue,
} from "@/components/ui/select";
import {
  Dialog, DialogContent, DialogHeader, DialogTitle, DialogDescription, DialogFooter,
} from "@/components/ui/dialog";
import {
  Table, TableBody, TableCell, TableHead, TableHeader, TableRow,
} from "@/components/ui/table";

/* ── Types ───────────────────────────────────────────────────────────── */

interface AuditLog {
  id: number;
  userEmail: string;
  userUid: string;
  action: string;
  entity: string;
  entityId?: string | null;
  companySlug?: string | null;
  details?: Record<string, unknown> | null;
  createdAt: string;
}

interface FilterState {
  action: string;
  companySlug: string;
  userEmail: string;
  startDate: string;
  endDate: string;
}

const ACTION_OPTIONS = [
  { value: "", label: "كل الإجراءات" },
  { value: "create", label: "إنشاء" },
  { value: "update", label: "تحديث" },
  { value: "delete", label: "حذف" },
  { value: "login_success", label: "تسجيل دخول ناجح" },
  { value: "login_failure", label: "تسجيل دخول فاشل" },
  { value: "logout", label: "تسجيل خروج" },
  { value: "register", label: "تسجيل حساب" },
  { value: "payment", label: "دفعة" },
  { value: "status_change", label: "تغيير حالة" },
  { value: "ai_chat", label: "محادثة AI" },
];

const PAGE_SIZE = 20;

/* ── Action Badge Color ──────────────────────────────────────────────── */

function getActionColor(action: string): string {
  if (action.includes("create")) return "bg-emerald-500/20 text-emerald-400 border-emerald-500/30";
  if (action.includes("update")) return "bg-blue-500/20 text-blue-400 border-blue-500/30";
  if (action.includes("delete")) return "bg-red-500/20 text-red-400 border-red-500/30";
  if (action.includes("login_success")) return "bg-green-500/20 text-green-400 border-green-500/30";
  if (action.includes("login_failure")) return "bg-red-500/20 text-red-400 border-red-500/30";
  if (action.includes("payment")) return "bg-amber-500/20 text-amber-400 border-amber-500/30";
  if (action.includes("ai")) return "bg-purple-500/20 text-purple-400 border-purple-500/30";
  return "bg-white/10 text-white/60 border-white/20";
}

/* ── Component ────────────────────────────────────────────────────────── */

export function EnhancedAuditView() {
  const [logs, setLogs] = useState<AuditLog[]>([]);
  const [loading, setLoading] = useState(true);
  const [filters, setFilters] = useState<FilterState>({
    action: "",
    companySlug: "",
    userEmail: "",
    startDate: "",
    endDate: "",
  });
  const [page, setPage] = useState(1);
  const [selectedLog, setSelectedLog] = useState<AuditLog | null>(null);
  const [isOnline, setIsOnline] = useState(true);
  const [isRefreshing, setIsRefreshing] = useState(false);

  // Online status
  useEffect(() => {
    setIsOnline(navigator.onLine);
    const onOffline = () => setIsOnline(false);
    const onOnline = () => setIsOnline(true);
    window.addEventListener("offline", onOffline);
    window.addEventListener("online", onOnline);
    return () => {
      window.removeEventListener("offline", onOffline);
      window.removeEventListener("online", onOnline);
    };
  }, []);

  const load = useCallback(async () => {
    setIsRefreshing(true);
    setLoading(true);
    try {
      const params = new URLSearchParams();
      if (filters.action) params.set("action", filters.action);
      if (filters.companySlug) params.set("companySlug", filters.companySlug);
      if (filters.userEmail) params.set("userEmail", filters.userEmail);
      if (filters.startDate) params.set("startDate", filters.startDate);
      if (filters.endDate) params.set("endDate", filters.endDate);
      params.set("limit", "500");
      const res = await authedFetch(`/api/audit?${params.toString()}`);
      if (res.ok) {
        const data = await res.json();
        setLogs(data.logs || []);
      }
    } catch {
      // Graceful error handling
    } finally {
      setLoading(false);
      setIsRefreshing(false);
    }
  }, [filters.action, filters.companySlug, filters.userEmail, filters.startDate, filters.endDate]);

  // eslint-disable-next-line react-hooks/set-state-in-effect
  useEffect(() => { load(); }, [load]);

  // Client-side filtering + pagination
  const filteredLogs = useMemo(() => {
    let result = logs;

    if (filters.userEmail) {
      const q = filters.userEmail.toLowerCase();
      result = result.filter((l) => l.userEmail.toLowerCase().includes(q));
    }
    if (filters.action) {
      result = result.filter((l) => l.action === filters.action);
    }
    if (filters.companySlug) {
      result = result.filter((l) => l.companySlug === filters.companySlug);
    }
    if (filters.startDate) {
      result = result.filter((l) => new Date(l.createdAt) >= new Date(filters.startDate));
    }
    if (filters.endDate) {
      result = result.filter((l) => new Date(l.createdAt) <= new Date(filters.endDate + "T23:59:59"));
    }

    return result;
  }, [logs, filters]);

  const totalPages = Math.ceil(filteredLogs.length / PAGE_SIZE);
  const paginatedLogs = useMemo(() => {
    const start = (page - 1) * PAGE_SIZE;
    return filteredLogs.slice(start, start + PAGE_SIZE);
  }, [filteredLogs, page]);

  // Unique company slugs for filter dropdown
  const companySlugs = useMemo(() => {
    const slugs = new Set(logs.map((l) => l.companySlug).filter(Boolean));
    return Array.from(slugs) as string[];
  }, [logs]);

  // Export to CSV
  const exportCSV = useCallback(() => {
    const headers = ["ID", "User", "Action", "Entity", "EntityID", "Company", "Details", "Date"];
    const rows = filteredLogs.map((l) => [
      l.id,
      l.userEmail,
      l.action,
      l.entity,
      l.entityId || "",
      l.companySlug || "",
      l.details ? JSON.stringify(l.details) : "",
      new Date(l.createdAt).toISOString(),
    ]);

    const csv = [headers.join(","), ...rows.map((r) => r.map((c) => `"${String(c).replace(/"/g, '""')}"`).join(","))].join("\n");

    const blob = new Blob(["\uFEFF" + csv], { type: "text/csv;charset=utf-8" }); // BOM for Arabic in Excel
    const url = URL.createObjectURL(blob);
    const a = document.createElement("a");
    a.href = url;
    a.download = `audit-log-${new Date().toISOString().slice(0, 10)}.csv`;
    a.click();
    URL.revokeObjectURL(url);
  }, [filteredLogs]);

  // Clear filters
  const clearFilters = () => {
    setFilters({ action: "", companySlug: "", userEmail: "", startDate: "", endDate: "" });
    setPage(1);
  };

  const hasFilters = filters.action || filters.companySlug || filters.userEmail || filters.startDate || filters.endDate;

  return (
    <div dir="rtl" className="flex flex-col gap-3 sm:gap-4">
      {/* ── Header ─────────────────────────────────────────────────── */}
      <div className="flex flex-col sm:flex-row flex-wrap items-center justify-between gap-3">
        <div>
          <h1 className="text-lg sm:text-xl md:text-2xl font-extrabold flex items-center gap-2">
            <History size={20} />
            سجل التدقيق
          </h1>
          <p className="text-[13px] text-[var(--muted-foreground)]">
            {filteredLogs.length} سجل {hasFilters ? `(مفلتر من ${logs.length})` : ""}
          </p>
        </div>
        <div className="flex items-center gap-1.5 sm:gap-2 flex-wrap">
          {/* Real-time status indicator */}
          <Badge
            variant="outline"
            className={cn(
              "text-[11px] font-bold",
              isOnline
                ? "bg-emerald-500/10 text-emerald-400 border-emerald-500/20"
                : "bg-red-500/10 text-red-400 border-red-500/20"
            )}
          >
            {isOnline ? <Wifi size={12} className="ms-1" /> : <WifiOff size={12} className="ms-1" />}
            {isOnline ? "متصل" : "غير متصل"}
          </Badge>
          <Button variant="outline" size="sm" onClick={load} disabled={isRefreshing}>
            <RefreshCw size={14} className={cn("ms-1", isRefreshing && "animate-spin")} />
            تحديث
          </Button>
          <Button variant="outline" size="sm" onClick={exportCSV} disabled={filteredLogs.length === 0}>
            <Download size={14} className="ms-1" />
            تصدير CSV
          </Button>
        </div>
      </div>

      {/* ── Filters ────────────────────────────────────────────────── */}
      <Card>
        <CardContent className="pt-4 pb-4">
          <div className="flex flex-wrap items-center gap-3">
            <div className="flex items-center gap-1.5">
              <Filter size={14} className="text-[var(--muted-foreground)]" />
              <span className="text-sm font-bold">الفلاتر</span>
            </div>

            <Select
              value={filters.action}
              onValueChange={(v) => setFilters((f) => ({ ...f, action: v }))}
            >
              <SelectTrigger className="w-full sm:w-[160px]">
                <SelectValue placeholder="كل الإجراءات" />
              </SelectTrigger>
              <SelectContent>
                {ACTION_OPTIONS.map((opt) => (
                  <SelectItem key={opt.value} value={opt.value || "__all__"}>
                    {opt.label}
                  </SelectItem>
                ))}
              </SelectContent>
            </Select>

            <Select
              value={filters.companySlug || "__all__"}
              onValueChange={(v) => setFilters((f) => ({ ...f, companySlug: v === "__all__" ? "" : v }))}
            >
              <SelectTrigger className="w-full sm:w-[160px]">
                <SelectValue placeholder="كل الشركات" />
              </SelectTrigger>
              <SelectContent>
                <SelectItem value="__all__">كل الشركات</SelectItem>
                {companySlugs.map((slug) => (
                  <SelectItem key={slug} value={slug}>{slug}</SelectItem>
                ))}
              </SelectContent>
            </Select>

            <div className="relative flex-1 min-w-0 sm:min-w-[180px] sm:max-w-[260px]">
              <Search size={14} className="absolute start-3 top-[50%] -translate-y-[50%] text-[var(--muted-foreground)]" />
              <Input
                placeholder="بحث بالبريد الإلكتروني..."
                value={filters.userEmail}
                onChange={(e) => setFilters((f) => ({ ...f, userEmail: e.target.value }))}
                className="ps-9"
                dir="ltr"
              />
            </div>

            <Input
              type="date"
              value={filters.startDate}
              onChange={(e) => setFilters((f) => ({ ...f, startDate: e.target.value }))}
              className="w-full sm:w-[140px]"
              placeholder="من تاريخ"
            />
            <Input
              type="date"
              value={filters.endDate}
              onChange={(e) => setFilters((f) => ({ ...f, endDate: e.target.value }))}
              className="w-full sm:w-[140px]"
              placeholder="إلى تاريخ"
            />

            {hasFilters && (
              <Button variant="ghost" size="sm" onClick={clearFilters}>
                <X size={14} className="ms-1" />
                إزالة الفلاتر
              </Button>
            )}
          </div>
        </CardContent>
      </Card>

      {/* ── Table ──────────────────────────────────────────────────── */}
      <Card>
        <CardContent className="p-0">
          {loading ? (
            <div className="py-12 text-center text-[var(--muted-foreground)]">
              <RefreshCw size={24} className="animate-spin mx-auto mb-3" />
              جارٍ التحميل…
            </div>
          ) : filteredLogs.length === 0 ? (
            <div className="py-12 text-center text-[var(--muted-foreground)]">
              <History size={24} className="mx-auto mb-3 opacity-30" />
              لا توجد سجلات
              {hasFilters && (
                <Button variant="outline" size="sm" onClick={clearFilters} className="mt-3">
                  إزالة الفلاتر
                </Button>
              )}
            </div>
          ) : (
            <div className="overflow-x-auto garfix-scroll">
              <Table>
                <TableHeader>
                  <TableRow className="bg-[var(--muted)]">
                    <TableHead className="text-right text-[11px] font-bold">
                      <Clock size={12} className="inline ms-1" />
                      الوقت
                    </TableHead>
                    <TableHead className="text-right text-[11px] font-bold">
                      <User size={12} className="inline ms-1" />
                      المستخدم
                    </TableHead>
                    <TableHead className="text-right text-[11px] font-bold">
                      <Shield size={12} className="inline ms-1" />
                      الإجراء
                    </TableHead>
                    <TableHead className="text-right text-[11px] font-bold hidden md:table-cell">الكيان</TableHead>
                    <TableHead className="text-right text-[11px] font-bold hidden md:table-cell">المعرّف</TableHead>
                    <TableHead className="text-right text-[11px] font-bold">
                      <Building2 size={12} className="inline ms-1" />
                      الشركة
                    </TableHead>
                    <TableHead className="text-right text-[11px] font-bold">تفاصيل</TableHead>
                  </TableRow>
                </TableHeader>
                <TableBody>
                  {paginatedLogs.map((l) => (
                    <TableRow key={l.id} className="cursor-pointer hover:bg-[var(--accent)]" onClick={() => setSelectedLog(l)}>
                      <TableCell className="text-[13px]">{new Date(l.createdAt).toLocaleString("ar-EG")}</TableCell>
                      <TableCell className="text-[13px] direction-ltr text-right" dir="ltr">{l.userEmail}</TableCell>
                      <TableCell>
                        <Badge variant="outline" className={cn("text-[11px] font-bold", getActionColor(l.action))}>
                          {l.action}
                        </Badge>
                      </TableCell>
                      <TableCell className="text-[13px] hidden md:table-cell">{l.entity}</TableCell>
                      <TableCell className="text-[13px] font-mono hidden md:table-cell">{l.entityId || "—"}</TableCell>
                      <TableCell className="text-[13px] font-mono">{l.companySlug || "—"}</TableCell>
                      <TableCell>
                        <Button variant="ghost" size="icon" className="h-7 w-7" onClick={() => setSelectedLog(l)}>
                          <Eye size={14} />
                        </Button>
                      </TableCell>
                    </TableRow>
                  ))}
                </TableBody>
              </Table>
            </div>
          )}
        </CardContent>
      </Card>

      {/* ── Pagination ─────────────────────────────────────────────── */}
      {!loading && filteredLogs.length > 0 && (
        <div className="flex items-center justify-between gap-3">
          <p className="text-[13px] text-[var(--muted-foreground)]">
            عرض {(page - 1) * PAGE_SIZE + 1} — {Math.min(page * PAGE_SIZE, filteredLogs.length)} من {filteredLogs.length}
          </p>
          <div className="flex items-center gap-1.5">
            <Button
              variant="outline"
              size="icon"
              className="h-8 w-8"
              disabled={page <= 1}
              onClick={() => setPage((p) => p - 1)}
            >
              <ChevronRight size={16} /> {/* RTL: right = previous */}
            </Button>
            <span className="text-sm font-bold">{page}</span>
            <span className="text-[13px] text-[var(--muted-foreground)]">/ {totalPages}</span>
            <Button
              variant="outline"
              size="icon"
              className="h-8 w-8"
              disabled={page >= totalPages}
              onClick={() => setPage((p) => p + 1)}
            >
              <ChevronLeft size={16} /> {/* RTL: left = next */}
            </Button>
          </div>
        </div>
      )}

      {/* ── Detail Modal ───────────────────────────────────────────── */}
      <Dialog open={!!selectedLog} onOpenChange={(open) => !open && setSelectedLog(null)}>
        <DialogContent className="sm:max-w-[560px]" dir="rtl">
          <DialogHeader>
            <DialogTitle className="flex items-center gap-2">
              <Shield size={16} />
              تفاصيل سجل التدقيق #{selectedLog?.id}
            </DialogTitle>
            <DialogDescription>
              عرض تفاصيل إجراء التدقيق
            </DialogDescription>
          </DialogHeader>

          {selectedLog && (
            <div className="flex flex-col gap-4">
              <div className="grid grid-cols-1 sm:grid-cols-2 gap-3">
                <div className="flex flex-col gap-1">
                  <span className="text-[11px] text-[var(--muted-foreground)] font-bold">
                    <Clock size={12} className="inline ms-1" />
                    الوقت
                  </span>
                  <span className="text-[13px]">{new Date(selectedLog.createdAt).toLocaleString("ar-EG")}</span>
                </div>
                <div className="flex flex-col gap-1">
                  <span className="text-[11px] text-[var(--muted-foreground)] font-bold">
                    <User size={12} className="inline ms-1" />
                    المستخدم
                  </span>
                  <span className="text-[13px]" dir="ltr">{selectedLog.userEmail}</span>
                </div>
                <div className="flex flex-col gap-1">
                  <span className="text-[11px] text-[var(--muted-foreground)] font-bold">
                    <Shield size={12} className="inline ms-1" />
                    الإجراء
                  </span>
                  <Badge variant="outline" className={cn("text-[11px] font-bold", getActionColor(selectedLog.action))}>
                    {selectedLog.action}
                  </Badge>
                </div>
                <div className="flex flex-col gap-1">
                  <span className="text-[11px] text-[var(--muted-foreground)] font-bold">
                    <Building2 size={12} className="inline ms-1" />
                    الشركة
                  </span>
                  <span className="text-[13px] font-mono">{selectedLog.companySlug || "—"}</span>
                </div>
                <div className="flex flex-col gap-1">
                  <span className="text-[11px] text-[var(--muted-foreground)] font-bold">الكيان</span>
                  <span className="text-[13px]">{selectedLog.entity}</span>
                </div>
                <div className="flex flex-col gap-1">
                  <span className="text-[11px] text-[var(--muted-foreground)] font-bold">معرّف الكيان</span>
                  <span className="text-[13px] font-mono">{selectedLog.entityId || "—"}</span>
                </div>
              </div>

              {/* Details JSON */}
              {selectedLog.details && (
                <div className="flex flex-col gap-1">
                  <span className="text-[11px] text-[var(--muted-foreground)] font-bold">تفاصيل إضافية</span>
                  <pre className="text-[12px] bg-[var(--muted)] rounded-lg p-3 overflow-x-auto whitespace-pre-wrap leading-relaxed font-mono" dir="ltr">
                    {JSON.stringify(selectedLog.details, null, 2)}
                  </pre>
                </div>
              )}
            </div>
          )}

          <DialogFooter className="flex-row-reverse">
            <Button variant="outline" onClick={() => setSelectedLog(null)}>
              إغلاق
            </Button>
          </DialogFooter>
        </DialogContent>
      </Dialog>
    </div>
  );
}

export default EnhancedAuditView;

"use client";

import { useEffect, useState, useCallback } from "react";
import { authedFetch } from "@/context/AuthContext";
import { toast } from "sonner";
import { FileText, Plus, Save } from "lucide-react";
import { decorativeIconProps } from "@/lib/a11y";
import { Input } from "@/components/ui/input";
import { Textarea } from "@/components/ui/textarea";

/**
 * Admin P2 — Landing Content tab.
 * Wires the previously-orphaned /api/platform-admin/landing-content
 * (GET/PATCH) endpoints into a founder-facing CMS UI. Lists every
 * LandingContent row (key + JSON value + last-updated metadata) and
 * lets the founder inline-edit scalar values (hero title/subtitle/CTA)
 * and JSON-array values (features list). Save calls PATCH with
 * { key, value }.
 *
 * Note: the backend is generic (any key, any JSON value) so this UI
 * stays generic — it renders a key→value editor. The landing page
 * module reads whatever keys it needs; this panel just writes them.
 */
export function LandingContentTab() {
  const [items, setItems] = useState<Array<{
    key: string;
    value: unknown;
    updatedAt: string;
    updatedBy: string | null;
  }>>([]);
  const [drafts, setDrafts] = useState<Record<string, string>>({});
  const [loading, setLoading] = useState(true);
  const [savingKey, setSavingKey] = useState<string | null>(null);
  const [showCreate, setShowCreate] = useState(false);
  const [newKey, setNewKey] = useState("");
  const [newValue, setNewValue] = useState("");

  const load = useCallback(async () => {
    setLoading(true);
    try {
      const res = await authedFetch("/api/platform-admin/landing-content");
      const d = await res.json();
      if (res.ok) {
        setItems(d.items || []);
        // Seed drafts: stringify objects/arrays as pretty JSON; leave strings as-is.
        const seed: Record<string, string> = {};
        for (const it of (d.items || []) as Array<{ key: string; value: unknown }>) {
          seed[it.key] = typeof it.value === "string" ? it.value : JSON.stringify(it.value, null, 2);
        }
        setDrafts(seed);
      } else {
        toast.error(d.error || "تعذّر التحميل");
      }
    } finally {
      setLoading(false);
    }
  }, []);

  // eslint-disable-next-line react-hooks/set-state-in-effect
  useEffect(() => { load(); }, [load]);

  const save = async (key: string) => {
    const raw = drafts[key];
    if (raw === undefined) return;
    // Try to parse JSON; if it fails, send as a plain string.
    let value: unknown = raw;
    const trimmed = raw.trim();
    if (trimmed.startsWith("{") || trimmed.startsWith("[")) {
      try {
        value = JSON.parse(trimmed);
      } catch {
        toast.error("JSON غير صالح — راجع الصياغة");
        return;
      }
    }
    setSavingKey(key);
    try {
      const res = await authedFetch("/api/platform-admin/landing-content", {
        method: "PATCH",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({ key, value }),
      });
      const d = await res.json();
      if (!res.ok) throw new Error(d.error || "Failed");
      toast.success("تم حفظ المحتوى");
      load();
    } catch (err) {
      toast.error(err instanceof Error ? err.message : "خطأ");
    } finally {
      setSavingKey(null);
    }
  };

  const create = async () => {
    if (!newKey.trim()) { toast.error("المفتاح مطلوب"); return; }
    setSavingKey("__new__");
    try {
      let value: unknown = newValue;
      const trimmed = newValue.trim();
      if (trimmed.startsWith("{") || trimmed.startsWith("[")) {
        try { value = JSON.parse(trimmed); } catch {
          toast.error("JSON غير صالح"); setSavingKey(null); return;
        }
      }
      const res = await authedFetch("/api/platform-admin/landing-content", {
        method: "PATCH",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({ key: newKey.trim(), value }),
      });
      const d = await res.json();
      if (!res.ok) throw new Error(d.error || "Failed");
      toast.success("تم إنشاء المحتوى");
      setNewKey(""); setNewValue(""); setShowCreate(false);
      load();
    } catch (err) {
      toast.error(err instanceof Error ? err.message : "خطأ");
    } finally {
      setSavingKey(null);
    }
  };

  if (loading) return <div className="p-6 md:p-12 text-center text-[var(--muted-foreground)]">جارٍ التحميل…</div>;

  return (
    <div className="bg-[var(--card)] rounded-2xl border border-[var(--border)] overflow-hidden">
      <div className="px-4 py-3 border-b border-b-[var(--border)] flex justify-between items-center flex-wrap gap-2">
        <h3 className="text-sm font-bold flex items-center gap-2">
          <FileText className="text-emerald-500" size={16} {...decorativeIconProps} />
          محتوى الصفحة الرئيسية ({items.length})
        </h3>
        <button onClick={() => setShowCreate((v) => !v)} className="inline-flex items-center gap-1 px-3 py-1.5 rounded-lg bg-[var(--primary)] text-[var(--primary-foreground)] border-none font-inherit text-[11px] font-bold cursor-pointer">
          <Plus size={12} {...decorativeIconProps} /> مفتاح جديد
        </button>
      </div>

      {showCreate && (
        <div className="p-4 border-b border-b-[var(--border)] bg-[var(--muted)] flex flex-col gap-2.5">
          <div>
            <label className="block text-[11px] font-semibold text-[var(--muted-foreground)] mb-1">المفتاح (مثال: hero.title)</label>
            <Input value={newKey} onChange={(e) => setNewKey(e.target.value)} placeholder="hero.title" dir="ltr" />
          </div>
          <div>
            <label className="block text-[11px] font-semibold text-[var(--muted-foreground)] mb-1">القيمة (نص أو JSON)</label>
            <Textarea value={newValue} onChange={(e) => setNewValue(e.target.value)} rows={3} placeholder="مرحباً بكم في GarfiX" className="resize-y" />
          </div>
          <button onClick={create} disabled={savingKey === "__new__"} className="self-end inline-flex items-center gap-1.5 px-5 py-2 rounded-lg bg-[var(--primary)] text-[var(--primary-foreground)] border-none font-inherit text-xs font-bold cursor-pointer disabled:opacity-70">
            <Save size={14} {...decorativeIconProps} /> {savingKey === "__new__" ? "جارٍ…" : "إنشاء"}
          </button>
        </div>
      )}

      {items.length === 0 ? (
        <div className="p-4 md:p-8 text-center text-[var(--muted-foreground)]">
          لا يوجد محتوى بعد. أنشئ مفتاحاً جديداً (مثل <code className="font-mono">hero.title</code>) ليقرأه صفحة الواجهة.
        </div>
      ) : (
        <div className="flex flex-col">
          {items.map((it) => {
            const isJson = typeof it.value === "object" && it.value !== null;
            return (
              <div className="px-4 py-3.5 border-b border-b-[var(--border)] flex flex-col gap-2" key={it.key}>
                <div className="flex justify-between items-center gap-2.5 flex-wrap">
                  <code className="font-mono text-xs font-bold [direction:ltr] text-[var(--foreground)]">{it.key}</code>
                  <span className="text-[10px] text-[var(--muted-foreground)]">
                    آخر تحديث: {new Date(it.updatedAt).toLocaleString("ar-EG")} {it.updatedBy ? `• ${it.updatedBy}` : ""}
                  </span>
                </div>
                <Textarea
                  value={drafts[it.key] ?? ""}
                  onChange={(e) => setDrafts({ ...drafts, [it.key]: e.target.value })}
                  rows={isJson ? 5 : 2}
                  className={`resize-y text-xs ${isJson ? "font-mono" : "font-inherit"}`}
                />
                <div className="flex justify-end">
                  <button
                    onClick={() => save(it.key)}
                    disabled={savingKey === it.key}
                    className="inline-flex items-center gap-1.5 px-3.5 py-1.5 rounded-lg bg-[var(--primary)] text-[var(--primary-foreground)] border-none font-inherit text-[11px] font-bold cursor-pointer disabled:opacity-70"
                  >
                    <Save size={12} {...decorativeIconProps} /> {savingKey === it.key ? "جارٍ…" : "حفظ"}
                  </button>
                </div>
              </div>
            );
          })}
        </div>
      )}
    </div>
  );
}

"use client";

import { useEffect, useState, useCallback } from "react";
import { authedFetch } from "@/context/AuthContext";
import { toast } from "sonner";
import { Gauge, Save, AlertTriangle } from "lucide-react";
import { DEFAULT_PLANS, type PlanDef, type PlanCatalog } from "@/lib/plans";

/**
 * PlansTab — Manage the plan catalog (pricing, limits).
 * Reads current plans from GET /api/settings (key: "plans.catalog"),
 * allows editing name, priceMonthly, maxInvoicesPerMonth, maxCompanies, maxUsers,
 * and saves via PATCH /api/settings.
 */
export function PlansTab() {
  const [plans, setPlans] = useState<PlanCatalog>(() => ({ ...DEFAULT_PLANS }));
  const [loading, setLoading] = useState(true);
  const [saving, setSaving] = useState(false);
  const [dirty, setDirty] = useState(false);

  // Load live catalog from settings API
  const load = useCallback(async () => {
    setLoading(true);
    try {
      const res = await authedFetch("/api/settings");
      const data = await res.json();
      if (res.ok) {
        const catalog = data.settings?.["plans.catalog"] || data.defaults?.["plans.catalog"] || DEFAULT_PLANS;
        setPlans(catalog);
        setDirty(false);
      } else {
        toast.error(data.error || "تعذّر تحميل الباقات");
      }
    } catch {
      toast.error("خطأ في الاتصال");
    } finally {
      setLoading(false);
    }
  }, []);

  // eslint-disable-next-line react-hooks/set-state-in-effect
  useEffect(() => { load(); }, [load]);

  const updatePlan = (key: string, field: keyof PlanDef, value: string | number) => {
    setPlans((prev) => ({
      ...prev,
      [key]: { ...prev[key], [field]: value },
    }));
    setDirty(true);
  };

  const save = async () => {
    setSaving(true);
    try {
      // Build a clean catalog with only the editable fields
      const cleanCatalog: Record<string, Record<string, unknown>> = {};
      for (const [key, plan] of Object.entries(plans)) {
        cleanCatalog[key] = {
          name: plan.name,
          priceMonthly: plan.priceMonthly,
          maxInvoicesPerMonth: plan.maxInvoicesPerMonth,
          maxCompanies: plan.maxCompanies,
          maxUsers: plan.maxUsers,
          trialDays: plan.trialDays,
          currency: plan.currency,
          billingPeriod: plan.billingPeriod,
          featureBullets: plan.featureBullets,
          highlight: plan.highlight,
        };
      }
      const res = await authedFetch("/api/settings", {
        method: "PATCH",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({ "plans.catalog": cleanCatalog }),
      });
      const data = await res.json();
      if (!res.ok) throw new Error(data.error || "تعذّر الحفظ");
      toast.success("تم حفظ كتالوج الباقات بنجاح");
      setDirty(false);
    } catch (err) {
      toast.error(err instanceof Error ? err.message : "خطأ");
    } finally {
      setSaving(false);
    }
  };

  const plansInputClass = "w-full px-1.5 py-1 bg-[var(--background)] border border-[var(--border)] rounded-md text-[var(--foreground)] text-xs font-inherit";

  if (loading) return <div className="p-6 md:p-12 text-center text-[var(--muted-foreground)]">جارٍ التحميل…</div>;

  return (
    <div className="flex flex-col gap-4">
      <div className="flex justify-between items-center">
        <h3 className="text-sm font-bold flex items-center gap-2">
          <Gauge className="text-violet-600" size={16} />
          كتالوج الباقات ({Object.keys(plans).length} باقة)
        </h3>
        <button
          onClick={save}
          disabled={saving || !dirty}
          className={`px-4 py-1.5 rounded-lg border-none text-white text-xs font-bold font-inherit flex items-center gap-1.5 disabled:cursor-not-allowed disabled:opacity-70 ${saving || !dirty ? "bg-[var(--muted)]" : "bg-[#7c3aed]"}`}
        >
          <Save size={12} />
          {saving ? "جارٍ الحفظ…" : "حفظ التغييرات"}
        </button>
      </div>

      {dirty && (
        <div className="px-3 py-2 bg-amber-500/12 border border-amber-500/30 rounded-lg text-[11px] text-amber-500 font-semibold flex items-center gap-1.5">
          <AlertTriangle size={14} />
          تغييرات غير محفوظة
        </div>
      )}

      {Object.entries(plans).map(([key, plan]) => (
        <div className="p-4 bg-[var(--card)] rounded-xl border border-[var(--border)]" key={key}>
          <div className="flex items-center gap-2 mb-3">
            <span className="px-2.5 py-0.5 rounded-lg bg-violet-600 text-white text-[10px] font-extrabold font-mono">
              {key}
            </span>
            <span className="text-[13px] font-bold">{plan.name}</span>
            {plan.highlight && (
              <span className="px-1.5 py-px rounded-md bg-emerald-500 text-white text-[9px] font-bold">مميزة</span>
            )}
          </div>
          <div className="grid grid-cols-[repeat(auto-fit,minmax(160px,1fr))] gap-2.5">
            <div>
              <label className="block text-[10px] text-[var(--muted-foreground)] font-semibold mb-1">الاسم</label>
              <input
                value={plan.name}
                onChange={(e) => updatePlan(key, "name", e.target.value)}
                className={plansInputClass}
              />
            </div>
            <div>
              <label className="block text-[10px] text-[var(--muted-foreground)] font-semibold mb-1">السعر الشهري ($)</label>
              <input
                type="number"
                step="0.01"
                value={plan.priceMonthly}
                onChange={(e) => updatePlan(key, "priceMonthly", parseFloat(e.target.value) || 0)}
                className={plansInputClass}
              />
            </div>
            <div>
              <label className="block text-[10px] text-[var(--muted-foreground)] font-semibold mb-1">الحد الأقصى للفواتير/شهر</label>
              <input
                type="number"
                value={plan.maxInvoicesPerMonth}
                onChange={(e) => updatePlan(key, "maxInvoicesPerMonth", parseInt(e.target.value) || -1)}
                className={plansInputClass}
              />
            </div>
            <div>
              <label className="block text-[10px] text-[var(--muted-foreground)] font-semibold mb-1">الحد الأقصى للشركات</label>
              <input
                type="number"
                value={plan.maxCompanies}
                onChange={(e) => updatePlan(key, "maxCompanies", parseInt(e.target.value) || -1)}
                className={plansInputClass}
              />
            </div>
            <div>
              <label className="block text-[10px] text-[var(--muted-foreground)] font-semibold mb-1">الحد الأقصى للمستخدمين</label>
              <input
                type="number"
                value={plan.maxUsers}
                onChange={(e) => updatePlan(key, "maxUsers", parseInt(e.target.value) || -1)}
                className={plansInputClass}
              />
            </div>
          </div>
        </div>
      ))}
    </div>
  );
}

"use client";

import { useEffect, useState, useCallback } from "react";
import { authedFetch } from "@/context/AuthContext";
import { toast } from "sonner";
import { Database, Trash2, Check } from "lucide-react";

/**
 * Admin P2 — Retention Cleanup tab.
 * Wires the previously-orphaned /api/platform-admin/retention-cleanup
 * (POST) endpoint into a founder-facing UI. The endpoint only exposes
 * POST (no GET), so we use POST with dryRun=true on tab-open to show
 * what WOULD be deleted (eligible counts). The "Run cleanup now" button
 * calls POST without dryRun after a confirm() dialog.
 *
 * Behavior:
 * - Cutoff date = now - retentionYears (default 5).
 * - Deletes soft-deleted (deletedAt < cutoff) invoices, journalEntries,
 *   paymentTransactions, eInvoices, purchaseInvoices (in a transaction).
 * - Founder-only; logs to audit trail.
 */
export function RetentionCleanupTab() {
  const [preview, setPreview] = useState<null | {
    dryRun: boolean;
    retentionPeriodYears: number;
    cutoffDate: string;
    eligible: Record<string, number>;
    deleted?: Record<string, number>;
  }>(null);
  const [loading, setLoading] = useState(true);
  const [running, setRunning] = useState(false);
  const [retentionYears, setRetentionYears] = useState(5);

  const runPreview = useCallback(async (years: number) => {
    setLoading(true);
    try {
      const res = await authedFetch("/api/platform-admin/retention-cleanup", {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({ confirmYears: years, dryRun: true }),
      });
      const d = await res.json();
      if (res.ok) setPreview(d);
      else toast.error(d.error || "تعذّر تحميل المعاينة");
    } finally {
      setLoading(false);
    }
  }, []);

  // eslint-disable-next-line react-hooks/set-state-in-effect
  useEffect(() => { runPreview(retentionYears); }, [runPreview, retentionYears]);

  const runCleanup = async () => {
    const total = preview ? Object.values(preview.eligible).reduce((a, b) => a + b, 0) : 0;
    if (total === 0) { toast.info("لا توجد سجلات مؤهّلة للحذف"); return; }
    if (!confirm(`حذف نهائي لـ ${total} سجل مالي معزول منذ أكثر من ${retentionYears} سنة؟ لا يمكن التراجع.`)) return;
    setRunning(true);
    try {
      const res = await authedFetch("/api/platform-admin/retention-cleanup", {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({ confirmYears: retentionYears, dryRun: false }),
      });
      const d = await res.json();
      if (!res.ok) throw new Error(d.error || "Failed");
      const deletedTotal = d.deleted ? Object.values(d.deleted as Record<string, number>).reduce((a, b) => a + b, 0) : 0;
      toast.success(`تم حذف ${deletedTotal} سجلاً نهائياً`);
      setPreview(d);
    } catch (err) {
      toast.error(err instanceof Error ? err.message : "خطأ");
    } finally {
      setRunning(false);
    }
  };

  if (loading) return <div className="p-6 md:p-12 text-center text-[var(--muted-foreground)]">جارٍ التحميل…</div>;
  if (!preview) return <div className="p-6 md:p-12 text-center text-[var(--muted-foreground)]">تعذّر التحميل</div>;

  const eligibleTotal = Object.values(preview.eligible).reduce((a, b) => a + b, 0);
  const deletedTotal = preview.deleted ? Object.values(preview.deleted).reduce((a, b) => a + b, 0) : 0;

  const labelMap: Record<string, string> = {
    invoices: "الفواتير",
    journalEntries: "قيود اليومية",
    paymentTransactions: "حركات الدفع",
    eInvoices: "الفواتير الإلكترونية",
    purchaseInvoices: "فواتير الشراء",
  };

  return (
    <div className="bg-[var(--card)] rounded-2xl border border-[var(--border)] overflow-hidden">
      <div className="px-4 py-3 border-b border-b-[var(--border)] flex justify-between items-center flex-wrap gap-2">
        <h3 className="text-sm font-bold flex items-center gap-2">
          <Database className="text-emerald-500" size={16} />
          التنظيف الدوري للسجلات المعزولة
        </h3>
        <div className="flex items-center gap-2">
          <label className="text-[11px] font-bold text-[var(--muted-foreground)]">سنوات الاحتفاظ:</label>
          <select
            value={retentionYears}
            onChange={(e) => setRetentionYears(Number(e.target.value))}
            className="w-full px-3 py-2 rounded-lg bg-[var(--background)] border border-[var(--border)] text-[var(--foreground)] font-inherit text-[13px] outline-none max-w-[100px]"
            disabled={running}
          >
            {[3, 5, 7, 10].map((y) => <option key={y} value={y}>{y} سنوات</option>)}
          </select>
        </div>
      </div>

      <div className="p-4 flex flex-col gap-3.5">
        <div className="bg-[var(--muted)] rounded-[10px] text-xs flex flex-col gap-1.5 px-3.5 py-3">
          <div><strong>تاريخ القطع:</strong> {new Date(preview.cutoffDate).toLocaleString("ar-EG")}</div>
          <div><strong>السجلات المعزولة قبل هذا التاريخ ستُحذف نهائياً.</strong></div>
          <div className="text-[10px] text-[var(--muted-foreground)]">
            يشمل: فواتير، قيود يومية، حركات دفع، فواتير إلكترونية، فواتير شراء — جميعها بحالة soft-deleted.
          </div>
        </div>

        <div className="grid grid-cols-[repeat(auto-fit,minmax(140px,1fr))] gap-2.5">
          {Object.entries(preview.eligible).map(([k, v]) => (
            <div className="p-3 rounded-[10px] bg-[var(--card)] border border-[var(--border)]" key={k}>
              <div className="text-[10px] text-[var(--muted-foreground)] font-bold">{labelMap[k] || k}</div>
              <div className={`text-xl font-black ${v > 0 ? "text-amber-500" : "text-[var(--foreground)]"}`}>{v}</div>
              {preview.deleted && (
                <div className="text-[10px] text-emerald-500 font-bold">حُذف: {preview.deleted[k] || 0}</div>
              )}
            </div>
          ))}
        </div>

        <div className="flex justify-between items-center flex-wrap gap-2.5">
          <div className="text-xs text-[var(--muted-foreground)]">
            الإجمالي المؤهّل: <strong className={eligibleTotal > 0 ? "text-amber-500" : "text-[var(--foreground)]"}>{eligibleTotal}</strong>
            {preview.deleted && <> • تم حذف: <strong className="text-emerald-500">{deletedTotal}</strong></>}
          </div>
          <button
            onClick={runCleanup}
            disabled={running || eligibleTotal === 0}
            className={`inline-flex items-center gap-1.5 px-5.5 py-2.5 rounded-[10px] border-none text-white font-inherit text-[13px] font-extrabold disabled:cursor-not-allowed disabled:opacity-70 ${eligibleTotal > 0 ? "bg-[#ef4444]" : "bg-[var(--muted)]"}`}
          >
            <Trash2 size={14} /> {running ? "جارٍ الحذف…" : "تشغيل التنظيف الآن"}
          </button>
        </div>

        {!preview.dryRun && deletedTotal > 0 && (
          <div className="px-3.5 py-2.5 bg-emerald-500/10 rounded-lg text-xs text-emerald-500 font-bold flex items-center gap-1.5">
            <Check size={14} /> تم تنفيذ التنظيف بنجاح — حُذف {deletedTotal} سجل نهائياً.
          </div>
        )}
      </div>
    </div>
  );
}

