                      <td className={cn(tdStyle, "[direction:ltr] text-end font-semibold")}>
                        {fmtMoney(inv.total)}
                      </td>
                      <td className={cn(tdStyle, "[direction:ltr] text-end text-[#10b981]")}>
                        {inv.paid > 0 ? fmtMoney(inv.paid) : "—"}
