          </div>
          {/* Mobile cards */}
          <div className="md:hidden flex flex-col divide-y divide-border">
            {pageMembers.map((m) => {
              const checked = selectedIds.has(m.uid);
              return (
                <div key={m.uid} className={cn("p-3 flex flex-col gap-3", checked ? "bg-accent" : "bg-transparent")}>
